# --- parallel import pre-warm -------------------------------------------------
# flask/socketio/fastapi/uvicorn/PIL/tkinter/asyncio cost ~3-4s of import time
# and are only referenced inside function bodies. Each dependency group is
# imported on its own daemon thread at module start (import I/O releases the
# GIL, so these genuinely overlap), then the real objects are injected into
# module globals so plain `Flask(...)`, `jsonify(...)`, `tk.Tk()` lookups work
# unchanged. Code paths that need a group call _require(group) at their entry
# point — the wait is normally zero because the import finished during the
# rest of startup.
import importlib
import importlib.util

_LAZY_GROUPS = {
    'flask':    ('markupsafe', 'jinja2', 'werkzeug', 'flask'),
    'socketio': ('aiohttp', 'engineio', 'socketio'),
    'fastapi':  ('fastapi', 'uvicorn'),
    'pil':      ('PIL.ImageTk',),
    'tkinter':  ('tkinter.ttk',),
    'asyncio':  ('asyncio',),
}
_LAZY_BIND = {
    'flask': {
        'Flask':               ('flask', 'Flask'),
        'Response':            ('flask', 'Response'),
        'flask_request':       ('flask', 'request'),
        'jsonify':             ('flask', 'jsonify'),
        'abort':               ('flask', 'abort'),
        'redirect':            ('flask', 'redirect'),
        'send_from_directory': ('flask', 'send_from_directory'),
        'stream_with_context': ('flask', 'stream_with_context'),
    },
    'socketio': {'socketio': ('socketio', None)},
    'fastapi': {
        'FastAPI':             ('fastapi', 'FastAPI'),
        'WebSocket':           ('fastapi', 'WebSocket'),
        'WebSocketDisconnect': ('fastapi', 'WebSocketDisconnect'),
        'HTMLResponse':        ('fastapi.responses', 'HTMLResponse'),
        'JSONResponse':        ('fastapi.responses', 'JSONResponse'),
        'uvicorn':             ('uvicorn', None),
    },
    'pil':     {'Image': ('PIL.Image', None), 'ImageTk': ('PIL.ImageTk', None)},
    'tkinter': {
        'tk':           ('tkinter', None),
        'ttk':          ('tkinter.ttk', None),
        'scrolledtext': ('tkinter.scrolledtext', None),
        'messagebox':   ('tkinter.messagebox', None),
    },
    'asyncio': {'asyncio': ('asyncio', None)},
}
_DEP_EVENTS = {g: threading.Event() for g in _LAZY_GROUPS}

def _require(group):
    """Block until a dependency group's names are bound in module globals.
    No-op once the pre-warm for that group has finished."""
    _DEP_EVENTS[group].wait()

def _prewarm_group(group):
    try:
        for mod_name in _LAZY_GROUPS[group]:
            try:
                importlib.import_module(mod_name)
            except Exception:
                pass
        for name, (mod_name, attr) in _LAZY_BIND[group].items():
            try:
                obj = importlib.import_module(mod_name)
                globals()[name] = obj if attr is None else getattr(obj, attr)
            except ImportError:
                globals()[name] = None
    finally:
        _DEP_EVENTS[group].set()

for _g in _LAZY_GROUPS:
    threading.Thread(target=_prewarm_group, args=(_g,),
                     daemon=True, name=f'ImportPrewarm:{_g}').start()

# Module-level __getattr__ (PEP 562): resolves the same names for external
# `module.Flask`-style attribute access and injects them into globals.
def __getattr__(name):
    for group, binds in _LAZY_BIND.items():
        if name in binds:
            _require(group)
            obj = globals().get(name)
            if obj is None:
                raise AttributeError(f"optional dependency for {name!r} unavailable")
            return obj
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

