def _lpay(pl):
    """Payload length without serialization — len(scapy_payload)
    rebuilds every layer incl. checksums; Raw/Padding carry .load,
    NoPayload carries nothing. Rare dissected inner packets fall
    back to the real len()."""
    ld = getattr(pl, 'load', None)
    if isinstance(ld, (bytes, bytearray)):
        return len(ld)
    return 0 if pl is None else len(pl)


def _ecs_subnet(dns):
    """EDNS Client-Subnet (OPT RR, option 8) inside a DNS message —
    the query itself carries the client's real subnet in cleartext,
    an origin leak that survives every forwarder and reveals the
    LAN even when the asking IP is a mask. Returns 'net/bits'."""
    try:
        _a = getattr(dns, 'ar', None)
        for _ in range(int(getattr(dns, 'arcount', 0) or 0) or 1):
            if _a is None:
                break
            if int(getattr(_a, 'type', 0) or 0) == 41:
                _rd = getattr(_a, 'rdata', None)
                if isinstance(_rd, (list, tuple)):
                    for _o in _rd:
                        _fam = int(getattr(_o, 'family', 0) or 0)
                        _adr = getattr(_o, 'address', None)
                        _nm = int(getattr(_o, 'source_netmask', 0) or 0)
                        if _adr and _fam in (1, 2):
                            return f"{_adr}/{_nm}"
                _rb = bytes(_rd) if isinstance(
                    _rd, (bytes, bytearray)) else b''
                _i = 0
                while _i + 4 <= len(_rb):
                    _c = int.from_bytes(_rb[_i:_i + 2], 'big')
                    _ln = int.from_bytes(_rb[_i + 2:_i + 4], 'big')
                    _v = _rb[_i + 4:_i + 4 + _ln]
                    if len(_v) < _ln:
                        break
                    _i += 4 + _ln
                    if _c == 8 and _ln >= 4:
                        _fam = int.from_bytes(_v[:2], 'big')
                        _nm = _v[2]
                        _ab = _v[4:]
                        if _fam == 1:
                            return ('.'.join(str(b) for b in _ab)
                                    + f"/{_nm}")
                        if _fam == 2 and len(_ab) <= 16:
                            return (str(ipaddress.IPv6Address(
                                bytes(_ab).ljust(16, b'\x00')))
                                + f"/{_nm}")
            _a = getattr(_a, 'payload', None)
    except Exception:
        pass
    return None


def _svcb_ips(rdata: bytes):
    """SVCB/HTTPS rdata → embedded ipv4hint/ipv6hint addresses: the
    DNS answer names the real pre-CDN origin endpoints. Wire format:
    priority(2) + targetname(labels) + SvcParam chain (key:2,len:2).
    Used only when scapy's SvcParam decode is unavailable."""
    out = []
    try:
        i = 2  # skip priority
        n = len(rdata)
        while i < n:  # targetname — uncompressed labels
            l = rdata[i]
            if l == 0:
                i += 1
                break
            i += 1 + l
        while i + 4 <= n:
            k = int.from_bytes(rdata[i:i + 2], 'big')
            ln = int.from_bytes(rdata[i + 2:i + 4], 'big')
            v = rdata[i + 4:i + 4 + ln]
            if len(v) < ln:
                break
            i += 4 + ln
            if k == 4:
                for o in range(0, ln - ln % 4, 4):
                    out.append('.'.join(str(b) for b in v[o:o + 4]))
            elif k == 6:
                for o in range(0, ln - ln % 16, 16):
                    out.append(str(ipaddress.IPv6Address(v[o:o + 16])))
    except Exception:
        pass
    return out


def _parse_stun_mapped(data: bytes):
    """Walk STUN TLVs for (XOR-)MAPPED-ADDRESS and decode it — a binding
    response carries the RECEIVER's public reflexive address XORed with
    the magic cookie. This is the honest version of "the IP is just a
    name": the address the outside world actually sees, read straight
    off the wire with zero packets sent. Returns 'ip:port' or ''."""
    if len(data) < 24 or data[4:8] != b'\x21\x12\xa4\x42':
        return ''
    mtype = int.from_bytes(data[:2], 'big')
    if mtype not in (0x0101, 0x0111):      # binding success / error response
        return ''
    off = 20
    for _ in range(40):                    # bounded TLV walk
        if off + 4 > len(data):
            break
        atype = int.from_bytes(data[off:off + 2], 'big')
        alen = int.from_bytes(data[off + 2:off + 4], 'big')
        aval = data[off + 4:off + 4 + alen]
        if atype in (0x0001, 0x0020) and len(aval) >= 8 and aval[1] == 0x01:
            xport = int.from_bytes(aval[2:4], 'big')
            xip = int.from_bytes(aval[4:8], 'big')
            if atype == 0x0020:            # XOR-MAPPED-ADDRESS
                xport ^= 0x2112
                xip ^= 0x2112A442
            try:
                return f"{ipaddress.ip_address(xip)}:{xport}"
            except Exception:
                return ''
        off += 4 + alen + ((4 - alen % 4) % 4)
    return ''


def _parse_inner_ip(data: bytes):
    """Decode an inner IP header carried verbatim inside a cleartext
    encapsulation (IPIP/6in4/GRE/GTP-U/ping tunnel). The inner src/dst
    are the REAL pre-tunnel endpoints — the literal peer-through read:
    the encapsulator's payload names what the outer address masks.
    Returns (src, dst) or None."""
    if not data or len(data) < 20:
        return None
    try:
        v = data[0] >> 4
        if v == 4 and (data[0] & 0x0F) >= 5:
            return (str(ipaddress.ip_address(data[12:16])),
                    str(ipaddress.ip_address(data[16:20])))
        if v == 6 and len(data) >= 40:
            return (str(ipaddress.ip_address(data[8:24])),
                    str(ipaddress.ip_address(data[24:40])))
    except Exception:
        return None
    return None


def _parse_gre_inner(data: bytes):
    """Slice the inner packet out of a GRE frame — RFC 2784 header is
    4B + optional fields (C/R=0xC0 → +4, K=0x20 → +4, S=0x10 → +4).
    PPTP's GRE variant carries PPP; 0x0021/0x0057 locate the inner IP
    there too. Returns inner bytes starting at the inner IP header."""
    if len(data) < 24 or data[1] & 0x07 not in (0, 1):
        return b''
    off = 4
    for flag in (0xC0, 0x20, 0x10):
        if data[0] & flag:
            off += 4
    if off + 20 > len(data):
        return b''
    inner = data[off:]
    if data[2:4] == b'\x88\x0b':          # PPP inside GRE — PPTP data
        for poff in (0, 2):               # address/control field optional
            if inner[poff:poff + 2] in (b'\x00\x21', b'\x00\x57'):
                return inner[poff + 2:]
        return b''
    return inner


def _parse_gtp_inner(data: bytes):
    """Slice the inner IP packet out of a GTP-U T-PDU (udp/2152): flags +
    type + len + TEID = 8B, plus seq/N-PDU/next-ext 4B when the E/S/PN
    flags are set, then a bounded extension-header chain. Returns inner
    bytes or b''. The inner header names the subscriber's real flow —
    the mobile-core equivalent of decapsulating a GRE tunnel."""
    if len(data) < 28 or data[1] != 0xFF or (data[0] & 0xE0) != 0x20:
        return b''
    off = 8
    if data[0] & 0x07:                     # optional fields present
        nxt = data[11] if len(data) > 11 else 0
        off = 12
        for _ in range(4):
            if not nxt:
                break
            if off >= len(data):
                return b''
            bl = data[off] * 4             # ext block len, 4B units
            if bl < 4 or off + bl > len(data):
                return b''
            nxt = data[off + bl - 1]
            off += bl
    return data[off:] if off + 20 <= len(data) else b''


def _parse_l2_inner(data: bytes):
    """Slice past an inner Ethernet header — VXLAN/Geneve carry full
    L2 frames, so the overlay's payload is an inner Ethernet+IP packet.
    Returns bytes starting at the inner IP header (802.1Q tags peeled),
    or b''."""
    if len(data) < 34:
        return b''
    et = data[12:14]
    off = 14
    for _ in range(2):                           # bounded VLAN peel
        if et not in (b'\x81\x00', b'\x88\xa8'):
            break
        if off + 4 > len(data):
            return b''
        et = data[off + 2:off + 4]             # real ethertype after TCI
        off += 4
    if et in (b'\x08\x00', b'\x86\xdd') and off + 20 <= len(data):
        return data[off:]
    return b''


def _parse_l2tp_inner(data: bytes):
    """Slice the inner IP out of an L2TP data message (udp/1701):
    flags+len+tid+sid = 8B base, +4B when the S bit sets sequence
    numbers, +2B offset field when the O bit sets it, then PPP —
    0x0021/0x0057 locate the inner IP inside PPP. Control messages
    (T bit) return b''."""
    if len(data) < 14 or data[0] & 0x80:         # T bit = control msg
        return b''
    off = 8
    if data[0] & 0x10:                           # S bit — Ns/Nr
        off += 4
    if data[0] & 0x02:                           # O bit — offset field
        if off + 2 > len(data):
            return b''
        off = int.from_bytes(data[off:off + 2], 'big')
    if off + 2 > len(data):
        return b''
    ppp = data[off:]
    for poff in (0, 2):                          # addr/control optional
        if ppp[poff:poff + 2] in (b'\x00\x21', b'\x00\x57'):
            return ppp[poff + 2:]
    return b''


def _parse_http_host(data: bytes):
    """Extract the Host: header from a plaintext HTTP request — the
    identity the connection CLAIMS to want. On a frontable CDN a Host
    that diverges from every SNI/DNS name seen is the classic domain-
    fronting tell, stronger than an unresolved SNI alone."""
    h = data[:600]
    i = h.find(b'Host:')
    if i < 0:
        return ''
    line = h[i + 5:h.find(b'\r', i) if b'\r' in h[i:] else len(h)]
    try:
        host = line.decode('ascii', 'ignore').strip().lower()
    except Exception:
        return ''
    if host.startswith('['):
        return host[1:host.find(']')] if ']' in host else ''
    return host.split(':')[0]


def _http_header_order(data: bytes):
    """HTTP/1.x response header ORDER — the sequence a stack emits its
    headers in fingerprints the implementation (Apache leads with
    Date,Server; nginx leads Server,Date; IIS interleaves its own
    order). Returns (signature, stack-hint): the full ordered name
    list doubles as a cross-remote correlation token — identical
    exotic order on two addresses is one deployment."""
    try:
        if not data.startswith(b'HTTP/'):
            return '', ''
        head = data.split(b'\r\n\r\n', 1)[0]
        names = []
        for ln in head.split(b'\r\n')[1:9]:
            n, _, _ = ln.partition(b':')
            n = n.strip().lower()
            if n and all(32 <= b < 127 for b in n):
                names.append(n.decode('latin1', 'replace'))
        if len(names) < 2:
            return '', ''
        sig = ','.join(names[:6])
        tag = ''
        if names[:2] == ['date', 'server']:
            tag = 'apache-order'
        elif names[:2] == ['server', 'date']:
            tag = 'nginx-order'
        elif 'x-powered-by' in names[:4] or 'x-aspnet' in names[:4]:
            tag = 'framework-order'
        elif names[0] in ('content-length', 'content-type') \
                and 'server' in names[1:4]:
            tag = 'iis-order'
        return sig, tag
    except Exception:
        return '', ''


def _http_server_banner(data: bytes):
    """HTTP/1.x response identity VALUES — `Server:` names the
    software+version (`Apache/2.4.41 (Ubuntu)`, `Microsoft-IIS/10.0`,
    `nginx/1.24.0`, `cloudflare`, `Cowboy`); `X-Powered-By:` names the
    framework (`PHP/8.1`, `ASP.NET`, `Express`); `Via:` names in-path
    proxies; `X-AspNet-Version:` leaks the CLR. Returns
    (server, powered_by, via) — any may be ''."""
    try:
        if not data.startswith(b'HTTP/'):
            return '', '', ''
        head = data.split(b'\r\n\r\n', 1)[0][:2000]
        srv = pwr = via = ''
        for ln in head.split(b'\r\n')[1:24]:
            n, _, v = ln.partition(b':')
            n = n.strip().lower()
            v = v.strip()
            if not v or not all(32 <= b < 127 for b in v):
                continue
            vs = v.decode('latin1', 'replace')[:80]
            if n == b'server' and not srv:
                srv = vs
            elif n == b'x-powered-by' and not pwr:
                pwr = vs
            elif n == b'via' and not via:
                via = vs
        return srv, pwr, via
    except Exception:
        return '', '', ''


def _parse_greeting_banner(data: bytes):
    """Service greeting banners — cleartext first-line greetings
    name software AND hostname: SMTP `220 mail.corp.local ESMTP
    Postfix`, FTP `220-FileZilla Server`, IMAP `* OK Dovecot`,
    POP3 `+OK mail.corp.local`, NNTP `200 news`, VNC `RFB 003.008`.
    Returns (proto, banner-text) — the hostname in the banner is
    often the deployment's real domain."""
    try:
        if len(data) < 4 or len(data) > 600:
            return '', ''
        ln = data.split(b'\r\n', 1)[0].split(b'\n', 1)[0]
        if len(ln) > 200:
            return '', ''
        low = ln.lower()
        if ln[:3] == b'220' and len(ln) > 4:
            # SMTP or FTP — same code family, both carry banners
            proto = 'smtp' if (b'esmtp' in low or b'smtp' in low
                               or b'mail' in low or b'postfix' in low
                               or b'exchange' in low) else 'ftp'
            return proto, ln[4:].decode('latin1', 'replace').strip()[:90]
        if low.startswith(b'+ok') and len(ln) > 3:
            return 'pop3', ln[3:].decode('latin1', 'replace').strip()[:90]
        if low.startswith(b'* ok') and len(ln) > 4:
            return 'imap', ln[4:].decode('latin1', 'replace').strip()[:90]
        if ln[:3] in (b'200', b'201') and len(ln) > 4 \
                and (b'nntp' in low or b'news' in low
                     or b'posting' in low or b'interim' in low):
            return 'nntp', ln[4:].decode('latin1', 'replace').strip()[:90]
        if ln.startswith(b'RFB ') and len(ln) >= 11:
            return 'vnc', ln[:12].decode('latin1', 'replace')
        return '', ''
    except Exception:
        return '', ''


def _icmp_echo_class(body: bytes):
    """ICMP echo-request payload class — the alphabet fingerprints the
    sender's OS: Windows ping ships `abcdefghijklmnopqrstuvwabcdefghi`,
    Linux/BSD ships timestamped binary, Cisco/mikrotik ship zero or
    counter patterns, crafted tools ship text or entropy. Passive OS
    identity from a ping the mask can't fake without rewriting its
    own probe tool."""
    try:
        if len(body) < 8:
            return ''
        b = body[:48]
        if b.startswith(b'abcdefghi') or b.startswith(b'abcdefg'):
            return 'win-alphabet'
        if not any(b):
            return 'zero-fill'
        if b == bytes(range(len(b))) or b[:4] == b'\x00\x01\x02\x03':
            return 'counter'
        pr = sum(32 <= x < 127 for x in b) / len(b)
        if pr > 0.9:
            return 'text'
        return 'binary'
    except Exception:
        return ''


def _parse_ssh_banner(data: bytes):
    """SSH version banner — the daemon names its own stack+version in
    cleartext: OpenSSH_9.2, dropbear_2022.83, ROSSSH (MikroTik),
    Cisco-1.x, libssh, paramiko, mod_sftp — an OS/vendor class the
    endpoint cannot hide without breaking the protocol."""
    if not data.startswith(b'SSH-'):
        return ''
    try:
        ln = data.split(b'\r\n', 1)[0].decode('ascii', 'replace')
        return ln[:60] if 6 < len(ln) < 100 else ''
    except Exception:
        return ''


def _parse_ssh_kexinit(data: bytes):
    """SSH_MSG_KEXINIT algorithm-name-lists — the ordered kex, hostkey,
    enc, mac and comp proposals ARE the stack's fingerprint (the SSH
    counterpart of JA3): identical exotic proposal sets on two remotes
    = one implementation answering twice. Returns (sig, tag)."""
    try:
        limit = min(len(data) - 22, 2048)
        for off in range(0, limit):
            plen = int.from_bytes(data[off:off + 4], 'big')
            if not (16 <= plen <= 35000):
                continue
            pad = data[off + 4]
            if data[off + 5] != 20 or not (4 <= pad < plen):
                continue
            body = data[off + 6:off + 4 + plen - pad]
            if len(body) < 16 + 40:
                continue
            pos, lists, ok = 16, [], True
            for _ in range(10):
                if pos + 4 > len(body):
                    ok = False
                    break
                ln = int.from_bytes(body[pos:pos + 4], 'big')
                pos += 4
                if pos + ln > len(body) or ln > 4096:
                    ok = False
                    break
                s = body[pos:pos + ln]
                pos += ln
                if not all(32 <= b < 127 for b in s):
                    ok = False
                    break
                lists.append(s.decode('latin1'))
            if not ok or len(lists) != 10 or not lists[0]:
                continue
            kex = lists[0]
            sig = hashlib.md5(
                '|'.join(lists[:9]).encode()).hexdigest()[:12]
            tag = 'ssh'
            if 'kex-strict' in kex:
                tag = 'openssh-strict'
            elif kex.startswith('curve25519-sha256'):
                tag = 'modern-ssh'
            elif kex.startswith('diffie-hellman-group'):
                tag = 'legacy-ssh'
            elif kex.startswith('ecdh-sha2-'):
                tag = 'nist-first ssh'
            return sig, tag
    except Exception:
        pass
    return '', ''


def _parse_ssh_hostkey(data: bytes):
    """SSH_MSG_KEXDH_REPLY/KEX_ECDH_REPLY (type 31): the FIRST string
    after the type byte is the server's host public-key blob —
    'ssh-rsa' e+n, 'ssh-ed25519' key, 'ecdsa-sha2-*' point. The host
    key IS the machine's identity: two remotes presenting the same
    host-key fingerprint are literally the same SSH daemon on the
    same host, stronger than any stack fingerprint. Returns
    (fp12, key_type) or ('', '')."""
    try:
        limit = min(len(data) - 24, 4096)
        for off in range(0, limit):
            plen = int.from_bytes(data[off:off + 4], 'big')
            if not (24 <= plen <= 35000):
                continue
            pad = data[off + 4]
            if data[off + 5] != 31 or not (4 <= pad < plen):
                continue
            body = data[off + 6:off + 4 + plen - pad]
            if len(body) < 40:
                continue
            klen = int.from_bytes(body[:4], 'big')
            if not (24 <= klen <= len(body) - 4):
                continue
            blob = body[4:4 + klen]
            # blob[0] is a name-list: 'ssh-rsa'/'ssh-ed25519'/
            # 'ecdsa-sha2-nistp256' — sanity-check the alg string.
            alen = int.from_bytes(blob[:4], 'big')
            if not (3 <= alen <= 40) or alen + 4 > len(blob):
                continue
            alg = blob[4:4 + alen]
            if not all(32 <= b < 127 for b in alg):
                continue
            alg_s = alg.decode('latin1', 'replace')
            if not (alg_s.startswith('ssh-')
                    or alg_s.startswith('ecdsa-')
                    or alg_s.startswith('sk-')
                    or alg_s.startswith('x509')):
                continue
            return (hashlib.sha256(blob).hexdigest()[:12], alg_s)
    except Exception:
        pass
    return '', ''


def _decode_v6_transition(ip: str):
    """IPv6 transition-address decode — Teredo/6to4/NAT64/ISATAP/
    v4-mapped addresses EMBED the real endpoint in their own bits.
    Returns a list of (mechanism, embedded_v4) pairs. The address
    itself is the mask; decoding it is a zero-packet unmask of the
    hidden IPv4 endpoint (which then goes through full verification).
    """
    out = []
    try:
        import ipaddress as _ipa
        a = _ipa.IPv6Address(str(ip).split('%')[0])
        w = a.packed
        if w[:4] == b'\x20\x01\x00\x00':                    # Teredo
            srv = '.'.join(str(b) for b in w[4:8])
            cli = '.'.join(str(b ^ 0xFF) for b in w[12:16])
            out.append(('teredo-client', cli))
            out.append(('teredo-server', srv))
        if w[:2] == b'\x20\x02':                             # 6to4
            out.append(('6to4',
                        '.'.join(str(b) for b in w[2:6])))
        if w[:4] == b'\x00\x64\xff\x9b' and w[4:12] == b'\x00' * 8:
            out.append(('nat64',                              # 64:ff9b::/96
                        '.'.join(str(b) for b in w[12:16])))
        if w[10:12] == b'\xff\xff' and w[:10] == b'\x00' * 10:
            out.append(('v4-mapped',
                        '.'.join(str(b) for b in w[12:16])))
        if w[8:12] in (b'\x00\x00\x5e\xfe', b'\x02\x00\x5e\xfe'):
            out.append(('isatap',
                        '.'.join(str(b) for b in w[12:16])))
        # Overlay-mesh ranges — Yggdrasil (0200::/7, first byte
        # 0x02/0x03) and CJDNS (fc00::/8) are self-declaring overlay
        # endpoints: the address family IS the mask's name. No
        # embedded v4 — the field echoes the v6 so the row reads the
        # mechanism. (fd00::/8 ULA stays unmarked — plain private.)
        if w[0] == 0x02 or w[0] == 0x03:
            out.append(('yggdrasil', str(a)))
        elif w[0] == 0xFC:
            out.append(('cjdns', str(a)))
    except Exception:
        pass
    return out


def _wire_public(ip: str) -> bool:
    """Remote-eligibility for wire harvest — a transition address
    (Teredo/6to4/NAT64…) is a tunnel endpoint BY DEFINITION even where
    ipaddress.is_global excludes the deprecated ranges (6to4/Teredo
    fall under 2001::/23 and 2002::/16, both non-global in Python
    ≥3.12)."""
    return (_is_public_ip_cached(ip) or
            (':' in ip and bool(_decode_v6_transition(ip))))


def _parse_proxy_hdr(data: bytes):
    """haproxy PROXY-protocol header — a relay stamps the REAL
    pre-relay client address in cleartext right at the head of the
    stream. v1: 'PROXY TCP4 <src> <dst> <sport> <dport>\\r\\n'.
    v2: \\r\\n\\r\\n\\0\\r\\nQUIT\\n + ver/cmd + fam + len + addrs.
    Returns the client IPs the relay named (empty when not a PROXY
    header)."""
    try:
        if data[:5] == b'PROXY':
            _e = data.find(b'\r\n')
            _f = data[:_e if 0 < _e < 128 else 128].split()
            if len(_f) >= 3 and _f[1] in (b'TCP4', b'TCP6'):
                return [_f[2].decode('ascii', 'replace')]
            return []
        if data[:12] == b'\r\n\r\n\x00\r\nQUIT\n' and len(data) >= 16:
            fam = data[13] & 0xF0
            if fam == 0x10 and len(data) >= 20:      # INET4
                return ['.'.join(str(b) for b in data[16:20])]
            if fam == 0x20 and len(data) >= 32:      # INET6
                import ipaddress as _ipa
                return [str(_ipa.IPv6Address(data[16:32]))]
    except Exception:
        pass
    return []


_REAL_IP_HEADERS = (
    # Ordered by trust: single-purpose client-address headers first. A
    # request carrying any of these has ALREADY crossed a relay chain
    # (CDN edge, reverse proxy, VPN egress) that stamped the original
    # client — the first/only address is the real pre-relay client.
    b'cf-connecting-ip:',         # Cloudflare edge -> origin
    b'true-client-ip:',           # Akamai / Cloudflare Enterprise
    b'x-real-ip:',                # nginx relay
    b'x-forwarded-for:',          # generic proxy chain
    b'forwarded:',                # RFC 7239
    b'fastly-client-ip:',         # Fastly edge
    b'x-cluster-client-ip:',      # LB clusters
    b'x-client-ip:',              # generic LB
    b'client-ip:',                # generic LB
    b'x-originating-ip:',         # IIS / WAF class
    b'x-remote-ip:',              # generic
    b'x-remote-addr:',            # generic
    b'x-azure-clientip:',         # Azure Front Door
    b'x-appengine-user-ip:',      # Google AppEngine
    b'x-ms-forwarded-client-ip:', # Azure Application Gateway
    b'ali-cdn-real-ip:',          # Alibaba Cloud CDN
    b'x-tencentedge-client-ip:',  # Tencent EdgeOne
    b'x-via:',                    # Squid chain with embedded IP
)


def _parse_http_xff(data: bytes):
    """Real-client headers stamped by a relay upstream — X-Forwarded-For,
    Forwarded, CF-Connecting-IP, True-Client-IP, X-Real-IP and the rest of
    the relay-to-origin header family. The first address in the value is
    the real pre-relay client."""
    try:
        low = data.lower()
        for mk in _REAL_IP_HEADERS:
            i = low.find(mk)
            if i < 0:
                continue
            j = low.find(b'\r\n', i)
            v = data[i + len(mk):j if j > 0 else i + len(mk) + 200]
            v = v.decode('ascii', 'replace')
            if mk == b'forwarded:':
                for part in v.split(';'):
                    part = part.strip().lower()
                    if part.startswith('for='):
                        v = part[4:].strip('"[] ')
                        break
            elif mk == b'x-via:':
                m = re.search(r'([0-9]{1,3}(?:\.[0-9]{1,3}){3}|[0-9a-fA-F:]{3,45})', v)
                v = m.group(1) if m else ''
            return v.split(',')[0].strip().strip('"[] ')
    except Exception:
        pass
    return ''




def _parse_sip_leak(data: bytes):
    """SIP headers leak pre-NAT addresses in cleartext — `Via:
    SIP/2.0/UDP <ip>:<port>`, `Contact: <sip:u@ip>`, and SDP
    `c=IN IP4 <ip>` all carry the phone's REAL address regardless
    of what the wire src claims. Returns every distinct IP found."""
    out = []
    try:
        txt = data.decode('latin-1', 'replace')
        import re as _re
        for m in _re.finditer(
                r'(?:Via:\s*SIP/2\.0/\w+\s+|Contact:\s*<?sip:[^@>]*@|'
                r'c=IN\s+IP[46]\s+)([0-9a-fA-F:.]{3,45})', txt):
            a = m.group(1).split(':')[0] if '.' in m.group(1) else \
                m.group(1)
            try:
                ipaddress.ip_address(a)
            except ValueError:
                continue
            if a not in out:
                out.append(a)
    except Exception:
        pass
    return out


def _parse_ftp_eprt(data: bytes):
    """FTP PORT / EPRT commands and PASV replies embed the
    data-channel endpoint verbatim: `PORT a,b,c,d,p1,p2`,
    `EPRT |1|a|p|`, `EPRT |2|v6|p|`, `227 ...(a,b,c,d,p,p)`.
    Returns the embedded addresses (empty when none)."""
    out = []
    try:
        txt = data.decode('latin-1', 'replace')
        import re as _re
        for m in _re.finditer(
                r'(?:(?:^|\r\n)\s*PORT\s+|227[^0-9]*)'
                r'(\d{1,3}(?:,\d{1,3}){5})', txt):
            a = '.'.join(m.group(1).split(',')[:4])
            try:
                ipaddress.ip_address(a)
            except ValueError:
                continue
            if a not in out:
                out.append(a)
        for m in _re.finditer(r'EPRT\s*\|\s*(\d)\s*\|'
                              r'([0-9a-fA-F:.]{3,45})\s*\|\s*\d+', txt):
            a = m.group(2)
            try:
                ipaddress.ip_address(a)
            except ValueError:
                continue
            if a not in out:
                out.append(a)
    except Exception:
        pass
    return out


def _cert_cn(data: bytes):
    """Minimal DER commonName extractor — scans certificate bytes for
    the `55.04.03` OID (id-at-commonName) followed by a
    PrintableString/UTF8String/IA5String/TeletexString and returns
    every CN found. Issuer and subject CNs both surface. No full ASN.1
    walk — sufficient for the TLS-intercept check and bounded."""
    out = []
    try:
        oid = b'\x06\x03\x55\x04\x03'
        pos = 0
        while True:
            i = data.find(oid, pos)
            if i < 0 or i + 7 > len(data) or len(out) >= 6:
                break
            st = data[i + 5]      # string tag
            ln = data[i + 6]      # short-form length
            if st in (0x0C, 0x13, 0x16, 0x14, 0x1E) \
                    and 0 < ln < 64 and i + 7 + ln <= len(data):
                cn = data[i + 7:i + 7 + ln].decode('utf-8', 'replace')
                if cn and cn not in out:
                    out.append(cn)
            pos = i + 1
    except Exception:
        pass
    return out


def _dom_suffix_match(a: str, b: str) -> bool:
    """Domain suffix match for cert/SNI comparison — wildcards
    stripped, either name may be the parent zone."""
    a = a.lower().lstrip('*.').rstrip('.')
    b = b.lower().lstrip('*.').rstrip('.')
    return bool(a and b) and \
        (a == b or a.endswith('.' + b) or b.endswith('.' + a))


def _classify_udp_wire(data: bytes, sport: int = 0, dport: int = 0):
    """First-bytes protocol identification of a UDP payload — returns
    (tag, detail) or (None, ''). Tags: wg1/wg2/wg3/wg4 (WireGuard msg
    types), ovpn# (OpenVPN opcode), dtls, quic, doq, stun, vxlan, geneve,
    l2tp, natt, espudp, gtp. A WireGuard handshake message is
    protocol-level proof of the one tunnel that answers NO probe;
    OpenVPN reset opcodes and DTLS record headers are nearly as
    definitive. Nothing is transmitted — this names traffic already on
    the wire."""
    if not data or len(data) < 4:
        return None, ''
    n = len(data)
    b0 = data[0]
    # Port-locked encapsulation channels first — a named port + header
    # shape is high-precision evidence and must run before the looser
    # opcode/QUIC heuristics below can swallow it.
    if n >= 8:
        if (sport == 4789 or dport == 4789) and data[0] & 0x08:
            return 'vxlan', (f"VXLAN overlay VNI "
                             f"{int.from_bytes(data[4:7], 'big')}")
        if (sport == 6081 or dport == 6081) and data[0] & 0xC0 == 0:
            return 'geneve', 'Geneve overlay encapsulation (udp/6081)'
        if (sport == 1701 or dport == 1701) and data[0] & 0xC0 \
                and data[1] & 0x0F == 0x02:
            # T bit (0x80) = control, L bit (0x40) = data w/ length —
            # either shape with L2TPv2 version is a tunnel frame.
            return 'l2tp', ('L2TP tunnel channel (udp/1701) — '
                            + ('control' if data[0] & 0x80 else 'data'))
        if sport in _GTP_PORTS or dport in _GTP_PORTS:
            if (b0 & 0xE0) in (0x20, 0x40):
                return 'gtp', (f"GTPv{b0 >> 5} mobile-core tunnel "
                               f"(udp/{sport if sport in _GTP_PORTS else dport})")
        if sport == 4500 or dport == 4500:
            if data[:4] == b'\x00\x00\x00\x00':
                return 'natt', 'IPsec NAT-T non-ESP marker (udp/4500)'
            return 'espudp', (f"ESP-in-UDP NAT-T SPI "
                              f"0x{int.from_bytes(data[:4], 'big'):08x}")
        # Mesh-VPN overlays — every hiding place that isn't a port
        # scan can see. ZeroTier frames embed the 40-bit node IDs;
        # Tailscale disco and Nebula handshakes carry ASCII magics.
        if (sport == 9993 or dport == 9993) and n >= 23 \
                and data[10] <= 0x0f:
            return 'zt', (f"ZeroTier overlay node "
                          f"{data[5:10].hex()}")
        if (sport == 41641 or dport == 41641) and \
                data[:6] == b'TS\xf0\x9f\x92\x9e':
            return 'tailscale', ('Tailscale disco — tailnet '
                                 'mesh-VPN node')
        if data[:7] == b'nebula\x01':
            return 'nebula', 'Nebula mesh-VPN handshake magic'
    # STUN/TURN — RFC 5389 magic cookie at offset 4. The ICE/VoIP/WebRTC
    # reflexive channel; binding responses carry the receiver's REAL
    # public address (decoded separately by _parse_stun_mapped).
    if n >= 20 and data[4:8] == b'\x21\x12\xa4\x42':
        return 'stun', ('STUN/TURN channel (RFC5389) — ICE/VoIP/WebRTC '
                        'reflexive transport')
    # DTLS record: content-type 0x16 + version fe.fd / fe.ff — the UDP TLS
    # Cisco AnyConnect, F5, and WebRTC-class VPNs speak.
    if b0 == 0x16 and n >= 3 and data[1] == 0xFE and data[2] in (0xFD, 0xFF):
        return 'dtls', 'DTLS record (fe.fd) — UDP TLS transport'
    # QUIC long header: form+fixed bits set, version field nonzero.
    # On udp/853 the same shape is DNS-over-QUIC — the encrypted-DNS
    # channel the resolver port names outright.
    if b0 & 0xC0 == 0xC0 and n >= 7:
        ver = int.from_bytes(data[1:5], 'big')
        if ver and data[5] <= 20:
            if sport == 853 or dport == 853:
                return 'doq', ('DNS-over-QUIC (udp/853) — encrypted '
                               'DNS channel')
            qtype = (b0 & 0x30) >> 4
            qnames = {0: 'initial', 1: '0-rtt', 2: 'handshake', 3: 'retry'}
            return 'quic', f"QUIC long-header {qnames.get(qtype, qtype)}"
    if b0 <= 4 and data[1:4] == b'\x00\x00\x00':
        want = _WG_MSG_SIZES.get(b0)
        if want is not None and n == want:
            return f'wg{b0}', f"WireGuard {_WG_MSG_NAMES[b0]} ({n}B)"
        if b0 == 4 and n >= 32:
            return 'wg4', f"WireGuard {_WG_MSG_NAMES[4]} ({n}B)"
        return None, ''
    op = b0 >> 3
    if op in _OVPN_OPS and n >= 9:
        return f'ovpn{op}', f"OpenVPN {_OVPN_OPS[op]}"
    return None, ''


def _classify_payload_head(data: bytes):
    """Classify the FIRST bytes of a TCP/UDP flow payload. Returns
    (tag, detail): 'tls' (real TLS record), 'wstun' (WebSocket upgrade —
    tunnels mask as ordinary HTTP), 'plain' (identified plaintext
    protocol), or None — a high-entropy payload matching NONE of these is
    the Shadowsocks/V2Ray/obfs4 obfuscated-transport signature."""
    if not data:
        return None, ''
    if len(data) >= 3 and data[0] == 0x16 and data[1] == 0x03:
        return 'tls', 'TLS record header'
    if len(data) >= 9 and (b'websocket' in data[:200].lower() or
                           b'Sec-WebSocket' in data[:200]):
        if b'HTTP' in data[:200] or b'Upgrade' in data[:200]:
            return 'wstun', 'WebSocket upgrade — HTTP-masked tunnel'
    # HTTP CONNECT — a proxy-relay channel named by its own method verb:
    # the flow's real destination is the CONNECT argument, not the peer.
    if data[:8] == b'CONNECT ':
        return 'connect', 'HTTP CONNECT — proxy tunnel channel'
    # SOCKS5 greeting / method-selection reply on ANY port — the proxy
    # protocol spoken where no proxy port was flagged. (VER 0x05,
    # NMETHODS ≤4 or a 2-byte method answer.)
    if 2 <= len(data) <= 6 and data[0] == 0x05 and \
            (len(data) == 2 or (data[1] <= 4 and data[2] <= 3)):
        return 'socks5', 'SOCKS5 greeting/reply — proxy relay channel'
    # SOCKS4/SOCKS4a request — VN 0x04 + CD 0x01/0x02: the older
    # proxy protocol, still in use on stealth relay chains.
    if len(data) >= 8 and data[0] == 0x04 and data[1] in (1, 2):
        return 'socks4', 'SOCKS4 connect request — proxy relay channel'
    # OpenVPN over TCP — a 2-byte length frame wrapping an opcode packet.
    if len(data) >= 11:
        _ln = int.from_bytes(data[:2], 'big')
        if _ln == len(data) - 2 and (data[2] >> 3) in _OVPN_OPS:
            return 'ovpntcp', f"OpenVPN-TCP {_OVPN_OPS[data[2] >> 3]}"
    # STUN over stream transport — same magic cookie as the UDP form.
    if len(data) >= 20 and data[4:8] == b'\x21\x12\xa4\x42':
        return 'stun', 'STUN/TURN channel over stream transport'
    if len(data) >= 4:
        head = data[:200]
        for m in _PLAINTEXT_MARKERS:
            if head.startswith(m):
                return 'plain', m.decode('ascii', 'replace').strip()
        # TLS ServerHello/cert/alert/app-data after handshake (0x17 app,
        # 0x15 alert, 0x14 CCS) also counts as identified TLS.
        if data[0] in (0x14, 0x15, 0x17) and data[1] == 0x03:
            return 'tls', 'TLS record header'
    return None, ''


# ============= SELF-NAMING / SELF-DECODING WIRE PROTOCOLS =============
# The strongest masks still leak identity in their OWN protocol bytes:
# a NetBIOS node reports its real hostname, an SNMP agent its sysName,
# an NTP daemon its upstream source, an SCTP endpoint its full address
# set, a TLS stack its session id, an EUI-64 address its NIC MAC. Each
# helper below either builds the one standard datagram the service
# answers anyway, or decodes what is already on the wire.

def _dns_skip_name(data: bytes, off: int) -> int:
    """Skip a (possibly compressed) DNS name starting at off; returns
    the offset AFTER the name, or -1 when malformed."""
    try:
        for _ in range(32):
            if off >= len(data):
                return -1
            b = data[off]
            if b & 0xC0 == 0xC0:
                return off + 2                       # compression pointer
            if b == 0:
                return off + 1
            if b & 0xC0:
                return -1
            off += 1 + b
        return -1
    except Exception:
        return -1


def _dns_answer_records(data: bytes):
    """Walk a DNS reply's answer section — returns [(qtype, rdata-bytes)].
    A bounded parse sufficient for TXT/A/CHAOS answers."""
    out = []
    try:
        if len(data) < 12:
            return out
        _tx, _fl, qd, an, _n, _a = struct.unpack('!6H', data[:12])
        off = 12
        for _ in range(min(qd, 8)):
            off = _dns_skip_name(data, off)
            if off < 0:
                return out
            off += 4
        for _ in range(min(an, 24)):
            off = _dns_skip_name(data, off)
            if off < 0 or off + 10 > len(data):
                return out
            rtype, _rc, _ttl, rdlen = struct.unpack('!HHIH', data[off:off + 10])
            off += 10
            if off + rdlen > len(data):
                return out
            out.append((rtype, data[off:off + rdlen]))
            off += rdlen
    except Exception:
        pass
    return out


def _dns_rcode(data: bytes) -> int:
    try:
        return data[3] & 0x0F if len(data) >= 4 else -1
    except Exception:
        return -1


def _nbns_status_packet() -> bytes:
    """NetBIOS-over-TCP/UDP node-status query for the wildcard name — a
    registered host answers with its full name table AND its MAC."""
    enc = b'CK' + b'A' * 30
    return (struct.pack('!HHHHHH', 0x5342, 0x0000, 1, 0, 0, 0)
            + b'\x20' + enc + b'\x00' + struct.pack('!HH', 0x0021, 0x0001))


def _parse_nbns(data: bytes):
    """Parse an NBSTAT (node-status) reply: answer RR after the question,
    then a name table of 16B entries + flags, stats tail carrying the
    6-byte adapter MAC. Returns {'names': [...], 'mac': '..'}."""
    out = {'names': [], 'mac': ''}
    try:
        if len(data) < 56 or data[2] & 0x80 == 0:
            return out
        off = _dns_skip_name(data, 12)
        if off < 0:
            return out
        off += 4                                # question type/class
        off = _dns_skip_name(data, off)         # answer name (ptr)
        if off < 0 or off + 10 > len(data):
            return out
        rtype, _rc, _t, rdlen = struct.unpack('!HHIH', data[off:off + 10])
        off += 10
        if rtype != 0x0021 or off + rdlen > len(data) or rdlen < 7:
            return out
        body = data[off:off + rdlen]
        n = body[0]
        for i in range(min(n, 18)):
            rec = body[1 + i * 18:1 + i * 18 + 18]
            if len(rec) < 18:
                break
            nm = rec[:15].rstrip(b'\x00 ').decode('ascii', 'replace')
            suffix = rec[15]
            flags = int.from_bytes(rec[16:18], 'big')
            if nm:
                out['names'].append(f"{nm}<{suffix:02x}>"
                                    + (' grp' if flags & 0x8000 else ''))
        mac_off = 1 + min(n, 18) * 18
        if len(body) >= mac_off + 6:
            raw = body[-6:]
            out['mac'] = ':'.join(f'{b:02X}' for b in raw)
    except Exception:
        pass
    return out


def _dns_read_name(data: bytes, off: int):
    """Decompress one DNS name at offset; returns (name, end_offset).
    end_offset is 0 on a malformed run so callers can bail cleanly."""
    labels, jumped, end, guard = [], False, off, 0
    while off < len(data) and guard < 64:
        guard += 1
        ln = data[off]
        if ln == 0:
            if not jumped:
                end = off + 1
            break
        if ln & 0xC0 == 0xC0:
            if off + 1 >= len(data):
                return '', 0
            ptr = ((ln & 0x3F) << 8) | data[off + 1]
            if not jumped:
                end = off + 2
            off = ptr
            jumped = True
            continue
        off += 1
        if off + ln > len(data):
            return '', 0
        labels.append(data[off:off + ln].decode('utf-8', 'replace'))
        off += ln
        if not jumped:
            end = off
    return '.'.join(labels), end


def _mdns_ptr_names(data: bytes) -> list:
    """Extract PTR target names from an mDNS response — the *.local
    hostnames a device publishes about itself."""
    names = []
    try:
        if len(data) < 12 or not (data[2] & 0x80):
            return names
        qd, an = struct.unpack('>HH', data[4:8])
        off = 12
        for _ in range(min(qd, 16)):
            _, e = _dns_read_name(data, off)
            if not e:
                return names
            off = e + 4
        for _ in range(min(an, 64)):
            _, e = _dns_read_name(data, off)
            if not e or e + 10 > len(data):
                break
            rtype, _cls, _ttl, rdlen = struct.unpack('>HHIH', data[e:e + 10])
            roff = e + 10
            if rtype == 12 and roff + rdlen <= len(data):
                nm, _ = _dns_read_name(data, roff)
                nm = nm.rstrip('.')
                if nm and nm not in names:
                    names.append(nm)
            off = roff + rdlen
    except Exception:
        pass
    return names


def _mdns_ptr(ip: str, timeout: float = 0.8) -> list:
    """Unicast mDNS reverse-PTR (QU bit set) — the name a Bonjour/Avahi
    host, printer or IoT device claims for itself on the LAN."""
    try:
        parts = ip.split('.')
        if len(parts) != 4:
            return []
        rev = '.'.join(reversed(parts)) + '.in-addr.arpa'
    except Exception:
        return []
    pkt = _dns_wire_query(rev, 12, 0x8001, qid=0)
    names = []
    for resp in MultiVerifier._udp_exchange(ip, 5353, pkt, timeout=timeout, reads=3):
        for n in _mdns_ptr_names(resp):
            if n not in names:
                names.append(n)
    return names[:8]


def _snmp_v1_get() -> bytes:
    """SNMPv1 GET sysDescr.0 + sysName.0, community 'public'. Hand-rolled
    BER — one standard datagram a discoverable agent answers."""
    def _oid(b):
        return b'\x06' + bytes([len(b)]) + b
    def _oct(b):
        return b'\x04' + bytes([len(b)]) + b
    def _seq(*items):
        b = b''.join(items)
        return b'\x30' + bytes([len(b)]) + b
    def _int(v):
        b = v.to_bytes(max(1, (v.bit_length() + 7) // 8), 'big')
        return b'\x02' + bytes([len(b)]) + b
    def _null():
        return b'\x05\x00'
    vb1 = _seq(_oid(bytes.fromhex('2b06010201010100')), _null())   # sysDescr
    vb2 = _seq(_oid(bytes.fromhex('2b06010201010500')), _null())   # sysName
    vb3 = _seq(_oid(bytes.fromhex('2b06010201010600')), _null())   # sysLocation
    vb = _seq(vb1, vb2, vb3)
    pdu = b'\xa0' + bytes([len(vb) + 9]) \
        + _int(1) + _int(0) + _int(0) + vb
    return _seq(_int(0), _oct(b'public'), pdu)


def _parse_snmp(data: bytes):
    """Pull the OCTET STRING values out of an SNMP response — the
    sysDescr/sysName bodies. Bounded TLV scan, no full ASN.1 walk."""
    vals = []
    try:
        i = 0
        while i + 2 <= len(data) and len(vals) < 8:
            if data[i] == 0x04 and i + 2 + data[i + 1] <= len(data):
                ln = data[i + 1]
                s = data[i + 2:i + 2 + ln].decode('utf-8', 'replace').strip()
                if s and not s.startswith('public') and s not in vals:
                    vals.append(s)
                i += 2 + ln
            else:
                i += 1
    except Exception:
        pass
    return vals


def _ntp_client_packet() -> bytes:
    """NTPv3 client request — LI=0, VN=3, Mode=3; a plain time query."""
    pkt = bytearray(48)
    pkt[0] = 0x1B
    ts = int((time.time() + 2208988800) * (2 ** 32))
    pkt[40:] = struct.pack('!Q', ts & 0xFFFFFFFFFFFFFFFF)
    return bytes(pkt)


def _parse_ntp(data: bytes):
    """Parse a 48-byte NTP server reply: stratum + reference ID. On
    stratum 2-15 the refid IS the daemon's upstream source IPv4 on
    pre-4.2.7p230 servers (nV-era daemons hash it — noted accordingly).
    Stratum 1 refid is an ASCII source (GPS/PPS/ATOM)."""
    try:
        if len(data) < 48 or (data[0] & 0x07) not in (4, 5):
            return None
        strat = data[1]
        mode = data[0] & 0x07
        refid_raw = data[12:16]
        out = {'mode': mode, 'stratum': strat,
               'precision': struct.unpack('!b', data[3:4])[0]}
        if strat == 1:
            out['refid'] = refid_raw.rstrip(b'\x00').decode('ascii', 'replace')
            out['refid_ip'] = ''
        else:
            refip = '.'.join(str(b) for b in refid_raw)
            out['refid'] = refip
            # nV-era refids are a hash (first byte |= 0x80 on IPv6 syncs);
            # classic IPv4 upstreams are a live address worth checking.
            out['refid_ip'] = refip if _is_public_ip_cached(refip) else ''
        return out
    except Exception:
        return None


def _ssdp_msearch() -> bytes:
    """Unicast SSDP M-SEARCH — many WAN-exposed UPnP devices (consumer
    routers / CGN CPE) answer with SERVER + LOCATION headers naming
    the real device."""
    return (b'M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\n'
            b'MAN: "ssdp:discover"\r\nMX: 1\r\nST: ssdp:all\r\n\r\n')


def _parse_ssrp(data: bytes):
    """SQL Server Browser (udp/1434) reply — a 0x05 token followed by
    ;-separated ServerName/InstanceName/Version/TCP pairs. The instance
    list names the machine outright."""
    out = {}
    try:
        if len(data) < 4 or data[0] not in (0x05, 0x04):
            return out
        txt = data[3:].rstrip(b';').decode('ascii', 'replace')
        parts = txt.split(';')
        kv = dict(zip(parts[0::2], parts[1::2]))
        out = {'name': kv.get('ServerName', ''),
               'instance': kv.get('InstanceName', ''),
               'version': kv.get('Version', ''),
               'tcp': kv.get('tcp', '')}
    except Exception:
        pass
    return out


def _eui64_decode(ip: str):
    """Decode an EUI-64 interface identifier — an IPv6 SLAAC address of
    the form <prefix>:XXXX:XXff:feXX:XXXX embeds the NIC's 48-bit MAC in
    its own bits (u/l bit flipped). The address literally IS the
    machine's hardware identity: it survives every address rotation and
    names the NIC vendor. Returns the MAC string or ''."""
    try:
        a = ipaddress.ip_address(ip)
        if a.version != 6:
            return ''
        b = a.packed
        iid = b[8:]
        if iid[3:5] != b'\xff\xfe':
            return ''
        mac = bytes([iid[0] ^ 0x02]) + iid[1:3] + iid[5:]
        return ':'.join(f'{x:02X}' for x in mac)
    except Exception:
        return ''


def _parse_sctp_addrs(data: bytes):
    """SCTP INIT / INIT-ACK multi-homing — the association's parameter
    list carries EVERY address the endpoint owns (IPv4 param 0x0005,
    IPv6 param 0x0006), each a self-reported alias of the same host.
    Bounded chunk+param walk; returns the embedded address list."""
    out = []
    try:
        if len(data) < 16:                     # 12B common hdr + chunk hdr
            return out
        off = 12
        for _ in range(6):                     # bounded chunk walk
            if off + 4 > len(data):
                break
            ctype, clen = data[off], int.from_bytes(data[off + 2:off + 4], 'big')
            if clen < 4 or off + clen > len(data):
                break
            if ctype in (1, 2):                # INIT / INIT-ACK
                poff = off + 4 + 16            # skip init-tag/window/etc
                for _ in range(24):
                    if poff + 4 > off + clen:
                        break
                    ptype = int.from_bytes(data[poff:poff + 2], 'big')
                    plen = int.from_bytes(data[poff + 2:poff + 4], 'big')
                    if plen < 4 or poff + plen > len(data):
                        break
                    pval = data[poff + 4:poff + plen]
                    try:
                        if ptype == 5 and len(pval) >= 4:
                            out.append(str(ipaddress.ip_address(pval[:4])))
                        elif ptype == 6 and len(pval) >= 16:
                            out.append(str(ipaddress.ip_address(pval[:16])))
                    except Exception:
                        pass
                    poff += plen + ((4 - plen % 4) % 4)
            off += clen + ((4 - clen % 4) % 4)
    except Exception:
        pass
    return list(dict.fromkeys(out))


def _tls_session_id(data: bytes, want_type: int = 2):
    """Extract the session_id from a TLS ClientHello (type 1) or
    ServerHello (type 2) record head. The id is CLEARTEXT by design —
    a resumption ticket echo: the same id surfaced from two different
    addresses means the two endpoints share one TLS session state —
    they are aliases of one service (server side) or one client
    (gateway/transit vantage). Returns the id bytes or b''."""
    try:
        if len(data) < 43 or data[0] != 0x16 or data[5] != want_type:
            return b''
        body = data[5:]
        hlen = int.from_bytes(body[1:4], 'big')
        if hlen + 4 > len(body) or hlen < 38:
            return b''
        sid_len = body[4 + 34]
        if sid_len < 8 or 4 + 34 + 1 + sid_len > len(body):
            return b''
        return body[4 + 35:4 + 35 + sid_len]
    except Exception:
        return b''


def _stun_bind_packet() -> bytes:
    """RFC 5389 Binding Request — one 20B datagram a TURN/STUN service
    answers with (XOR-)MAPPED-ADDRESS + optional SOFTWARE."""
    return (b'\x00\x01\x00\x00' + b'\x21\x12\xa4\x42' + os.urandom(12))


def _parse_stun_software(data: bytes):
    """Walk STUN TLVs for the SOFTWARE attribute (0x8022) — names the
    server stack (Coturn/rfc5766-turn-server, etc)."""
    try:
        if len(data) < 24 or data[4:8] != b'\x21\x12\xa4\x42':
            return ''
        off = 20
        for _ in range(40):
            if off + 4 > len(data):
                break
            atype = int.from_bytes(data[off:off + 2], 'big')
            alen = int.from_bytes(data[off + 2:off + 4], 'big')
            if off + 4 + alen > len(data):
                break
            if atype == 0x8022:
                return data[off + 4:off + 4 + alen].decode('utf-8', 'replace')[:60]
            off += 4 + alen + ((4 - alen % 4) % 4)
    except Exception:
        pass
    return ''


def _ike1_init_packet() -> bytes:
    """Minimal IKEv1 aggressive-mode initiator — older IPsec
    concentrators that ignore IKEv2 still answer v1, and the v1 reply
    carries the responder's ID payload (address/FQDN/USER_FQDN) in the
    clear: a self-declared identity on the mask itself."""
    spi = os.urandom(8)
    # IKEv1 transform: ENCR 3DES(5)/DES(1), HASH MD5(1)/SHA(2),
    # AUTH psk(1), GROUP 2 — attribute-form (0x8xxx) AF=1 pairs.
    def _attr(af, val):
        return struct.pack('!HH', 0x8000 | af, val)
    xforms = b''
    for enc, hsh in ((5, 1), (1, 2)):
        tf = (_attr(1, enc) + _attr(2, hsh) + _attr(3, 1) + _attr(4, 2)
              + _attr(11, 28800) + _attr(12, 0))
        xforms += struct.pack('!BBH', 3, 0, 8 + len(tf)) + tf
    prop = struct.pack('!BBHBBBB', 3, 0, 8 + len(xforms), 1, 1, 0, 0)
    sa = struct.pack('!BBH', 4, 0, 12 + len(prop)) + b'\x00' * 4 + prop
    ke = struct.pack('!BBH', 10, 0, 132) + os.urandom(128)
    nonce = struct.pack('!BBH', 5, 0, 24) + os.urandom(20)
    idp = struct.pack('!BBH', 0, 0, 12) + struct.pack('!BBH', 1, 0, 0) \
        + b'\x00' * 4
    body = sa + ke + nonce + idp
    return (struct.pack('!8s8sBBBBII', spi, b'\x00' * 8, 1, 0x10,
                        4, 0x04, 0, 28 + len(body)) + body)


def _parse_ike1_id(data: bytes):
    """Walk an IKEv1 reply's payload chain for the responder ID payload
    (type 5): IPV4_ADDR / FQDN / USER_FQDN / KEY_ID — the gateway's own
    declared identity, often a real hostname ('vpn.acme-corp.com')."""
    try:
        if len(data) < 28:
            return ''
        nxt = data[16]
        off = 28
        for _ in range(32):
            if off + 4 > len(data) or not nxt:
                break
            ptype = nxt
            nxt, _c, plen = struct.unpack('!BBH', data[off:off + 4])
            if plen < 4 or off + plen > len(data):
                break
            body = data[off + 4:off + plen]
            if ptype == 5 and len(body) >= 5:
                idt = body[0]
                val = body[4:]
                if idt == 1 and len(val) >= 4:
                    return '.'.join(str(b) for b in val[:4])
                if idt in (2, 3, 9, 10, 11):
                    s = val.decode('ascii', 'replace').strip('\x00')
                    if s:
                        return s[:80]
            off += plen
    except Exception:
        pass
    return ''


def _dhcpv6_duid_mac(data: bytes):
    """DHCPv6 client/server DUID (option 1/2) — DUID-LL (type 3) and
    DUID-LLT (type 1) embed the interface's MAC verbatim; DUID-EN (2)
    carries an enterprise number instead. The client's NIC identity in
    cleartext inside every lease message. Returns 'aa:bb:..' or ''."""
    try:
        if len(data) < 12:
            return ''
        off = 4                                     # msg-type(1)+txn(3)
        for _ in range(12):
            if off + 4 > len(data):
                break
            code = int.from_bytes(data[off:off + 2], 'big')
            ln = int.from_bytes(data[off + 2:off + 4], 'big')
            if off + 4 + ln > len(data):
                break
            body = data[off + 4:off + 4 + ln]
            if code in (1, 2) and ln >= 8:
                dtype = int.from_bytes(body[:2], 'big')
                if dtype == 1 and ln >= 10:
                    return ':'.join(f'{b:02X}' for b in body[8:14][:6])
                if dtype == 3 and ln >= 6:
                    return ':'.join(f'{b:02X}' for b in body[4:10][:6])
            off += 4 + ln
    except Exception:
        pass
    return ''


def _flow_cadence(ts_list):
    """Fixed-cadence flow detection — the encrypted channel's metronome.
    A flow emitting packets at a near-constant interval (keepalives,
    C2 heartbeat, tunnel NTT) is a machine-driven channel regardless
    of what the (unreadable) payload says. Returns (mean_s, count) or
    None. Requires ≥5 gaps inside 4..600s, CV ≤ 0.35."""
    try:
        ts = sorted(t for t in ts_list if t)
        if len(ts) < 6:
            return None
        gaps = [b - a for a, b in zip(ts, ts[1:])
                if 4.0 <= b - a <= 600.0]
        if len(gaps) < 5:
            return None
        mean = sum(gaps) / len(gaps)
        if mean <= 0:
            return None
        var = sum((g - mean) ** 2 for g in gaps) / len(gaps)
        if (var ** 0.5) / mean <= 0.35:
            return (mean, len(gaps) + 1)
    except Exception:
        pass
    return None


# Provider-published VPN exit feeds — the operators' OWN server lists.
# One fetch a day, disk-cached: a hit is definitive exit identity
# (provider + relay hostname + the exit's real city), the registry-
# class truth about which anonymizer this IP belongs to.
_EXIT_FEED_URLS = {
    'mullvad': 'https://api.mullvad.net/www/relays/all/',
    'nordvpn': 'https://api.nordvpn.com/v1/servers?limit=9000',
    'pia': 'https://serverlist.piaservers.net/vpninfo/servers/v6',
    'apple_relay': 'https://mask-api.icloud.com/egress-ip-ranges.csv',
}
_EXIT_FEED_TTL_S = 24 * 3600
_EXIT_FEED_FILE = 'medianbox_exitlists.json'
_exit_feed_cache = {'ts': 0, 'ips': {}, 'nets': [], 'starts': []}
_exit_feed_lock = threading.Lock()
_exit_feed_fetching = threading.Event()


def _apple_cidr_row(line: str):
    """Parse one Apple egress CSV row: 'CIDR,CC,REGION,CITY,'."""
    parts = line.split(',')
    if len(parts) < 4 or '/' not in parts[0]:
        return None
    try:
        net = ipaddress.ip_network(parts[0].strip())
        return (int(net.network_address), int(net.broadcast_address),
                parts[1].strip().upper(), parts[3].strip(),
                parts[2].strip())
    except Exception:
        return None


def _fetch_exit_feeds(force: bool = False):
    """Populate `_exit_feed_cache` from the provider-published lists +
    Apple Private Relay egress ranges. One fetch per _EXIT_FEED_TTL_S,
    disk-cached in _EXIT_FEED_FILE; a failure keeps the last good data
    and retries on the next TTL window."""
    now = time.time()
    if not force and _exit_feed_cache['ts'] \
            and now - _exit_feed_cache['ts'] < _EXIT_FEED_TTL_S:
        return
    if _exit_feed_fetching.is_set():
        return
    _exit_feed_fetching.set()
    try:
        blobs = {}

        def _get(name, url):
            try:
                req = urllib.request.Request(
                    url, headers={'User-Agent': 'boxmon-exitfeed/2'})
                blobs[name] = urllib.request.urlopen(req, timeout=20).read()
            except Exception:
                blobs[name] = None

        pool = [threading.Thread(target=_get, args=(n, u), daemon=True)
                for n, u in _EXIT_FEED_URLS.items()]
        for t in pool:
            t.start()
        for t in pool:
            t.join(22)
        ips: dict = {}
        nets: list = []
        # Mullvad — relays/all: [{hostname, country_code, city_name,
        #   ipv4_addr_in, type, provider, owned}]
        try:
            for r in json.loads(blobs['mullvad'] or b'[]'):
                ip = r.get('ipv4_addr_in') or ''
                if ip:
                    ips[ip] = {'provider': 'Mullvad VPN',
                               'kind': r.get('type') or 'vpn',
                               'host': r.get('hostname') or '',
                               'city': r.get('city_name') or '',
                               'cc': (r.get('country_code') or '').upper(),
                               'org': r.get('provider') or 'Mullvad'}
        except Exception:
            pass
        # NordVPN — v1/servers: [{name, station, hostname, locations[0]}]
        try:
            for r in json.loads(blobs['nordvpn'] or b'[]'):
                ip = r.get('station') or ''
                loc = (r.get('locations') or [{}])[0]
                cty = (loc.get('city') or {})
                ctry = (loc.get('country') or {})
                if ip and ipaddress.ip_address(ip).is_global:
                    ips[ip] = {'provider': 'NordVPN',
                               'kind': 'vpn', 'host': r.get('hostname') or '',
                               'city': cty.get('name') or '',
                               'cc': (ctry.get('code') or '').upper(),
                               'org': 'Nord Security'}
        except Exception:
            pass
        # PIA — v6 first line is JSON: {regions:{id:{name,country,
        #   servers:{proto:[{ip,cn}]}}}}
        try:
            first = (blobs['pia'] or b'').split(b'\n')[0]
            regions = json.loads(first).get('regions', {})
            for reg in regions.values():
                ctry = (reg.get('country') or '').upper()
                cname = reg.get('name') or ''
                for _proto, hosts in (reg.get('servers') or {}).items():
                    for h in (hosts or []):
                        ip = h.get('ip') or ''
                        if ip and ip not in ips:
                            ips[ip] = {'provider': 'Private Internet Access',
                                       'kind': 'vpn',
                                       'host': h.get('cn') or '',
                                       'city': cname,
                                       'cc': ctry, 'org': 'PIA'}
        except Exception:
            pass
        # Apple Private Relay egress ranges — CIDR,CC,REGION,CITY.
        # The relay deliberately picks an egress near the client, so a
        # hit localizes the USER's approximate region — the closest a
        # client-side tool gets to seeing through Apple's relay.
        try:
            rows = []
            for line in (blobs['apple_relay'] or b'').decode(
                    'utf-8', 'replace').splitlines():
                r = _apple_cidr_row(line)
                if r:
                    rows.append(r)
            nets = sorted(rows)            # by start int
        except Exception:
            pass
        if ips or nets:
            with _exit_feed_lock:
                _exit_feed_cache['ips'] = ips
                _exit_feed_cache['nets'] = nets
                _exit_feed_cache['starts'] = [n[0] for n in nets]
                _exit_feed_cache['ts'] = now
            try:
                _tmp = _EXIT_FEED_FILE + '.tmp'
                with open(_tmp, 'w', encoding='utf-8') as fh:
                    json.dump({'ts': now, 'ips': ips,
                               'nets': [list(n) for n in nets]}, fh)
                os.replace(_tmp, _EXIT_FEED_FILE)
            except Exception:
                pass
    finally:
        _exit_feed_fetching.clear()


def _exit_feed_load_disk():
    """Warm the feed cache from _EXIT_FEED_FILE when it is fresh enough —
    second-and-later runs cost zero network."""
    try:
        # Once memory is warm the disk copy cannot improve it — skip the
        # file entirely. The old order parsed ~30MB of JSON on every call
        # (twice per verify: _exit_job then _exit_lookup), and the GIL
        # burn starved every other probe thread under an 18-worker pool.
        if _exit_feed_cache['ts']:
            return
        # Parse under the lock too: N workers cold-starting together must
        # not each decode the ~30MB file — the first in warms the cache
        # and the rest fall through on the re-check.
        with _exit_feed_lock:
            if _exit_feed_cache['ts']:
                return
            if not os.path.exists(_EXIT_FEED_FILE):
                return
            st = json.load(open(_EXIT_FEED_FILE, encoding='utf-8'))
            if time.time() - st.get('ts', 0) >= _EXIT_FEED_TTL_S:
                return
            _exit_feed_cache['ips'] = st.get('ips') or {}
            _exit_feed_cache['nets'] = [tuple(n) for n in st.get('nets') or []]
            _exit_feed_cache['starts'] = [n[0] for n in _exit_feed_cache['nets']]
            _exit_feed_cache['ts'] = st.get('ts', 0)
    except Exception:
        pass


def _exit_lookup(ip: str):
    """Match an IP against the provider-published exit feeds + Apple
    relay ranges. Returns (exit-entry|None, apple-entry|None)."""
    _exit_feed_load_disk()
    ent = _exit_feed_cache['ips'].get(ip)
    apple = None
    if ':' not in ip:
        try:
            iv = int(ipaddress.ip_address(ip))
            nets = _exit_feed_cache['nets']
            starts = _exit_feed_cache['starts']
            if nets and starts:
                import bisect as _bs
                pos = _bs.bisect_right(starts, iv)
                for n in nets[max(0, pos - 3):pos]:
                    if n[0] <= iv <= n[1]:
                        apple = {'provider': 'Apple iCloud Private Relay',
                                 'kind': 'relay', 'cc': n[2],
                                 'city': n[3].title(),
                                 'region': n[4]}
                        break
        except Exception:
            pass
    return ent, apple


