def get_vendor(mac: str) -> str:
    if not mac:
        return "Unknown"
    if _HAS_MANUF:
        try:
            result = _PARSER.get_manuf(mac)
            if result:
                return result
        except Exception as exc:
            _logger.debug("manuf lookup failed for %s: %s", mac, exc)
    prefix = mac.upper().replace(':', '').replace('-', '')[:6]
    return _FALLBACK_OUI.get(prefix, "Unknown Vendor")


# ========================== DNS CACHE & TUNNEL DETECTOR ==========================
class DNSCache:
    """Thread-safe DNS resolution cache built from sniffed DNS responses."""
    def __init__(self):
        self.ip_to_domains: dict[str, set[str]] = defaultdict(set)
        self.domain_to_ips: dict[str, set[str]] = defaultdict(set)
        self.query_log: deque = deque(maxlen=5000)
        self.lock = threading.Lock()
        # Per-IP domain-set version — the inventory's per-conn refresh used
        # to lock+copy+sorted() the domain set EVERY scan even though DNS
        # mappings for a conn change ~never. dom_version() is a lock-free
        # dict read; a stale read just refreshes one scan late.
        self._dom_ver: dict[str, int] = {}
        self._dom_seq = 0
        # Whole-map change counters — the snapshot's recent_dns section is
        # rebuilt only when queries arrive (q_seq) or mappings change (map_seq).
        self.q_seq = 0
        self.map_seq = 0

    def _bump_dom(self, ip: str):
        """Call with self.lock held, after a domain was actually added."""
        self._dom_seq += 1
        self._dom_ver[ip] = self._dom_seq
        if len(self._dom_ver) > 120000:
            # Clear = one refresh round for live conns, then stable again.
            self._dom_ver.clear()

    def dom_version(self, ip: str) -> int:
        return self._dom_ver.get(ip, 0)

    _MAX_MAP_ENTRIES = 60000  # bound on ip_to_domains / domain_to_ips size

    def _bound_maps(self):
        """Cap the DNS maps — they grew for the whole session otherwise.
        Dicts are insertion-ordered, so the first quarter is the oldest data;
        hot names get re-added by the next response anyway.
        Call with self.lock held. Also the single funnel every map mutation
        flows through — bumping map_seq here versions ip_to_domains /
        domain_to_ips for snapshot caching."""
        self.map_seq += 1
        for d in (self.ip_to_domains, self.domain_to_ips):
            if len(d) > self._MAX_MAP_ENTRIES:
                for k in list(d)[: self._MAX_MAP_ENTRIES // 4]:
                    d.pop(k, None)

    def process_packet(self, pkt):
        if not pkt.haslayer(DNS):
            return
        dns_layer = pkt[DNS]
        if dns_layer.qr == 1 and dns_layer.ancount > 0:
            try:
                qname = dns_layer.qd.qname.decode(errors='ignore').rstrip('.')
                rr = dns_layer.an
                # Collect first, apply under ONE lock — an answer can carry
                # up to 30 RRs and taking the lock per record was 30
                # acquisitions per response.
                new_pairs = []
                for _ in range(min(dns_layer.ancount, 30)):
                    if rr is None:
                        break
                    if hasattr(rr, 'rdata'):
                        ip_str = str(rr.rdata)
                        try:
                            ipaddress.ip_address(ip_str)
                            new_pairs.append((ip_str, qname))
                        except ValueError:
                            pass
                    rr = rr.payload if hasattr(rr, 'payload') and rr.payload else None
                if new_pairs:
                    with self.lock:
                        for ip_str, qn in new_pairs:
                            _s = self.ip_to_domains[ip_str]
                            if qn not in _s:
                                _s.add(qn)
                                self._bump_dom(ip_str)
                            self.domain_to_ips[qn].add(ip_str)
                        self._bound_maps()
            except Exception as exc:
                _logger.debug("DNS response parse error: %s", exc)
        elif dns_layer.qr == 0:
            try:
                qname = dns_layer.qd.qname.decode(errors='ignore').rstrip('.')
                src = pkt[IP].src if pkt.haslayer(IP) else "?"
                with self.lock:
                    self.query_log.append((time.time(), src, qname))
                    self.q_seq += 1
            except Exception as exc:
                _logger.debug("DNS query parse error: %s", exc)

    def get_domains(self, ip: str) -> set[str]:
        with self.lock:
            doms = self.ip_to_domains.get(ip)
            if not doms:
                return set()
            return set(doms)

    def get_ips(self, domain: str) -> set[str]:
        with self.lock:
            return set(self.domain_to_ips.get(domain, set()))

    def ips_for(self, domains) -> dict:
        """domain -> sorted ips for many domains under ONE lock — the
        snapshot build used to lock once per query row (~200/build)."""
        with self.lock:
            return {d: sorted(self.domain_to_ips.get(d, ()))[:6]
                    for d in domains}

    def recent_queries(self, keyword: str = '', window: float = 120) -> list[tuple]:
        """Recent DNS queries, newest first. An empty keyword returns them all."""
        cutoff = time.time() - window
        kw = (keyword or '').lower()
        with self.lock:
            # query_log is time-ordered (append-only) — walk newest-first
            # and stop at the cutoff instead of scanning all 5000 rows.
            hits = []
            for t, s, d in reversed(self.query_log):
                if t <= cutoff:
                    break
                if not kw or kw in d.lower():
                    hits.append((t, s, d))
        return hits

    # --- Windows DNS client cache polling ---
    def poll_system_dns_cache(self):
        """Harvest IP→domain mappings from the Windows DNS client cache.
        Uses ipconfig /displaydns with CNAME chain tracking every poll, and
        PowerShell Get-DnsClientCache every 3rd — a PS process costs
        ~300-800ms of startup alone, and its extra records are also caught
        by the sniffed-DNS path anyway."""
        added = 0
        added += self._poll_ipconfig_displaydns()
        self._dns_poll_n = getattr(self, '_dns_poll_n', 0) + 1
        if self._dns_poll_n % 3 == 0:
            added += self._poll_powershell_dns_cache()
        if added:
            _logger.debug("DNS cache poll: added %d new IP→domain mappings total", added)

    def _add_domain_ip(self, ip_str: str, domain: str) -> bool:
        """Add a single IP→domain mapping. Returns True if new."""
        domain = domain.rstrip('.').lower()
        if not domain or not ip_str:
            return False
        with self.lock:
            if domain not in self.ip_to_domains.get(ip_str, set()):
                self.ip_to_domains[ip_str].add(domain)
                self.domain_to_ips[domain].add(ip_str)
                self._bump_dom(ip_str)
                self._bound_maps()
                return True
        return False

    def _poll_ipconfig_displaydns(self) -> int:
        """Parse 'ipconfig /displaydns' with CNAME chain resolution."""
        try:
            result = subprocess.run(
                ['ipconfig', '/displaydns'],
                capture_output=True, text=True, timeout=10,
                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
            )
            if result.returncode != 0:
                return 0
            # Pass 1: collect all record names → A/AAAA IPs and CNAME targets
            current_name = None
            a_records = {}      # record_name → set of IPs
            cname_map = {}      # cname_target → set of original names that point to it
            for line in result.stdout.splitlines():
                stripped = line.strip()
                if stripped.startswith('Record Name'):
                    parts = stripped.split(':', 1)
                    if len(parts) == 2:
                        current_name = parts[1].strip().rstrip('.').lower()
                elif current_name:
                    if 'A (Host) Record' in stripped or 'AAAA' in stripped:
                        parts = stripped.split(':', 1)
                        if len(parts) == 2:
                            ip_str = parts[1].strip()
                            try:
                                ipaddress.ip_address(ip_str)
                                a_records.setdefault(current_name, set()).add(ip_str)
                            except ValueError:
                                pass
                    elif 'CNAME Record' in stripped:
                        parts = stripped.split(':', 1)
                        if len(parts) == 2:
                            target = parts[1].strip().rstrip('.').lower()
                            cname_map.setdefault(target, set()).add(current_name)
            # Pass 2: for each A record, follow CNAME chains back to original names
            added = 0
            for record_name, ips in a_records.items():
                # Collect all names that resolve to these IPs (including CNAME sources)
                all_names = {record_name}
                queue = [record_name]
                visited = set()
                while queue:
                    name = queue.pop()
                    if name in visited:
                        continue
                    visited.add(name)
                    # Find names that CNAME to this name
                    for source in cname_map.get(name, set()):
                        all_names.add(source)
                        queue.append(source)
                for ip_str in ips:
                    for name in all_names:
                        if self._add_domain_ip(ip_str, name):
                            added += 1
            return added
        except Exception as exc:
            _logger.debug("ipconfig /displaydns parse error: %s", exc)
            return 0

    def _poll_powershell_dns_cache(self) -> int:
        """Use PowerShell Get-DnsClientCache for richer DNS data with original query names."""
        try:
            cmd = (
                'Get-DnsClientCache -Status Success -ErrorAction SilentlyContinue '
                '| Where-Object { $_.Type -in 1,28 } '
                '| Select-Object -Property Entry,Data '
                '| Format-Table -HideTableHeaders -AutoSize'
            )
            result = subprocess.run(
                ['powershell', '-NoProfile', '-NonInteractive', '-Command', cmd],
                capture_output=True, text=True, timeout=15,
                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
            )
            if result.returncode != 0:
                return 0
            added = 0
            for line in result.stdout.splitlines():
                parts = line.split()
                if len(parts) >= 2:
                    entry = parts[0].strip().rstrip('.').lower()
                    ip_str = parts[-1].strip()
                    try:
                        ipaddress.ip_address(ip_str)
                        if self._add_domain_ip(ip_str, entry):
                            added += 1
                    except ValueError:
                        pass
            return added
        except Exception as exc:
            _logger.debug("PowerShell DNS cache error: %s", exc)
            return 0

    # --- Persistent domain history ---
    _HISTORY_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), '.dns_domain_history.json')

    def save_history(self):
        """Persist all IP→domain mappings to disk so they survive restarts."""
        try:
            with self.lock:
                data = {ip: sorted(doms) for ip, doms in self.ip_to_domains.items() if doms}
            with open(self._HISTORY_FILE, 'w', encoding='utf-8') as f:
                json.dump(data, f)
        except Exception as exc:
            _logger.debug("DNS history save error: %s", exc)

    def load_history(self):
        """Load persisted IP→domain mappings from a previous session."""
        try:
            if not os.path.exists(self._HISTORY_FILE):
                return
            with open(self._HISTORY_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
            added = 0
            with self.lock:
                for ip, doms in data.items():
                    for d in doms:
                        if d not in self.ip_to_domains.get(ip, set()):
                            self.ip_to_domains[ip].add(d)
                            self.domain_to_ips[d].add(ip)
                            self._bump_dom(ip)
                            added += 1
                self._bound_maps()
            if added:
                _logger.debug("DNS history: loaded %d IP→domain mappings from disk", added)
        except Exception as exc:
            _logger.debug("DNS history load error: %s", exc)


class DNSTunnelingDetector:
    """Detects data exfiltration via DNS queries (long subdomains, high entropy, high rate)."""
    def __init__(self):
        self.domain_query_counts: dict[str, deque] = defaultdict(lambda: deque(maxlen=200))
        self.lock = threading.Lock()

    @staticmethod
    def shannon_entropy(s: str) -> float:
        if not s:
            return 0.0
        freq = Counter(s)
        length = len(s)
        return -sum((c / length) * math.log2(c / length) for c in freq.values())

    def analyze_query(self, qname: str) -> tuple[bool, float, list[str]]:
        evidence = []
        score = 0.0
        parts = qname.split('.')
        if len(parts) < 2:
            return False, 0, []
        base_domain = '.'.join(parts[-2:])
        subdomain = '.'.join(parts[:-2])
        max_label = max((len(p) for p in parts[:-2]), default=0)
        if max_label > CONFIG['dns_tunnel_max_label_len']:
            evidence.append(f"Very long subdomain label: {max_label} chars")
            score += 25
        if subdomain:
            ent = self.shannon_entropy(subdomain.replace('.', ''))
            if ent > CONFIG['dns_tunnel_entropy_threshold']:
                evidence.append(f"High subdomain entropy: {ent:.2f} bits")
                score += 25
        now = time.time()
        with self.lock:
            counts = self.domain_query_counts
            if len(counts) > 50000:
                for k in list(counts)[:12500]:  # oldest quarter (insertion order)
                    counts.pop(k, None)
            counts[base_domain].append(now)
            recent = sum(1 for t in counts[base_domain] if now - t < 60)
        if recent > CONFIG['dns_tunnel_query_rate_threshold']:
            evidence.append(f"High query rate: {recent}/min to {base_domain}")
            score += 25
        if len(evidence) >= 2:
            score += 15
            evidence.append("Multiple indicators — high confidence DNS tunneling")
        return score >= 25, score, evidence


# ========================== NETWORK DETECTORS ==========================
class BeaconDetector:
    """Catches C2 beaconing via inter-packet timing regularity analysis."""
    @staticmethod
    def analyze(timestamps) -> tuple[bool, float, str]:
        if len(timestamps) < CONFIG['beacon_min_samples']:
            return False, 0.0, ""
        ts = sorted(timestamps)
        intervals = [ts[i+1] - ts[i] for i in range(len(ts)-1)]
        if not intervals:
            return False, 0.0, ""
        mean_iv = statistics.mean(intervals)
        if mean_iv < 0.5:
            return False, 0.0, ""
        try:
            stdev_iv = statistics.stdev(intervals)
            cv = stdev_iv / mean_iv if mean_iv > 0 else float('inf')
        except statistics.StatisticsError:
            return False, 0.0, ""
        if cv < 0.12 and mean_iv > 2:
            conf = min(1.0, (0.12 - cv) / 0.12 + 0.5)
            return True, conf, f"Fixed beacon: {mean_iv:.1f}s +/-{stdev_iv:.2f}s jitter={cv:.3f}"
        if cv < 0.25 and mean_iv > 5 and len(intervals) > 40:
            conf = min(0.85, (0.25 - cv) / 0.25 + 0.3)
            return True, conf, f"Periodic callback: ~{mean_iv:.1f}s jitter={cv:.3f}"
        if len(intervals) > 30:
            median_iv = statistics.median(intervals)
            if median_iv > 3:
                within = sum(1 for i in intervals if abs(i - median_iv) < median_iv * 0.15)
                ratio = within / len(intervals)
                if ratio > 0.65:
                    return True, ratio * 0.75, f"Clustered: ~{median_iv:.1f}s {ratio:.0%} consistent"
        return False, 0.0, ""


class SNIExtractor:
    """Extracts Server Name Indication from TLS ClientHello, plus the
    encrypted-ClientHello (ECH) marker — extension 0xfe0d means the REAL
    service name is encrypted inside the handshake and the visible SNI is
    a decoy cover name: the "server mask" that hides which backend of a
    CDN actually answers."""
    @staticmethod
    def inspect(pkt) -> Optional[dict]:
        """Parse a TLS ClientHello once → {'sni': str|None, 'ech': bool}
        or None when the packet is not a ClientHello."""
        if not (pkt.haslayer(TCP) and pkt.haslayer(Raw)):
            return None
        try:
            data = pkt[Raw].load
            if not isinstance(data, bytes):
                data = bytes(data)
            if len(data) < 6 or data[0] != 0x16:
                return None
            hs_data = data[5:]
            if len(hs_data) < 4 or hs_data[0] != 0x01:
                return None
            ch_len = int.from_bytes(hs_data[1:4], 'big')
            ch = hs_data[4:4+ch_len]
            if len(ch) < 38:
                return None
            offset = 34
            sess_id_len = ch[offset]
            offset += 1 + sess_id_len
            if offset + 2 > len(ch):
                return None
            cipher_len = int.from_bytes(ch[offset:offset+2], 'big')
            offset += 2 + cipher_len
            if offset >= len(ch):
                return None
            comp_len = ch[offset]
            offset += 1 + comp_len
            if offset + 2 > len(ch):
                return None
            ext_total = int.from_bytes(ch[offset:offset+2], 'big')
            offset += 2
            end = min(offset + ext_total, len(ch))
            sni, ech = None, False
            while offset + 4 < end:
                ext_type = int.from_bytes(ch[offset:offset+2], 'big')
                ext_len = int.from_bytes(ch[offset+2:offset+4], 'big')
                offset += 4
                if ext_type == 0x0000:
                    sni_data = ch[offset:offset+ext_len]
                    if len(sni_data) >= 5:
                        name_len = int.from_bytes(sni_data[3:5], 'big')
                        if len(sni_data) >= 5 + name_len:
                            sni = sni_data[5:5+name_len].decode(
                                'ascii', errors='ignore')
                elif ext_type == 0xFE0D:
                    ech = True
                offset += ext_len
            return {'sni': sni, 'ech': ech}
        except Exception as exc:
            _logger.debug("SNI extraction error: %s", exc)
        return None

    @staticmethod
    def extract(pkt) -> Optional[str]:
        r = SNIExtractor.inspect(pkt)
        return (r or {}).get('sni')


# Ports that are expected to carry encrypted (high-entropy) payloads — the
# entropy screen skips these both before and inside is_suspicious().
_TLS_PAYLOAD_PORTS = frozenset({443, 8443, 993, 995, 465, 636})


class EntropyAnalyzer:
    """Shannon entropy analysis on packet payloads to detect encrypted C2."""
    @staticmethod
    def payload_entropy(data: bytes) -> float:
        if not data:
            return 0.0
        freq = Counter(data)
        length = len(data)
        return -sum((c / length) * math.log2(c / length) for c in freq.values())

    @staticmethod
    def is_suspicious(pkt, entropy_val: float) -> tuple[bool, str]:
        sport = pkt[TCP].sport if pkt.haslayer(TCP) else (pkt[UDP].sport if pkt.haslayer(UDP) else 0)
        dport = pkt[TCP].dport if pkt.haslayer(TCP) else (pkt[UDP].dport if pkt.haslayer(UDP) else 0)
        if dport in _TLS_PAYLOAD_PORTS or sport in _TLS_PAYLOAD_PORTS:
            return False, ""
        if entropy_val > CONFIG['entropy_suspicious_threshold']:
            return True, (f"High entropy {entropy_val:.2f} on non-TLS port "
                          f"(sport={sport} dport={dport}) — possible encrypted C2")
        return False, ""


# ========================== PROCESS DETECTORS ==========================
class ProcessLegitimacyChecker:
    """Detects impersonation by verifying exe path and parent chain."""
    @staticmethod
    def check_path(name: str, exe_path: str) -> tuple[bool, str]:
        name_l = name.lower()
        exe_l = (exe_path or "").lower()
        if name_l in EXPECTED_EXE_PATHS and exe_l and not any(f in exe_l for f in EXPECTED_EXE_PATHS[name_l]):
            return True, f"'{name}' at unexpected path: {exe_path}"
        return False, ""

    @staticmethod
    def check_parent(name: str, parent_name: str) -> tuple[bool, str]:
        name_l = name.lower()
        parent_l = (parent_name or "").lower()
        if name_l in EXPECTED_PARENTS:
            expected = EXPECTED_PARENTS[name_l]
            if parent_l and parent_l not in expected:
                return True, f"'{name}' has unexpected parent '{parent_name}' (expected: {expected})"
        return False, ""

    @staticmethod
    def check_all(proc) -> list[str]:
        reasons = []
        try:
            name = proc.name()
            exe = proc.exe() or ""
            sus, msg = ProcessLegitimacyChecker.check_path(name, exe)
            if sus:
                reasons.append(msg)
            try:
                parent = psutil.Process(proc.ppid())
                sus2, msg2 = ProcessLegitimacyChecker.check_parent(name, parent.name())
                if sus2:
                    reasons.append(msg2)
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
            if name.lower() in ("svchost.exe", "csrss.exe", "lsass.exe", "services.exe",
                                "smss.exe", "winlogon.exe", "wininit.exe"):
                if exe and "system32" not in exe.lower() and "syswow64" not in exe.lower():
                    reasons.append(f"SYSTEM IMPERSONATION: '{name}' at '{exe}' — NOT in System32")
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
        return reasons


class DLLInspector:
    """Checks loaded modules per process for suspicious DLL paths."""
    @staticmethod
    def inspect(proc) -> list[str]:
        suspicious = []
        if not _IS_WINDOWS:
            return suspicious
        try:
            for mmap in proc.memory_maps(grouped=False):
                path_lower = (mmap.path or "").lower()
                if not path_lower or not _is_image_path(path_lower):
                    continue  # mapped data file, not a loaded module
                if _progdata_safe(path_lower):
                    continue  # OS vendor component under ProgramData
                if any(frag in path_lower for frag in SUSPICIOUS_DLL_PATHS):
                    suspicious.append(mmap.path)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
        except Exception as exc:
            _logger.debug("DLL inspection error for %s: %s", proc, exc)
        return suspicious


# ========================== SYSTEM DETECTORS ==========================
class RegistryMonitor:
    """Monitors Windows Run keys and scheduled tasks for persistence changes."""
    def __init__(self):
        self.baseline: dict[str, str] = {}
        self.lock = threading.Lock()

    def scan(self) -> list[tuple[str, str, str]]:
        if not _IS_WINDOWS:
            return []
        changes = []
        current = {}
        for hive, key_path in PERSISTENCE_KEYS:
            try:
                with winreg.OpenKey(hive, key_path, 0, winreg.KEY_READ) as key:
                    i = 0
                    while True:
                        try:
                            name, value, _ = winreg.EnumValue(key, i)
                            full_key = f"{key_path}\\{name}"
                            current[full_key] = str(value)
                            i += 1
                        except OSError:
                            break
            except OSError as exc:
                _logger.debug("Registry scan error for %s: %s", key_path, exc)
        with self.lock:
            if self.baseline:
                for k, v in current.items():
                    if k not in self.baseline:
                        changes.append(("ADDED", k, v))
                    elif self.baseline[k] != v:
                        changes.append(("MODIFIED", k, v))
                for k in self.baseline:
                    if k not in current:
                        changes.append(("REMOVED", k, self.baseline[k]))
            self.baseline = current
        return changes


class UserIdleMonitor:
    """Tracks user idle time via Windows GetLastInputInfo."""
    @staticmethod
    def get_idle_seconds() -> float:
        if not _IS_WINDOWS:
            return 0.0
        try:
            class LASTINPUTINFO(ctypes.Structure):
                _fields_ = [("cbSize", ctypes.c_uint), ("dwTime", ctypes.c_uint)]
            ctypes.windll.user32.GetLastInputInfo.argtypes = [ctypes.c_void_p]
            ctypes.windll.user32.GetLastInputInfo.restype = ctypes.wintypes.BOOL
            ctypes.windll.kernel32.GetTickCount.argtypes = []
            ctypes.windll.kernel32.GetTickCount.restype = ctypes.wintypes.DWORD
            lii = LASTINPUTINFO()
            lii.cbSize = ctypes.sizeof(LASTINPUTINFO)
            if ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lii)):
                millis = ctypes.windll.kernel32.GetTickCount() - lii.dwTime
                return millis / 1000.0
        except Exception as exc:
            _logger.debug("GetLastInputInfo failed: %s", exc)
        return 0.0


# ========================== STATISTICAL BASELINE ==========================
class StatisticalBaseline:
    """Z-score anomaly detection per process name on key behavioral metrics."""
    def __init__(self):
        self.models: dict[str, dict] = defaultdict(lambda: {
            'conn_rate': deque(maxlen=500),
            'dst_count': deque(maxlen=500),
            'bytes_rate': deque(maxlen=500),
            'cpu_mean': deque(maxlen=500),
            'ts': deque(maxlen=500),
        })
        self.lock = threading.Lock()

    # Absolute-deviation floors — a z-score only counts when the raw
    # delta is also material (3 conn/s, 3 dsts, 50 KB/s, 5% CPU).
    _ML_ABS_FLOOR = {'conn_rate': 3.0, 'dst_count': 3.0,
                     'bytes_rate': 50_000.0, 'cpu_mean': 5.0}

    def record(self, proc_name: str, conn_rate: float, dst_count: int,
               bytes_rate: float, cpu_mean: float):
        now = time.time()
        with self.lock:
            m = self.models[proc_name]
            m['conn_rate'].append(conn_rate)
            m['dst_count'].append(dst_count)
            m['bytes_rate'].append(bytes_rate)
            m['cpu_mean'].append(cpu_mean)
            m['ts'].append(now)
            # Age out anything older than ml_baseline_window so a baseline
            # tracks recent behaviour rather than the whole session.
            window = CONFIG.get('ml_baseline_window', 86400)
            cutoff = now - window
            while m['ts'] and m['ts'][0] < cutoff:
                m['ts'].popleft()
                for key in ('conn_rate', 'dst_count', 'bytes_rate', 'cpu_mean'):
                    if m[key]:
                        m[key].popleft()

    def score(self, proc_name: str, conn_rate: float, dst_count: int,
              bytes_rate: float, cpu_mean: float) -> tuple[float, list[str]]:
        anomalies = []
        total_z = 0.0
        # Honour the configured warm-up length instead of a hardcoded 30/10.
        min_samples = max(5, int(CONFIG.get('baseline_min_samples', 50)))
        with self.lock:
            m = self.models.get(proc_name)
            if not m or len(m['conn_rate']) < min_samples:
                return 0.0, []
            for metric_name, current_val in [('conn_rate', conn_rate), ('dst_count', dst_count),
                                              ('bytes_rate', bytes_rate), ('cpu_mean', cpu_mean)]:
                samples = list(m[metric_name])
                if len(samples) < min_samples:
                    continue
                mean = statistics.mean(samples)
                try:
                    std = statistics.stdev(samples)
                except statistics.StatisticsError:
                    continue
                if std < 0.001:
                    continue
                delta = abs(current_val - mean)
                # Absolute noise floor — a z-score is only meaningful
                # when the raw deviation is too. A daemon idling at
                # ~0% CPU / ~0 B/s otherwise earns CRITICAL z-scores
                # from rounding noise (std≈0 → z explodes).
                if delta < self._ML_ABS_FLOOR.get(metric_name, 0.0):
                    continue
                z = delta / std
                if z > CONFIG['ml_zscore_threshold']:
                    anomalies.append(f"{metric_name}: z={z:.1f} (val={current_val:.1f} mean={mean:.1f} std={std:.1f})")
                    total_z += z
        score = min(100, total_z * 10)
        return score, anomalies

    _PERSIST_KEYS = ('conn_rate', 'dst_count', 'bytes_rate', 'cpu_mean', 'ts')

    def save(self, path: str) -> bool:
        """Persist learned baselines so a restart does not start cold."""
        try:
            with self.lock:
                data = {name: {k: list(m[k]) for k in self._PERSIST_KEYS}
                        for name, m in self.models.items() if m['ts']}
            tmp = path + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump({'version': 1, 'saved': time.time(), 'models': data}, f)
            os.replace(tmp, path)
            return True
        except Exception as exc:
            _logger.debug("Baseline save failed: %s", exc)
            return False

    def load(self, path: str) -> int:
        """Load a saved baseline, dropping samples older than the window.
        Returns the number of process models restored."""
        try:
            with open(path, encoding='utf-8') as f:
                blob = json.load(f)
        except (OSError, ValueError):
            return 0
        cutoff = time.time() - CONFIG.get('ml_baseline_window', 86400)
        restored = 0
        with self.lock:
            for name, m in (blob.get('models') or {}).items():
                try:
                    ts = m['ts']
                    cols = {k: m[k] for k in self._PERSIST_KEYS}
                    if any(len(cols[k]) != len(ts) for k in cols):
                        continue
                    model = self.models[name]
                    for i, t in enumerate(ts):
                        if t >= cutoff:
                            for k in self._PERSIST_KEYS:
                                model[k].append(float(cols[k][i]))
                    restored += 1 if model['ts'] else 0
                except (KeyError, TypeError, ValueError):
                    continue
        return restored

    def start_autosave(self, path: str, stop_event: threading.Event,
                       interval: float = 300.0) -> None:
        def _loop():
            while not stop_event.wait(interval):
                self.save(path)
            self.save(path)
        threading.Thread(target=_loop, daemon=True, name="Baseline-Save").start()


# ========================== JA4+ FINGERPRINTING ==========================
class JA4Plus:
    """Extended JA4 — JA4S (ServerHello), JA4H (HTTP), JA4X (X.509 cert)."""
    @staticmethod
    def ja4(pkt) -> Optional[str]:
        if not (pkt.haslayer(TCP) and pkt.haslayer(Raw)):
            return None
        try:
            data = bytes(pkt[Raw])
            if len(data) < 9 or data[0] != 0x16:
                return None
            handshake = data[5:]
            if len(handshake) < 4 or handshake[0] != 0x01:
                return None
            ch = handshake[4:]
            if len(ch) < 38:
                return None
            tls_ver = f"t{ch[0]:02x}{ch[1]:02x}"
            sess_id_len = ch[34]
            offset = 35 + sess_id_len
            cipher_len = int.from_bytes(ch[offset:offset+2], 'big')
            offset += 2 + cipher_len
            comp_len = ch[offset]
            offset += 1 + comp_len
            ext_len = int.from_bytes(ch[offset:offset+2], 'big')
            alpn = "h2" if b'\x00\x10' in data else "http1"
            return f"{tls_ver}d{cipher_len//2:02d}{ext_len//4:02d}_{alpn}"
        except Exception as exc:
            _logger.debug("JA4 fingerprint error: %s", exc)
            return None

    @staticmethod
    def ja4s(pkt) -> Optional[str]:
        if not (pkt.haslayer(TCP) and pkt.haslayer(Raw)):
            return None
        try:
            data = pkt[Raw].load
            if not isinstance(data, bytes):
                data = bytes(data)
            if len(data) < 6 or data[0] != 0x16:
                return None
            hs = data[5:]
            if len(hs) < 4 or hs[0] != 0x02:
                return None
            sh = hs[4:]
            if len(sh) < 38:
                return None
            ver = f"s{sh[0]:02x}{sh[1]:02x}"
            cipher = int.from_bytes(sh[35:37], 'big')
            return f"{ver}c{cipher:04x}"
        except Exception as exc:
            _logger.debug("JA4S parse error: %s", exc)
            return None

    @staticmethod
    def ja4h(pkt) -> Optional[str]:
        if not pkt.haslayer(Raw):
            return None
        try:
            data = pkt[Raw].load
            if not isinstance(data, bytes):
                data = bytes(data)
            # Byte-level method prefix first — decoding every payload to str
            # just to throw ~all of them away was the per-packet hot spot.
            if not data.startswith(
                    (b'GET ', b'POST ', b'PUT ', b'DELETE ', b'PATCH ', b'HEAD ')):
                return None
            text = data.decode('ascii', errors='ignore')
            lines = text.split('\r\n')
            method = lines[0].split(' ')[0]
            headers = []
            for line in lines[1:]:
                if ':' in line:
                    headers.append(line.split(':')[0].strip().lower())
                elif line == '':
                    break
            h_hash = hashlib.sha256(','.join(headers).encode()).hexdigest()[:12]
            return f"h_{method}_{len(headers):02d}_{h_hash}"
        except Exception as exc:
            _logger.debug("JA4H parse error: %s", exc)
            return None

    @staticmethod
    def ja4x(cert_data: bytes) -> Optional[str]:
        try:
            h = hashlib.sha256(cert_data).hexdigest()[:16]
            return f"x_{h}"
        except Exception as exc:
            _logger.debug("JA4X hash error: %s", exc)
            return None


# ========================== VIRUSTOTAL INTEGRATION ==========================
class VirusTotalChecker:
    """Check executable hashes against VirusTotal API (free tier: 4 req/min)."""
    _VT_URL = "https://www.virustotal.com/api/v3/files/{hash}"

    def __init__(self, api_key: str = ""):
        self.api_key = api_key or os.environ.get('VT_API_KEY', '')
        self.cache: dict[str, dict] = {}  # sha256 -> result
        self.lock = threading.Lock()
        self._rate_bucket = TokenBucket(rate=4.0, capacity=4.0)
        self._checked_pids: set[int] = set()
        # Hash+API work used to run synchronously on the watcher thread —
        # a full exe read plus a 10s-timeout HTTP call per new process.
        # Now the watcher just enqueues; results surface via _done on the
        # next scan (~0.5s later, same flag path).
        self._queue: deque = deque(maxlen=500)
        self._done: dict[int, dict] = {}
        self._worker: Optional[threading.Thread] = None

    def _hash_file(self, filepath: str) -> Optional[str]:
        try:
            h = hashlib.sha256()
            with open(filepath, 'rb') as f:
                for chunk in iter(lambda: f.read(65536), b''):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return None

    def _ensure_worker(self):
        if self._worker is None:
            self._worker = threading.Thread(
                target=self._work, daemon=True, name="VT-Checker")
            self._worker.start()

    def _work(self):
        while True:
            with self.lock:
                item = self._queue.popleft() if self._queue else None
            if item is None:
                time.sleep(0.5)
                continue
            pid, exe_path = item
            result = self._lookup(exe_path)
            if result is not None:
                with self.lock:
                    self._done[pid] = result
                    # The watcher pops results; a dead pid would strand one —
                    # keep the map from growing past queued depth anyway.
                    if len(self._done) > 2000:
                        for k in list(self._done)[:1000]:
                            self._done.pop(k, None)

    def check_exe(self, pid: int, exe_path: str) -> Optional[dict]:
        if not self.api_key or not exe_path:
            return None
        # dict.pop / `in` on a set are atomic under the GIL — the two common
        # exits (result ready, already-queued) don't need the lock, which
        # otherwise cost an acquisition per proc per scan.
        r = self._done.pop(pid, None)
        if r is not None:
            return r
        if pid in self._checked_pids:
            return None
        with self.lock:
            if pid in self._checked_pids:
                return None
            if len(self._checked_pids) > 20000:
                self._checked_pids.clear()
            self._checked_pids.add(pid)
            self._queue.append((pid, exe_path))
        self._ensure_worker()
        return None

    def _lookup(self, exe_path: str) -> Optional[dict]:
        sha256 = self._hash_file(exe_path)
        if not sha256:
            return None
        with self.lock:
            if sha256 in self.cache:
                return self.cache[sha256]
        if not self._rate_bucket.consume():
            # Rate limit hit — requeue-free: the pid stays in _checked_pids
            # but the sha gets no cache entry; acceptable (4/min quota).
            return None
        try:
            req = urllib.request.Request(
                self._VT_URL.format(hash=sha256),
                headers={'x-apikey': self.api_key, 'Accept': 'application/json'})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read())
            stats = data.get('data', {}).get('attributes', {}).get('last_analysis_stats', {})
            result = {
                'sha256': sha256, 'malicious': stats.get('malicious', 0),
                'suspicious': stats.get('suspicious', 0),
                'undetected': stats.get('undetected', 0),
                'harmless': stats.get('harmless', 0),
                'name': data.get('data', {}).get('attributes', {}).get('meaningful_name', ''),
            }
            with self.lock:
                self.cache[sha256] = result
            return result
        except urllib.error.HTTPError as e:
            if e.code == 404:
                result = {'sha256': sha256, 'malicious': 0, 'suspicious': 0,
                          'undetected': 0, 'harmless': 0, 'name': 'NOT IN VT DB'}
                with self.lock:
                    self.cache[sha256] = result
                return result
            return None
        except Exception:
            return None

    def get_all_results(self) -> dict:
        with self.lock:
            return dict(self.cache)


# ========================== FILE SYSTEM WATCHDOG ==========================
class FileSystemWatchdog:
    """Monitor sensitive directories for suspicious file changes (ransomware, staging)."""
    RANSOMWARE_EXTS = {'.encrypted', '.locked', '.crypto', '.crypt', '.enc', '.pay',
                       '.ransom', '.locky', '.cerber', '.zepto', '.odin', '.thor',
                       '.aesir', '.zzzzz', '.micro', '.xxx'}

    def __init__(self):
        self.lock = threading.Lock()
        self._baseline: dict[str, dict] = {}  # path -> {mtime, size}
        self._events: deque = deque(maxlen=5000)
        self._dirs_to_watch: list[str] = []
        home = os.path.expanduser("~")
        for d in ['Desktop', 'Documents', 'Downloads', 'AppData\\Local\\Temp']:
            p = os.path.join(home, d)
            if os.path.isdir(p):
                self._dirs_to_watch.append(p)
        self._baseline_set = False
        self._rename_counter: dict[str, int] = defaultdict(int)  # dir -> rename count in window
        self._rename_window_start: float = time.time()

    def scan(self) -> list[dict]:
        events = []
        current: dict[str, dict] = {}
        now = time.time()
        # Reset rename window every 60s
        if now - self._rename_window_start > 60:
            self._rename_counter.clear()
            self._rename_window_start = now
        for watch_dir in self._dirs_to_watch:
            try:
                for entry in os.scandir(watch_dir):
                    if not entry.is_file(follow_symlinks=False):
                        continue
                    try:
                        st = entry.stat()
                        current[entry.path] = {'mtime': st.st_mtime, 'size': st.st_size}
                    except Exception:
                        continue
                    _, ext = os.path.splitext(entry.name)
                    if ext.lower() in self.RANSOMWARE_EXTS:
                        events.append({
                            'type': 'RANSOMWARE_EXT', 'path': entry.path,
                            'time': now, 'severity': 'CRITICAL',
                            'detail': f"Suspicious extension: {ext}"})
            except Exception:
                continue
        if self._baseline_set:
            for path, info in current.items():
                if path not in self._baseline:
                    events.append({'type': 'FILE_CREATED', 'path': path,
                                   'time': now, 'severity': 'INFO',
                                   'detail': f"New file: {os.path.basename(path)} ({info['size']} bytes)"})
                    d = os.path.dirname(path)
                    self._rename_counter[d] = self._rename_counter.get(d, 0) + 1
                elif self._baseline[path]['mtime'] != info['mtime']:
                    events.append({'type': 'FILE_MODIFIED', 'path': path,
                                   'time': now, 'severity': 'INFO',
                                   'detail': f"Modified: {os.path.basename(path)}"})
            for path in self._baseline:
                if path not in current:
                    # A single delete is routine churn (browser partials,
                    # temp files) — INFO. The rename_counter below still
                    # escalates a BURST of deletes to WARNING, which is
                    # the actual ransomware/mass-wipe signal.
                    events.append({'type': 'FILE_DELETED', 'path': path,
                                   'time': now, 'severity': 'INFO',
                                   'detail': f"Deleted: {os.path.basename(path)}"})
                    d = os.path.dirname(path)
                    self._rename_counter[d] = self._rename_counter.get(d, 0) + 1
            # Mass rename detection (ransomware pattern)
            for d, count in self._rename_counter.items():
                if count > 20:
                    events.append({'type': 'MASS_RENAME', 'path': d,
                                   'time': now, 'severity': 'CRITICAL',
                                   'detail': f"Mass file changes in {d}: {count} files in 60s"})
        with self.lock:
            self._baseline = current
            if not self._baseline_set:
                self._baseline_set = True
            for ev in events:
                self._events.append(ev)
        return events

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== CLIPBOARD MONITOR ==========================
class ClipboardMonitor:
    """Watch for clipboard hijacking (crypto address swaps, data theft)."""
    _CRYPTO_PATTERNS = {
        'BTC': re.compile(r'^(bc1|[13])[a-zA-HJ-NP-Z0-9]{25,62}$'),
        'ETH': re.compile(r'^0x[0-9a-fA-F]{40}$'),
        'XMR': re.compile(r'^4[0-9AB][1-9A-HJ-NP-Za-km-z]{93}$'),
    }

    def __init__(self):
        self.lock = threading.Lock()
        self._last_content: str = ""
        self._events: deque = deque(maxlen=1000)
        self._change_count: int = 0
        self._window_start: float = time.time()

    def check(self) -> list[dict]:
        if not _IS_WINDOWS:
            return []
        events = []
        now = time.time()
        if now - self._window_start > 60:
            if self._change_count > 50:
                events.append({'type': 'RAPID_CLIPBOARD', 'time': now,
                               'severity': 'WARNING',
                               'detail': f"Clipboard changed {self._change_count} times in 60s"})
            self._change_count = 0
            self._window_start = now
        try:
            text = self._read_clipboard()
            if text and text != self._last_content:
                self._change_count += 1
                for coin, pat in self._CRYPTO_PATTERNS.items():
                    if pat.match(text.strip()):
                        events.append({
                            'type': 'CRYPTO_ADDRESS', 'time': now,
                            'severity': 'CRITICAL',
                            'detail': f"Clipboard contains {coin} address: {text[:40]}..."})
                self._last_content = text
        except Exception:
            pass
        with self.lock:
            for ev in events:
                self._events.append(ev)
        return events

    @staticmethod
    def _read_clipboard() -> str:
        """Read clipboard text via the Win32 API. The old path spawned
        `powershell Get-Clipboard` every 5 s — ~12 process launches a minute
        for the whole session. OpenClipboard/GetClipboardData is a few µs."""
        try:
            import ctypes
            CF_UNICODETEXT = 13
            user32 = ctypes.windll.user32
            kernel32 = ctypes.windll.kernel32
            # 64-bit signatures are mandatory here: GetClipboardData returns a
            # 64-bit HGLOBAL and without them ctypes truncates it to c_int,
            # so GlobalLock walks garbage memory -> access violation.
            user32.OpenClipboard.argtypes = [ctypes.c_void_p]
            user32.OpenClipboard.restype = ctypes.wintypes.BOOL
            user32.GetClipboardData.argtypes = [ctypes.wintypes.UINT]
            user32.GetClipboardData.restype = ctypes.c_void_p
            user32.CloseClipboard.argtypes = []
            user32.CloseClipboard.restype = ctypes.wintypes.BOOL
            kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
            kernel32.GlobalLock.restype = ctypes.c_wchar_p
            kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
            kernel32.GlobalUnlock.restype = ctypes.wintypes.BOOL
            if not user32.OpenClipboard(None):
                return ""
            try:
                handle = user32.GetClipboardData(CF_UNICODETEXT)
                if not handle:
                    return ""
                try:
                    data = kernel32.GlobalLock(handle)
                    return (data or "")[:2000].strip()
                finally:
                    kernel32.GlobalUnlock(handle)
            finally:
                user32.CloseClipboard()
        except Exception:
            return ""

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== USB DEVICE MONITOR ==========================
class USBMonitor:
    """Detect new USB devices being plugged in."""
    def __init__(self):
        self.lock = threading.Lock()
        self._known_devices: set[str] = set()
        self._events: deque = deque(maxlen=500)
        self._baseline_set = False

    def _enum_usb(self) -> dict:
        """Platform USB census -> {device_id: description}."""
        if not _IS_WINDOWS:
            devs = {}
            base = '/sys/bus/usb/devices'
            try:
                for entry in os.listdir(base):
                    prod = os.path.join(base, entry, 'product')
                    vid = os.path.join(base, entry, 'idVendor')
                    try:
                        desc = open(prod).read().strip() if \
                            os.path.exists(prod) else ''
                        ven = open(vid).read().strip() if \
                            os.path.exists(vid) else '????'
                        devs[entry] = desc or f'USB device {ven}'
                    except Exception:
                        devs[entry] = entry
            except Exception:
                pass
            return devs
        current = {}
        try:
            key_path = r"SYSTEM\CurrentControlSet\Enum\USB"
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path, 0, winreg.KEY_READ) as key:
                i = 0
                while True:
                    try:
                        subkey_name = winreg.EnumKey(key, i)
                        with winreg.OpenKey(key, subkey_name, 0, winreg.KEY_READ) as subkey:
                            j = 0
                            while True:
                                try:
                                    instance = winreg.EnumKey(subkey, j)
                                    dev_id = f"{subkey_name}\\{instance}"
                                    try:
                                        with winreg.OpenKey(subkey, instance, 0, winreg.KEY_READ) as inst_key:
                                            desc, _ = winreg.QueryValueEx(inst_key, 'DeviceDesc')
                                    except Exception:
                                        desc = dev_id
                                    current[dev_id] = desc
                                    j += 1
                                except OSError:
                                    break
                        i += 1
                    except OSError:
                        break
        except Exception as exc:
            _logger.debug("USB scan error: %s", exc)
        return current

    def scan(self) -> list[dict]:
        events = []
        current_map = self._enum_usb()
        current = set(current_map)
        if self._baseline_set:
            for dev_id in current - self._known_devices:
                events.append({
                    'type': 'USB_NEW', 'device_id': dev_id,
                    'time': time.time(), 'severity': 'WARNING',
                    'detail': f"New USB device: {current_map[dev_id]}"})
        with self.lock:
            self._known_devices = current
            if not self._baseline_set:
                self._baseline_set = True
            for ev in events:
                self._events.append(ev)
        return events

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== SCHEDULED TASK MONITOR ==========================
class ScheduledTaskMonitor:
    """Monitor Windows scheduled tasks for new/modified entries."""
    def __init__(self):
        self.lock = threading.Lock()
        self._baseline: dict[str, str] = {}  # task_name -> hash
        self._events: deque = deque(maxlen=500)
        self._baseline_set = False

    def _get_tasks(self) -> dict:
        current: dict[str, str] = {}
        if not _IS_WINDOWS:
            # cron spool + system cron dirs + systemd timers + user crontab
            paths = ['/etc/crontab']
            for d in ('/etc/cron.d', '/etc/cron.daily', '/etc/cron.hourly',
                      '/etc/cron.weekly', '/etc/cron.monthly',
                      '/var/spool/cron', '/var/spool/cron/crontabs'):
                if os.path.isdir(d):
                    for f in os.listdir(d):
                        paths.append(os.path.join(d, f))
            for p in paths:
                try:
                    data = open(p, 'rb').read()
                    current['cron:' + p] = hashlib.md5(data).hexdigest()
                except Exception:
                    continue
            try:
                out = subprocess.run(
                    ['systemctl', 'list-timers', '--all', '--no-legend',
                     '--no-pager'],
                    capture_output=True, text=True, timeout=10)
                for line in out.stdout.split(chr(10)):
                    unit = line.split()[-1] if line.split() else ''
                    if unit.endswith('.timer'):
                        current['timer:' + unit] = hashlib.md5(
                            line.encode()).hexdigest()
            except Exception:
                pass
            return current
        try:
            result = subprocess.run(
                ['schtasks', '/query', '/fo', 'CSV', '/nh'],
                capture_output=True, text=True, timeout=15,
                creationflags=0x08000000)
            for line in result.stdout.strip().split(chr(10)):
                parts = line.strip().strip('"').split('","')
                if len(parts) >= 2:
                    task_name = parts[0].strip('"')
                    task_hash = hashlib.md5(line.encode()).hexdigest()
                    current[task_name] = task_hash
        except Exception as exc:
            _logger.debug("Scheduled task scan error: %s", exc)
        return current

    def scan(self) -> list[dict]:
        events = []
        current = self._get_tasks()
        if not current and self._baseline_set:
            return []
        if self._baseline_set:
            for name, h in current.items():
                if name not in self._baseline:
                    events.append({'type': 'TASK_ADDED', 'task': name,
                                   'time': time.time(), 'severity': 'WARNING',
                                   'detail': f"New scheduled task: {name}"})
                elif self._baseline[name] != h:
                    events.append({'type': 'TASK_MODIFIED', 'task': name,
                                   'time': time.time(), 'severity': 'WARNING',
                                   'detail': f"Modified scheduled task: {name}"})
            for name in self._baseline:
                if name not in current:
                    events.append({'type': 'TASK_REMOVED', 'task': name,
                                   'time': time.time(), 'severity': 'INFO',
                                   'detail': f"Removed scheduled task: {name}"})
        with self.lock:
            self._baseline = current
            if not self._baseline_set:
                self._baseline_set = True
            for ev in events:
                self._events.append(ev)
        return events

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== NAMED PIPE / IPC MONITOR ==========================
class NamedPipeMonitor:
    """Detect inter-process communication via named pipes (used by RATs, Cobalt Strike)."""
    SUSPICIOUS_PIPES = {'msagent_', 'postex_', 'status_', 'msse-', 'MSSE-',
                        'mssecsvc', 'mypipe', 'win_svc', 'ntsvcs', 'scerpc',
                        'isapi', 'sdclient', 'chromepipe', 'gecko', '\\psexec',
                        'csexec', 'paexec', 'remcom'}

    def __init__(self):
        self.lock = threading.Lock()
        self._known_pipes: set[str] = set()
        self._events: deque = deque(maxlen=500)
        self._baseline_set = False

    def scan(self) -> list[dict]:
        if not _IS_WINDOWS:
            return []
        events = []
        current = set()
        try:
            pipe_dir = r'\\.\pipe'
            import win32file
            pipes = win32file.FindFilesW(pipe_dir + r'\*')
            for p in pipes:
                current.add(p[8])  # cFileName
        except ImportError:
            try:
                result = subprocess.run(
                    ['cmd', '/c', 'dir', r'\\.\pipe\\', '/b'],
                    capture_output=True, text=True, timeout=10,
                    creationflags=0x08000000)
                for line in result.stdout.strip().split('\n'):
                    name = line.strip()
                    if name:
                        current.add(name)
            except Exception:
                pass
        except Exception as exc:
            _logger.debug("Named pipe scan error: %s", exc)
        if self._baseline_set:
            new_pipes = current - self._known_pipes
            for pipe_name in new_pipes:
                is_suspicious = any(s.lower() in pipe_name.lower() for s in self.SUSPICIOUS_PIPES)
                if is_suspicious:
                    events.append({'type': 'SUSPICIOUS_PIPE', 'pipe': pipe_name,
                                   'time': time.time(), 'severity': 'CRITICAL',
                                   'detail': f"Suspicious named pipe: {pipe_name}"})
                elif len(new_pipes) <= 20:  # only log if not too noisy
                    events.append({'type': 'NEW_PIPE', 'pipe': pipe_name,
                                   'time': time.time(), 'severity': 'INFO',
                                   'detail': f"New named pipe: {pipe_name}"})
        with self.lock:
            self._known_pipes = current
            if not self._baseline_set:
                self._baseline_set = True
            for ev in events:
                self._events.append(ev)
        return events

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== WHOIS LOOKUP ==========================
class WhoisLookup:
    """Look up IP ownership via RDAP/whois for unknown IPs."""
    _RDAP_URL = "https://rdap.org/ip/{ip}"

    def __init__(self):
        self.cache: dict[str, dict] = {}
        self.lock = threading.Lock()
        self._rate = TokenBucket(rate=10.0, capacity=10.0)
        # The watcher used to call lookup() inline — an 8s-timeout HTTP call
        # on the scan loop per new high-risk conn. warm() queues the same
        # fetch on a daemon; results land in cache for the UI/RDAP paths.
        self._warm_q: deque = deque(maxlen=1000)
        self._warm_queued: set[str] = set()
        self._warm_worker: Optional[threading.Thread] = None

    def warm(self, ip: str):
        """Fire-and-forget RDAP fetch — never blocks the caller."""
        with self.lock:
            if ip in self.cache or ip in self._warm_queued:
                return
            if len(self._warm_queued) > 2000:
                return
            self._warm_queued.add(ip)
            self._warm_q.append(ip)
            if self._warm_worker is None:
                self._warm_worker = threading.Thread(
                    target=self._warm_loop, daemon=True, name="Whois-Warm")
                self._warm_worker.start()

    def _warm_loop(self):
        while True:
            with self.lock:
                ip = self._warm_q.popleft() if self._warm_q else None
                if ip is not None:
                    self._warm_queued.discard(ip)
            if ip is None:
                time.sleep(0.5)
                continue
            try:
                self.lookup(ip)
            except Exception:
                pass

    def lookup(self, ip: str) -> Optional[dict]:
        with self.lock:
            if ip in self.cache:
                return self.cache[ip]
        if not self._rate.consume():
            return None
        try:
            req = urllib.request.Request(self._RDAP_URL.format(ip=ip),
                                        headers={'Accept': 'application/json'})
            with urllib.request.urlopen(req, timeout=8) as resp:
                data = json.loads(resp.read())
            result = {
                'name': data.get('name', '?'),
                'handle': data.get('handle', '?'),
                'type': data.get('type', '?'),
                'country': data.get('country', '?'),
                'start_address': data.get('startAddress', '?'),
                'end_address': data.get('endAddress', '?'),
                'entities': [],
            }
            abuse = []
            contacts = []

            def _walk(ents, depth=0):
                for ent in ents[:8]:
                    vcard = ent.get('vcardArray', [None, []])[1] if 'vcardArray' in ent else []
                    org_name = email = ''
                    tels, emails, adr = [], [], ''
                    for v in vcard:
                        if v[0] == 'org':
                            org_name = v[3] if len(v) > 3 else ''
                        elif v[0] == 'fn':
                            org_name = org_name or (v[3] if len(v) > 3 else '')
                        elif v[0] == 'email' and len(v) > 3:
                            email = str(v[3])
                            emails.append(email)
                        elif v[0] == 'tel' and len(v) > 3:
                            tels.append(str(v[3]).replace('tel:', ''))
                        elif v[0] == 'adr' and len(v) > 3:
                            lab = (v[1] or {}).get('label') if isinstance(v[1], dict) else ''
                            if lab:
                                adr = str(lab).replace('\n', ', ')
                            elif isinstance(v[3], list):
                                adr = ', '.join(str(x) for x in v[3] if x)
                    roles = ent.get('roles', [])
                    if len(result['entities']) < 12:
                        result['entities'].append({'name': org_name, 'roles': roles})
                    if (emails or tels or adr) and len(contacts) < 12:
                        contacts.append({'name': org_name, 'handle': ent.get('handle', ''),
                                         'roles': roles, 'emails': emails[:3],
                                         'phones': tels[:3], 'address': adr[:200]})
                    if email and 'abuse' in roles and email not in abuse:
                        abuse.append(email)
                    if depth < 3:
                        _walk(ent.get('entities', []), depth + 1)

            _walk(data.get('entities', []))
            result['abuse'] = abuse
            result['contacts'] = contacts
            result['status'] = list(data.get('status') or [])
            result['remarks'] = [' '.join(d for d in (r.get('description') or []))[:240]
                                 for r in (data.get('remarks') or [])[:4]]
            result['port43'] = data.get('port43', '')
            result['ip_version'] = data.get('ipVersion', '')
            result['cidr'] = [f"{c.get('v4prefix') or c.get('v6prefix')}/{c.get('length')}"
                              for c in data.get('cidr0_cidrs', []) if c.get('length') is not None]
            result['events'] = {e.get('eventAction'): e.get('eventDate')
                                for e in data.get('events', []) if e.get('eventAction')}
            result['parent'] = data.get('parentHandle', '')
            with self.lock:
                if len(self.cache) > 20000:
                    for k in list(self.cache)[:5000]:
                        self.cache.pop(k, None)
                self.cache[ip] = result
            return result
        except Exception as exc:
            _logger.debug("RDAP lookup failed for %s: %s", ip, exc)
            result = {'name': '?', 'handle': '?', 'type': '?', 'country': '?',
                      'start_address': '?', 'end_address': '?',
                      'entities': [], 'error': True}
            with self.lock:
                if len(self.cache) > 20000:
                    for k in list(self.cache)[:5000]:
                        self.cache.pop(k, None)
                self.cache[ip] = result
            return result


# ========================== INBOUND SCAN DETECTOR ==========================
class InboundScanDetector:
    """Detect external IPs port-scanning this machine (inbound SYN probes)."""
    def __init__(self):
        self.lock = threading.Lock()
        self._inbound_syns: dict[str, list[int]] = defaultdict(list)  # src_ip -> [ports]
        self._alerts: deque = deque(maxlen=500)
        self._alerted: set[str] = set()
        self._window_start: float = time.time()

    def record_inbound_syn(self, src_ip: str, dst_port: int):
        now = time.time()
        with self.lock:
            if now - self._window_start > 120:
                self._inbound_syns.clear()
                # Clear the alerted set with the window too, so a scanner that
                # comes back later is reported again instead of being suppressed
                # forever (and so the set cannot grow without bound).
                self._alerted.clear()
                self._window_start = now
            if len(self._inbound_syns[src_ip]) < 500:
                self._inbound_syns[src_ip].append(dst_port)

    def check(self) -> list[dict]:
        events = []
        with self.lock:
            for ip, ports in self._inbound_syns.items():
                unique_ports = set(ports)
                if len(unique_ports) >= 5 and ip not in self._alerted:
                    self._alerted.add(ip)
                    events.append({
                        'type': 'INBOUND_SCAN', 'source_ip': ip,
                        'time': time.time(), 'severity': 'CRITICAL',
                        'ports_probed': sorted(unique_ports)[:20],
                        'detail': f"Port scan from {ip}: {len(unique_ports)} ports probed"})
            for ev in events:
                self._alerts.append(ev)
        return events

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._alerts)


# ========================== ANTI-HACK MONITORS (18 features) ==========================
# Each monitor returns a list of event dicts: {type, severity, detail, ...extras}
# All events are flagged via _flag_suspicious and pinned to connections.

# ---- 1. Security Event Log Monitor ----
class SecurityEventMonitor:
    """Reads Windows Security event log for logon, process-creation, service-install,
    user-creation, and admin-group-change events."""
    def __init__(self):
        self._last_record = 0
        self._events: deque = deque(maxlen=200)

    def scan(self) -> list:
        if not _IS_WINDOWS:
            return []
        results = []
        try:
            import win32evtlog  # type: ignore
            import win32evtlogutil  # type: ignore
            hand = win32evtlog.OpenEventLog(None, 'Security')
            flags = win32evtlog.EVENTLOG_BACKWARDS_READ | win32evtlog.EVENTLOG_SEQUENTIAL_READ
            events = win32evtlog.ReadEventLog(hand, flags, 0)
            max_rec = self._last_record
            for ev in events[:100]:
                rec = ev.RecordNumber
                if rec <= self._last_record:
                    break
                max_rec = max(max_rec, rec)
                eid = ev.EventID & 0xFFFF
                if eid in (4624, 4625, 4688, 7045, 4720, 4728, 4732, 4768, 4769):
                    sev = 'CRITICAL' if eid in (4625, 7045, 4720, 4728, 4732) else 'WARNING'
                    desc = {
                        4624: 'Successful logon', 4625: 'Failed logon',
                        4688: 'Process created', 7045: 'Service installed',
                        4720: 'User account created', 4728: 'User added to admin group',
                        4732: 'Member added to local group', 4768: 'Kerberos TGT requested',
                        4769: 'Kerberos service ticket requested',
                    }.get(eid, f'Event {eid}')
                    results.append({
                        'type': 'SECURITY_EVENT', 'severity': sev,
                        'detail': f'Event {eid}: {desc} — {str(ev.StringInserts)[:200]}',
                        'event_id': eid, 'record': rec,
                    })
            self._last_record = max_rec
            win32evtlog.CloseEventLog(hand)
        except ImportError:
            # win32evtlog not available — fall back to wevtutil
            try:
                out = subprocess.run(
                    ['wevtutil', 'qe', 'Security', '/c:50', '/rd:true', '/f:text'],
                    capture_output=True, text=True, timeout=10)
                for line in out.stdout.split('\n'):
                    if 'Event ID:' in line:
                        eid_str = line.split('Event ID:')[1].strip()
                        try:
                            eid = int(eid_str)
                        except ValueError:
                            continue
                        if eid in (4624, 4625, 4688, 7045, 4720, 4728, 4732):
                            sev = 'CRITICAL' if eid in (4625, 7045, 4720) else 'WARNING'
                            results.append({
                                'type': 'SECURITY_EVENT', 'severity': sev,
                                'detail': f'Event {eid}: security event',
                                'event_id': eid,
                            })
            except Exception:
                pass
        except Exception:
            pass
        self._events.extend(results)
        return results


# ---- 5. Hosts File / DNS Hijack Monitor ----
class HostsFileMonitor:
    """Detects modifications to the hosts file and DNS server changes."""
    HOSTS_PATH = r'C:\Windows\System32\drivers\etc\hosts' if _IS_WINDOWS else '/etc/hosts'

    def __init__(self):
        self._hosts_hash = ''
        self._dns_servers = set()
        self._first_run = True

    def _hash_hosts(self) -> str:
        try:
            import hashlib
            with open(self.HOSTS_PATH, 'rb') as f:
                return hashlib.md5(f.read()).hexdigest()
        except Exception:
            return ''

    def _get_dns_servers(self) -> set:
        if not _IS_WINDOWS:
            servers = set()
            try:
                for line in open('/etc/resolv.conf'):
                    parts = line.split()
                    if len(parts) >= 2 and parts[0] == 'nameserver':
                        servers.add(parts[1].strip())
            except Exception:
                pass
            return servers
        # Registry read — the same source ipconfig /all reports, but an
        # in-process enumeration instead of a subprocess spawn every cycle.
        servers = set()
        try:
            with winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r'SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                    0, winreg.KEY_READ) as k:
                i = 0
                while True:
                    try:
                        sub = winreg.EnumKey(k, i)
                        i += 1
                    except OSError:
                        break
                    try:
                        with winreg.OpenKey(k, sub, 0, winreg.KEY_READ) as sk:
                            for vn in ('NameServer', 'DhcpNameServer'):
                                try:
                                    raw, _ = winreg.QueryValueEx(sk, vn)
                                except (OSError, FileNotFoundError):
                                    continue
                                for tok in re.split(r'[\s,;]+', str(raw)):
                                    tok = tok.strip()
                                    if tok and tok != '127.0.0.1':
                                        try:
                                            ipaddress.ip_address(tok)
                                            servers.add(tok)
                                        except ValueError:
                                            pass
                    except OSError:
                        continue
            return servers
        except Exception:
            pass
        # Fallback: ipconfig /all
        try:
            out = subprocess.run(['ipconfig', '/all'], capture_output=True,
                                 text=True, timeout=10)
            for line in out.stdout.split('\n'):
                if 'DNS Servers' in line:
                    parts = line.split(':')
                    if len(parts) > 1:
                        ip = parts[1].strip()
                        if ip and ip != '127.0.0.1':
                            servers.add(ip)
            return servers
        except Exception:
            return set()

    def scan(self) -> list:
        results = []
        h = self._hash_hosts()
        if self._first_run:
            self._hosts_hash = h
            self._dns_servers = self._get_dns_servers()
            self._first_run = False
            return []
        if h and h != self._hosts_hash:
            results.append({
                'type': 'DNS_HIJACK', 'severity': 'CRITICAL',
                'detail': 'Hosts file modified — possible DNS hijack',
                'path': self.HOSTS_PATH,
            })
            self._hosts_hash = h
        dns = self._get_dns_servers()
        if dns and self._dns_servers and dns != self._dns_servers:
            results.append({
                'type': 'DNS_HIJACK', 'severity': 'WARNING',
                'detail': f'DNS servers changed: {self._dns_servers} -> {dns}',
            })
            self._dns_servers = dns
        return results


# ---- 6. Windows Service Creation Monitor ----
class ServiceMonitor:
    """Detects new Windows services and services with suspicious binary paths."""
    SUSPICIOUS_PATHS = ('\\temp\\', '\\tmp\\', '\\downloads\\', '\\appdata\\',
                        '\\desktop\\', '\\public\\', '\\programdata\\', '/tmp/', '/dev/shm/', '/var/tmp/', '/run/user/')

    def __init__(self):
        self._baseline: set = set()
        self._first_run = True

    def _get_services(self) -> dict:
        if not _IS_WINDOWS:
            try:
                out = subprocess.run(
                    ['systemctl', 'list-units', '--type=service', '--all',
                     '--no-legend', '--no-pager'],
                    capture_output=True, text=True, timeout=15)
                services = {}
                for line in out.stdout.split(chr(10)):
                    name = line.split()[0].strip() if line.split() else ''
                    if name.endswith('.service'):
                        name = name[:-8]
                        desc = ' '.join(line.split()[4:]) if len(
                            line.split()) > 4 else name
                        services[name] = desc
                return services
            except Exception:
                return {}
        # Registry enumeration — every service key carries DisplayName +
        # ImagePath, so one in-process pass replaces the 'sc query' spawn
        # (and the per-service 'sc qc' spawns below).
        services = {}
        binpaths = {}
        try:
            with winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r'SYSTEM\CurrentControlSet\Services', 0,
                    winreg.KEY_READ) as k:
                i = 0
                while True:
                    try:
                        svc_name = winreg.EnumKey(k, i)
                        i += 1
                    except OSError:
                        break
                    try:
                        with winreg.OpenKey(k, svc_name, 0,
                                            winreg.KEY_READ) as sk:
                            try:
                                disp, _ = winreg.QueryValueEx(sk, 'DisplayName')
                                services[svc_name] = disp
                            except (OSError, FileNotFoundError):
                                services[svc_name] = svc_name
                            try:
                                img, _ = winreg.QueryValueEx(sk, 'ImagePath')
                                if img:
                                    binpaths[svc_name] = os.path.expandvars(
                                        str(img)).strip('"')
                            except (OSError, FileNotFoundError):
                                pass
                    except OSError:
                        continue
        except Exception:
            pass
        if services:
            self._svc_binpaths = binpaths
            return services
        try:
            out = subprocess.run(
                ['sc', 'query', 'type=', 'service', 'state=', 'all'],
                capture_output=True, text=True, timeout=15)
            services = {}
            current = ''
            for line in out.stdout.split('\n'):
                if 'SERVICE_NAME:' in line:
                    current = line.split('SERVICE_NAME:')[1].strip()
                if 'DISPLAY_NAME:' in line and current:
                    services[current] = line.split('DISPLAY_NAME:')[1].strip()
            return services
        except Exception:
            return {}

    def _get_service_binpath(self, svc: str) -> str:
        if not _IS_WINDOWS:
            try:
                out = subprocess.run(
                    ['systemctl', 'show', svc + '.service',
                     '-p', 'ExecStart', '--value'],
                    capture_output=True, text=True, timeout=5)
                return out.stdout.strip()
            except Exception:
                return ''
        # Harvested during the same registry pass as _get_services —
        # 'sc qc' only runs now when the enumeration itself failed.
        binpaths = getattr(self, '_svc_binpaths', None)
        if binpaths is not None:
            return binpaths.get(svc, '')
        try:
            out = subprocess.run(['sc', 'qc', svc], capture_output=True,
                                 text=True, timeout=5)
            for line in out.stdout.split('\n'):
                if 'BINARY_PATH_NAME' in line:
                    return line.split('BINARY_PATH_NAME')[1].strip().strip(':').strip()
            return ''
        except Exception:
            return ''

    def scan(self) -> list:
        results = []
        svcs = self._get_services()
        if self._first_run:
            self._baseline = set(svcs.keys())
            self._first_run = False
            return []
        current = set(svcs.keys())
        new_svcs = current - self._baseline
        for svc in new_svcs:
            binpath = self._get_service_binpath(svc)
            sev = 'CRITICAL'
            detail = f'New service: {svc}'
            if binpath:
                detail += f' (binary: {binpath})'
                if any(p in binpath.lower() for p in self.SUSPICIOUS_PATHS):
                    detail += ' [SUSPICIOUS PATH]'
                    sev = 'CRITICAL'
            results.append({
                'type': 'SERVICE_CREATE', 'severity': sev,
                'detail': detail, 'service': svc, 'binpath': binpath,
            })
        self._baseline = current
        return results


# ---- 9. Defender / AV Disable Monitor ----
class SecurityToolMonitor:
    """Detects Windows Defender disable, firewall disable, and AV tampering."""
    def __init__(self):
        self._defender_enabled = True
        self._firewall_on = True
        self._first_run = True

    def _check_defender(self) -> bool:
        # Registry fast-path — catches the direct-tamper case (malware sets
        # these to 1) instantly with zero subprocess cost.
        try:
            for path, val in (
                (r'SOFTWARE\Microsoft\Windows Defender\Real-Time Protection',
                 'DisableRealtimeMonitoring'),
                (r'SOFTWARE\Microsoft\Windows Defender', 'DisableAntiSpyware'),
                (r'SOFTWARE\Microsoft\Windows Defender', 'DisableAntiVirus'),
            ):
                try:
                    with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, path, 0,
                                        winreg.KEY_READ) as k:
                        v, _ = winreg.QueryValueEx(k, val)
                    if v:
                        return False
                except (OSError, FileNotFoundError):
                    continue
        except Exception:
            pass
        # Authoritative source (third-party-AV takeovers don't set the
        # flags above): Get-MpComputerStatus — but PowerShell costs
        # ~0.5-1.5s per spawn, so run it only every 4th scan and ride the
        # cached verdict between runs.
        self._defender_probe_n = getattr(self, '_defender_probe_n', 0) + 1
        if self._defender_probe_n % 4 != 1 and hasattr(
                self, '_defender_wmi_state'):
            return self._defender_wmi_state
        try:
            out = subprocess.run(
                ['powershell', '-NoProfile', '-NonInteractive', '-Command',
                 'Get-MpComputerStatus | Select-Object -Property RealTimeProtectionEnabled'],
                capture_output=True, text=True, timeout=10)
            self._defender_wmi_state = 'True' in out.stdout
            return self._defender_wmi_state
        except Exception:
            return getattr(self, '_defender_wmi_state', True)

    def _check_firewall(self) -> bool:
        # EnableFirewall DWORD per profile — the same source netsh reads,
        # minus the ~0.5-1s netsh spawn every cycle.
        try:
            states = []
            for prof in ('DomainProfile', 'StandardProfile', 'PublicProfile'):
                with winreg.OpenKey(
                        winreg.HKEY_LOCAL_MACHINE,
                        'SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\'
                        'Parameters\\FirewallPolicy\\' + prof,
                        0, winreg.KEY_READ) as k:
                    v, _ = winreg.QueryValueEx(k, 'EnableFirewall')
                    states.append(bool(v))
            return all(states) if states else True
        except Exception:
            pass
        try:
            out = subprocess.run(
                ['netsh', 'advfirewall', 'show', 'allprofiles', 'state'],
                capture_output=True, text=True, timeout=10)
            return 'ON' in out.stdout.upper()
        except Exception:
            return True

    def scan(self) -> list:
        results = []
        defender = self._check_defender()
        firewall = self._check_firewall()
        if self._first_run:
            self._defender_enabled = defender
            self._firewall_on = firewall
            self._first_run = False
            return []
        if defender != self._defender_enabled:
            sev = 'CRITICAL' if not defender else 'WARNING'
            results.append({
                'type': 'AV_DISABLE', 'severity': sev,
                'detail': f'Defender real-time protection: {"DISABLED" if not defender else "ENABLED"}',
            })
            self._defender_enabled = defender
        if firewall != self._firewall_on:
            sev = 'CRITICAL' if not firewall else 'WARNING'
            results.append({
                'type': 'AV_DISABLE', 'severity': sev,
                'detail': f'Windows Firewall: {"DISABLED" if not firewall else "ENABLED"}',
            })
            self._firewall_on = firewall
        return results


# ---- 10. New User Account / Admin Escalation Monitor ----
class UserAccountMonitor:
    """Detects new user accounts and admin group membership changes."""
    def __init__(self):
        self._users: set = set()
        self._admins: set = set()
        self._first_run = True

    def _get_users(self) -> set:
        if not _IS_WINDOWS:
            try:
                return {l.split(':', 1)[0] for l in open('/etc/passwd')
                        if ':' in l}
            except Exception:
                return set()
        try:
            out = subprocess.run(['net', 'user'], capture_output=True,
                                 text=True, timeout=10)
            lines = out.stdout.split('\n')
            for i, line in enumerate(lines):
                if '---' in line and i > 0:
                    user_lines = lines[i+1:]
                    users = set()
                    for ul in user_lines:
                        if 'The command' in ul or not ul.strip():
                            break
                        users.update(ul.split())
                    return users
        except Exception:
            pass
        return set()

    def _get_admins(self) -> set:
        if not _IS_WINDOWS:
            admins = set()
            for grp in ('sudo', 'wheel', 'root', 'admin'):
                try:
                    out = subprocess.run(['getent', 'group', grp],
                                         capture_output=True, text=True,
                                         timeout=5)
                    for line in out.stdout.split(chr(10)):
                        members = line.split(':')[-1]
                        admins.update(m.strip() for m in members.split(',')
                                      if m.strip())
                except Exception:
                    pass
            return admins
        try:
            out = subprocess.run(
                ['net', 'localgroup', 'administrators'],
                capture_output=True, text=True, timeout=10)
            lines = out.stdout.split('\n')
            for i, line in enumerate(lines):
                if '---' in line and i > 0:
                    admin_lines = lines[i+1:]
                    admins = set()
                    for al in admin_lines:
                        if 'The command' in al or not al.strip():
                            break
                        admins.update(al.split())
                    return admins
        except Exception:
            pass
        return set()

    def scan(self) -> list:
        results = []
        users = self._get_users()
        admins = self._get_admins()
        if self._first_run:
            self._users = users
            self._admins = admins
            self._first_run = False
            return []
        new_users = users - self._users
        for u in new_users:
            results.append({
                'type': 'NEW_ACCOUNT', 'severity': 'CRITICAL',
                'detail': f'New user account created: {u}',
                'account': u,
            })
        new_admins = admins - self._admins
        for a in new_admins:
            results.append({
                'type': 'NEW_ACCOUNT', 'severity': 'CRITICAL',
                'detail': f'User added to Administrators group: {a}',
                'account': a,
            })
        self._users = users
        self._admins = admins
        return results


# ---- 11. WMI Subscription Monitor ----
class WMISubscriptionMonitor:
    """Detects WMI event subscriptions used for stealthy persistence."""
    def __init__(self):
        self._baseline_filters: set = set()
        self._baseline_consumers: set = set()
        self._first_run = True

    def _get_filters(self) -> set:
        try:
            out = subprocess.run(
                ['wmic', '/namespace:\\\\root\\subscription',
                 'path', '__EventFilter', 'get', 'Name'],
                capture_output=True, text=True, timeout=10)
            return {l.strip() for l in out.stdout.split('\n')
                    if l.strip() and l.strip() != 'Name'}
        except Exception:
            return set()

    def _get_consumers(self) -> set:
        try:
            out = subprocess.run(
                ['wmic', '/namespace:\\\\root\\subscription',
                 'path', '__CommandLineEventConsumer', 'get', 'Name'],
                capture_output=True, text=True, timeout=10)
            return {l.strip() for l in out.stdout.split('\n')
                    if l.strip() and l.strip() != 'Name'}
        except Exception:
            return set()

    def scan(self) -> list:
        results = []
        filters = self._get_filters()
        consumers = self._get_consumers()
        if self._first_run:
            self._baseline_filters = filters
            self._baseline_consumers = consumers
            self._first_run = False
            return []
        new_filters = filters - self._baseline_filters
        new_consumers = consumers - self._baseline_consumers
        for f in new_filters:
            results.append({
                'type': 'WMI_PERSIST', 'severity': 'CRITICAL',
                'detail': f'New WMI EventFilter: {f}',
            })
        for c in new_consumers:
            results.append({
                'type': 'WMI_PERSIST', 'severity': 'CRITICAL',
                'detail': f'New WMI CommandLineEventConsumer: {c}',
            })
        self._baseline_filters = filters
        self._baseline_consumers = consumers
        return results


# ---- 14. Driver / Rootkit Load Monitor ----
class DriverLoadMonitor:
    """Detects new kernel driver loads and .sys files in non-standard paths."""
    SYS_DIR = r'C:\Windows\System32\drivers' if _IS_WINDOWS else ''
    SUSPICIOUS_DRIVER_DIRS = (r'\temp\\', r'\downloads\\', r'\appdata\\',
                              r'\desktop\\', r'\public\\')

    def __init__(self):
        self._baseline_drivers: set = set()
        self._baseline_sys_files: set = set()
        self._first_run = True

    def _get_drivers(self) -> set:
        try:
            out = subprocess.run(
                ['sc', 'query', 'type=', 'driver', 'state=', 'active'],
                capture_output=True, text=True, timeout=15)
            drivers = set()
            for line in out.stdout.split('\n'):
                if 'SERVICE_NAME:' in line:
                    drivers.add(line.split('SERVICE_NAME:')[1].strip())
            return drivers
        except Exception:
            return set()

    def _get_sys_files(self) -> set:
        if not self.SYS_DIR or not os.path.isdir(self.SYS_DIR):
            return set()
        try:
            return {f for f in os.listdir(self.SYS_DIR) if f.lower().endswith('.sys')}
        except Exception:
            return set()

    def scan(self) -> list:
        results = []
        drivers = self._get_drivers()
        sys_files = self._get_sys_files()
        if self._first_run:
            self._baseline_drivers = drivers
            self._baseline_sys_files = sys_files
            self._first_run = False
            return []
        new_drivers = drivers - self._baseline_drivers
        for d in new_drivers:
            results.append({
                'type': 'DRIVER_LOAD', 'severity': 'WARNING',
                'detail': f'New kernel driver loaded: {d}',
                'driver': d,
            })
        new_sys = sys_files - self._baseline_sys_files
        for s in new_sys:
            results.append({
                'type': 'DRIVER_LOAD', 'severity': 'WARNING',
                'detail': f'New .sys file in drivers directory: {s}',
                'file': s,
            })
        self._baseline_drivers = drivers
        self._baseline_sys_files = sys_files
        return results


class ThreatIntelDB:
    """Refreshable threat-intelligence lists. The built-in constants
    (LOLBins, malware mutexes, exfil/C2 channels) are the baseline;
    public feeds and an optional user file extend them so the monitor's
    indicators stay current without a code release.

    Feeds:
      - LOLBAS official API (lolbas-project.github.io) -> living-off-the-
        land binary names, refreshed from the project's own dataset.
      - abuse.ch Feodo Tracker + SSLBL blocklists -> active C2
        destination IPs observed in the wild in the last days.
      - `threat_intel_file` (JSON, user-supplied) -> {"lolbins": [...],
        "mutexes": {"name": "desc"}, "exfil_channels": [...]} merged
        verbatim; never fetched, always honoured.

    Fetched at most once per TTL on a background thread, cached on disk;
    a failed fetch keeps the last good copy — the static baseline means
    detection never regresses when a feed is unreachable."""

    _LOLBAS_API = 'https://lolbas-project.github.io/api/lolbas.json'
    _FEODO_C2 = 'https://feodotracker.abuse.ch/downloads/ipblocklist.json'
    _SSLBL_C2 = 'https://sslbl.abuse.ch/blacklist/sslipblacklist.txt'

    def __init__(self, cache_path: Optional[str] = None,
                 user_file: Optional[str] = None,
                 ttl_s: float = 86400.0):
        self._cache_path = cache_path or os.path.join(
            os.path.dirname(os.path.abspath(__file__)),
            'threat_intel_cache.json')
        self._user_file = user_file
        self._ttl_s = ttl_s
        self._lock = threading.Lock()
        self._lolbins: set = set()
        self._mutexes: dict = {}
        self._domains: set = set()
        self._c2_ips: dict = {}
        self._user_lolbins: set = set()
        self._user_mutexes: dict = {}
        self._user_domains: set = set()
        self._user_c2: set = set()
        self._fetched_at = 0.0
        self._refreshing = False
        self.sources: list = []
        self._user_loaded = False
        self._load_cache()

    # ---- persistence -------------------------------------------------
    def _load_cache(self) -> None:
        try:
            data = json.loads(open(self._cache_path, encoding='utf-8').read())
            if time.time() - float(data.get('ts', 0)) <= self._ttl_s * 7:
                self._lolbins = set(data.get('lolbins') or [])
                self._mutexes = dict(data.get('mutexes') or {})
                self._domains = set(data.get('domains') or [])
                self._c2_ips = dict(data.get('c2_ips') or {})
                self._fetched_at = float(data.get('ts', 0))
        except Exception:
            pass

    def _save_cache(self) -> None:
        try:
            tmp = self._cache_path + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as fh:
                json.dump({'ts': self._fetched_at,
                           'lolbins': sorted(self._lolbins),
                           'mutexes': self._mutexes,
                           'domains': sorted(self._domains),
                           'c2_ips': self._c2_ips}, fh)
            os.replace(tmp, self._cache_path)
        except Exception:
            pass

    def _cfg_user_file(self) -> Optional[str]:
        try:
            return self._user_file or CONFIG.get('threat_intel_file') or None
        except Exception:
            return self._user_file

    def _load_user_file(self) -> None:
        if self._user_loaded or not self._cfg_user_file():
            return
        self._user_loaded = True
        try:
            data = json.loads(open(self._cfg_user_file(), encoding='utf-8').read())
            self._user_lolbins = {str(n).lower() for n in
                                  data.get('lolbins') or []}
            self._user_mutexes = {str(k): str(v) for k, v in
                                  dict(data.get('mutexes') or {}).items()}
            self._user_domains = {str(d).lower().lstrip('*.')
                                  for d in data.get('exfil_channels') or []}
            self._user_c2 = {str(ip).strip() for ip in
                             data.get('c2_ips') or []}
            self.sources.append(self._cfg_user_file())
        except Exception:
            pass

    # ---- feeds -------------------------------------------------------
    @staticmethod
    def _fetch(url: str, limit: int = 4 * 1024 * 1024) -> bytes:
        req = urllib.request.Request(
            url, headers={'User-Agent': 'medianbox-monitor/2'})
        with urllib.request.urlopen(req, timeout=12) as resp:
            return resp.read(limit)

    def refresh(self, blocking: bool = False) -> None:
        try:
            if not CONFIG.get('threat_intel_feeds', True):
                return
        except Exception:
            pass
        if self._refreshing:
            return
        try:
            ttl = float(CONFIG.get('threat_intel_ttl_s', self._ttl_s))
        except Exception:
            ttl = self._ttl_s
        if time.time() - self._fetched_at < ttl:
            return
        if blocking:
            self._do_refresh()
            return
        self._refreshing = True
        threading.Thread(target=self._do_refresh, daemon=True).start()

    def _do_refresh(self) -> None:
        try:
            got = False
            try:
                data = json.loads(self._fetch(self._LOLBAS_API))
                names = set()
                for entry in data if isinstance(data, list) else []:
                    nm = str(entry.get('Name') or '').strip().lower()
                    if nm:
                        names.add(nm)
                if names:
                    with self._lock:
                        self._lolbins |= names
                    got = True
                    if 'lolbas' not in self.sources:
                        self.sources.append('lolbas')
            except Exception:
                pass
            try:
                ips = {}
                for row in json.loads(self._fetch(self._FEODO_C2)):
                    if not isinstance(row, dict):
                        continue
                    ip = str(row.get('ip_address') or '').strip()
                    if ip:
                        ips[ip] = 'Feodo C2: ' + str(
                            row.get('malware') or 'botnet C2')
                if ips:
                    with self._lock:
                        self._c2_ips.update(ips)
                    got = True
                    if 'feodo' not in self.sources:
                        self.sources.append('feodo')
            except Exception:
                pass
            try:
                ips = {}
                for line in self._fetch(self._SSLBL_C2).decode(
                        'utf-8', 'replace').splitlines():
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    host = line.split(',')[0].split(':')[0].strip()
                    if host:
                        ips[host] = 'SSLBL C2: ' + (
                            line.split(',')[-1].strip()
                            if ',' in line else 'SSL blacklisted')
                if ips:
                    with self._lock:
                        self._c2_ips.update(ips)
                    got = True
                    if 'sslbl' not in self.sources:
                        self.sources.append('sslbl')
            except Exception:
                pass
            except Exception:
                pass
            if got:
                self._fetched_at = time.time()
                self._save_cache()
        finally:
            self._refreshing = False

    # ---- accessors (baseline constants ∪ fetched ∪ user file) --------
    def lolbins(self) -> set:
        self._load_user_file()
        self.refresh()
        return self._lolbins | self._user_lolbins

    def mutexes(self) -> dict:
        self._load_user_file()
        self.refresh()
        return dict(self._mutexes, **self._user_mutexes)

    def exfil_channels(self) -> set:
        self._load_user_file()
        self.refresh()
        return self._domains | self._user_domains


    def c2_ips(self) -> dict:
        self._load_user_file()
        self.refresh()
        out = dict(self._c2_ips)
        for ip in self._user_c2:
            out.setdefault(ip, 'user threat-intel file')
        return out


THREAT_INTEL = ThreatIntelDB()


# Static baselines live next to their consumers; the accessors above add
# fetched + user-supplied indicators on top, so a stale or unreachable
# feed never reduces coverage.

# ---- 16. Mutex / Named Object Scanner ----
class MutexScanner:
    """Checks for known malware mutex names."""
    KNOWN_MUTEXES = {
        'Synaptics': 'Possible keylogger (Synaptics mutex)',
        'avira_gui_lock': 'Avira AV mutex',
        'OneOneMutex': 'Possible malware single-instance check',
        'WinInitMutex': 'Possible malware (fake WinInit)',
        'Global\\__DDAInterface': 'Possible screen capture malware',
        'Global\\D3DWindow': 'Possible game hijack malware',
        'B0184A2A-1F90-4D55-A6B0-13A8B5C0E6B2': 'Possible Cobalt Strike beacon',
        'Global\\MSEdgeRedirector': 'Possible Edge redirector',
        'Global\\ChromeExtPipe': 'Possible Chrome extension hijack',
        'MUTEX_UUID': 'Possible Meterpreter',
    }

    def __init__(self):
        self._found: set = set()

    def scan(self) -> list:
        if not _IS_WINDOWS:
            return []
        results = []
        import ctypes
        kernel32 = ctypes.windll.kernel32
        kernel32.OpenMutexW.argtypes = [ctypes.wintypes.DWORD,
                                        ctypes.wintypes.BOOL, ctypes.c_wchar_p]
        kernel32.OpenMutexW.restype = ctypes.c_void_p
        kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
        kernel32.CloseHandle.restype = ctypes.wintypes.BOOL
        for name, desc in dict(self.KNOWN_MUTEXES, **THREAT_INTEL.mutexes()).items():
            if name in self._found:
                continue
            try:
                handle = kernel32.OpenMutexW(
                    0x1F0001, False, name)  # SYNCHRONIZE | all access
                if handle:
                    results.append({
                        'type': 'MUTEX_HIT', 'severity': 'CRITICAL',
                        'detail': f'Known malware mutex found: {name} ({desc})',
                        'mutex': name,
                    })
                    self._found.add(name)
                    kernel32.CloseHandle(handle)
            except Exception:
                pass
        return results


# ========================== DoH DETECTION ==========================
class DoHDetector:
    """Detect DNS over HTTPS usage (bypasses local DNS monitoring)."""
    DOH_SERVERS = {
        '1.1.1.1': 'Cloudflare', '1.0.0.1': 'Cloudflare',
        '8.8.8.8': 'Google', '8.8.4.4': 'Google',
        '9.9.9.9': 'Quad9', '149.112.112.112': 'Quad9',
        '208.67.222.222': 'OpenDNS', '208.67.220.220': 'OpenDNS',
        '94.140.14.14': 'AdGuard', '94.140.15.15': 'AdGuard',
        '185.228.168.9': 'CleanBrowsing', '185.228.169.9': 'CleanBrowsing',
    }

    def __init__(self):
        self.lock = threading.Lock()
        self._detections: dict[int, dict] = {}  # pid -> info
        self._events: deque = deque(maxlen=500)

    def check_connection(self, pid: int, proc_name: str, dst_ip: str, dst_port: int) -> Optional[dict]:
        if dst_port != 443 or dst_ip not in self.DOH_SERVERS:
            return None
        provider = self.DOH_SERVERS[dst_ip]
        key = (pid, dst_ip)
        with self.lock:
            if key in self._detections:
                return None
            ev = {'type': 'DOH_DETECTED', 'pid': pid, 'process': proc_name,
                  'dst_ip': dst_ip, 'provider': provider,
                  'time': time.time(), 'severity': 'WARNING',
                  'detail': f"{proc_name} (PID {pid}) using DNS-over-HTTPS via {provider} ({dst_ip})"}
            self._detections[key] = ev
            self._events.append(ev)
            return ev

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== TLS CERT / MITM DETECTOR ==========================
class TLSCertDetector:
    """Detect possible MITM by checking TLS ServerHello certificate fingerprints."""
    KNOWN_ISSUERS = {
        'google': ['GTS', 'Google Trust Services'],
        'microsoft': ['Microsoft', 'DigiCert'],
        'cloudflare': ['Cloudflare', 'DigiCert', "Let's Encrypt"],
        'amazon': ['Amazon', 'DigiCert', 'Starfield'],
    }

    def __init__(self):
        self.lock = threading.Lock()
        self._cert_cache: dict[str, str] = {}  # ip -> cert_hash
        self._ja4x: dict[str, str] = {}        # ip -> JA4X cert fingerprint
        self._events: deque = deque(maxlen=500)
        self._cert_change_count: dict[str, int] = defaultdict(int)

    def record_cert(self, dst_ip: str, cert_data: bytes) -> Optional[dict]:
        if not cert_data:
            return None
        cert_hash = hashlib.sha256(cert_data).hexdigest()[:16]
        ja4x = JA4Plus.ja4x(cert_data) or ''
        with self.lock:
            prev = self._cert_cache.get(dst_ip)
            self._cert_cache[dst_ip] = cert_hash
            if ja4x:
                self._ja4x[dst_ip] = ja4x
            if prev and prev != cert_hash:
                self._cert_change_count[dst_ip] += 1
                if self._cert_change_count[dst_ip] >= 3:
                    ev = {'type': 'CERT_CHANGE', 'ip': dst_ip,
                          'time': time.time(), 'severity': 'CRITICAL',
                          'old_hash': prev, 'new_hash': cert_hash, 'ja4x': ja4x,
                          'detail': f"TLS cert changed {self._cert_change_count[dst_ip]}x for {dst_ip} — possible MITM"}
                    self._events.append(ev)
                    return ev
        return None

    def get_ja4x(self) -> dict:
        """Per-IP JA4X certificate fingerprints seen this session."""
        with self.lock:
            return dict(self._ja4x)

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== CONNECTION HISTORY ==========================
class ConnectionHistory:
    """Track all connections seen during session, including closed ones, with timestamps."""
    def __init__(self):
        self.lock = threading.Lock()
        self._active: dict[tuple, dict] = {}  # (rip, rport, lip, lport, pid) -> info
        self._history: deque = deque(maxlen=20000)
        self._bandwidth: dict[str, dict] = defaultdict(lambda: {  # ip -> bandwidth
            'bytes_sent': 0, 'bytes_recv': 0, 'last_update': 0})
        # Change counters — _get_full_data re-derives the timeline/bandwidth
        # payloads only when these move, and the GUI render sigs key off them
        # instead of the snapshot's identity.
        self.version = 0        # bumps on conn open/close
        self.bw_seq = 0         # bumps on every bandwidth sample
        self._tln_cache = None  # (version, limit) -> sorted list

    def update(self, connections: list):
        """Called each cycle with current psutil connections."""
        now = time.time()
        current_keys = set()
        with self.lock:
            for conn in connections:
                if not conn.raddr:
                    continue
                key = (conn.raddr[0], conn.raddr[1],
                       conn.laddr[0] if conn.laddr else '',
                       conn.laddr[1] if conn.laddr else 0,
                       conn.pid or 0)
                current_keys.add(key)
                if key not in self._active:
                    self._active[key] = {
                        'remote_ip': conn.raddr[0], 'remote_port': conn.raddr[1],
                        'local_ip': conn.laddr[0] if conn.laddr else '',
                        'local_port': conn.laddr[1] if conn.laddr else 0,
                        'pid': conn.pid or 0, 'status': conn.status,
                        'start_time': now, 'end_time': None,
                        'duration': 0, 'active': True,
                    }
                else:
                    self._active[key]['status'] = conn.status
                    self._active[key]['duration'] = now - self._active[key]['start_time']
            # Close connections that disappeared
            closed_keys = set(self._active.keys()) - current_keys
            for key in closed_keys:
                entry = self._active.pop(key)
                entry['end_time'] = now
                entry['duration'] = now - entry['start_time']
                entry['active'] = False
                self._history.append(entry)
            # Every pass moves durations/statuses, so the rendered view is
            # only valid until the next update — the seq IS the cadence.
            self.version += 1

    def update_bandwidth(self, ip: str, sent: int, recv: int):
        with self.lock:
            bw = self._bandwidth[ip]
            bw['bytes_sent'] += sent
            bw['bytes_recv'] += recv
            bw['last_update'] = time.time()
            self.bw_seq += 1

    def get_active(self) -> list[dict]:
        with self.lock:
            return [dict(v) for v in self._active.values()]

    def get_history(self) -> list[dict]:
        with self.lock:
            active = [dict(v) for v in self._active.values()]
            closed = list(self._history)
            return active + closed

    def get_bandwidth(self) -> dict:
        with self.lock:
            return {ip: dict(v) for ip, v in self._bandwidth.items()}

    def prune_bandwidth(self, max_entries: int = 5000):
        """Drop the least recently updated IPs so the table stays bounded."""
        with self.lock:
            if len(self._bandwidth) <= max_entries:
                return
            ordered = sorted(self._bandwidth.items(),
                             key=lambda kv: kv[1].get('last_update', 0))
            for ip, _ in ordered[:len(self._bandwidth) - max_entries]:
                del self._bandwidth[ip]
            self.bw_seq += 1

    def get_timeline(self, limit: int = 0) -> list[dict]:
        """Connections sorted by start_time, oldest first.

        `limit` keeps only the most recent N. The payload is rebuilt on every
        GUI refresh, and the closed-connection deque holds up to 20 000
        entries, so copying and sorting the whole thing several times a second
        was pure overhead — the view only ever shows the tail. The result is
        cached on `version`: between update() passes the same (version, limit)
        query returns the already-built list.
        """
        cached = self._tln_cache
        if cached is not None:
            with self.lock:
                ver = self.version
            if cached[0] == ver and cached[1] == limit:
                return cached[2]
        with self.lock:
            all_conns = list(self._history) + [dict(v) for v in self._active.values()]
            # Read the version under the same lock that serializes update() —
            # the copy and the version it answers for are then consistent.
            ver = self.version
        # nlargest before sort — same pattern as the action log: picking the
        # newest `limit` of ~20k rows is far cheaper than sorting them all.
        if limit and len(all_conns) > limit:
            all_conns = heapq.nlargest(limit, all_conns,
                                       key=lambda c: c.get('start_time', 0))
        all_conns.sort(key=lambda c: c.get('start_time', 0))
        self._tln_cache = (ver, limit, all_conns)
        return all_conns

    def get_counts(self) -> dict:
        """True active/closed totals, independent of any timeline truncation."""
        with self.lock:
            return {'active': len(self._active), 'closed': len(self._history),
                    'total': len(self._active) + len(self._history)}


# ========================== BLUETOOTH SCANNER ==========================
class BluetoothScanner:
    """Enumerate Bluetooth devices via Windows registry and WMI."""
    def __init__(self):
        self.lock = threading.Lock()
        self._known_devices: dict[str, dict] = {}
        self._events: deque = deque(maxlen=500)
        self._baseline_set = False

    def scan(self) -> list[dict]:
        if not _IS_WINDOWS:
            return []
        events = []
        current: dict[str, dict] = {}
        now = time.time()
        # Method 1: Registry enumeration of paired BT devices
        try:
            bt_key = r"SYSTEM\CurrentControlSet\Enum\BTHENUM"
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, bt_key, 0,
                                winreg.KEY_READ) as key:
                i = 0
                while True:
                    try:
                        subkey_name = winreg.EnumKey(key, i)
                        i += 1
                        try:
                            with winreg.OpenKey(key, subkey_name) as sub:
                                j = 0
                                while True:
                                    try:
                                        instance = winreg.EnumKey(sub, j)
                                        j += 1
                                        dev_id = f"{subkey_name}\\{instance}"
                                        try:
                                            with winreg.OpenKey(sub, instance) as inst_key:
                                                friendly = ""
                                                try:
                                                    friendly, _ = winreg.QueryValueEx(inst_key, "FriendlyName")
                                                except FileNotFoundError:
                                                    pass
                                                current[dev_id] = {
                                                    'device_id': dev_id,
                                                    'name': friendly or subkey_name[:40],
                                                    'time': now,
                                                    'type': 'bluetooth',
                                                }
                                        except Exception:
                                            pass
                                    except OSError:
                                        break
                        except Exception:
                            pass
                    except OSError:
                        break
        except FileNotFoundError:
            pass
        except Exception:
            pass
        # Method 2: Bluetooth radios via registry
        try:
            radio_key = r"SYSTEM\CurrentControlSet\Enum\USB"
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, radio_key, 0,
                                winreg.KEY_READ) as key:
                i = 0
                while True:
                    try:
                        subkey_name = winreg.EnumKey(key, i)
                        i += 1
                        if 'BTHUSB' in subkey_name.upper() or 'BLUETOOTH' in subkey_name.upper():
                            current[f"radio_{subkey_name}"] = {
                                'device_id': subkey_name,
                                'name': f"BT Radio: {subkey_name[:30]}",
                                'time': now, 'type': 'bt_radio',
                            }
                    except OSError:
                        break
        except Exception:
            pass
        # Detect new devices
        if self._baseline_set:
            for dev_id, info in current.items():
                if dev_id not in self._known_devices:
                    events.append({
                        'severity': 'WARNING',
                        'detail': f"New Bluetooth device: {info['name']} ({dev_id[:50]})",
                        'device': info,
                    })
        with self.lock:
            self._known_devices = current
            if not self._baseline_set:
                self._baseline_set = True
            for ev in events:
                self._events.append(ev)
        return events

    def get_devices(self) -> list[dict]:
        with self.lock:
            return list(self._known_devices.values())

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ========================== SERIAL PORT SCANNER ==========================
class SerialPortScanner:
    """Enumerate active COM/Serial ports and detect new ones."""
    def __init__(self):
        self.lock = threading.Lock()
        self._known_ports: dict[str, dict] = {}
        self._events: deque = deque(maxlen=500)
        self._baseline_set = False

    def scan(self) -> list[dict]:
        if not _IS_WINDOWS:
            return []
        events = []
        current: dict[str, dict] = {}
        now = time.time()
        # Registry: SERIALCOMM
        try:
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                                r"HARDWARE\DEVICEMAP\SERIALCOMM", 0,
                                winreg.KEY_READ) as key:
                i = 0
                while True:
                    try:
                        name, val, _ = winreg.EnumValue(key, i)
                        i += 1
                        current[val] = {
                            'port': val, 'device': name,
                            'time': now, 'type': 'serial',
                        }
                    except OSError:
                        break
        except FileNotFoundError:
            pass
        except Exception:
            pass
        # Detect new ports
        if self._baseline_set:
            for port_name, info in current.items():
                if port_name not in self._known_ports:
                    events.append({
                        'severity': 'WARNING',
                        'detail': f"New serial port: {port_name} ({info['device']})",
                        'port_info': info,
                    })
        with self.lock:
            self._known_ports = current
            if not self._baseline_set:
                self._baseline_set = True
            for ev in events:
                self._events.append(ev)
        return events

    def get_ports(self) -> list[dict]:
        with self.lock:
            return list(self._known_ports.values())

    def get_events(self) -> list[dict]:
        with self.lock:
            return list(self._events)


# ================= SPECTRUM / NON-IP SIGNAL INTELLIGENCE =================
# Tracks every device that emits a signal the host can perceive — not just
# IP-level connections. Each emitter is fingerprinted, its RSSI history is
# kept for distance estimation (log-distance path loss), and when the same
# emitter is reported from >=3 spatially-separated sensor positions the
# Trilaterator solves a 2D fix. Everything is a labeled feed for deduction:
# approach trends, evil-twin suspects, hidden SSIDs, spectrum coverage gaps.


def _sig_pct_to_dbm(pct):
    """Windows reports Wi-Fi signal as 0-100%. The documented approximation:
    % = (rssi_dbm + 100) * 2  ->  dbm = %/2 - 100  (range -100..-50)."""
    try:
        p = float(str(pct).rstrip('%').strip())
    except (TypeError, ValueError):
        return None
    p = max(0.0, min(100.0, p))
    return p / 2.0 - 100.0


def _wifi_freq_mhz(channel, band: str = ''):
    """Channel number + netsh band label -> center frequency in MHz."""
    try:
        ch = int(str(channel).strip())
    except (TypeError, ValueError):
        return None
    b = (band or '').lower()
    if '6' in b or (1 <= ch <= 233 and b == '' and ch > 14):
        if 1 <= ch <= 233:
            return 5950 + ch * 5
    if '5' in b or (36 <= ch <= 177):
        return 5000 + ch * 5
    if '60' in b or ch in (1, 2, 3, 4, 5, 6) and '60' in b:
        return 58320 + ch * 2160
    if ch == 14:
        return 2484
    if 1 <= ch <= 13:
        return 2407 + ch * 5
    return 5000 + ch * 5 if ch > 14 else None


def _rssi_to_distance_m(rssi_dbm, freq_mhz=None, n=None):
    """Log-distance path-loss model: d = 10^((RSSI_1m - rssi) / (10*n)).
    RSSI_1m is derived from free-space path loss at 1 m for the emitter's
    frequency plus a nominal 15 dBm AP transmit power — the standard
    heuristic when the beacon TX-power field isn't advertised."""
    if rssi_dbm is None:
        return None
    if n is None:
        n = float(CONFIG.get('rf_path_loss_exp', 2.7))
    freq = freq_mhz or 2437
    # FSPL(dB) at 1 m = 20*log10(f_MHz) - 27.55; assume ~15 dBm EIRP beacon.
    rssi_1m = 15.0 - (20.0 * math.log10(max(1.0, freq)) - 27.55)
    return 10.0 ** ((rssi_1m - float(rssi_dbm)) / (10.0 * n))


def _rssi_trend_db_min(hist, now=None):
    """Least-squares slope of recent RSSI samples, in dB/minute.
    Positive = emitter getting stronger (approaching)."""
    now = now or time.time()
    pts = [(t, r) for t, r in hist if now - t <= 90]
    if len(pts) < 3:
        return 0.0
    t0 = pts[0][0]
    xs = [(t - t0) / 60.0 for t, _ in pts]
    ys = [r for _, r in pts]
    xm = sum(xs) / len(xs)
    ym = sum(ys) / len(ys)
    num = sum((x - xm) * (y - ym) for x, y in zip(xs, ys))
    den = sum((x - xm) ** 2 for x in xs)
    return num / den if den > 1e-9 else 0.0


def _fmt_dist(m):
    if m is None:
        return 'n/a'
    return f"{m * 100:.0f}cm" if m < 1 else (f"{m:.1f}m" if m < 1000 else f"{m/1000:.2f}km")


_MAC_RE = re.compile(r'^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$')


def _norm_mac(addr):
    """Normalize any MAC-looking address to lowercase colon form so one
    physical radio is one emitter regardless of source notation."""
    s = str(addr).strip()
    if _MAC_RE.match(s):
        return s.lower().replace('-', ':')
    return s.lower()


# ---- Trilateration -------------------------------------------------------
class Trilaterator:
    """Weighted least-squares 2D trilateration over RSSI-derived ranges.

    Observations are (sensor, lat, lon, rssi_dbm, freq_mhz, ts) per emitter.
    With >=3 sensors at >=~5 m spread it produces a lat/lon fix with an RMS
    residual; fewer observations still yield a distance ring per sensor.
    Positions are projected onto a local equirectangular tangent plane
    (valid for the short baselines RSSI surveys cover)."""

    def __init__(self):
        self.lock = threading.Lock()
        self.obs: dict[str, dict[str, dict]] = {}  # emitter -> sensor -> obs

    def add(self, emitter_key, sensor, lat, lon, rssi_dbm, freq_mhz=None, ts=None):
        if lat is None or lon is None or rssi_dbm is None:
            return
        with self.lock:
            slot = self.obs.setdefault(emitter_key, {})
            slot[sensor] = {
                'sensor': sensor, 'lat': float(lat), 'lon': float(lon),
                'rssi_dbm': float(rssi_dbm), 'freq_mhz': freq_mhz,
                'ts': ts or time.time(),
            }

    def observations(self, emitter_key):
        with self.lock:
            return list(self.obs.get(emitter_key, {}).values())

    def all_obs(self):
        with self.lock:
            return {k: dict(v) for k, v in self.obs.items()}

    def solve(self, emitter_key):
        """Return fix dict or None. Needs >=3 spatially separated sensors."""
        with self.lock:
            obs = list(self.obs.get(emitter_key, {}).values())
        obs = [o for o in obs if o.get('rssi_dbm') is not None]
        if len(obs) < 3:
            return None
        lat0 = sum(o['lat'] for o in obs) / len(obs)
        lon0 = sum(o['lon'] for o in obs) / len(obs)
        kx = 111320.0 * math.cos(math.radians(lat0))   # m per degree lon
        ky = 110540.0                                   # m per degree lat
        pts = [((o['lon'] - lon0) * kx, (o['lat'] - lat0) * ky, o) for o in obs]
        spread = 0.0
        for i in range(len(pts)):
            for j in range(i + 1, len(pts)):
                spread = max(spread, math.hypot(pts[i][0] - pts[j][0],
                                                pts[i][1] - pts[j][1]))
        ds = [max(0.05, _rssi_to_distance_m(o['rssi_dbm'], o.get('freq_mhz')) or 999)
              for _, _, o in pts]
        # Linearize |X - p_i|^2 = d_i^2 against the last equation:
        #   2(p_i - p_n).X = |p_i|^2 - |p_n|^2 - d_i^2 + d_n^2
        xn, yn = pts[-1][0], pts[-1][1]
        dn2 = ds[-1] ** 2
        ata = [[0.0, 0.0], [0.0, 0.0]]
        atb = [0.0, 0.0]
        used = 0
        for i in range(len(pts) - 1):
            xi, yi = pts[i][0], pts[i][1]
            a = 2.0 * (xi - xn)
            b = 2.0 * (yi - yn)
            if abs(a) < 1e-6 and abs(b) < 1e-6:
                continue  # co-located sensor — no information
            c = (xi * xi + yi * yi) - (xn * xn + yn * yn) - ds[i] ** 2 + dn2
            w = 1.0 / (1.0 + ds[i])          # nearer sensors weigh more
            ata[0][0] += w * a * a
            ata[0][1] += w * a * b
            ata[1][1] += w * b * b
            atb[0] += w * a * c
            atb[1] += w * b * c
            used += 1
        ata[1][0] = ata[0][1]
        det = ata[0][0] * ata[1][1] - ata[0][1] * ata[1][0]
        if used < 2 or abs(det) < 1e-9:
            return {'solved': False, 'reason': 'degenerate geometry — sensors '
                    'co-located or collinear', 'n_sensors': len(obs),
                    'spread_m': round(spread, 1)}
        xx = (atb[0] * ata[1][1] - atb[1] * ata[0][1]) / det
        yy = (ata[0][0] * atb[1] - ata[0][1] * atb[0]) / det
        resid = [abs(math.hypot(xx - p[0], yy - p[1]) - d)
                 for p, d in zip(pts, ds)]
        rms = math.sqrt(sum(r * r for r in resid) / len(resid))
        quality = ('good' if rms < 3 and spread >= 20 else
                   'fair' if rms < 15 and spread >= 8 else 'coarse')
        return {
            'solved': True, 'lat': lat0 + yy / ky, 'lon': lon0 + xx / kx,
            'rms_m': round(rms, 1), 'n_sensors': len(obs),
            'spread_m': round(spread, 1), 'quality': quality,
            'method': 'weighted-least-squares / log-distance ranges',
            'updated': time.time(),
            'ranges_m': {o['sensor']: round(d, 1) for (_, _, o), d in zip(pts, ds)},
        }


