# ---- Unified emitter registry -------------------------------------------
class SignalRegistry:
    """Every signal-emitting device the machine can perceive, across all
    media — Wi-Fi beacons, BT/BLE endpoints, WWAN radios, local
    transmitters, RF analysis hardware. Holds RSSI history for distance
    estimation, approach/recession trends, and trilateration fixes."""

    APPROACH_WINDOW_S = 90

    def __init__(self):
        self.lock = threading.RLock()
        self.emitters: dict[str, dict] = {}
        self.events: deque = deque(maxlen=800)
        self.seq = 0
        self._alert_cool: dict[str, float] = {}
        self._event_sink = None

    # -- events ---------------------------------------------------------
    def _emit(self, etype, severity, detail, **kw):
        ev = {'type': etype, 'severity': severity, 'detail': detail,
              'time': time.time()}
        ev.update(kw)
        with self.lock:
            self.events.append(ev)
            self.seq += 1
        sink = self._event_sink
        if sink is not None:
            try:
                sink(ev)
            except Exception:
                pass
        return ev

    def _cool(self, key, secs):
        now = time.time()
        last = self._alert_cool.get(key, 0)
        if now - last < secs:
            return False
        self._alert_cool[key] = now
        return True

    # -- observe ----------------------------------------------------------
    def observe(self, medium, address, name='', rssi_dbm=None, freq_mhz=None,
                band=None, channel=None, sensor='local', extra=None):
        """Record one observation of an emitter. Creates the record on
        first sight and merges fields on every subsequent sighting."""
        if not address:
            return None, False
        address = _norm_mac(address)
        key = f"{medium}:{address}"
        now = time.time()
        created = False
        with self.lock:
            em = self.emitters.get(key)
            if em is None:
                created = True
                em = {
                    'key': key, 'medium': medium,
                    'address': address,
                    'name': name or '', 'vendor': get_vendor(address),
                    'first_seen': now, 'seen_count': 0, 'scans_absent': 0,
                    'rssi_hist': deque(maxlen=90), 'sensors': set(),
                    'status': 'active', 'notes': set(),
                }
                self.emitters[key] = em
            em['last_seen'] = now
            em['seen_count'] += 1
            em['scans_absent'] = 0
            em['status'] = 'active'
            if name and not em['name']:
                em['name'] = name
            if band and not em.get('band'):
                em['band'] = band
            if channel is not None:
                em['channel'] = channel
            if freq_mhz and not em.get('freq_mhz'):
                em['freq_mhz'] = freq_mhz
            if extra:
                ex = em.setdefault('extra', {})
                for k, v in extra.items():
                    if v not in (None, '', [], {}):
                        ex[k] = v
            em['sensors'].add(sensor)
            if rssi_dbm is not None:
                em['rssi_hist'].append((now, float(rssi_dbm)))
                em['rssi_dbm'] = float(rssi_dbm)
                d = _rssi_to_distance_m(rssi_dbm, em.get('freq_mhz'))
                if d is not None:
                    em['dist_m'] = d
            self.seq += 1
            hist_len = len(em['rssi_hist'])
            if hist_len:
                vals = [r for _, r in em['rssi_hist']]
                em['rssi_avg'] = sum(vals) / len(vals)
                em['rssi_min'] = min(vals)
                em['rssi_max'] = max(vals)
            if hist_len >= 3:
                em['rssi_trend_db_min'] = _rssi_trend_db_min(em['rssi_hist'], now)
                slope = em['rssi_trend_db_min']
                thr = float(CONFIG.get('rf_rssi_approach_db_min', 6.0))
                em['dist_trend'] = ('approaching' if slope >= thr else
                                    'receding' if slope <= -thr else 'stable')
            return em, created

    # -- scan completion ---------------------------------------------------
    def mark_scan(self, medium, seen_keys):
        """After a medium's sweep, mark emitters absent and emit LOST events
        once they've missed `rf_lost_after_scans` consecutive sweeps."""
        lost_after = int(CONFIG.get('rf_lost_after_scans', 3))
        out = []
        with self.lock:
            for key, em in self.emitters.items():
                if em['medium'] != medium:
                    continue
                if key in seen_keys:
                    continue
                if em['status'] == 'active':
                    em['scans_absent'] += 1
                    if em['scans_absent'] >= lost_after:
                        em['status'] = 'lost'
                        out.append((key, em))
            self.seq += 1
        for key, em in out:
            self._emit('RF_EMITTER_LOST', 'INFO',
                       f"{em['medium']} emitter gone quiet: "
                       f"{em.get('name') or em['address']} "
                       f"(last rssi {em.get('rssi_dbm','n/a')} dBm, "
                       f"seen x{em['seen_count']})", emitter=key)
        return out

    # -- serialization -----------------------------------------------------
    def snapshot(self, include_lost=True):
        with self.lock:
            out = []
            for em in self.emitters.values():
                if not include_lost and em['status'] != 'active':
                    continue
                d = {k: v for k, v in em.items()
                     if k not in ('rssi_hist', 'sensors', 'notes')}
                d['sensors'] = sorted(em['sensors'])
                d['notes'] = sorted(em['notes'])
                d['rssi_samples'] = len(em['rssi_hist'])
                d['rssi_recent'] = list(em['rssi_hist'])[-24:]
                out.append(d)
        return out

    def stats(self):
        per = {}
        active = lost = 0
        with self.lock:
            for em in self.emitters.values():
                per[em['medium']] = per.get(em['medium'], 0) + 1
                if em['status'] == 'active':
                    active += 1
                else:
                    lost += 1
            return {'total': len(self.emitters), 'active': active,
                    'lost': lost, 'per_medium': per, 'seq': self.seq,
                    'events_buffered': len(self.events)}

    def get_events(self):
        with self.lock:
            return list(self.events)


# ---- Wi-Fi spectrum scanner (netsh wlan) --------------------------------
class WiFiSpectrumScanner:
    """Surveys 2.4/5/6 GHz beacons via `netsh wlan show networks mode=bssid`
    and own-radio state via `netsh wlan show interfaces`. No extra hardware
    needed — the WLAN driver's periodic beacon scan is the RF feed."""

    def __init__(self):
        self.last = {'status': 'never-ran', 'ms': 0, 'err': '', 'aps': 0,
                     'ago': None}
        self._ssid_prev: dict[str, set] = {}
        self._alerted: dict[str, float] = {}

    def _netsh(self, args, timeout=15):
        t0 = time.time()
        out = subprocess.run(
            ['netsh'] + args, capture_output=True, text=True,
            timeout=timeout, creationflags=_CREATE_NO_WINDOW,
            errors='replace').stdout
        return out, (time.time() - t0) * 1000.0

    # -- parsers ---------------------------------------------------------
    @staticmethod
    def _parse_bssid_scan(text):
        aps = []
        ssid = None
        cur = None
        def flush():
            nonlocal cur
            if cur is not None:
                aps.append(cur)
                cur = None
        for raw in text.splitlines():
            line = raw.rstrip()
            m = re.match(r'^SSID\s+\d+\s*:\s*(.*)$', line)
            if m:
                flush()
                ssid = {'ssid': m.group(1).strip(), 'network_type': '',
                        'auth': '', 'cipher': ''}
                continue
            if ssid is None:
                continue
            m = re.match(r'^\s{4}Network type\s*:\s*(.*)$', line)
            if m:
                ssid['network_type'] = m.group(1).strip(); continue
            m = re.match(r'^\s{4}Authentication\s*:\s*(.*)$', line)
            if m:
                ssid['auth'] = m.group(1).strip(); continue
            m = re.match(r'^\s{4}Encryption\s*:\s*(.*)$', line)
            if m:
                ssid['cipher'] = m.group(1).strip(); continue
            m = re.match(r'^\s{4}BSSID\s+(\d+)\s*:\s*([0-9a-fA-F:]{17})', line)
            if m:
                flush()
                cur = dict(ssid)
                cur.update({'bssid': m.group(2).strip().lower(),
                            'signal_pct': None, 'radio_type': '',
                            'band': '', 'channel': None,
                            'basic_rates': '', 'other_rates': '',
                            'stations': None, 'chan_util_pct': None,
                            'colocated': []})
                continue
            if cur is None:
                continue
            m = re.match(r'^\s{5,}Signal\s*:\s*(\d+)\s*%', line)
            if m:
                cur['signal_pct'] = int(m.group(1)); continue
            m = re.match(r'^\s{5,}Radio type\s*:\s*(.*)$', line)
            if m:
                cur['radio_type'] = m.group(1).strip(); continue
            m = re.match(r'^\s{5,}Band\s*:\s*(.*)$', line)
            if m:
                cur['band'] = m.group(1).strip(); continue
            m = re.match(r'^\s{5,}Channel\s*:\s*(\d+)', line)
            if m:
                cur['channel'] = int(m.group(1)); continue
            m = re.match(r'^\s{5,}Basic rates \(Mbps\)\s*:\s*(.*)$', line)
            if m:
                cur['basic_rates'] = ' '.join(m.group(1).split()); continue
            m = re.match(r'^\s{5,}Other rates \(Mbps\)\s*:\s*(.*)$', line)
            if m:
                cur['other_rates'] = ' '.join(m.group(1).split()); continue
            m = re.match(r'^\s{5,}Connected Stations\s*:\s*(\d+)', line)
            if m:
                cur['stations'] = int(m.group(1)); continue
            m = re.match(r'^\s{5,}Channel Utilization\s*:\s*(\d+)', line)
            if m:
                cur['chan_util_pct'] = int(m.group(1)); continue
            m = re.match(r'^\s{5,}BSSID:\s*([0-9a-fA-F:]{17})\s*,\s*Band:\s*([^,]+),\s*Channel:\s*(\d+)', line)
            if m:
                cur['colocated'].append({'bssid': m.group(1).lower(),
                                         'band': m.group(2).strip(),
                                         'channel': int(m.group(3))})
                continue
        flush()
        return aps

    @staticmethod
    def _parse_interfaces(text):
        ifaces = []
        cur = None
        for raw in text.splitlines():
            m = re.match(r'^\s{4}Name\s*:\s*(.*)$', raw)
            if m:
                if cur:
                    ifaces.append(cur)
                cur = {}
                continue
            if cur is None:
                continue
            m = re.match(r'^\s{4}([A-Za-z() /%-]+?)\s*:\s*(.*)$', raw)
            if m:
                key = m.group(1).strip().lower()
                val = m.group(2).strip()
                cur[key] = val
                continue
        if cur:
            ifaces.append(cur)
        return ifaces

    # -- the sweep ----------------------------------------------------------
    def scan(self):
        t0 = time.time()
        res = {'aps': [], 'radios': [], 'events': [], 'status': 'ok',
               'err': ''}
        try:
            out, ms = self._netsh(['wlan', 'show', 'networks', 'mode=bssid'])
            if 'no wireless interface' in out.lower() or 'is not running' in out.lower():
                res['status'] = 'unavailable'
                res['err'] = out.strip().splitlines()[0] if out.strip() else 'no wlan'
            else:
                res['aps'] = self._parse_bssid_scan(out)
            out2, _ = self._netsh(['wlan', 'show', 'interfaces'])
            if 'no wireless interface' not in out2.lower():
                res['radios'] = self._parse_interfaces(out2)
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': res['status'], 'ms': res['ms'],
                         'err': res['err'], 'aps': len(res['aps']),
                         'ago': time.time()}
        except Exception as exc:
            res['status'] = 'error'
            res['err'] = str(exc)
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': 'error', 'ms': res['ms'],
                         'err': str(exc), 'aps': 0, 'ago': time.time()}
        return res


# ---- Bluetooth / BLE radio-frequency scanner ------------------------------
class BluetoothRFScanner:
    """Bluetooth spectrum feed beyond the paired-device registry walk.
    Layer 1: Win32 PnP class 'Bluetooth' — radios + devices whose drivers
    are actually loaded right now (active = in-range). BTHLE* instance IDs
    mark BLE peripherals, BTHENUM classic. Layer 2 (optional): a live
    advertisement sweep via `bleak` (WinRT) yielding real RSSI per device."""

    def __init__(self):
        self.last = {'status': 'never-ran', 'ms': 0, 'err': '', 'devices': 0,
                     'ago': None}
        self.ble_live = {'available': False, 'reason': 'not tried'}
        self._bleak_checked = False
        self._bleak = None
        self._ble_lock = threading.Lock()
        self._ble_last_results = {}
        self._ble_last_ts = 0.0

    # -- PnP enumeration ---------------------------------------------------
    def _pnp_scan(self):
        """Status=OK devices in the Bluetooth PnP class — present/active."""
        try:
            out = subprocess.run(
                ['powershell', '-NoProfile', '-NonInteractive', '-Command',
                 "Get-PnpDevice -Class Bluetooth -ErrorAction SilentlyContinue | "
                 "Select-Object Status, Name, InstanceId | ConvertTo-Json -Compress"],
                capture_output=True, text=True, timeout=25,
                creationflags=_CREATE_NO_WINDOW).stdout.strip()
            if not out:
                return []
            data = json.loads(out)
            if isinstance(data, dict):
                data = [data]
            return data if isinstance(data, list) else []
        except Exception:
            return []

    # -- optional bleak live scan -------------------------------------------
    def _ble_live_scan(self):
        if not CONFIG.get('rf_ble_live_scan', True):
            return
        if not self._bleak_checked:
            self._bleak_checked = True
            try:
                import bleak  # noqa
                self._bleak = True
                self.ble_live = {'available': True,
                                 'reason': 'bleak importable — live adverts on'}
            except Exception:
                self._bleak = False
                self.ble_live = {'available': False,
                                 'reason': 'bleak not installed — install for '
                                           'live BLE adverts + real RSSI'}
        if not self._bleak:
            return
        with self._ble_lock:
            if time.time() - self._ble_last_ts < float(
                    CONFIG.get('rf_bt_interval', 30)):
                return
            self._ble_last_ts = time.time()
        def _work():
            try:
                import asyncio
                from bleak import BleakScanner
                async def _go():
                    try:
                        return await BleakScanner.discover(
                            timeout=float(CONFIG.get('rf_ble_scan_secs', 6)),
                            return_adv=True)
                    except TypeError:
                        # older bleak: no return_adv kwarg
                        return await BleakScanner.discover(
                            timeout=float(CONFIG.get('rf_ble_scan_secs', 6)))
                res = asyncio.run(_go())
                snap = {}
                if isinstance(res, dict):          # bleak>=0.21 return_adv
                    for addr, (dev, adv) in res.items():
                        snap[addr.upper()] = {
                            'name': getattr(dev, 'name', None) or adv.local_name or '',
                            'rssi': getattr(adv, 'rssi', None),
                            'tx_power': getattr(adv, 'tx_power', None),
                            'uuids': list(getattr(adv, 'service_uuids', []) or [])[:8]}
                else:                               # older bleak: list of devices
                    for dev in res or []:
                        addr = getattr(dev, 'address', '')
                        if addr:
                            snap[addr.upper()] = {
                                'name': getattr(dev, 'name', '') or '',
                                'rssi': getattr(dev, 'rssi', None),
                                'tx_power': None, 'uuids': []}
                with self._ble_lock:
                    self._ble_last_results = snap
            except Exception as exc:
                self.ble_live = {'available': False,
                                 'reason': f'bleak scan failed: {exc}'}
        threading.Thread(target=_work, daemon=True,
                         name='BLE-Live-Scan').start()

    def get_ble_snapshot(self):
        with self._ble_lock:
            return dict(self._ble_last_results)

    # -- the sweep ----------------------------------------------------------
    def scan(self):
        t0 = time.time()
        res = {'devices': [], 'radios': [], 'events': [], 'status': 'ok',
               'err': ''}
        try:
            for e in self._pnp_scan():
                inst = e.get('InstanceId', '') or ''
                name = e.get('Name', '') or ''
                status = e.get('Status', '') or ''
                up = inst.upper()
                rec = {'name': name, 'instance': inst, 'status': status,
                       'mac': None, 'kind': 'bt-device'}
                mm = re.search(r'Dev_([0-9A-Fa-f]{12})', inst)
                if mm:
                    raw = mm.group(1).upper()
                    rec['mac'] = ':'.join(raw[i:i + 2] for i in range(0, 12, 2))
                if up.startswith('BTHLE') or '\\BTHLE' in up:
                    rec['kind'] = 'ble'
                elif 'BTHENUM' in up:
                    rec['kind'] = 'bt-classic'
                elif up.startswith('USB\\') or 'BTHUSB' in up:
                    rec['kind'] = 'bt-radio'
                (res['radios'] if rec['kind'] == 'bt-radio'
                 else res['devices']).append(rec)
            self._ble_live_scan()
            res['ble_live'] = self.ble_live
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': 'ok', 'ms': res['ms'], 'err': '',
                         'devices': len(res['devices']) + len(res['radios']),
                         'ago': time.time()}
        except Exception as exc:
            res['status'] = 'error'
            res['err'] = str(exc)
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': 'error', 'ms': res['ms'], 'err': str(exc),
                         'devices': 0, 'ago': time.time()}
        return res


# ---- WWAN / cellular scanner ----------------------------------------------
class WWANScanner:
    """Cellular medium feed via `netsh mbn`. Covers the modem interface
    itself, radio state, signal and registered provider. No tower scan is
    possible without AT access — the feed states that explicitly."""

    def __init__(self):
        self.last = {'status': 'never-ran', 'ms': 0, 'err': '', 'ifaces': 0,
                     'ago': None}

    def scan(self):
        t0 = time.time()
        res = {'ifaces': [], 'status': 'ok', 'err': '', 'note': ''}
        try:
            out = subprocess.run(
                ['netsh', 'mbn', 'show', 'interfaces'], capture_output=True,
                text=True, timeout=15, creationflags=_CREATE_NO_WINDOW).stdout
            low = out.lower()
            if 'not running' in low or 'no interface' in low or not out.strip():
                res['status'] = 'unavailable'
                res['note'] = ('Mobile Broadband service idle/absent — '
                               'no cellular modem enumerated on this host')
            else:
                cur = None
                for raw in out.splitlines():
                    m = re.match(r'^\s{4}Name\s*:\s*(.*)$', raw)
                    if m:
                        if cur:
                            res['ifaces'].append(cur)
                        cur = {}
                        continue
                    if cur is None:
                        continue
                    m = re.match(r'^\s{4}(.+?)\s*:\s*(.*)$', raw)
                    if m:
                        cur[m.group(1).strip().lower()] = m.group(2).strip()
                if cur:
                    res['ifaces'].append(cur)
                if not res['ifaces']:
                    res['status'] = 'unavailable'
                    res['note'] = 'wwansvc up but zero WWAN interfaces'
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': res['status'], 'ms': res['ms'],
                         'err': res['err'], 'ifaces': len(res['ifaces']),
                         'ago': time.time()}
        except Exception as exc:
            res['status'] = 'error'
            res['err'] = str(exc)
            self.last = {'status': 'error', 'ms': 0, 'err': str(exc),
                         'ifaces': 0, 'ago': time.time()}
        return res


# ---- Connection-medium census (every interface/transport) ----------------
class InterfaceCensus:
    """Enumerates every connection medium present on the host — Ethernet,
    Wi-Fi, Bluetooth PAN, WWAN/PPP, tunnels, loopback, virtual adapters —
    with link state, MAC, addresses, speed and MTU, so no transport is
    invisible to the monitor. Classification: psutil + `netsh interface
    show interface` admin/operational type merged."""

    _TYPE_HINTS = [
        (('loopback', 'pseudo-interface', 'km-test'), 'loopback'),
        (('wi-fi direct', 'wifi direct', 'wfd', 'wi-fi display',
          'miracast'), 'wifi-direct'),
        (('wi-fi', 'wifi', 'wireless', '802.11', 'wlan',
          'native 802.11'), 'wifi-802.11'),
        (('bluetooth', 'bt pan', 'personal area network',
          '802.15'), 'bluetooth-pan'),
        (('mbn', 'wwan', 'cellular', 'mobile broadband',
          'mobile bb'), 'wwan-cellular'),
        (('wireguard', 'wintun', 'openvpn', 'tap-', 'tun', 'nordlynx',
          'tailscale', 'zerotier', 'vpn', 'wan miniport',
          'sstp', 'pptp', 'l2tp', 'ikev2', 'gre'), 'vpn-tunnel'),
        (('vethernet', 'hyper-v', 'vmware', 'virtualbox', 'vbox',
          'virtual', 'hyperv', 'wsl', 'docker'), 'virtual-nic'),
        (('teredo', 'isatap', '6to4', 'ipsextunnel',
          'local area connection*'), 'tunnel/transition'),
        (('ethernet', '802.3'), 'ethernet-802.3'),
    ]

    def __init__(self):
        self.last = {'status': 'never-ran', 'ms': 0, 'err': '', 'count': 0,
                     'ago': None}
        self._netsh_types: dict[str, dict] = {}
        self._adapter_desc: dict[str, dict] = {}
        self._desc_ts = 0.0

    @classmethod
    def _classify(cls, text):
        low = (text or '').lower()
        for keys, label in cls._TYPE_HINTS:
            for k in keys:
                if k in low:
                    return label
        return 'unknown-medium'

    def _refresh_adapter_desc(self):
        """Get-NetAdapter gives the true InterfaceDescription — the only
        reliable way to tell a Microsoft Wi-Fi Direct virtual adapter or a
        Bluetooth PAN from a tunnel by name. Slow (~1s), cached 5 min."""
        if not _IS_WINDOWS:
            return
        if time.time() - self._desc_ts < 300 and self._adapter_desc:
            return
        try:
            out = subprocess.run(
                ['powershell', '-NoProfile', '-NonInteractive', '-Command',
                 "Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue | "
                 "Select-Object Name, InterfaceDescription, MediaType, Status, "
                 "LinkSpeed | ConvertTo-Json -Compress"],
                capture_output=True, text=True, timeout=25,
                creationflags=_CREATE_NO_WINDOW).stdout.strip()
            if not out:
                return
            data = json.loads(out)
            if isinstance(data, dict):
                data = [data]
            for a in data or []:
                nm = a.get('Name', '')
                if nm:
                    self._adapter_desc[nm] = {
                        'desc': a.get('InterfaceDescription', '') or '',
                        'media_type': a.get('MediaType', '') or '',
                        'link_speed': a.get('LinkSpeed', '') or '',
                    }
            self._desc_ts = time.time()
        except Exception:
            pass

    def _refresh_netsh_types(self):
        try:
            out = subprocess.run(
                ['netsh', 'interface', 'show', 'interface'],
                capture_output=True, text=True, timeout=12,
                creationflags=_CREATE_NO_WINDOW).stdout
            for line in out.splitlines():
                m = re.match(r'^\s*(\S+)\s+(\S+)\s+(\S+)\s+(.+?)\s*$', line)
                if not m or m.group(1).lower() == 'admin':
                    continue
                self._netsh_types[m.group(4).strip()] = {
                    'admin_state': m.group(1), 'state': m.group(2),
                    'netsh_type': m.group(3)}
        except Exception:
            pass

    def scan(self):
        t0 = time.time()
        res = {'interfaces': [], 'status': 'ok', 'err': ''}
        try:
            self._refresh_netsh_types()
            self._refresh_adapter_desc()
            addrs = psutil.net_if_addrs()
            stats = psutil.net_if_stats()
            for name, addr_list in addrs.items():
                st = stats.get(name)
                macs = [a.address for a in addr_list
                        if _MAC_RE.match(a.address or '')]
                ips = [f"{a.address}" for a in addr_list
                       if getattr(a, 'family', None) in (2, 10)]
                nt = self._netsh_types.get(name, {})
                ad = self._adapter_desc.get(name, {})
                desc = ad.get('desc', '')
                medium = self._classify(f"{name} {desc} {ad.get('media_type','')}")
                rec = {
                    'name': name,
                    'medium': medium,
                    'desc': desc,
                    'media_type': ad.get('media_type', ''),
                    'link_speed': ad.get('link_speed', ''),
                    'mac': _norm_mac(macs[0]) if macs else '',
                    'ips': ips[:6], 'up': bool(st.isup) if st else False,
                    'speed_mbps': st.speed if st else 0,
                    'mtu': st.mtu if st else 0,
                    'duplex': str(st.duplex).split('.')[-1] if st and getattr(st, 'duplex', None) else '',
                    'admin_state': nt.get('admin_state', ''),
                    'oper_state': nt.get('state', 'up' if st and st.isup else 'down'),
                    'netsh_type': nt.get('netsh_type', ''),
                    'addr_count': len(addr_list),
                }
                res['interfaces'].append(rec)
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': 'ok', 'ms': res['ms'], 'err': '',
                         'count': len(res['interfaces']), 'ago': time.time()}
        except Exception as exc:
            res['status'] = 'error'
            res['err'] = str(exc)
            self.last = {'status': 'error', 'ms': 0, 'err': str(exc),
                         'count': 0, 'ago': time.time()}
        return res


# ---- RF-capable hardware detector -----------------------------------------
class RFHardwareDetector:
    """Walks the USB device tree for known radios and analysis gear —
    SDR dongles, Zigbee/Z-Wave/NFC interfaces, proprietary 2.4 GHz receiver
    dongles — and checks PATH for SDR tools. Tells the coverage matrix
    which spectrums are physically observable on this host."""

    def __init__(self):
        self.last = {'status': 'never-ran', 'ms': 0, 'err': '', 'count': 0,
                     'ago': None}
        self.tools: list[str] = []

    def _usb_enum(self):
        devs = []
        if not _IS_WINDOWS:
            return devs
        try:
            with winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"SYSTEM\CurrentControlSet\Enum\USB", 0,
                    winreg.KEY_READ) as root:
                i = 0
                while True:
                    try:
                        vidpid = winreg.EnumKey(root, i)
                        i += 1
                    except OSError:
                        break
                    if 'VID_' not in vidpid.upper():
                        continue
                    friendly = ''
                    try:
                        with winreg.OpenKey(root, vidpid) as vk:
                            j = 0
                            while True:
                                try:
                                    inst = winreg.EnumKey(vk, j)
                                    j += 1
                                    try:
                                        with winreg.OpenKey(vk, inst) as ik:
                                            v, _ = winreg.QueryValueEx(
                                                ik, 'FriendlyName')
                                            friendly = v or friendly
                                    except Exception:
                                        pass
                                except OSError:
                                    break
                    except Exception:
                        pass
                    devs.append({'id': vidpid, 'name': friendly})
        except Exception:
            pass
        return devs

    def scan(self):
        t0 = time.time()
        res = {'hardware': [], 'tools': [], 'status': 'ok', 'err': ''}
        try:
            seen_sig: dict[str, dict] = {}
            for dev in self._usb_enum():
                up = dev['id'].upper()
                for sig, (label, capability) in _RF_USB_TABLE.items():
                    if sig in up:
                        ent = seen_sig.setdefault(sig, {
                            'id': dev['id'], 'label': label,
                            'name': dev['name'] or label,
                            'capability': capability,
                            'vid_pid': sig, 'instances': 0})
                        ent['instances'] += 1
                        if dev['name'] and not ent['name']:
                            ent['name'] = dev['name']
                        break
            res['hardware'] = list(seen_sig.values())
            self.tools = [t for t in _SDR_TOOLS if shutil.which(t)]
            res['tools'] = list(self.tools)
            res['ms'] = round((time.time() - t0) * 1000, 1)
            self.last = {'status': 'ok', 'ms': res['ms'], 'err': '',
                         'count': len(res['hardware']), 'ago': time.time()}
        except Exception as exc:
            res['status'] = 'error'
            res['err'] = str(exc)
            self.last = {'status': 'error', 'ms': 0, 'err': str(exc),
                         'count': 0, 'ago': time.time()}
        return res


# ---- Spectrum hub: orchestrates every medium feed --------------------------
class SpectrumHub:
    """One object owning all non-IP signal feeds. tick() runs each scanner
    on its own cadence, feeds the SignalRegistry, ingests external sensor
    observations for trilateration, solves fixes, and buffers labeled
    events for the monitor/UI."""

    MEDIUMS = {
        'wifi-ap':     'Wi-Fi access point beacons (2.4/5/6 GHz)',
        'wifi-radio':  'Local Wi-Fi radio (own transmitter)',
        'wifi-direct': 'Wi-Fi Direct / Miracast virtual adapters',
        'bt-radio':    'Local Bluetooth radio (own transmitter)',
        'bt-classic':  'Bluetooth classic devices (BR/EDR)',
        'ble':         'Bluetooth Low-Energy advertisers',
        'wwan-modem':  'Cellular / mobile-broadband modem',
        'local-radio': 'Other local RF transmitters',
        'rf-hw':       'RF analysis hardware (SDR/Zigbee/NFC dongles)',
        'local-iface': 'Wired/virtual host interfaces (non-RF transports)',
        'l2-wire':     'Layer-2 wire talkers — every MAC emitting frames '
                       '(IP, ARP, non-IP ethertypes, discovery chatter)',
    }

    def __init__(self, local_geo_fn=None):
        self.registry = SignalRegistry()
        self.trilat = Trilaterator()
        self.wifi = WiFiSpectrumScanner()
        self.bt = BluetoothRFScanner()
        self.wwan = WWANScanner()
        self.ifaces = InterfaceCensus()
        self.rfhw = RFHardwareDetector()
        self._local_geo_fn = local_geo_fn
        self._events: deque = deque(maxlen=800)   # drained by monitor thread
        self._ui_events: deque = deque(maxlen=400)  # persistent UI feed copy
        self.seq = 0
        self.enabled = bool(CONFIG.get('rf_monitor_enabled', True))
        self._last_run: dict[str, float] = {}
        self._results: dict[str, dict] = {}
        self._fixes: dict[str, dict] = {}
        self._fix_seq = 0
        self._obs_received = 0
        self._obs_file_pos = 0
        self._obs_file_err = ''
        self._scan_cycle = 0
        self._evil_last: dict[str, float] = {}
        self._hw_sig = ''
        self.lock = threading.RLock()
        self._sensors: dict[str, dict] = {}
        for s in CONFIG.get('rf_sensors') or []:
            try:
                self._sensors[str(s.get('name') or f"sensor{len(self._sensors)}")] = {
                    'lat': float(s['lat']), 'lon': float(s['lon']),
                    'source': 'config'}
            except Exception:
                pass

    # -- helpers -------------------------------------------------------------
    def _ev(self, etype, severity, detail, **kw):
        ev = {'type': etype, 'severity': severity, 'detail': detail,
              'time': time.time()}
        ev.update(kw)
        with self.lock:
            self._events.append(ev)
            self._ui_events.append(ev)
            self.seq += 1

    def _due(self, name, interval_key, default):
        now = time.time()
        interval = float(CONFIG.get(interval_key, default))
        if now - self._last_run.get(name, -1e9) < interval:
            return False
        self._last_run[name] = now
        return True

    def _local_pos(self):
        try:
            g = self._local_geo_fn() if self._local_geo_fn else None
            if isinstance(g, dict):
                lat, lon = g.get('lat'), g.get('lon')
                if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                    return float(lat), float(lon)
        except Exception:
            pass
        return None, None

    # -- per-medium processing -------------------------------------------------
    def _process_wifi(self, res):
        lat, lon = self._local_pos()
        seen = set()
        connected_bssid = ''
        for radio in res.get('radios', []):
            bssid = (radio.get('ap bssid') or '').lower()
            if bssid:
                connected_bssid = bssid
            mac = (radio.get('physical address') or '').lower()
            if mac:
                self.registry.observe(
                    'wifi-radio', mac,
                    name=f"{radio.get('name','Wi-Fi')} ({radio.get('description','')[:40]})",
                    rssi_dbm=None, freq_mhz=_wifi_freq_mhz(
                        radio.get('channel'), radio.get('band', '')),
                    band=radio.get('band'), channel=radio.get('channel'),
                    extra={'role': 'local-transmitter',
                           'state': radio.get('state'),
                           'ssid': radio.get('ssid'),
                           'rssi_to_ap_dbm': radio.get('rssi'),
                           'rx_rate_mbps': radio.get('receive rate (mbps)'),
                           'tx_rate_mbps': radio.get('transmit rate (mbps)'),
                           'auth': radio.get('authentication'),
                           'radio_type': radio.get('radio type'),
                           'profile': radio.get('profile')})
                seen.add(f"wifi-radio:{mac}")
        for ap in res.get('aps', []):
            ssid = ap.get('ssid') or ''
            hidden = not ssid
            dbm = _sig_pct_to_dbm(ap.get('signal_pct'))
            freq = _wifi_freq_mhz(ap.get('channel'), ap.get('band', ''))
            em, created = self.registry.observe(
                'wifi-ap', ap['bssid'],
                name=ssid or '(hidden SSID)',
                rssi_dbm=dbm, freq_mhz=freq, band=ap.get('band'),
                channel=ap.get('channel'),
                extra={
                    'ssid': ssid, 'hidden': hidden,
                    'auth': ap.get('auth'), 'cipher': ap.get('cipher'),
                    'radio_type': ap.get('radio_type'),
                    'network_type': ap.get('network_type'),
                    'signal_pct': ap.get('signal_pct'),
                    'basic_rates_mbps': ap.get('basic_rates'),
                    'other_rates_mbps': ap.get('other_rates'),
                    'stations': ap.get('stations'),
                    'chan_util_pct': ap.get('chan_util_pct'),
                    'colocated_aps': ap.get('colocated'),
                    'connected': ap['bssid'] == connected_bssid,
                })
            seen.add(f"wifi-ap:{ap['bssid']}")
            if dbm is not None and lat is not None:
                self.trilat.add(f"wifi-ap:{ap['bssid']}", 'local', lat, lon,
                                dbm, freq)
            if created:
                kind = 'hidden SSID' if hidden else f"SSID '{ssid}'"
                self._ev('RF_NEW_EMITTER', 'INFO',
                         f"Wi-Fi AP beacons first heard: {kind} on "
                         f"{ap.get('band','?')} ch{ap.get('channel','?')} "
                         f"({ap['bssid']}, {get_vendor(ap['bssid'])}, "
                         f"rssi {dbm:.0f} dBm ≈ "
                         f"{_fmt_dist(em.get('dist_m'))})",
                         emitter=f"wifi-ap:{ap['bssid']}", medium='wifi-ap')
                if hidden:
                    self._ev('RF_HIDDEN_AP', 'WARNING',
                             f"Hidden-SSID AP broadcasting without a name: "
                             f"{ap['bssid']} ({get_vendor(ap['bssid'])}) — "
                             f"unlabeled emitters are classic rogue-AP cover",
                             emitter=f"wifi-ap:{ap['bssid']}")
            auth = (ap.get('auth') or '').lower()
            if 'open' in auth or (not ap.get('auth') and not ap.get('cipher')):
                if self.registry._cool(f"open:{ap['bssid']}", 1800):
                    self._ev('RF_OPEN_AP', 'WARNING',
                             f"Open/unencrypted AP: '{ssid or '(hidden)'}' "
                             f"({ap['bssid']}) ch{ap.get('channel','?')} — "
                             f"traffic fully sniffable in the clear",
                             emitter=f"wifi-ap:{ap['bssid']}")
        # Evil-twin cross-check: one SSID advertised by multiple BSSIDs with
        # different vendors or security settings is the classic rogue-AP tell.
        by_ssid: dict[str, list] = {}
        for ap in res.get('aps', []):
            s = (ap.get('ssid') or '').strip().lower()
            if s:
                by_ssid.setdefault(s, []).append(ap)
        now = time.time()
        for ssid, lst in by_ssid.items():
            if len(lst) < 2:
                continue
            auths = {(a.get('auth') or '').strip().lower() for a in lst}
            vendors = {get_vendor(a['bssid']) for a in lst}
            if len(auths) > 1 or len(vendors) > 1:
                key = f"twin:{ssid}"
                if now - self._evil_last.get(key, 0) < float(
                        CONFIG.get('rf_evil_twin_cooldown', 600)):
                    continue
                self._evil_last[key] = now
                bss = ', '.join(f"{a['bssid']}({get_vendor(a['bssid'])},"
                                f"{a.get('auth','?')})" for a in lst[:6])
                self._ev('RF_EVIL_TWIN_SUSPECT', 'WARNING',
                         f"SSID '{ssid}' advertised by {len(lst)} differing "
                         f"transmitters — possible evil-twin/roque AP: {bss}",
                         medium='wifi-ap', ssid=ssid,
                         deduct={'category': 'RF_EVIL_TWIN', 'score': 45,
                                 'severity': 'WARNING',
                                 'evidence': [
                                     f"SSID: {ssid}",
                                     f"Transmitters: {bss}",
                                     'Legit mesh/roaming keeps one vendor + auth; '
                                     'mixed vendors/auth = spoof suspect']})
        # Only absence-mark on a *conclusive* sweep — 'ok' or 'unavailable'
        # (interface genuinely absent) count; 'error' is inconclusive.
        if res.get('status') in ('ok', 'unavailable'):
            self.registry.mark_scan('wifi-ap', seen)
            self.registry.mark_scan('wifi-radio', {k for k in seen
                                                   if k.startswith('wifi-radio:')})
        return res

    def _process_bt(self, res):
        seen = set()
        for dev in res.get('devices', []):
            addr = dev.get('mac') or dev.get('instance') or ''
            kind = dev.get('kind', 'bt-classic')
            medium = 'ble' if kind == 'ble' else 'bt-classic'
            em, created = self.registry.observe(
                medium, addr, name=dev.get('name', ''),
                extra={'pnp_status': dev.get('status'),
                       'instance_id': dev.get('instance'),
                       'active_in_range': dev.get('status') == 'OK'})
            seen.add(f"{medium}:{addr.lower()}")
            if created:
                self._ev('RF_NEW_EMITTER', 'INFO',
                         f"{medium.upper()} device enumerated active: "
                         f"{dev.get('name') or addr} "
                         f"(status {dev.get('status','?')})",
                         emitter=f"{medium}:{addr.lower()}", medium=medium)
        for radio in res.get('radios', []):
            addr = radio.get('instance') or ''
            em, _ = self.registry.observe(
                'bt-radio', addr, name=radio.get('name', ''),
                extra={'role': 'local-transmitter',
                       'pnp_status': radio.get('status')})
            seen.add(f"bt-radio:{addr.lower()}")
        # Optional bleak live adverts (real RSSI for every advertiser)
        lat, lon = self._local_pos()
        for addr, adv in self.bt.get_ble_snapshot().items():
            em, created = self.registry.observe(
                'ble', addr.lower(), name=adv.get('name', ''),
                rssi_dbm=adv.get('rssi'), freq_mhz=2437,
                extra={'live_advert': True,
                       'tx_power': adv.get('tx_power'),
                       'service_uuids': adv.get('uuids')})
            seen.add(f"ble:{addr.lower()}")
            if adv.get('rssi') is not None and lat is not None:
                self.trilat.add(f"ble:{addr.lower()}", 'local', lat, lon,
                                adv['rssi'], 2437)
        # Empty PnP results are inconclusive (a silent powershell failure
        # looks identical to "no BT") — only absence-mark when something
        # was actually enumerated this sweep.
        if res.get('status') == 'ok' and (res.get('devices')
                                        or res.get('radios')
                                        or self.bt.get_ble_snapshot()):
            for medium in ('bt-classic', 'ble', 'bt-radio'):
                self.registry.mark_scan(medium, {k for k in seen
                                                 if k.startswith(f"{medium}:")})
        return res

    def _process_wwan(self, res):
        seen = set()
        for iface in res.get('ifaces', []):
            name = iface.get('name', 'wwan')
            desc = iface.get('description', '')
            self.registry.observe(
                'wwan-modem', name.lower(),
                name=desc or name,
                extra={k: v for k, v in iface.items()},
                rssi_dbm=_sig_pct_to_dbm(iface.get('signal')))
            seen.add(f"wwan-modem:{name.lower()}")
        if res.get('status') in ('ok', 'unavailable'):
            self.registry.mark_scan('wwan-modem', seen)
        return res

    def _process_ifaces(self, res):
        seen = set()
        for it in res.get('interfaces', []):
            medium = it.get('medium', 'unknown-medium')
            mac = it.get('mac') or ''
            name = it['name']
            if medium == 'wifi-802.11' and mac:
                em_medium, ident = 'wifi-radio', mac
            elif medium == 'wifi-direct':
                em_medium, ident = 'wifi-direct', mac or name.lower()
            elif medium == 'bluetooth-pan':
                em_medium, ident = 'local-radio', name.lower()
            elif medium == 'wwan-cellular':
                em_medium, ident = 'wwan-modem', name.lower()
            else:
                em_medium, ident = 'local-iface', name.lower()
            self.registry.observe(
                em_medium, ident,
                name=f"{name} ({it.get('desc') or it.get('medium','?')})",
                extra={'role': 'local-interface', 'medium_class': medium,
                       'up': it.get('up'), 'speed_mbps': it.get('speed_mbps'),
                       'mtu': it.get('mtu'), 'ips': it.get('ips'),
                       'oper_state': it.get('oper_state'),
                       'admin_state': it.get('admin_state'),
                       'mac': mac, 'link_speed': it.get('link_speed')})
            seen.add(f"{em_medium}:{_norm_mac(ident)}")
        if res.get('status') == 'ok':
            for medium in ('local-radio', 'local-iface', 'wifi-direct',
                           'wwan-modem'):
                self.registry.mark_scan(medium, {k for k in seen
                                                 if k.startswith(f"{medium}:")})
        return res

    def _process_rfhw(self, res):
        seen = set()
        sig = '|'.join(sorted(h['id'] for h in res.get('hardware', [])))
        for hw in res.get('hardware', []):
            key = f"rf-hw:{hw['id'].lower()}"
            self.registry.observe(
                'rf-hw', hw['id'].lower(), name=hw['label'],
                extra={'role': 'analysis-gear', 'name': hw.get('name'),
                       'capability': hw['capability'],
                       'vid_pid': hw['vid_pid']})
            seen.add(key)
        if sig != self._hw_sig:
            new = [h for h in res.get('hardware', [])
                   if h['id'] not in self._hw_sig]
            for h in new:
                self._ev('RF_HARDWARE_FOUND', 'WARNING' if 'SDR' in
                         h['capability'] or 'transceiver' in h['capability']
                         else 'INFO',
                         f"RF-capable hardware detected: {h['label']} — "
                         f"{h['capability']} [{h['id']}]",
                         hardware=h['id'])
            self._hw_sig = sig
        if res.get('status') == 'ok':
            self.registry.mark_scan('rf-hw', seen)
        return res

    def _process_wire(self, talkers, lan_devices=None):
        """Flush the sniffer's per-MAC census into the emitter registry.

        Every source MAC seen on the wire becomes a traced 'l2-wire'
        emitter labelled with the ethertypes it speaks, the L3 identities
        it claims (src/ARP/ND), the discovery services it announces, and
        derived roles (ipv6-router, discovery-announcer, raw-ethertype-
        channel, never-speaks-ip…). When the monitor's LAN-device table
        is passed in, matching emitters pick up the device record's
        hostname/OS-guess/open-ports/JA4 — the wire talker becomes a
        named, fingerprinted device. Stale rows are pruned back into the
        caller's table; quiet emitters get absent-marked per scan rules.
        """
        now = time.time()
        seen = set()
        total = nonip = created_n = emitted_n = 0
        roles_seen: set = set()
        svcs: set = set()
        active_horizon = float(CONFIG.get('rf_l2_active_s', 120))
        drop_after = float(CONFIG.get('rf_l2_drop_s', 3600))
        dev_by_mac = {}
        if lan_devices:
            for dv in lan_devices.values():
                if isinstance(dv, dict) and dv.get('mac'):
                    dev_by_mac.setdefault(_norm_mac(dv['mac']), dv)
        own_macs = set()
        for it in (self._results.get('ifaces', {}) or {}) \
                .get('interfaces', []):
            if it.get('mac'):
                own_macs.add(_norm_mac(it['mac']))
        for r in (self._results.get('wifi', {}) or {}).get('radios', []):
            if r.get('physical address'):
                own_macs.add(_norm_mac(r['physical address']))
        try:
            items = list(talkers.items())
        except Exception:
            items = []
        for mac, rec in items:
            if not isinstance(rec, dict):
                continue
            last = rec.get('last') or 0.0
            if now - last > drop_after:
                try:
                    talkers.pop(mac, None)
                except Exception:
                    pass
                continue
            total += 1
            ets = rec.get('ets') or set()
            et_names = sorted(
                _ETHERTYPE_NAMES.get(
                    e, 'llc/802.3' if isinstance(e, int) and e < 0x0600
                    else f"0x{e:04x}") for e in ets)
            speaks_ip = bool(ets & {0x0800, 0x86DD})
            nonip_ets = [e for e in ets if isinstance(e, int)
                         and e >= 0x0600 and e not in _RAWETH_OK]
            svc = rec.get('svc') or set()
            svcs.update(svc)
            roles = []
            if 'ipv6-nd-router-adv' in svc:
                roles.append('ipv6-router')
            if 'DHCPv4-server-side' in svc or 'DHCPv6-server-side' in svc:
                roles.append('dhcp-server')
            if svc & {'mDNS/Bonjour', 'SSDP/UPnP', 'WS-Discovery', 'LLMNR',
                      'NetBIOS-name-svc', 'NetBIOS-datagram',
                      'Dropbox-LAN-beacon'}:
                roles.append('discovery-announcer')
            if svc & {'arp-is-at', 'arp-who-has'}:
                roles.append('arp-speaker')
            if 'ipv6-nd-neighbor-adv' in svc:
                roles.append('ipv6-nd-speaker')
            if nonip_ets:
                roles.append('raw-ethertype-channel')
            if (rec.get('fwd') or 0) >= 5:
                roles.append('gateway/forwarder')
            if ets and not speaks_ip and 0x0806 not in ets:
                roles.append('never-speaks-ip')
            dv = dev_by_mac.get(_norm_mac(mac))
            if _norm_mac(mac) in own_macs:
                roles.append('this-host')
            if dv:
                if dv.get('open_ports'):
                    roles.append(f"service-host:{len(dv['open_ports'])}ports")
                roles.append('lan-device')
            if not roles:
                roles.append('ip-endpoint' if speaks_ip else 'l2-only')
            roles_seen.update(roles)
            if nonip_ets:
                nonip += 1
            key = f"l2-wire:{_norm_mac(mac)}"
            em, created = self.registry.observe(
                'l2-wire', mac, sensor='wire',
                name=(dv or {}).get('hostname') or '',
                extra={
                    'ethertypes_spoken': et_names,
                    'claimed_ips': sorted(rec.get('ips') or [])[:16],
                    'announces': sorted(svc),
                    'roles': roles,
                    'frames_counted': rec.get('pkts', 0),
                    'speaks_ip': speaks_ip,
                    'non_ip_ethertypes': [f"0x{e:04x}"
                                          for e in sorted(nonip_ets)],
                    'forwarded_public_srcs': rec.get('fwd', 0),
                    'device_hostname': (dv or {}).get('hostname'),
                    'device_os_guess': (dv or {}).get('os_guess'),
                    'device_open_ports': (dv or {}).get('open_ports'),
                    'device_ja4': (dv or {}).get('ja4'),
                    'device_confidence': (dv or {}).get('confidence'),
                    'first_frame': _fmt_ts(rec.get('first')),
                    'last_frame': _fmt_ts(last),
                })
            if last and now - last <= active_horizon:
                seen.add(key)
            if created:
                created_n += 1
                if emitted_n < 25:
                    emitted_n += 1
                    self._ev(
                        'RF_NEW_EMITTER', 'INFO',
                        f"L2 wire talker first heard: {mac} "
                        f"({get_vendor(mac)}) speaking "
                        f"{'/'.join(et_names[:4]) or 'frames'} — "
                        f"roles {', '.join(roles)}"
                        + (f"; announces {', '.join(sorted(svc)[:4])}"
                           if svc else '')
                        + (f"; claims {', '.join(sorted(rec.get('ips') or [])[:3])}"
                           if rec.get('ips') else ''),
                        emitter=key, medium='l2-wire')
        if created_n > emitted_n:
            self._ev('RF_NEW_EMITTER', 'INFO',
                     f"L2 wire census: +{created_n - emitted_n} more new "
                     f"wire talkers this flush (tracked {total}) — see "
                     f"EMITTERS TRACKED → l2-wire for the full roll",
                     medium='l2-wire')
        if seen:
            self.registry.mark_scan('l2-wire', seen)
        return {'status': 'ok', 'ago': now, 'talkers': total,
                'non_ip_channel': nonip,
                'roles': sorted(roles_seen), 'services': sorted(svcs),
                'new_this_flush': created_n}

    # -- external sensor observations ------------------------------------------
    def _ingest_obs_file(self):
        """External sensors drop JSONL observations into rf_obs_file:
        {"sensor":"name","lat":..,"lon":..,"key":"wifi-ap:aa:bb..","rssi":-55,
         "freq_mhz":2437,"medium":"wifi-ap","address":"aa:bb:cc..","name":"x"}
        Each line is ingested once; the file can be appended forever."""
        path = CONFIG.get('rf_obs_file', 'medianbox_rf_observations.json')
        if not path or not os.path.exists(path):
            self._obs_file_err = '' if not path else 'file absent'
            return
        try:
            size = os.path.getsize(path)
            if size < self._obs_file_pos:      # truncated/rotated
                self._obs_file_pos = 0
            with open(path, encoding='utf-8', errors='replace') as f:
                f.seek(self._obs_file_pos)
                chunk = f.read()
                self._obs_file_pos = f.tell()
        except Exception as exc:
            self._obs_file_err = str(exc)
            return
        for line in chunk.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue
            sensor = str(o.get('sensor') or 'external')
            lat, lon = o.get('lat'), o.get('lon')
            if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                self._sensors.setdefault(sensor, {
                    'lat': float(lat), 'lon': float(lon),
                    'source': 'obs-file'})
            key = o.get('key')
            medium = o.get('medium')
            addr = o.get('address')
            if not key and medium and addr:
                key = f"{medium}:{str(addr).lower()}"
            if not key:
                continue
            rssi = o.get('rssi')
            freq = o.get('freq_mhz')
            if key not in self.registry.emitters and medium and addr:
                self.registry.observe(medium, addr, name=o.get('name', ''),
                                      rssi_dbm=None, freq_mhz=freq,
                                      sensor=sensor)
            if isinstance(lat, (int, float)) and isinstance(lon, (int, float)) \
                    and isinstance(rssi, (int, float)):
                self.trilat.add(key, sensor, lat, lon, rssi, freq)
                self._obs_received += 1
        self._obs_file_err = ''

    # -- trilateration ----------------------------------------------------------
    def _solve_fixes(self):
        for key in list(self.trilat.obs.keys()):
            fix = self.trilat.solve(key)
            if fix is None:
                continue
            prev = self._fixes.get(key)
            if fix.get('solved'):
                self._fixes[key] = fix
                em = self.registry.emitters.get(key)
                if em is not None:
                    em['geo_fix'] = fix
                if not (prev and prev.get('solved')):
                    self._ev('RF_TRILATERATED', 'WARNING',
                             f"Emitter located: {key} ≈ "
                             f"({fix['lat']:.5f}, {fix['lon']:.5f}) "
                             f"rms±{fix['rms_m']}m from "
                             f"{fix['n_sensors']} sensors "
                             f"[{fix['quality']}]",
                             emitter=key, fix=fix)
            elif fix.get('reason') and prev is None:
                self._fixes[key] = fix

    # -- main tick ----------------------------------------------------------------
    def tick(self, wire_talkers=None, lan_devices=None):
        if not self.enabled:
            return
        self._scan_cycle += 1
        if wire_talkers is not None and self._due(
                'l2wire', 'rf_l2_flush_interval', 15):
            self._results['l2wire'] = self._process_wire(
                wire_talkers, lan_devices=lan_devices)
        if self._due('wifi', 'rf_wifi_interval', 15):
            self._results['wifi'] = self._process_wifi(self.wifi.scan())
        if self._due('bt', 'rf_bt_interval', 30):
            self._results['bt'] = self._process_bt(self.bt.scan())
        if self._due('wwan', 'rf_wwan_interval', 60):
            self._results['wwan'] = self._process_wwan(self.wwan.scan())
        if self._due('ifaces', 'rf_iface_interval', 30):
            self._results['ifaces'] = self._process_ifaces(self.ifaces.scan())
        if self._due('rfhw', 'rf_hw_interval', 120):
            self._results['rfhw'] = self._process_rfhw(self.rfhw.scan())
        self._ingest_obs_file()
        self._solve_fixes()
        db = getattr(self, 'db', None)
        if db is not None and CONFIG.get('db_persist_emitters', True)                 and self._scan_cycle % max(1, int(CONFIG.get(
                    'db_persist_interval_scans', 20))) == 0:
            try:
                db.save_emitters(self.registry.snapshot())
            except Exception:
                pass
        # approach alerts — emitters with a sustained rising RSSI inside the
        # alert radius get a proximity flag (someone physically closing in)
        thr_m = float(CONFIG.get('rf_approach_alert_m', 8.0))
        for em in self.registry.snapshot():
            if em.get('dist_trend') == 'approaching' and \
                    em.get('dist_m') is not None and em['dist_m'] <= thr_m:
                if self.registry._cool(f"appr:{em['key']}", 300):
                    self._ev('RF_APPROACHING', 'WARNING',
                             f"{em['medium']} emitter approaching: "
                             f"{em.get('name') or em['address']} now ≈ "
                             f"{_fmt_dist(em['dist_m'])} "
                             f"(+{em.get('rssi_trend_db_min', 0):.1f} dB/min) — "
                             f"transmitter physically closing in",
                             emitter=em['key'])
        self.seq = self.registry.seq + self._fix_seq

    def drain_events(self):
        """New events since the last drain. _ui_events is never cleared —
        the UI's raw-feed block keeps the full history."""
        with self.lock:
            out = list(self._events)
            self._events.clear()
        return out

    # -- snapshots for UI ---------------------------------------------------------
    def _scanner_meta(self):
        out = {}
        for name, sc in (('wifi-bssid', self.wifi), ('bt-pnp-ble', self.bt),
                         ('wwan-mbn', self.wwan), ('iface-census', self.ifaces),
                         ('rf-hardware', self.rfhw)):
            st = dict(sc.last)
            if st.get('ago'):
                st['ago_s'] = round(time.time() - st['ago'], 1)
            out[name] = st
        lw = dict(self._results.get('l2wire', {}))
        if lw:
            if lw.get('ago'):
                lw['ago_s'] = round(time.time() - lw['ago'], 1)
            out['l2-wire-census'] = lw
        return out

    def coverage(self):
        """Per-medium coverage matrix — what we can hear and how."""
        w = self._results.get('wifi', {})
        b = self._results.get('bt', {})
        u = self._results.get('wwan', {})
        i = self._results.get('ifaces', {})
        h = self._results.get('rfhw', {})
        hw_caps = ' '.join(x.get('capability', '') for x in h.get('hardware', []))
        ble_live = self.bt.ble_live.get('available')
        rows = [
            {'medium': 'Wi-Fi AP beacons', 'spectrum': '2.4/5/6 GHz 802.11',
             'method': 'netsh wlan BSSID survey (driver beacon scan)',
             'state': ('LIVE' if w.get('status') == 'ok' else
                       w.get('status', 'pending').upper()),
             'detail': f"{len(w.get('aps', []))} BSSIDs this sweep"},
            {'medium': 'Bluetooth classic', 'spectrum': '2.4 GHz BR/EDR',
             'method': 'PnP Bluetooth class enumeration + registry',
             'state': 'LIVE' if b.get('status') == 'ok' else 'PENDING',
             'detail': f"{sum(1 for d in b.get('devices', []) if d.get('kind') == 'bt-classic')} active"},
            {'medium': 'Bluetooth LE adverts', 'spectrum': '2.4 GHz BLE',
             'method': ('bleak live advert sweep' if ble_live else
                        'PnP BTHLE enumeration (no live RSSI — install bleak)'),
             'state': 'LIVE' if ble_live else
                      ('ENUMERATED' if b.get('status') == 'ok' else 'PENDING'),
             'detail': self.bt.ble_live.get('reason', '')},
            {'medium': 'Cellular / WWAN', 'spectrum': '700 MHz-3.8 GHz LTE/5G',
             'method': 'netsh mbn interface + signal state',
             'state': u.get('status', 'pending').upper(),
             'detail': u.get('note') or f"{len(u.get('ifaces', []))} modem(s)"},
            {'medium': 'Wi-Fi Direct / P2P', 'spectrum': '2.4/5 GHz 802.11 p2p',
             'method': 'virtual-adapter census + beacon survey',
             'state': 'LIVE' if i.get('status') == 'ok' else 'PENDING',
             'detail': 'local virtual adapters tracked as interfaces'},
            {'medium': 'Zigbee / 802.15.4', 'spectrum': '868/915 MHz, 2.4 GHz',
             'method': 'needs sniffer hardware — USB VID/PID watch',
             'state': ('HARDWARE PRESENT' if 'Zigbee' in hw_caps or 'CC2531' in hw_caps
                       else 'NO HARDWARE'),
             'detail': 'CC2531/ConBee/Sonoff dongles auto-detected'},
            {'medium': 'Z-Wave', 'spectrum': '~900 MHz',
             'method': 'needs Z-Stick hardware — USB VID/PID watch',
             'state': ('HARDWARE PRESENT' if 'Z-Wave' in hw_caps or 'Z-Stick' in hw_caps
                       else 'NO HARDWARE'),
             'detail': 'Aeotec/similar controllers auto-detected'},
            {'medium': 'Wideband sweep (SDR)', 'spectrum': '0.5 MHz-6 GHz',
             'method': 'rtl_power/hackrf_sweep when gear present',
             'state': ('HARDWARE PRESENT' if 'SDR' in hw_caps or 'transceiver' in hw_caps
                       else 'NO HARDWARE'),
             'detail': (f"tools in PATH: {', '.join(self.rfhw.tools)}"
                        if self.rfhw.tools else 'no SDR dongle or sweep tool found')},
            {'medium': 'NFC / RFID', 'spectrum': '13.56 MHz',
             'method': 'reader hardware watch',
             'state': ('HARDWARE PRESENT' if 'NFC' in hw_caps or 'RFID' in hw_caps
                       else 'NO HARDWARE'),
             'detail': 'ACR122U/ACS-class readers auto-detected'},
            {'medium': 'Proprietary 2.4 GHz', 'spectrum': '2.4 GHz vendor RF',
             'method': 'receiver-dongle presence (Unifying/HRD/NRF24)',
             'state': ('HARDWARE PRESENT' if 'receiver' in hw_caps else 'DETECTED VIA USB' if hw_caps else 'NO HARDWARE'),
             'detail': 'peripheral dongles are emitters by proxy'},
            {'medium': 'Non-IP L2 frames', 'spectrum': 'Ethernet raw ethertypes',
             'method': 'passive wire-talker census — every src MAC traced, '
                       'ARP/ND/discovery roles labeled',
             'state': 'LIVE',
             'detail': (f"{self._results.get('l2wire', {}).get('talkers', 0)} "
                        f"talkers · {self._results.get('l2wire', {}).get('non_ip_channel', 0)} "
                        f"raw-ethertype channels · roles: "
                        f"{', '.join(self._results.get('l2wire', {}).get('roles', [])[:5]) or 'none yet'}")},
            {'medium': 'Serial / UART', 'spectrum': 'baseband wired',
             'method': 'SERIALCOMM registry + COM-port watcher',
             'state': 'LIVE',
             'detail': 'DEV tab serial feed'},
        ]
        return rows

    def snapshot(self):
        emitters = self.registry.snapshot()
        stats = self.registry.stats()
        with self.lock:
            hub_evs = list(self._ui_events)
        # One canonical spectrum feed: hub events (approach/fixes/hardware)
        # + registry events (new/lost emitters), newest last.
        events = sorted(hub_evs + self.registry.get_events(),
                        key=lambda e: e.get('time', 0))[-200:]
        sensors = dict(self._sensors)
        lat, lon = self._local_pos()
        if lat is not None:
            sensors.setdefault('local', {'lat': lat, 'lon': lon,
                                         'source': 'geoip-self'})
        obs = self.trilat.all_obs()
        return {
            'enabled': self.enabled,
            'scan_cycle': self._scan_cycle,
            'emitters': emitters,
            'emitters_total': stats['total'],
            'emitters_active': stats['active'],
            'emitters_lost': stats['lost'],
            'per_medium': stats['per_medium'],
            'fixes': dict(self._fixes),
            'coverage': self.coverage(),
            'interfaces': self._results.get('ifaces', {}).get('interfaces', []),
            'rf_hardware': self._results.get('rfhw', {}).get('hardware', []),
            'sdr_tools': list(self.rfhw.tools),
            'radios': self._results.get('wifi', {}).get('radios', []),
            'scanners': self._scanner_meta(),
            'sensors': sensors,
            'observations': {k: list(v.values()) for k, v in obs.items()},
            'obs_received': self._obs_received,
            'obs_file': CONFIG.get('rf_obs_file', ''),
            'obs_file_err': self._obs_file_err,
            'ble_live': self.bt.ble_live,
            'events': events,
        }

    def summary(self):
        stats = self.registry.stats()
        return {'emitters': stats['total'], 'active': stats['active'],
                'per_medium': stats['per_medium'],
                'fixes': sum(1 for f in self._fixes.values() if f.get('solved')),
                'seq': self.seq,
                'scan_cycle': self._scan_cycle}

    def processing_state(self):
        return {
            'registry': self.registry.stats(),
            'scanners': self._scanner_meta(),
            'sensors_known': len(self._sensors),
            'observations_ingested': self._obs_received,
            'trilat_emitters_with_obs': len(self.trilat.obs),
            'fixes_solved': sum(1 for f in self._fixes.values()
                                if f.get('solved')),
            'fixes_attempted': len(self._fixes),
            'obs_drop_file': CONFIG.get('rf_obs_file', ''),
            'obs_file_err': self._obs_file_err,
            'ble_live': self.bt.ble_live,
            'scan_cycle': self._scan_cycle,
            'l2_wire_census': self._results.get('l2wire', {}),
        }


# ========================== GEOIP WITH RATE LIMITER ==========================
class TokenBucket:
    """Thread-safe token bucket rate limiter. ip-api.com free tier: 45 req/min."""
    def __init__(self, rate: float = 40.0, capacity: float = 45.0):
        self.rate = rate / 60.0
        self.capacity = capacity
        self.tokens = capacity
        self._last_refill = time.monotonic()
        self._lock = threading.Lock()

    def consume(self, tokens: float = 1.0) -> bool:
        with self._lock:
            now = time.monotonic()
            elapsed = now - self._last_refill
            self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)
            self._last_refill = now
            if self.tokens >= tokens:
                self.tokens -= tokens
                return True
            return False


