class GNATracerGUI:
    """Full-detail popup window for GNA Tracer — shows 100% of all data."""

    # Dark HUD palette shared by every chrome element (header, KPI strip,
    # cards, status chips, bottom bar). Follows the same severity grammar as
    # the text tags: cyan=info/interactive, green=pass/ok, amber=warning,
    # red=critical/fail, purple=VPN/proxy state.
    PAL = {
        'bg':       '#0a0a0f',   # window backdrop
        'panel':    '#1a1a2e',   # chrome panels (header, toolbars, banners)
        'panel_hi': '#141426',   # sub-toolbars / recessed chips
        'card':     '#161c33',   # raised card fill (KPI tiles, chips)
        'border':   '#2e3450',   # 1px borders on cards/chips
        'text':     '#d0d6e4',   # primary chrome text
        'dim':      '#8a8a9a',   # secondary text
        'faint':    '#666e84',   # hints / captions
        'accent':   '#00d4ff',   # cyan — info / interactive
        'brand':    '#ff5566',   # brand red — title, selected tab, alerts
        'good':     '#44dd66',   # pass / healthy
        'warn':     '#ffcc44',   # warning / attention
        'bad':      '#ff4444',   # critical / fail
        'orange':   '#ff8833',   # elevated (between warn and bad)
        'purple':   '#c792ff',   # VPN / proxy state
        'textbox':  '#12121a',   # text-widget background
        'entry':    '#222233',   # entry fields
        'edge':     '#3a4568',   # Radiant top-edge highlight on panels
        'track':    '#0d0d18',   # gauge / sparkline track fill
        'sel':      '#ffd278',   # selection amber (flysuit UI_SEL)
    }

    def __init__(self, get_state_fn, get_full_data_fn, stop_event: threading.Event,
                 geoip=None, proxy_detector=None, location_verifier=None,
                 monitor=None, whois=None):
        self._get_state = get_state_fn
        self._get_full_data = get_full_data_fn
        self._stop = stop_event
        # Intelligence sources for the Double Trace tab (all optional).
        self._geoip = geoip
        self._proxy_detector = proxy_detector
        self._location_verifier = location_verifier
        # The owning monitor: watchlist API and remote-IP -> process lookup.
        self._monitor = monitor
        self._whois = whois if whois is not None else getattr(monitor, 'whois_lookup', None)
        # Right-click targets, keyed by the Tk tag applied to each rendered row.
        self._ctx_conns: dict = {}
        self._ctx_procs: dict = {}
        self._search_jobs: dict = {}     # debounce handles per search box
        self._last_full_data = None      # newest payload, for search re-renders
        self._alert_flash_tabs: dict[str, int] = {}  # tabs currently flashing
        self._last_suspicious_count = 0
        # Mirror of the monitor's watchlist, refreshed on every cycle.
        self._watchlist_ips: set[str] = set()
        self._watchlist_procs: set[str] = set()
        self._root = None
        self._map_canvas = None
        self._map_dots = {}  # ip -> canvas item id
        # tag name -> callback, for text spans that stand in for buttons
        self._click_cmds: dict = {}
        # Set while the map tab is hidden; the tab repaints once on return
        # instead of redrawing every tile on every refresh cycle.
        self._map_data_dirty = False
        self._map_w = 1200
        self._map_h = 700
        self._tooltip = None
        self._tooltip_id = None
        self._selected_ip = None
        # Zoom / pan state for real tile map (Web Mercator).
        # Default zoom raised from 2.0 to 3.0 (50% more, per request) — the
        # old default plus a center point unrelated to the user (20°N, 0°E,
        # mid-Atlantic) meant the very first view of the map was a huge,
        # mostly-empty world view. Once the user's own GeoIP resolves, the
        # first map refresh re-centers on it (see _refresh_map) — this is
        # just the fallback for before that lookup completes, or when GeoIP
        # is disabled.
        self._map_zoom = 3.0          # fractional zoom (integer part = OSM tile level)
        self._map_center_lat = 20.0   # initial center latitude (until auto-centered)
        self._map_center_lon = 0.0    # initial center longitude (until auto-centered)
        self._map_auto_centered = False  # True once centered on the user's own location
        self._map_drag_start = None   # (x, y) when drag starts
        self._map_left_drag_start = None  # for left-button panning
        self._map_left_pan_offset = (0, 0)
        self._map_left_click_moved = False  # True if left-drag exceeded threshold
        self._map_min_zoom = 0.0
        self._map_max_zoom = 19.0
        self._map_tile_images = []    # keep refs to PhotoImage objects to prevent GC
        self._map_use_tiles = HAS_PIL  # use real tiles if PIL available
        self._map_tile_retry_after = 0  # timestamp to retry tile rendering
        self._last_map_data: dict = {}   # cached map payload for redraws
        self._notebook = None            # set in _run_gui, used to switch tabs
        self._map_pan_offset = (0, 0)  # screen offset for smooth panning
        self._map_scale_bar_id: list = []  # canvas item ids for the scale bar
        self._map_style_var = None     # tk.StringVar for style selector
        self._map_search_var = None    # tk.StringVar for location search
        self._map_help_visible = False # keyboard help overlay toggle
        self._map_action_log_expanded = True  # action log panel state
        # Pinpoint/geo sidebar — multi-toggle selection of every mapped
        # point (IP pinpoints plus IP-less geo points: local marker, trace
        # hops, trilateration fixes, RF sensors). key -> item dict.
        self._map_sel: dict = {}
        self._map_sel_last = None      # key of last-clicked row (detail pane)
        self._map_sidebar = None       # outer sidebar frame
        self._map_sidebar_canvas = None  # scroll host for the row list
        self._map_sidebar_list = None    # inner frame rows live in
        self._map_sidebar_rows: dict = {}   # key -> row label widget
        self._map_sidebar_count = None  # "N points · M selected" label
        self._map_detail = None        # detail Text widget
        self._map_sidebar_sig = None   # signature the row list was built for
        self._ip_actions_text = None
        self._update_job = None
        self._status_job = None
        # Low-latency GUI tuning
        self._gui_refresh_ms = int(CONFIG.get('gui_refresh_ms', 250))
        self._last_refresh_time = 0.0
        self._refresh_latency_ms = 0.0
        self._active_tab_index = 0  # currently visible tab (for delta refresh)
        # Connection blocking — dict: ip -> {service, domain, process, pid, time_blocked, ...}
        self._blocked_ips: dict = {}
        self._conn_paused = False
        self._fw_rule_prefix = 'GNA_Tracer_Block_'
        # Auto-save series
        self._session_start = time.time()
        self._save_counter = 0
        self._autosave_job = None
        self._autosave_interval_ms = 10 * 60 * 1000  # 10 minutes

        # ---- HUD chrome state (KPI strip, cards, status chips, hints) ----
        self._chips = {}             # header KPI strip: key -> value Label
        self._bb = {}                # bottom-bar chips: key -> (caption, Label)
        self._ov_cards = {}          # overview KPI cards: key -> widget dict
        self._posture_chips = {}     # posture chips: key -> (caption, Label)
        self._posture_verdict = None # master posture verdict Label
        self._ov_sysline = None      # overview secondary-stats Label
        self._ov_ledger = {}         # overview session-ledger cells: key -> Label
        self._ins_status = None      # inspector footer status Label
        self._save_lbl = None        # bottom-bar autosave countdown Label
        self._hint_lbl = None        # bottom-bar per-tab hint Label
        self._threat_chip = None     # header threat-level chip Label
        self._clock_lbl = None       # header clock Label
        self._date_lbl = None        # header date Label
        self._up_lbl = None          # bottom-bar uptime Label
        self._loc_lbl = None         # bottom-bar location Label
        self._search_labels = {}     # StringVar -> match-count Label
        self._search_meta = {}       # text widget -> StringVar (for counts)
        self._last_sus_count = 0     # suspicious count (ticked data lacks it)
        self._last_vpn_status = {}   # last seen vpn_leak_status payload
        self._sys_text = None        # tab 17 SYS detail ScrolledText

        # ---- Double / Multi-hop Trace state ----
        self._trace_lock = threading.Lock()
        self._trace_thread = None
        self._trace_stop = threading.Event()   # set to abort an in-flight trace
        self._trace_running = False
        self._trace_proc = None                # live traceroute subprocess
        # results is a list of "trace blocks", newest last; each block is a dict:
        #   {target, started, finished, status, hops:[hop dicts]}
        self._trace_blocks: list = []
        self._trace_max_blocks = 200           # keep memory bounded
        self._trace_dirty = True               # redraw display when True
        # Rotating .txt logging — inside the GNAT record folder so the
        # Desktop root stays clean.
        self._trace_log_dir = os.path.join(
            os.path.expanduser("~"), "Desktop", "GNAT", "trace_logs")
        self._trace_log_index = 1
        self._trace_log_max_bytes = 1 * 1024 * 1024   # rotate at 1 MB (configurable in UI)
        self._trace_log_path = None
        self._trace_log_lock = threading.Lock()
        # TCP traceroute fallback: when ICMP traceroute returns no hops (common
        # for VPN/proxy endpoints that block ICMP), retry with TCP SYN probes
        # to a common port (80/443). Many firewalls allow TCP but drop ICMP.
        self._trace_tcp_fallback = True
        self._trace_tcp_ports = (443, 80, 8080)
        # Auto-retrace interval (seconds). 0 = disabled.
        self._trace_auto_interval = 0
        self._trace_auto_job = None
        self._trace_auto_targets: list = []
        # Provider-name fragments used to LABEL a hop's infrastructure (detection
        # only; this does NOT defeat a VPN). Shared with MultiVerifier.
        self._vpn_org_markers = _VPN_ORG_MARKERS
        self._hosting_org_markers = _HOSTING_ORG_MARKERS
        # Full cross-verification engine (built lazily from the passed sources).
        self._multiverifier = None

        # ---- Submarine-style right inspector dock ----
        # A collapsible dossier panel that shows EVERY known field for the
        # currently selected entity (remote IP / process / LAN device).
        # Selection comes from left-clicking a row, a map dot, or the
        # right-click menu's "Inspect" item.
        self._inspector_target = None      # ('ip'|'proc'|'dev', key) or None
        self._inspector_collapsed = False
        self._inspector_dock = None        # outer frame (rail + body)
        self._inspector_body = None        # the ~300px dossier column
        self._inspector_text = None        # dossier ScrolledText
        self._inspector_title = None       # entity-kind badge label
        self._inspector_sub = None         # entity id line
        self._inspector_rail_btn = None    # collapse/expand button on the rail
        # Sensors strip: second row of tiny status pills covering every
        # extended monitor + cache (Radiant bottom-bar chip pattern).
        self._sensor_chips = {}            # key -> (caption, Label)
        self._pub_chip = None              # header public-IP chip Label
        self._tabpos_lbl = None            # bottom-bar "[NN/16]" position label
        self._refresh_lbl = None           # sensors-strip refresh-rate Label
        # Submarine topbar pattern: per-view blurb after the title plus a
        # row of toggle-state chips (X:SECT / E:EXPL style) showing every
        # user-flippable GUI switch at a glance.
        self._mode_blurb = None            # header "-- <active tab>" Label
        self._toggle_chips = {}            # key -> (caption, Label)
        # flysuit bottom-bar live-status pattern: a third always-visible
        # strip carrying the connection status mix, summed interface
        # bandwidth and the verify/conflict ledger.
        self._flow_lbls = {}               # key -> Label
        # ASF _bar-style threat gauge on the Overview posture strip.
        self._posture_gauge_fill = None    # inner fill Frame (relwidth)
        self._posture_gauge_lbl = None     # "TH nn" Label beside the bar
        # Live counters on the MAP / CONNS toolbars.
        self._map_count_lbl = None         # "N dots · M vpn · K crit" Label
        self._conn_count_lbl = None        # "N shown · M estab" Label
        # Right-click payload registries for the device / blocked tabs so
        # those rows can feed the inspector too.
        self._ctx_devs: dict = {}
        self._ctx_blocked: dict = {}
        # Flow probe (momentary block→observe→auto-unblock verification).
        self._probe_in_flight: set = set()    # ips currently being probed
        self._probe_results: dict = {}        # ip -> {time, kind, verdict}
        # Radiant sparkline motif: rolling threat-score history drawn in the
        # header as a 1px polyline + threshold rule. One sample per status
        # tick (~1s) gives a minute-scale trend of the composite score.
        self._threat_history: list = []       # last N composite threat scores
        self._threat_history_max = 60
        self._spark_canvas = None             # header sparkline Canvas
        self._spark_lbl = None                # "TH nn" caption beside it
        self._blink_on = False                # ASF int(t*2)%2 blink state
        self._threat_level = 'LOW'            # last computed level, for pulse
        # Bottom-bar second row: save countdown + dossier footer line.
        self._save_lbl = None                 # "SAVE mm:ss" countdown Label
        self._inspector_foot = None           # dossier footer status Label
        self._ov_ledger = {}                  # session ledger grid: key -> Label

    def _get_multiverifier(self):
        # Prefer the monitor's instance. A GUI-local one kept a *separate*
        # cache, so an IP verified from the trace tab stayed unlabelled
        # everywhere else and got re-probed from scratch by the workers.
        shared = getattr(self._monitor, 'multiverifier', None)
        if shared is not None:
            return shared
        if self._multiverifier is None:
            self._multiverifier = MultiVerifier(
                geoip=self._geoip,
                location_verifier=self._location_verifier,
                proxy_detector=self._proxy_detector,
                local_geo_getter=lambda: (
                    self._last_full_data or {}).get('local_geo', {}))
        return self._multiverifier

    def _toggle_conn_pause(self):
        self._conn_paused = not self._conn_paused
        if hasattr(self, '_pause_btn'):
            self._pause_btn.config(
                text='▶ Resume Updates' if self._conn_paused else '⏸ Pause Updates',
                bg='#4caf50' if self._conn_paused else '#333344')

    def _toggle_block_ip(self, ip, conn_info=None):
        if ip in self._blocked_ips:
            self._unblock_ip(ip)
        else:
            self._block_ip(ip, conn_info)

    @staticmethod
    def _is_admin():
        """Check if the current process has admin/elevated privileges."""
        try:
            import ctypes
            return ctypes.windll.shell32.IsUserAnAdmin() != 0
        except Exception:
            return False

    def _run_firewall_cmd(self, args):
        """Run a netsh firewall command and return (success, stderr_text).
        If already admin, runs directly. Otherwise runs normally (may fail)."""
        try:
            result = subprocess.run(
                args, capture_output=True, timeout=10,
                creationflags=0x08000000, text=True)
            if result.returncode == 0:
                return True, ''
            return False, result.stderr.strip() or result.stdout.strip()
        except Exception as exc:
            return False, str(exc)

    def _run_elevated_batch(self, commands):
        """Write commands to a temp .bat, run it elevated via UAC prompt, wait for it.
        Returns True if UAC was accepted and commands executed."""
        import ctypes
        import ctypes.wintypes
        import tempfile

        # Write batch file
        bat_path = os.path.join(tempfile.gettempdir(), 'gna_tracer_fw.bat')
        with open(bat_path, 'w', encoding='ascii', errors='replace') as f:
            f.write('@echo off\n')
            for cmd in commands:
                f.write(cmd + '\n')

        # SHELLEXECUTEINFOW structure for ShellExecuteExW
        class SHELLEXECUTEINFO(ctypes.Structure):
            _fields_ = [
                ("cbSize", ctypes.wintypes.DWORD),
                ("fMask", ctypes.c_ulong),
                ("hwnd", ctypes.wintypes.HANDLE),
                ("lpVerb", ctypes.c_wchar_p),
                ("lpFile", ctypes.c_wchar_p),
                ("lpParameters", ctypes.c_wchar_p),
                ("lpDirectory", ctypes.c_wchar_p),
                ("nShow", ctypes.c_int),
                ("hInstApp", ctypes.wintypes.HINSTANCE),
                ("lpIDList", ctypes.c_void_p),
                ("lpClass", ctypes.c_wchar_p),
                ("hkeyClass", ctypes.wintypes.HKEY),
                ("dwHotKey", ctypes.wintypes.DWORD),
                ("hIcon", ctypes.wintypes.HANDLE),
                ("hProcess", ctypes.wintypes.HANDLE),
            ]

        SEE_MASK_NOCLOSEPROCESS = 0x00000040
        SW_HIDE = 0

        sei = SHELLEXECUTEINFO()
        sei.cbSize = ctypes.sizeof(sei)
        sei.fMask = SEE_MASK_NOCLOSEPROCESS
        sei.hwnd = None
        sei.lpVerb = "runas"
        sei.lpFile = bat_path
        sei.lpParameters = ""
        sei.lpDirectory = None
        sei.nShow = SW_HIDE
        sei.hProcess = None

        try:
            ctypes.windll.shell32.ShellExecuteExW.argtypes = [ctypes.c_void_p]
            ctypes.windll.shell32.ShellExecuteExW.restype = ctypes.wintypes.BOOL
            ctypes.windll.kernel32.WaitForSingleObject.argtypes = [
                ctypes.c_void_p, ctypes.wintypes.DWORD]
            ctypes.windll.kernel32.WaitForSingleObject.restype = ctypes.wintypes.DWORD
            ctypes.windll.kernel32.GetExitCodeProcess.argtypes = [
                ctypes.c_void_p, ctypes.POINTER(ctypes.wintypes.DWORD)]
            ctypes.windll.kernel32.GetExitCodeProcess.restype = ctypes.wintypes.BOOL
            ctypes.windll.kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
            ctypes.windll.kernel32.CloseHandle.restype = ctypes.wintypes.BOOL
            if not ctypes.windll.shell32.ShellExecuteExW(ctypes.byref(sei)):
                return False  # user cancelled UAC or error
            if sei.hProcess:
                # Wait up to 30 seconds for the batch to finish
                ctypes.windll.kernel32.WaitForSingleObject(sei.hProcess, 30000)
                # Get exit code — previously computed and then discarded, so a
                # failed netsh still reported success.
                exit_code = ctypes.wintypes.DWORD()
                ok = ctypes.windll.kernel32.GetExitCodeProcess(
                    sei.hProcess, ctypes.byref(exit_code))
                ctypes.windll.kernel32.CloseHandle(sei.hProcess)
                if ok and exit_code.value not in (0, 259):  # 259 = STILL_ACTIVE
                    _logger.warning("Elevated batch exited with code %s", exit_code.value)
                    return False
            return True  # UAC accepted, commands ran
        except Exception as exc:
            _logger.warning("Elevated execution failed: %s", exc)
            return False
        finally:
            try:
                os.remove(bat_path)
            except Exception:
                pass

    def _verify_rule_exists(self, rule_name):
        """Check if a firewall rule exists by name."""
        try:
            result = subprocess.run(
                ['netsh', 'advfirewall', 'firewall', 'show', 'rule',
                 f'name={rule_name}'],
                capture_output=True, timeout=10,
                creationflags=0x08000000, text=True)
            return result.returncode == 0 and 'Rule Name' in result.stdout
        except Exception:
            return False

    def _block_ip(self, ip, conn_info=None):
        if not ip or ip in self._blocked_ips:
            return
        rule_name = f'{self._fw_rule_prefix}{ip.replace(".", "_").replace(":", "_")}'
        if self._is_admin():
            # Already admin — run directly
            ok_out, _ = self._run_firewall_cmd(
                ['netsh', 'advfirewall', 'firewall', 'add', 'rule',
                 f'name={rule_name}', 'dir=out', f'remoteip={ip}',
                 'action=block', 'protocol=any'])
            ok_in, _ = self._run_firewall_cmd(
                ['netsh', 'advfirewall', 'firewall', 'add', 'rule',
                 f'name={rule_name}_in', 'dir=in', f'remoteip={ip}',
                 'action=block', 'protocol=any'])
            success = ok_out and ok_in
        else:
            # Not admin — elevate via UAC prompt
            commands = [
                f'netsh advfirewall firewall add rule name="{rule_name}" dir=out remoteip={ip} action=block protocol=any',
                f'netsh advfirewall firewall add rule name="{rule_name}_in" dir=in remoteip={ip} action=block protocol=any',
            ]
            uac_ok = self._run_elevated_batch(commands)
            if not uac_ok:
                messagebox.showwarning(
                    "Block Cancelled",
                    f"UAC prompt was cancelled or failed for {ip}.\n"
                    "You must click Yes on the Windows permission dialog.")
                return
            # Verify the rules were actually created
            success = self._verify_rule_exists(rule_name)

        if success:
            meta = {
                'ip': ip,
                'time_blocked': datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                'service': (conn_info or {}).get('service', '?'),
                'domain': (conn_info or {}).get('domain', '?'),
                'process': (conn_info or {}).get('process', '?'),
                'pid': (conn_info or {}).get('pid', '?'),
                'country': (conn_info or {}).get('country', '?'),
                'city': (conn_info or {}).get('city', '?'),
                'org': (conn_info or {}).get('org', '?'),
                'isp': (conn_info or {}).get('isp', '?'),
                'remote_port': (conn_info or {}).get('remote_port', '?'),
                'local_ip': (conn_info or {}).get('local_ip', '?'),
                'local_port': (conn_info or {}).get('local_port', '?'),
                'protocol': (conn_info or {}).get('protocol', '?'),
                'status': (conn_info or {}).get('status', '?'),
                'category': (conn_info or {}).get('category', '?'),
                'website_tag': (conn_info or {}).get('website_tag', ''),
                'exe_path': (conn_info or {}).get('exe_path', ''),
                'parent_name': (conn_info or {}).get('parent_name', ''),
                'rdns': (conn_info or {}).get('rdns', ''),
                'asn': (conn_info or {}).get('asn', ''),
                'verify_grade': (conn_info or {}).get('verify_grade', ''),
                'is_vpn': (conn_info or {}).get('is_vpn', False),
                'vpn_provider': (conn_info or {}).get('vpn_provider', ''),
            }
            self._blocked_ips[ip] = meta
            _logger.info('GNA Tracer: Blocked IP %s (both directions)', ip)
        else:
            messagebox.showerror(
                "Block Failed",
                f"Failed to create firewall rules for {ip}.\n\n"
                "The rules could not be verified after execution.")
            _logger.warning('GNA Tracer: Failed to block %s', ip)
        self._update_blocked_label()

    def _unblock_ip(self, ip):
        if not ip or ip not in self._blocked_ips:
            return
        rule_name = f'{self._fw_rule_prefix}{ip.replace(".", "_").replace(":", "_")}'
        if self._is_admin():
            self._run_firewall_cmd(
                ['netsh', 'advfirewall', 'firewall', 'delete', 'rule',
                 f'name={rule_name}'])
            self._run_firewall_cmd(
                ['netsh', 'advfirewall', 'firewall', 'delete', 'rule',
                 f'name={rule_name}_in'])
        else:
            commands = [
                f'netsh advfirewall firewall delete rule name="{rule_name}"',
                f'netsh advfirewall firewall delete rule name="{rule_name}_in"',
            ]
            self._run_elevated_batch(commands)
        self._blocked_ips.pop(ip, None)
        _logger.info('GNA Tracer: Unblocked IP %s', ip)
        self._update_blocked_label()

    def _unblock_all(self):
        ips = list(self._blocked_ips)
        if not ips:
            return
        if self._is_admin():
            for ip in ips:
                self._unblock_ip(ip)
            return
        # Not admin: batch every delete into ONE elevated call so the user gets a
        # single UAC prompt instead of one per blocked IP.
        commands = []
        for ip in ips:
            rule_name = f'{self._fw_rule_prefix}{ip.replace(".", "_").replace(":", "_")}'
            commands.append(f'netsh advfirewall firewall delete rule name="{rule_name}"')
            commands.append(f'netsh advfirewall firewall delete rule name="{rule_name}_in"')
        self._run_elevated_batch(commands)
        for ip in ips:
            self._blocked_ips.pop(ip, None)
            _logger.info('GNA Tracer: Unblocked IP %s', ip)
        self._update_blocked_label()

    def _update_blocked_label(self):
        if hasattr(self, '_blocked_lbl'):
            n = len(self._blocked_ips)
            if n:
                ip_list = ', '.join(sorted(self._blocked_ips.keys()))
                self._blocked_lbl.config(
                    text=f'🚫 Blocked ({n}): {ip_list}',
                    fg='#ff4444')
            else:
                self._blocked_lbl.config(
                    text='No IPs blocked',
                    fg='#8a8a9a')

    # ─── Flow probe: momentary block → observe → auto-unblock ───
    # Verifies what a connection actually does when its endpoint dies. This is
    # a LOCAL diagnostic on our own firewall — it never sends anything to the
    # remote host. What it proves: if killing exit IP `x` makes the same
    # process reappear seconds later on a *different* public IP with the same
    # service/domain/provider, the original address was just a relay label
    # (VPN rotation). If the flow returns to the same IP, the endpoint is
    # sticky. The block is ALWAYS lifted again — a probe can never leave an
    # endpoint blocked by accident.
    def _probe_ip_flow(self, ip, conn_info=None):
        if not ip or ip in self._probe_in_flight:
            return
        if ip in self._blocked_ips:
            messagebox.showinfo(
                "Flow Probe",
                f"{ip} is already blocked.\nUnblock it first, then probe.")
            return
        secs = int(CONFIG.get('flow_probe_secs', 8))
        settle = int(CONFIG.get('flow_probe_settle_secs', 6))
        data = self._last_full_data or {}
        conns = [c for c in data.get('connections', [])
                 if c.get('remote_ip') == ip]
        before = {
            'procs': {c.get('process') for c in conns if c.get('process')},
            'domain': next((c.get('domain') for c in conns
                            if c.get('domain')), ''),
            'service': next((c.get('service') for c in conns
                             if c.get('service')), ''),
            'provider': next((c.get('vpn_provider') for c in conns
                              if c.get('vpn_provider')), ''),
            'conns': len(conns),
        }
        self._probe_in_flight.add(ip)
        self._probe_note(ip, f"⚗ FLOW-PROBE armed on {ip} — "
                             f"blocking {secs}s, then watching {settle}s")
        if self._is_admin():
            self._block_ip(ip, (conn_info or (conns[0] if conns else None)))
            if ip not in self._blocked_ips:
                self._probe_in_flight.discard(ip)
                return  # block itself failed; message already shown
            self._root.after(secs * 1000,
                             lambda: self._probe_release(ip, before, settle))
        else:
            # Non-admin: ONE elevated batch does add→wait→delete so the whole
            # probe costs a single UAC prompt and self-terminates.
            rule = f'{self._fw_rule_prefix}' \
                   f'{ip.replace(".", "_").replace(":", "_")}'
            cmds = [
                f'netsh advfirewall firewall add rule name="{rule}" '
                f'dir=out remoteip={ip} action=block protocol=any',
                f'netsh advfirewall firewall add rule name="{rule}_in" '
                f'dir=in remoteip={ip} action=block protocol=any',
                # `timeout` fails in a non-interactive batch (no console
                # stdin); `ping -n` is the reliable ~1s-per-count wait.
                f'ping -n {secs + 1} 127.0.0.1 >nul',
                f'netsh advfirewall firewall delete rule name="{rule}"',
                f'netsh advfirewall firewall delete rule name="{rule}_in"',
            ]
            threading.Thread(
                target=self._probe_elevated_worker,
                args=(ip, cmds, before, secs, settle),
                daemon=True, name=f"FlowProbe-{ip}").start()

    def _probe_release(self, ip, before, settle):
        """Admin path: lift the temp block, then judge after the settle window."""
        try:
            self._unblock_ip(ip)
        finally:
            self._root.after(settle * 1000,
                             lambda: self._probe_verdict(ip, before))

    def _probe_elevated_worker(self, ip, cmds, before, secs, settle):
        ok = self._run_elevated_batch(cmds)
        if not ok:
            def _abort():
                self._probe_in_flight.discard(ip)
                self._probe_note(ip, f"⚗ FLOW-PROBE on {ip} aborted — "
                                     f"UAC declined or batch failed")
            self._root.after(0, _abort)
            return
        time.sleep(max(1, settle))
        self._root.after(0, lambda: self._probe_verdict(ip, before))

    def _probe_verdict(self, ip, before):
        """Compare pre/post-block connection state and record the verdict."""
        self._probe_in_flight.discard(ip)
        data = self._last_full_data or {}
        conns = data.get('connections', [])
        mon = getattr(self, '_monitor', None)
        if not conns and mon is not None:
            try:
                conns = mon.conn_inventory.get_all()
            except Exception:
                conns = []
        procs = before.get('procs') or set()
        back = [c for c in conns if c.get('remote_ip') == ip]
        rotated = {}
        for c in conns:
            rip = c.get('remote_ip', '')
            if rip == ip or not _is_public_ip_cached(rip):
                continue
            if procs and c.get('process') not in procs:
                continue
            if (before.get('domain') and c.get('domain') == before['domain']) or \
               (before.get('service') and c.get('service') == before['service']) or \
               (before.get('provider') and
                    c.get('vpn_provider') == before['provider']):
                rotated[rip] = c
        rot_ips = sorted(rotated)
        proc_lbl = ', '.join(sorted(procs)[:3]) or '?'
        if rot_ips:
            kind, sev, score = 'ROTATED', 'WARNING', 40
            verdict = (f"flow returned on NEW exit(s) {', '.join(rot_ips[:4])} "
                       f"after {ip} was blocked → provider rotation = "
                       f"VPN/relay infrastructure")
        elif back:
            kind, sev, score = 'STICKY', 'INFO', 15
            verdict = (f"flow returned to the same {ip} after unblock → "
                       f"endpoint is persistent (direct host or pinned exit)")
        else:
            kind, sev, score = 'GONE', 'INFO', 10
            verdict = (f"flow to {ip} did not return within the settle "
                       f"window → ended, went idle, or stayed severed")
        self._probe_results[ip] = {
            'time': _fmt_hms(int(time.time())), 'kind': kind,
            'verdict': verdict, 'rotated_to': rot_ips,
        }
        self._probe_note(ip, f"⚗ FLOW-PROBE {kind} {ip}: {verdict}")
        if mon is not None:
            pid = next((c.get('pid') for c in conns
                        if c.get('remote_ip') == ip and c.get('pid')), 0)
            try:
                # _add_deduction feeds the deductions deque, action stream,
                # structured log, deductions log, DB, SIEM and suspicious
                # buffer — so the verdict lands in every .txt export stream.
                mon._add_deduction(
                    sev, 'FLOW_PROBE', proc_lbl, pid,
                    f"Flow probe {ip} → {kind}",
                    [verdict] + ([f"processes observed: {proc_lbl}"]
                                 if procs else []), score)
            except Exception:
                pass
        if (self._inspector_target or (None, None)) == ('ip', ip):
            self._refresh_inspector(data)

    def _probe_note(self, ip, msg):
        """Probe progress → monitor terminal (lands in session .txt exports)."""
        mon = getattr(self, '_monitor', None)
        try:
            if mon is not None:
                mon._log(msg, color=Colors.C)
        except Exception:
            pass
        _logger.info(msg)

    # ─── Scroll-aware refresh helpers ───
    def _is_at_bottom(self, widget):
        """Return True if the scrollbar is near the bottom (auto-scroll zone)."""
        return widget.yview()[1] >= 0.95

    def _begin_refresh(self, widget):
        """Save scroll state before a full rewrite. Returns (was_at_bottom, top_line).
        Uses line-number-based preservation so the view doesn't bump when content grows."""
        at_bottom = self._is_at_bottom(widget)
        # Get the line number at the top of the viewport (not a fraction)
        try:
            top_index = widget.index("@0,0")
            top_line = int(top_index.split('.')[0])
        except Exception:
            top_line = 1
        return at_bottom, top_line

    def _end_refresh(self, widget, at_bottom, top_line):
        """Restore scroll: auto-scroll to end if was at bottom, else restore line position.
        Uses line-number-based preservation to avoid view bumping on content changes."""
        if at_bottom:
            widget.see("end")
        else:
            # Get total lines in the widget after the rewrite
            try:
                end_index = widget.index("end-1c")
                total_lines = int(end_index.split('.')[0])
                # Calculate fraction to position the saved line at the top
                if total_lines > 1:
                    frac = max(0.0, min(1.0, (top_line - 1) / max(1, total_lines - 1)))
                    widget.yview_moveto(frac)
            except Exception:
                pass

    def _render_skip(self, tag: str, sig) -> bool:
        """True when a tab's render inputs haven't changed since last paint.

        Full-data snapshots are immutable — the same dict object guarantees
        the same content — so id(data) plus the renderer's own UI state
        (search text, expanded rows, block set) is a complete signature.
        Skipping saves a full delete+insert widget rebuild (and the embedded
        button churn that comes with it) on every tick that reuses a cached
        snapshot."""
        if not hasattr(self, '_render_sigs'):
            self._render_sigs = {}
        if self._render_sigs.get(tag) == sig:
            return True
        self._render_sigs[tag] = sig
        return False

    @staticmethod
    def _ver(data, key):
        """Content version for one snapshot section.

        `_get_full_data` publishes `_versions` — real change counters from
        the underlying stores. Keying render signatures on those means a tab
        repaints when its feed actually moved, not every time a new snapshot
        object exists. Payloads without `_versions` (tests, sparse feeds)
        fall back to object identity — same behavior as before.
        """
        v = data.get('_versions')
        if v is None:
            return id(data)
        return v.get(key, id(data))

    @staticmethod
    def _cfg(widget, **opts):
        """widget.config() that no-ops when the values are already applied.

        The 250ms status tick re-set identical text/colors on ~70 labels —
        every .config is a Tcl round-trip even when nothing changed, which
        was the bulk of per-tick GUI time. The last-applied opts are kept on
        the widget itself; a failed config leaves the cache stale so the
        next pass retries.
        """
        if widget is None:
            return
        try:
            last = widget._mb_cfg
        except AttributeError:
            last = widget._mb_cfg = {}
        diff = {k: v for k, v in opts.items() if last.get(k) != v}
        if not diff:
            return
        try:
            widget.config(**diff)
        except Exception:
            return
        last.update(diff)

    # ─── Search infrastructure ───
    def _make_search_bar(self, parent, search_var):
        """Create a search toolbar frame with entry + match count + clear button.
        The match-count label is registered on self._search_labels[search_var];
        _highlight_search updates it once the owning text widget is mapped in
        self._search_meta."""
        P = self.PAL
        bar = tk.Frame(parent, bg=P['panel'], height=28)
        bar.pack(fill="x", side="top")
        bar.pack_propagate(False)
        mag_lbl = tk.Label(bar, text="🔍", bg=P['panel'], fg=P['dim'],
                           font=("Consolas", 10))
        mag_lbl.pack(side="left", padx=(8, 2))
        _add_tooltip(mag_lbl,
            "Search filter\n─────────────────────\n"
            "Type in the box to live-filter the\n"
            "rows below. ✕ clears the filter.")
        entry = tk.Entry(bar, textvariable=search_var, bg=P['entry'], fg=P['accent'],
                         insertbackground=P['accent'], font=("Consolas", 9),
                         bd=0, highlightthickness=1, highlightcolor=P['border'])
        entry.pack(side="left", fill="x", expand=True, padx=4, pady=3)
        _add_tooltip(entry,
            "Filter this view\n"
            "─────────────────────\n"
            "Type to highlight matches instantly.\n"
            "Prefix 'r:' or '/' for regex search.\n"
            "The counter on the right shows hits.")
        clear_btn = tk.Button(bar, text="✕", bg=P['panel'], fg=P['dim'],
                              font=("Consolas", 9), bd=0, padx=4,
                              activebackground=P['panel_hi'],
                              activeforeground=P['text'],
                              command=lambda: search_var.set(""))
        clear_btn.pack(side="right", padx=4)
        count_lbl = tk.Label(bar, text="", bg=P['panel'], fg=P['accent'],
                             font=("Consolas", 8, "bold"))
        count_lbl.pack(side="right", padx=(0, 2))
        _add_tooltip(count_lbl,
            "Match counter\n─────────────────────\n"
            "Rows matching the current search\n"
            "filter / total rows in the view.")
        self._search_labels[str(search_var)] = count_lbl
        return bar

