    def _on_style_change(self, event=None):
        """Handle tile style dropdown change."""
        if not self._map_style_var:
            return
        selection = self._map_style_var.get()
        # Parse "key — Label" format
        style_key = selection.split(' — ')[0].strip() if ' — ' in selection else selection
        if style_key in TileManager.TILE_STYLES:
            TileManager.set_style(style_key)
            self._map_max_zoom = TileManager.get_style_max_zoom()
            # Clamp current zoom to new max
            if self._map_zoom > self._map_max_zoom:
                self._map_zoom = self._map_max_zoom
            if hasattr(self, '_map_zoom_slider'):
                self._map_zoom_slider.configure(to=self._map_max_zoom)
            self._draw_map_full()
            self._redraw_dots_only()

    def _on_zoom_slider(self, value):
        """Handle zoom slider drag."""
        try:
            new_zoom = float(value)
        except (ValueError, TypeError):
            return
        if abs(new_zoom - self._map_zoom) < 0.01:
            return
        self._map_zoom = max(self._map_min_zoom, min(self._map_max_zoom, new_zoom))
        TileManager.clear_photo_cache()
        self._draw_map_full()
        self._redraw_dots_only()

    def _on_map_search(self, event=None):
        """Search for a location by city name or 'lat, lon' coordinates."""
        if not self._map_search_var:
            return
        query = self._map_search_var.get().strip()
        if not query:
            return
        # Try parsing as coordinates "lat, lon"
        if ',' in query:
            parts = query.split(',')
            if len(parts) == 2:
                try:
                    lat = float(parts[0].strip())
                    lon = float(parts[1].strip())
                    self._goto_preset(lat, lon, max(self._map_zoom, 10.0))
                    self._map_search_var.set('')
                    return
                except ValueError:
                    pass
        # Try city name lookup
        key = query.lower()
        if key in self._CITY_SEARCH:
            lat, lon = self._CITY_SEARCH[key]
            self._goto_preset(lat, lon, 11.0)
            self._map_search_var.set('')
            return
        # Try partial match
        for city, (lat, lon) in self._CITY_SEARCH.items():
            if city.startswith(key) or key.startswith(city):
                self._goto_preset(lat, lon, 11.0)
                self._map_search_var.set('')
                return
        # Not found — flash the entry
        if self._map_search_var:
            self._map_search_var.set(f'Not found: {query}')

    def _goto_preset(self, lat, lon, zoom):
        """Jump to a preset location and zoom level."""
        self._map_zoom = max(self._map_min_zoom, min(self._map_max_zoom, float(zoom)))
        self._map_center_lat = max(-85, min(85, lat))
        self._map_center_lon = max(-180, min(180, lon))
        if hasattr(self, '_map_zoom_slider'):
            self._map_zoom_slider.set(self._map_zoom)
        TileManager.clear_photo_cache()
        self._draw_map_full()
        self._redraw_dots_only()

    def _toggle_map_action_log(self):
        """Collapse/expand the IP action log panel below the map."""
        if self._map_action_log_expanded:
            self._map_action_log_frame.pack_forget()
            self._map_action_log_expanded = False
        else:
            self._map_action_log_frame.pack(fill="both", expand=False)
            self._map_action_log_expanded = True

    def _toggle_map_help(self):
        """Show/hide keyboard shortcut help overlay on the map."""
        self._map_help_visible = not self._map_help_visible
        if not self._map_canvas:
            return
        self._map_canvas.delete("help_overlay")
        if self._map_help_visible:
            w = self._map_w
            lines = [
                "MAP CONTROLS",
                "",
                "Mouse wheel / ➕➖     Zoom in/out",
                "Left-drag             Pan map",
                "Right-drag            Pan map (alt)",
                "Click dot             IP details / actions",
                "Right-click empty     Context menu",
                "",
                "+ / =                 Zoom in",
                "-                     Zoom out",
                "Arrow keys            Pan (↑↓←→)",
                "R                     Reset view",
                "H                     Toggle this help",
                "",
                "Style dropdown        Switch map layer",
                "Go to box             City name or 'lat, lon'",
                "Presets               Jump to region/city",
            ]
            # Semi-transparent background
            box_w, box_h = 260, len(lines) * 16 + 20
            x0, y0 = w - box_w - 10, 40
            self._map_canvas.create_rectangle(
                x0, y0, x0 + box_w, y0 + box_h,
                fill="#0a0a0f", stipple="gray50", outline="#00d4ff",
                width=1, tags="help_overlay")
            for i, line in enumerate(lines):
                color = "#00d4ff" if i == 0 else "#c0c0c0"
                font = ("Consolas", 9, "bold") if i == 0 else ("Consolas", 8)
                self._map_canvas.create_text(
                    x0 + 12, y0 + 12 + i * 16, text=line,
                    fill=color, font=font, anchor="nw", tags="help_overlay")

    # --- Left-drag panning (new, more natural than right-drag only) ---

    def _on_map_left_press(self, event):
        """Start left-button drag for panning. Also tracks click for context menu."""
        self._map_left_drag_start = (event.x, event.y)
        self._map_left_pan_offset = (0, 0)
        self._map_left_click_moved = False

    def _on_map_left_drag(self, event):
        """Pan the map with left-button drag."""
        if not self._map_left_drag_start:
            return
        dx = event.x - self._map_left_drag_start[0]
        dy = event.y - self._map_left_drag_start[1]
        if abs(dx) > 3 or abs(dy) > 3:
            self._map_left_click_moved = True
        if dx == 0 and dy == 0:
            return
        self._map_left_drag_start = (event.x, event.y)
        ox, oy = self._map_left_pan_offset
        self._map_left_pan_offset = (ox + dx, oy + dy)
        if self._map_canvas:
            self._map_canvas.move("all", dx, dy)

    def _on_map_left_release(self, event):
        """Commit left-drag pan, or show context menu if it was a click."""
        if not self._map_left_drag_start:
            return
        ox, oy = self._map_left_pan_offset
        self._map_left_drag_start = None
        self._map_left_pan_offset = (0, 0)
        if not self._map_left_click_moved:
            # It was a click, not a drag — show context menu
            self._on_map_left_click(event)
            return
        if ox == 0 and oy == 0:
            return
        z = self._map_zoom
        cx_px, cy_px = TileManager.latlon_to_pixel(
            self._map_center_lat, self._map_center_lon, z)
        lat, lon = TileManager.pixel_to_latlon(cx_px - ox, cy_px - oy, z)
        self._map_center_lat = max(-85, min(85, lat))
        self._map_center_lon = max(-180, min(180, lon))
        self._draw_map_full()
        self._redraw_dots_only()

    def _map_reset_view(self):
        """Reset map to the default view — centered on the user's own
        location (same as the initial auto-center) when it's known, rather
        than the generic mid-Atlantic point, at the default zoom."""
        self._map_zoom = 3.0
        local_geo = (self._last_full_data or {}).get('local_geo', {})
        if local_geo.get('lat') or local_geo.get('lon'):
            self._map_center_lat = max(-85, min(85, local_geo.get('lat', 0)))
            self._map_center_lon = max(-180, min(180, local_geo.get('lon', 0)))
        else:
            self._map_center_lat = 20.0
            self._map_center_lon = 0.0
        if hasattr(self, '_map_zoom_slider'):
            self._map_zoom_slider.set(self._map_zoom)
        TileManager.clear_photo_cache()
        self._draw_map_full()
        self._redraw_dots_only()

    def _on_map_scroll(self, event):
        """Mouse wheel zoom — smooth fractional zoom."""
        if event.delta > 0:
            self._map_zoom_by(1.15, event)
        else:
            self._map_zoom_by(1 / 1.15, event)

    def _on_map_drag_start(self, event):
        self._map_drag_start = (event.x, event.y)
        self._map_pan_offset = (0, 0)

    def _on_map_drag(self, event):
        """Shift what is already drawn while the button is held. Reprojecting
        and re-rendering every tile on each motion event made dragging crawl;
        the real redraw happens once on release."""
        if not self._map_drag_start:
            return
        dx = event.x - self._map_drag_start[0]
        dy = event.y - self._map_drag_start[1]
        if dx == 0 and dy == 0:
            return
        self._map_drag_start = (event.x, event.y)
        ox, oy = self._map_pan_offset
        self._map_pan_offset = (ox + dx, oy + dy)
        if self._map_canvas:
            self._map_canvas.move("all", dx, dy)

    def _on_map_drag_end(self, event):
        """Commit the accumulated pan: convert it to a new centre and redraw."""
        if not self._map_drag_start and self._map_pan_offset == (0, 0):
            self._map_drag_start = None
            return
        ox, oy = self._map_pan_offset
        self._map_drag_start = None
        self._map_pan_offset = (0, 0)
        if ox == 0 and oy == 0:
            return
        z = self._map_zoom
        # The view moved with the pointer, so the centre moves the other way.
        cx_px, cy_px = TileManager.latlon_to_pixel(
            self._map_center_lat, self._map_center_lon, z)
        lat, lon = TileManager.pixel_to_latlon(cx_px - ox, cy_px - oy, z)
        self._map_center_lat = max(-85, min(85, lat))
        self._map_center_lon = max(-180, min(180, lon))
        self._draw_map_full()
        self._redraw_dots_only()

    def _on_map_mouse_move(self, event):
        """Show lat/lon coordinates under cursor with crosshair reticle."""
        lat, lon = self._xy_to_latlon(event.x, event.y)
        if hasattr(self, '_coords_lbl'):
            self._coords_lbl.config(text=f"Lat: {lat:.4f}° Lon: {lon:.4f}°  (z={self._map_zoom:.1f})")
        # Draw crosshair reticle
        if self._map_canvas:
            self._map_canvas.delete("crosshair")
            w, h = self._map_w, self._map_h
            # Horizontal line
            self._map_canvas.create_line(
                0, event.y, w, event.y, fill="#3a5a5a", width=1,
                tags="crosshair", dash=(2, 4))
            # Vertical line
            self._map_canvas.create_line(
                event.x, 0, event.x, h, fill="#3a5a5a", width=1,
                tags="crosshair", dash=(2, 4))
            # Coordinate label near cursor
            coord_text = f"{lat:.4f}°, {lon:.4f}°"
            self._map_canvas.create_text(
                event.x + 10, event.y - 10, text=coord_text,
                fill="#00d4ff", font=("Consolas", 8), anchor="sw",
                tags="crosshair")

    def _pan_map(self, dx, dy):
        """Pan the map by a pixel offset (used by keyboard navigation)."""
        z = self._map_zoom
        cx_px, cy_px = TileManager.latlon_to_pixel(self._map_center_lat, self._map_center_lon, z)
        new_cx_px = cx_px + dx
        new_cy_px = cy_px + dy
        lat, lon = TileManager.pixel_to_latlon(new_cx_px, new_cy_px, z)
        self._map_center_lat = max(-85, min(85, lat))
        self._map_center_lon = max(-180, min(180, lon))
        self._draw_map_full()
        self._redraw_dots_only()

    def _on_map_left_click(self, event):
        """Left-click on empty map area: show context menu."""
        # Check if we clicked on a dot — if so, let the dot binding handle it
        items = self._map_canvas.find_overlapping(
            event.x - 3, event.y - 3, event.x + 3, event.y + 3)
        for item in items:
            tags = self._map_canvas.gettags(item)
            if "dot" in tags:
                return  # let the dot click handler work
        # Show context menu
        lat, lon = self._xy_to_latlon(event.x, event.y)
        menu = tk.Menu(self._root, tearoff=0, bg="#1a1a2e", fg="#c0c0c0",
                       activebackground="#0f3460", activeforeground="#ffffff",
                       font=("Consolas", 9))
        menu.add_command(label=f"📍 {lat:.4f}°, {lon:.4f}°", state="disabled")
        menu.add_separator()
        menu.add_command(label="🎯 Center map here", command=lambda: self._center_map_at(lat, lon))
        menu.add_command(label="🔍 Zoom in here", command=lambda: self._zoom_to_location(lat, lon, self._map_zoom + 1))
        menu.add_command(label="🔍 Zoom out", command=lambda: self._zoom_to_location(lat, lon, max(0, self._map_zoom - 1)))
        menu.add_separator()
        menu.add_command(label="📋 Copy coordinates", command=lambda: self._copy_coords(lat, lon))
        menu.add_command(label="🌐 Open in browser (OSM)", command=lambda: self._open_in_browser(lat, lon))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _center_map_at(self, lat, lon):
        """Center the map at the given coordinates."""
        self._map_center_lat = max(-85, min(85, lat))
        self._map_center_lon = max(-180, min(180, lon))
        self._draw_map_full()
        self._redraw_dots_only()

    def _zoom_to_location(self, lat, lon, zoom):
        """Zoom to a specific location and zoom level."""
        self._map_zoom = max(self._map_min_zoom, min(self._map_max_zoom, float(zoom)))
        self._map_center_lat = max(-85, min(85, lat))
        self._map_center_lon = max(-180, min(180, lon))
        TileManager.clear_photo_cache()
        self._draw_map_full()
        self._redraw_dots_only()

    def _copy_coords(self, lat, lon):
        """Copy coordinates to clipboard."""
        text = f"{lat:.6f}, {lon:.6f}"
        self._root.clipboard_clear()
        self._root.clipboard_append(text)

    def _open_in_browser(self, lat, lon):
        """Open the location in OpenStreetMap web."""
        z = int(self._map_zoom)
        url = f"https://www.openstreetmap.org/?mlat={lat}&mlon={lon}#map={z}/{lat}/{lon}"
        import webbrowser
        webbrowser.open(url)

    def _redraw_dots_only(self):
        """Quick redraw of just the connection dots and trace path without full data refresh."""
        if not self._map_canvas:
            return
        self._map_canvas.delete("dot", "line_to_dot", "trace_path", "trace_hop", "crosshair")
        self._map_dots.clear()
        if hasattr(self, '_last_map_data') and self._last_map_data:
            self._plot_map_dots(self._last_map_data)
        self._plot_trace_on_map()

    # ================== PINPOINT / GEO SIDEBAR ==================
    # Every mapped point — IP pinpoints plus geo locations that have no IP
    # but are relevant to an observed connection (your local marker, trace
    # hops, trilateration fixes, RF sensors, traced emitters) — is listed
    # in the scrollable sidebar. Clicking a row toggles it in a
    # multi-select set: every selected point gets a map ring, the
    # last-clicked row gets the "every field" detail dump, and
    # ✖ DESELECT ALL resets to the default state.
    _MAP_SEL_ICON = {'ip': '●', 'local': '📍', 'hop': '↳',
                     'fix': '◎', 'sensor': '◆', 'em': '✶'}
    # Emitter roles that describe this machine itself — censused but not
    # something you "locate" as a separate geo point.
    _MAP_SEL_SELF_ROLES = {'local-transmitter', 'local-interface',
                         'analysis-gear'}

    def _build_map_sidebar(self, parent):
        """Right-edge sidebar: scrollable pinpoint/geo list + detail pane."""
        sb = self._map_sidebar = tk.Frame(parent, bg="#101018", width=292)
        sb.pack(side="right", fill="y", padx=(0, 2), pady=2)
        sb.pack_propagate(False)
        hdr = tk.Label(sb, text="PINPOINTS & GEO LOCATIONS",
                       bg="#1a1a2e", fg="#ff5566",
                       font=("Consolas", 8, "bold"))
        hdr.pack(fill="x")
        _add_tooltip(hdr,
            "Every mapped point\n─────────────────────\n"
            "IP pinpoints plus geo locations with no\n"
            "IP that relate to an observed connection:\n"
            "your local marker, trace hops, trilater-\n"
            "ation fixes, RF sensors and traced emitters.\n\n"
            "Click a row to select it and see every\n"
            "field. Click again to toggle it off —\n"
            "multiple points can stay selected at\n"
            "once. ✖ DESELECT ALL resets the view.")
        ctl = tk.Frame(sb, bg="#101018")
        ctl.pack(fill="x", padx=4, pady=(3, 1))
        btn_desel = tk.Button(ctl, text="✖ DESELECT ALL", bg="#333344",
                              fg="#ffcc66", font=("Consolas", 7, "bold"),
                              bd=0, padx=6, command=self._map_deselect_all)
        btn_desel.pack(side="left")
        _add_tooltip(btn_desel,
            "Deselect everything\n─────────────────────\n"
            "Clears every selected row, the detail\n"
            "pane and all selection rings — back to\n"
            "the default map state.")
        btn_center = tk.Button(ctl, text="⌖", bg="#333344", fg="#a0a0b0",
                               font=("Consolas", 8, "bold"), bd=0, padx=6,
                               command=self._map_center_on_selection)
        btn_center.pack(side="left", padx=(3, 0))
        _add_tooltip(btn_center,
            "Center on selection\n─────────────────────\n"
            "Pans the map to the last-selected point\n"
            "(or the middle of the selected set).")
        self._map_sidebar_count = tk.Label(ctl, text="", bg="#101018",
                                           fg="#00d4ff", font=("Consolas", 7))
        self._map_sidebar_count.pack(side="right", padx=2)
        _add_tooltip(self._map_sidebar_count,
            "Selection count\n─────────────────────\n"
            "pts = rows listed · sel = currently\n"
            "toggled on (ringed on the map).")
        leg = tk.Label(sb,
            text="● ip  📍 you  ↳ hop  ◎ fix  ◆ sensor  ✶ emitter",
            bg="#101018", fg="#6a7a9a", font=("Consolas", 7))
        leg.pack(fill="x", padx=4)
        _add_tooltip(leg,
            "Row kinds\n─────────────────────\n"
            "  ● ip      — connection endpoint pinpoint\n"
            "  📍 you    — your own GeoIP marker (arc origin)\n"
            "  ↳ hop     — traceroute hop geo point\n"
            "  ◎ fix     — trilaterated emitter (no IP)\n"
            "  ◆ sensor  — configured RF sensor node (no IP)\n"
            "  ✶ emitter — traced signal device (no IP)")
        # Scrollable row list — canvas + inner frame + scrollbar.
        wrap = tk.Frame(sb, bg="#101018")
        wrap.pack(fill="both", expand=True, padx=2, pady=(2, 0))
        self._map_sidebar_canvas = tk.Canvas(
            wrap, bg="#0d1117", highlightthickness=0)
        vsb = tk.Scrollbar(wrap, orient="vertical",
                           command=self._map_sidebar_canvas.yview)
        self._map_sidebar_canvas.configure(yscrollcommand=vsb.set)
        vsb.pack(side="right", fill="y")
        self._map_sidebar_canvas.pack(side="left", fill="both", expand=True)
        self._map_sidebar_list = tk.Frame(self._map_sidebar_canvas, bg="#0d1117")
        _lwin = self._map_sidebar_canvas.create_window(
            (0, 0), window=self._map_sidebar_list, anchor="nw")
        self._map_sidebar_list.bind(
            "<Configure>",
            lambda e: self._map_sidebar_canvas.configure(
                scrollregion=self._map_sidebar_canvas.bbox("all")))
        self._map_sidebar_canvas.bind(
            "<Configure>",
            lambda e: self._map_sidebar_canvas.itemconfigure(
                _lwin, width=e.width))
        # Wheel over the list scrolls the list, not the map zoom.
        self._map_sidebar_canvas.bind(
            "<Enter>",
            lambda e: self._map_sidebar_canvas.bind_all(
                "<MouseWheel>", self._on_sidebar_wheel))
        self._map_sidebar_canvas.bind(
            "<Leave>",
            lambda e: self._map_sidebar_canvas.unbind_all("<MouseWheel>"))
        # Detail pane — every field of the last-selected point.
        dhead = tk.Label(sb, text="SELECTED DETAIL — every field",
                         bg="#1a1a2e", fg="#00d4ff",
                         font=("Consolas", 8, "bold"))
        dhead.pack(fill="x", pady=(3, 0))
        _add_tooltip(dhead,
            "Full detail dump\n─────────────────────\n"
            "Every recorded field of the last-clicked\n"
            "row — nothing filtered, same raw data\n"
            "the map and inspector consume.")
        self._map_detail = tk.Text(sb, bg="#0d1117", fg="#c0c0c0",
                                   font=("Consolas", 8), height=17,
                                   wrap="word", bd=0, highlightthickness=0)
        self._map_detail.pack(fill="x", padx=2, pady=(0, 2))
        self._map_detail_show(None)

    def _on_sidebar_wheel(self, event):
        try:
            self._map_sidebar_canvas.yview_scroll(
                int(-event.delta / 120), "units")
        except Exception:
            pass

    def _map_sidebar_items(self, data):
        """(kind, key, label, item) for every sidebar row."""
        items = []
        md = self._last_map_data or {}
        for pt in md.get('all_points', []):
            if not (pt.get('lat') or pt.get('lon')):
                continue
            ip = pt.get('ip', '?')
            loc = ', '.join(x for x in (
                pt.get('city') or '', pt.get('country_code') or
                pt.get('country') or '') if x and x != '??')
            items.append(('ip', f"ip:{ip}",
                          f"{ip}  {loc or 'unresolved'}",
                          dict(pt, _sel_kind='ip')))
        lg = md.get('local_geo') or data.get('local_geo') or {}
        if lg.get('lat') or lg.get('lon'):
            items.append(('local', 'local',
                          f"you  {lg.get('ip', '?')}  "
                          f"{lg.get('city', '?')}, {lg.get('country_code', '?')}",
                          dict(lg, _sel_kind='local')))
        with self._trace_lock:
            blocks = list(self._trace_blocks)
        if blocks:
            blk = blocks[-1]
            for h in blk.get('hops', []):
                if not (h.get('lat') or h.get('lon')):
                    continue
                ip = h.get('ip') or '* no-IP'
                hloc = ', '.join(x for x in (
                    h.get('city') or '', h.get('country') or '')
                    if x and x != '??')
                items.append(('hop', f"hop:{h.get('hop')}:{ip}",
                              f"hop {h.get('hop')}  {ip}  {hloc}",
                              dict(h, _sel_kind='hop',
                                   _blk_target=blk.get('target'),
                                   _blk_status=blk.get('status'))))
        sp = data.get('spectrum') or {}
        for key, fix in (sp.get('fixes') or {}).items():
            if not fix.get('solved') or not (fix.get('lat') or fix.get('lon')):
                continue
            items.append(('fix', f"fix:{key}",
                          f"{key}  ({fix['lat']:.3f},{fix['lon']:.3f}) "
                          f"{fix.get('quality', '?')}",
                          dict(fix, _sel_kind='fix', emitter=key)))
        for name, s in (sp.get('sensors') or {}).items():
            if not (s.get('lat') or s.get('lon')):
                continue
            items.append(('sensor', f"sensor:{name}",
                          f"{name}  ({s.get('lat', 0):.3f},{s.get('lon', 0):.3f})",
                          dict(s, _sel_kind='sensor', sensor=name)))
        # Traced emitters — no IP by nature. A solved geo_fix gives true
        # coords; unsolved ones are at your site (ring sits on YOU marker).
        for em in sp.get('emitters') or []:
            ex = em.get('extra') or {}
            if ex.get('role') in self._MAP_SEL_SELF_ROLES or \
                    'this-host' in ex.get('roles', []):
                continue
            nm = em.get('name') or em.get('address') or em.get('key', '?')
            dist = f" ≈{_fmt_dist(em['dist_m'])}" \
                if em.get('dist_m') is not None else ''
            fx = em.get('geo_fix') or {}
            pos = (f" ({fx['lat']:.3f},{fx['lon']:.3f})"
                   if fx.get('solved') else " @site")
            items.append(('em', f"em:{em.get('key', nm)}",
                          f"{nm} [{em.get('medium', '?')}]{dist}{pos}",
                          dict(em, _sel_kind='em')))
        return items

    def _map_sidebar_refresh(self, data):
        """Rebuild the sidebar row list when the mapped data changed."""
        if not self._map_sidebar_list:
            return
        items = self._map_sidebar_items(data)
        live = {k for _k2, k, _l, _i in items}
        for k in list(self._map_sel):          # prune selections for points
            if k not in live:                   # that no longer exist
                del self._map_sel[k]
        if self._map_sel_last not in self._map_sel:
            self._map_sel_last = next(reversed(self._map_sel), None) \
                if self._map_sel else None
        for w in self._map_sidebar_list.winfo_children():
            w.destroy()
        self._map_sidebar_rows.clear()
        max_rows = 400
        shown = items[:max_rows]
        for kind, key, label, item in shown:
            row = tk.Label(self._map_sidebar_list,
                           text=f" {self._MAP_SEL_ICON.get(kind, '·')} {label}",
                           bg="#0d1117", fg="#b8c8dd",
                           font=("Consolas", 7), anchor="w", cursor="hand2")
            row.pack(fill="x")
            row.bind("<Button-1>",
                     lambda e, k=key, it=item, kd=kind:
                     self._map_sidebar_toggle(k, it, kd))
            _add_tooltip(row,
                f"{kind} point\n─────────────────────\n"
                "Click to select — shows every field\n"
                "below and rings it on the map.\n"
                "Click again to toggle off.")
            self._map_sidebar_rows[key] = row
        if len(items) > max_rows:
            tk.Label(self._map_sidebar_list,
                     text=f" … +{len(items) - max_rows} more points",
                     bg="#0d1117", fg="#5a6a7a",
                     font=("Consolas", 7), anchor="w").pack(fill="x")
        if not items:
            tk.Label(self._map_sidebar_list,
                     text=" no mapped points yet — waiting on\n GeoIP / traces / spectrum fixes",
                     bg="#0d1117", fg="#5a6a7a",
                     font=("Consolas", 7), anchor="w",
                     justify="left").pack(fill="x")
        self._map_sidebar_restyle()
        self._map_update_sel_count(len(items))

    def _map_sidebar_restyle(self):
        """Highlight selected rows, dim the rest."""
        for key, row in self._map_sidebar_rows.items():
            try:
                if key in self._map_sel:
                    row.config(bg="#26334d", fg="#ffe066")
                else:
                    row.config(bg="#0d1117", fg="#b8c8dd")
            except Exception:
                pass

    def _map_update_sel_count(self, n_points=None):
        if self._map_sidebar_count is None:
            return
        n = len(self._map_sel)
        pts = (f"{n_points} pts" if n_points is not None
               else f"{len(self._map_sidebar_rows)} pts")
        self._map_sidebar_count.config(
            text=f"{pts} · {n} sel" if n else f"{pts}")

    def _map_sidebar_toggle(self, key, item, kind):
        """Toggle one row in the multi-select set."""
        if key in self._map_sel:
            del self._map_sel[key]
            if self._selected_ip and key == f"ip:{self._selected_ip}":
                self._selected_ip = next(
                    (k[3:] for k in reversed(self._map_sel)
                     if k.startswith('ip:')), None)
        else:
            self._map_sel[key] = item
            if kind == 'ip':
                self._selected_ip = item.get('ip')
                self._inspector_select('ip', item.get('ip'))
        if self._map_sel:
            self._map_sel_last = key if key in self._map_sel \
                else next(reversed(self._map_sel))
        else:
            self._map_sel_last = None
        self._map_detail_show(self._map_sel.get(self._map_sel_last))
        self._map_sidebar_restyle()
        self._map_update_sel_count()
        self._redraw_dots_only()

    def _map_deselect_all(self):
        """DESELECT ALL — reset selection, detail pane and rings."""
        self._map_sel.clear()
        self._map_sel_last = None
        self._selected_ip = None
        self._map_detail_show(None)
        self._map_sidebar_restyle()
        self._map_update_sel_count()
        self._redraw_dots_only()

    def _map_center_on_selection(self):
        """Pan the map to the selection's midpoint."""
        pts = []
        for it in self._map_sel.values():
            lat, lon = it.get('lat', 0), it.get('lon', 0)
            if it.get('_sel_kind') == 'em':
                fx = it.get('geo_fix') or {}
                if fx.get('solved'):
                    lat, lon = fx.get('lat', 0), fx.get('lon', 0)
                elif (self._last_map_data or {}).get('local_geo'):
                    lg = self._last_map_data['local_geo']
                    lat, lon = lg.get('lat', 0), lg.get('lon', 0)
            if lat or lon:
                pts.append((lat, lon))
        if not pts:
            return
        self._map_center_lat = sum(p[0] for p in pts) / len(pts)
        self._map_center_lon = sum(p[1] for p in pts) / len(pts)
        self._draw_map_full()
        self._redraw_dots_only()

    def _map_detail_show(self, item):
        """Fill the detail pane with every recorded field of one point."""
        w = self._map_detail
        if not w:
            return
        w.config(state="normal")
        w.delete("1.0", "end")
        if not item:
            w.insert("end", "Nothing selected — click a row above\n"
                            "or a dot on the map. Click again to\n"
                            "toggle off. Multiple points can stay\n"
                            "selected at once; ✖ DESELECT ALL\n"
                            "resets everything.")
            w.config(state="disabled")
            return
        kind = item.get('_sel_kind', 'point')
        icon = self._MAP_SEL_ICON.get(kind, '·')
        w.insert("end", f"{icon} {kind.upper()}\n{'─' * 34}\n")
        for k in sorted(item):
            if k.startswith('_') and k not in ('_blk_target', '_blk_status'):
                continue
            v = item[k]
            if isinstance(v, (list, tuple)):
                vs = ', '.join(str(x) for x in v[:12]) or '[]'
                if len(v) > 12:
                    vs += f" …(+{len(v) - 12})"
            elif isinstance(v, dict):
                vs = ', '.join(f"{a}={b}" for a, b in
                               list(v.items())[:12]) or '{}'
                if len(v) > 12:
                    vs += f" …(+{len(v) - 12})"
            else:
                vs = str(v)
            if len(vs) > 200:
                vs = vs[:200] + '…'
            w.insert("end", f"{k:>16}: {vs}\n")
        w.config(state="disabled")

    def _plot_sel_extras(self):
        """Ring every selected non-IP point (fixes, hops, sensors, local,
        traced emitters — unsolved ones ring at the YOU site marker)."""
        if not self._map_canvas:
            return
        lg = (self._last_map_data or {}).get('local_geo') or {}
        for key, item in self._map_sel.items():
            kind = item.get('_sel_kind')
            if kind == 'ip':
                continue  # IP points get their ring in _plot_map_dots
            lat, lon = item.get('lat', 0), item.get('lon', 0)
            if kind == 'em':
                fx = item.get('geo_fix') or {}
                if fx.get('solved'):
                    lat, lon = fx.get('lat', 0), fx.get('lon', 0)
                elif lg.get('lat') or lg.get('lon'):
                    # unsolved emitter is at your site — ring on YOU
                    lat, lon = lg.get('lat', 0), lg.get('lon', 0)
                else:
                    continue
            if not (lat or lon):
                continue
            x, y = self._latlon_to_xy(lat, lon)
            w, h = self._map_w, self._map_h
            if x < -30 or x > w + 30 or y < -30 or y > h + 30:
                continue
            self._sel_ring(x, y, item)

    def _sel_ring(self, x, y, item):
        """Yellow selection ring + label around one non-IP map point."""
        r = 11 * _MAP_MARKER_SCALE
        self._map_canvas.create_oval(
            x - r, y - r, x + r, y + r,
            outline="#ffe066", width=2, tags="dot")
        cd = 3 * _MAP_MARKER_SCALE
        self._map_canvas.create_oval(
            x - cd, y - cd, x + cd, y + cd,
            fill="#ffe066", outline="#ffffff", width=1, tags="dot")
        kind = item.get('_sel_kind', 'point')
        lbl = (item.get('name') or item.get('emitter') or item.get('sensor')
               or (f"hop {item.get('hop')}" if kind == 'hop' else None)
               or item.get('ip') or kind)
        self._map_chip_label(
            x + r + 8, y, str(lbl)[:34], "#ffe066", 9, anchor="w")

    def _plot_trace_on_map(self):
        """Plot trace hops on the map as a connected path with numbered hop markers.
        Only shows hops that have valid lat/lon coordinates.
        Includes RTT-based distance estimation rings and inter-hop latency labels."""
        if not self._map_canvas or not self._map_use_tiles:
            return
        w, h = self._map_w, self._map_h
        with self._trace_lock:
            blocks = list(self._trace_blocks)
        if not blocks:
            return
        # Plot the most recent trace block
        block = blocks[-1]
        hops = block.get("hops", [])
        if len(hops) < 2:
            return
        # Collect valid hop points
        points = []
        for hop in hops:
            lat, lon = hop.get("lat", 0), hop.get("lon", 0)
            if lat == 0 and lon == 0:
                continue
            x, y = self._latlon_to_xy(lat, lon)
            if -50 <= x <= w + 50 and -50 <= y <= h + 50:
                points.append((x, y, hop))
        if len(points) < 2:
            return
        # Draw connecting path with inter-hop latency labels
        coords = []
        for x, y, _ in points:
            coords.extend([x, y])
        self._map_canvas.create_line(
            *coords, fill="#00d4ff", width=2, dash=(4, 3),
            tags="trace_path", smooth=True)
        # Draw inter-hop latency labels at midpoints
        for i in range(len(points) - 1):
            x1, y1, hop1 = points[i]
            x2, y2, hop2 = points[i + 1]
            rtts1 = hop1.get("rtts", [])
            rtts2 = hop2.get("rtts", [])
            if rtts1 and rtts2:
                delta_rtt = abs(min(rtts2) - min(rtts1))
                if delta_rtt > 0.5:
                    mid_x = (x1 + x2) / 2
                    mid_y = (y1 + y2) / 2
                    self._map_canvas.create_text(
                        mid_x, mid_y - 6, text=f"+{delta_rtt:.0f}ms",
                        fill="#ffaa44",
                        font=("Consolas", max(4, round(7 * _MAP_MARKER_SCALE))),
                        anchor="center", tags="trace_path")
        # Draw hop markers with RTT distance rings
        for i, (x, y, hop) in enumerate(points):
            hop_no = hop.get("hop", i + 1)
            tag = hop.get("label_tag", "default")
            # Color by label type
            if tag == "critical":
                color = "#ff0000"
            elif tag == "warning":
                color = "#ff8800"
            elif tag == "cyan":
                color = "#00d4ff"
            elif tag == "dim":
                color = "#666666"
            else:
                color = "#4caf50"
            # Draw RTT-based distance estimation ring
            rtts = hop.get("rtts", [])
            if rtts and self._map_zoom >= 3:
                min_rtt = min(rtts)
                # Estimate distance: light travels ~200km/ms in fiber
                est_km = min_rtt * 100  # rough: 100km per ms (round-trip / 2)
                # Convert km to pixels at current zoom
                mpp = TileManager.meters_per_pixel(
                    hop.get("lat", self._map_center_lat), self._map_zoom)
                if mpp > 0 and est_km > 0:
                    ring_px = min(80, max(8, (est_km * 1000) / mpp))
                    # Draw distance ring (faint)
                    self._map_canvas.create_oval(
                        x - ring_px, y - ring_px, x + ring_px, y + ring_px,
                        outline=color, width=1, stipple="gray25",
                        tags="trace_path")
            # Draw hop marker
            r = 6 * _MAP_MARKER_SCALE
            self._map_canvas.create_oval(
                x - r, y - r, x + r, y + r,
                fill=color, outline="#ffffff", width=2, tags="trace_hop")
            self._map_canvas.create_text(
                x, y, text=str(hop_no), fill="#ffffff",
                font=("Consolas", max(4, round(7 * _MAP_MARKER_SCALE)), "bold"),
                tags="trace_hop")
            # Show IP + RTT label at higher zoom
            if self._map_zoom >= 4:
                ip = hop.get("ip", "")
                if ip:
                    rtt_str = f" {min(rtts):.0f}ms" if rtts else ""
                    label = hop.get("label", "")
                    label_str = f" [{label}]" if label else ""
                    self._map_canvas.create_text(
                        x + r + 2, y, text=f"{ip}{rtt_str}{label_str}",
                        fill=color,
                        font=("Consolas",
                              max(4, round(max(7, min(9, int(6 + self._map_zoom * 0.3)))
                                           * _MAP_MARKER_SCALE)), "bold"),
                        anchor="w", tags="trace_hop")

    def _show_tooltip(self, event, text, delay_ms: int = 350):
        """Show a tooltip after a short hover delay, so simply moving the
        pointer across the map does not flash tooltips."""
        self._hide_tooltip()
        x, y = event.x_root + 15, event.y_root + 10
        if delay_ms > 0 and self._root is not None:
            self._tooltip_id = self._root.after(
                delay_ms, lambda: self._render_tooltip(x, y, text))
            return
        self._render_tooltip(x, y, text)

    def _render_tooltip(self, x, y, text):
        self._tooltip_id = None
        self._tooltip = tk.Toplevel(self._root)
        self._tooltip._gna_is_tip = True
        self._tooltip.wm_overrideredirect(True)
        self._tooltip.wm_geometry(f"+{x}+{y}")
        self._tooltip.attributes("-topmost", True)
        frame = tk.Frame(self._tooltip, bg="#1e1e30", bd=1, relief="solid")
        frame.pack()
        lbl = tk.Label(frame, text=text, bg="#1e1e30", fg="#c8c8e0",
                       font=("Consolas", 9), justify="left", padx=6, pady=4)
        lbl.pack()

    def _hide_tooltip(self):
        if self._tooltip_id is not None:
            try:
                self._root.after_cancel(self._tooltip_id)
            except Exception:
                pass
            self._tooltip_id = None
        if self._tooltip:
            try:
                self._tooltip.destroy()
            except Exception:
                pass
            self._tooltip = None

    # ---------- universal label hover descriptions ----------
    def _install_label_tooltips(self):
        """Class-level <Enter> bindings so EVERY Label in the program —
        existing, future, and inside any popup — gets a hover description.
        Labels that already carry an explicit _add_tooltip are skipped via
        the _gna_has_tip flag; labels inside tooltip popups are skipped via
        the _gna_is_tip flag on their Toplevel."""
        for cls in ("Label", "TLabel"):
            try:
                self._root.bind_class(cls, "<Enter>",
                                      self._label_tip_enter, add="+")
            except Exception:
                pass

    def _label_tip_enter(self, event):
        """Fallback hover handler for labels without an explicit tooltip.
        Lazily attaches a WidgetTooltip whose text resolves live from
        _describe_label, so counters and other dynamic labels always show
        their current content."""
        w = event.widget
        try:
            if getattr(w, '_gna_has_tip', False):
                return
            if getattr(w.winfo_toplevel(), '_gna_is_tip', False):
                return
            tip = getattr(w, '_gna_auto_tip', None)
            if tip is None:
                tip = _add_tooltip(w, lambda ww=w: self._describe_label(ww))
                w._gna_auto_tip = tip
            # The widget-level <Enter> binding was just installed — too late
            # to catch this event — so schedule the popup directly.
            tip._on_enter(event)
        except Exception:
            pass

    def _describe_label(self, w):
        """Describe whatever the pointer is hovering over. Priority:
        registered description for known label texts, otherwise the
        label's own current text (resolving textvariable when needed)."""
        text = ""
        try:
            text = w.cget("text") or ""
        except Exception:
            pass
        if not text:
            try:
                var = w.cget("textvariable")
                if var:
                    text = w.tk.globalgetvar(str(var)) or ""
            except Exception:
                pass
        text = str(text).strip()
        if not text:
            return ""
        desc = _LABEL_DESCRIPTIONS.get(' '.join(text.split()))
        if desc:
            return f"{text}\n{'─' * 24}\n{desc}"
        return text

    def _on_map_dot_enter(self, event, ip, info):
        loc_conf = info.get('loc_confidence', 0)
        loc_grade = info.get('loc_grade', '')
        loc_line = f"\n📍 Location: {loc_conf}% {loc_grade}" if loc_grade else ""
        proof_lines = ""
        for p in info.get('loc_proof', [])[:3]:
            proof_lines += f"\n  {p}"
        proxy_line = ""
        pt = info.get('proxy_type', '')
        if pt:
            proxy_line = f"\n🔀 Proxy: {pt}"
            pd = info.get('proxy_detail', '')
            if pd:
                proxy_line += f"\n  {pd}"
        # VPN/proxy disclaimer — check both the MultiVerifier cache and the
        # connection's proxy_type. This is the EXIT NODE, not the real source.
        vpn_disclaimer = ""
        vpn_rep = (self._last_full_data or {}).get('multi_verifications', {}).get(ip)
        is_vpn = bool(vpn_rep and (vpn_rep.get('is_vpn') or vpn_rep.get('is_proxy')))
        if not is_vpn and pt and 'NONE' not in pt.upper():
            is_vpn = True
        if is_vpn:
            vpn_score = vpn_rep.get('vpn_score', 0) if vpn_rep else 50
            vpn_labels = ', '.join(vpn_rep.get('labels', [])) if vpn_rep else pt
            vpn_disclaimer = (
                f"\n⚠⚠⚠ VPN/PROXY EXIT NODE ⚠⚠⚠\n"
                f"  VPN Score: {vpn_score}/100\n"
                f"  Labels: {vpn_labels}\n"
                f"  ⚠ This location is the VPN EXIT NODE,\n"
                f"    NOT the real source location.\n"
                f"  ⚠ The actual user could be anywhere.\n"
                f"  ⚠ This marker may be MISLEADING.\n"
                f"  Do NOT assume this is the real origin."
            )
        domain_str = info.get('domain', '?')
        via = info.get('via', '')
        domain_line = f"Domain: {domain_str}"
        if via:
            domain_line += f" (via {via})"
        all_doms = info.get('all_domains', [])
        all_doms_line = ""
        if all_doms and len(all_doms) > 1:
            all_doms_line = f"\nAll Domains: {', '.join(all_doms[:6])}"
            if len(all_doms) > 6:
                all_doms_line += f" (+{len(all_doms)-6})"
        # Identity extras the map point carries — port/state, rdns/asn/tz,
        # verify + RTT/TTL, infra flags. Same fields the connection rows show.
        extra_lines = ""
        if info.get('remote_port'):
            extra_lines += f"\nPort: {info['remote_port']}"
            if info.get('protocol') or info.get('status'):
                extra_lines += (f"  {info.get('protocol', '')}"
                                f" {info.get('status', '')}").rstrip()
        if info.get('local_ip'):
            extra_lines += f"\nLocal: {info['local_ip']}:{info.get('local_port', '?')}"
        if info.get('region'):
            extra_lines += f"\nRegion: {info['region']}"
        if info.get('isp'):
            extra_lines += f"\nISP: {info['isp']}"
        if info.get('rdns'):
            extra_lines += f"\nrDNS: {info['rdns']}"
        if info.get('asn'):
            extra_lines += f"\nASN: {info['asn']}"
        if info.get('timezone'):
            extra_lines += f"\nTimezone: {info['timezone']}"
        if info.get('geo_source'):
            extra_lines += f"\nGeo Source: {info['geo_source']}"
        vg = info.get('verify_grade')
        if vg:
            extra_lines += f"\nVerify: {vg}"
        if info.get('rtt_ms') is not None:
            extra_lines += f"\nRTT: {info['rtt_ms']:.0f} ms"
            if info.get('ttl_os'):
                extra_lines += f"  TTL {info['ttl_os']}"
        if info.get('hop_distance') is not None:
            extra_lines += f"\nHop Dist: ~{info['hop_distance']}"
        oports = info.get('open_ports') or []
        if oports:
            extra_lines += "\nOpen Ports: " + ', '.join(
                f"{p[0]}/{p[1]}" if isinstance(p, (list, tuple)) and len(p) > 1
                else str(p) for p in oports[:8])
        infra = [k for k in ('is_vpn', 'is_proxy', 'is_tor', 'is_hosting',
                             'is_cdn') if info.get(k)]
        if infra:
            extra_lines += f"\nInfra: {', '.join(infra)}"
        _vcf = info.get('verify_conflicts') or []
        if _vcf and not vpn_rep:
            extra_lines += f"\nConflicts: {len(_vcf)}"
        if info.get('vpn_provider'):
            extra_lines += f"\nProvider: {info['vpn_provider']}"
        if info.get('vpn_labels'):
            _vl = (', '.join(map(str, info['vpn_labels'][:6]))
                   if isinstance(info['vpn_labels'], (list, tuple))
                   else str(info['vpn_labels']))
            extra_lines += f"\nVPN Labels: {_vl}"
        if info.get('category'):
            extra_lines += f"\nCategory: {info['category']}"
        if info.get('asn_org') and info.get('asn_org') != info.get('org'):
            extra_lines += f"\nASN Org: {info['asn_org']}"
        if info.get('verify_summary'):
            extra_lines += f"\nSummary: {str(info['verify_summary'])[:90]}"
        # ── MultiVerifier detail the conn row doesn't carry — surfaced so
        # the dot tooltip shows every label the verifier produced ──
        if vpn_rep:
            _cons = ', '.join(x for x in (vpn_rep.get('consensus_city', ''),
                                          vpn_rep.get('consensus_country', '')) if x)
            if _cons:
                extra_lines += f"\nConsensus: {_cons}"
            if vpn_rep.get('serving_cc'):
                extra_lines += (f"\nServing: {vpn_rep.get('serving_city') or '?'}"
                                f", {vpn_rep['serving_cc']}"
                                f" ({vpn_rep.get('serving_src') or '?'})")
            if vpn_rep.get('edge_city'):
                extra_lines += (f"\nEdge PoP: {vpn_rep.get('edge_iata') or '?'} "
                                f"→ {vpn_rep['edge_city']}")
            if vpn_rep.get('dns_leak'):
                extra_lines += f"\nDNS Leak: {vpn_rep['dns_leak'][:70]}"
            if vpn_rep.get('ttl') is not None:
                extra_lines += f"\nTTL: {vpn_rep['ttl']}"
                if vpn_rep.get('hop_distance') is None and vpn_rep.get('tcp_hops'):
                    extra_lines += f" · TCP-path {vpn_rep['tcp_hops']} hops"
            if vpn_rep.get('mss'):
                extra_lines += f"\nMSS: {vpn_rep['mss']}"
            if vpn_rep.get('aliases'):
                extra_lines += f"\nAliases: {', '.join(map(str, vpn_rep['aliases'][:4]))}"
            _n_cf = len(vpn_rep.get('conflicts') or [])
            if _n_cf:
                extra_lines += f"\nConflicts: {_n_cf}"
            _n_meth = len(vpn_rep.get('methods') or [])
            if _n_meth:
                extra_lines += f"\nEvidence: {_n_meth} methods"
        if info.get('first_seen'):
            extra_lines += f"\nSeen: {_fmt_ts(info['first_seen'])} → {_fmt_ts(info.get('last_seen', 0))}"
        wtag = info.get('website_tag', '')
        wtag_line = f"🏷️ {wtag}\n" if wtag else ""
        _icon = info.get('icon', '')
        _icon_pfx = f"{_icon} " if _icon else ""
        _cc = info.get('country_code', '')
        _cc_sfx = f" [{_cc}]" if _cc else ""
        _pid = info.get('pid')
        _pid_sfx = f" (PID {_pid})" if _pid else ""
        text = (f"{wtag_line}"
                f"IP: {ip}\n"
                f"Service: {_icon_pfx}{info.get('service', '?')}\n"
                f"{domain_line}\n"
                f"Process: {info.get('process', '?')}{_pid_sfx}\n"
                f"City: {info.get('city', '?')}, {info.get('country', '?')}{_cc_sfx}\n"
                f"Org: {info.get('org', '?')}\n"
                f"Lat: {info.get('lat', 0):.4f}, Lon: {info.get('lon', 0):.4f}"
                f"{all_doms_line}{extra_lines}{loc_line}{proof_lines}"
                f"{proxy_line}{vpn_disclaimer}\n"
                "[Click for full action log]")
        self._show_tooltip(event, text)

    def _on_map_dot_leave(self, event):
        self._hide_tooltip()

    def _on_map_dot_right_click(self, event, ip, info):
        """Right-clicking a map dot opens the same menu as the list views."""
        self._hide_tooltip()
        conn = None
        for c in (self._last_full_data or {}).get('connections', []):
            if c.get('remote_ip') == ip:
                conn = c
                break
        self._show_conn_context_menu(event, ip, conn or info)

    def _ip_owner_line(self, ip) -> str:
        """Resolve which local process currently owns a remote IP."""
        if self._monitor is None:
            return ""
        try:
            owner = self._monitor.owner_of_ip(ip)
        except Exception:
            return ""
        if not owner:
            return ""
        line = f"{owner.get('name', '?')} (PID {owner.get('pid', '?')})"
        if owner.get('status'):
            line += f" [{owner['status']}]"
        return line

    def _on_map_dot_click(self, ip):
        if self._selected_ip != ip:
            self._selected_ip = ip
            self._redraw_dots_only()   # repaint so the selection ring moves
        self._inspector_select('ip', ip)  # map dots feed the dossier too
        if self._ip_actions_text:
            self._ip_actions_text.config(state="normal")
            self._ip_actions_text.delete("1.0", "end")
            data = self._get_full_data()
            lines = [f"=== FULL ACTION LOG FOR IP: {ip} ===\n"]
            owner = self._ip_owner_line(ip)
            if owner:
                lines.append(f"Currently owned by: {owner}")
            if ip in self._watchlist_ips:
                lines.append("★ This IP is on your watchlist")
            if ip in self._blocked_ips:
                lines.append("🚫 This IP is blocked by a firewall rule")
            lines.append("")
            # Find all connections for this IP
            for conn in data.get('connections', []):
                if conn.get('remote_ip') == ip:
                    wtag = conn.get('website_tag', '')
                    if wtag:
                        lines.append(f"🏷️ WEBSITE: {wtag}")
                    lines.append(f"Connection: {conn.get('process', '?')} (PID {conn.get('pid', '?')})")
                    exe_p = conn.get('exe_path', '')
                    if exe_p:
                        lines.append(f"  Exe Path: {exe_p}")
                    parent_n = conn.get('parent_name', '')
                    if parent_n:
                        lines.append(f"  Parent: {parent_n} (PID {conn.get('parent_pid', '?')})")
                    if conn.get('cmdline'):
                        lines.append(f"  Command: {str(conn['cmdline'])[:200]}")
                    if conn.get('owner_via'):
                        lines.append(f"  Owner evidence: {conn['owner_via']}")
                    lines.append(f"  Remote: {ip}:{conn.get('remote_port', '?')}")
                    lines.append(f"  Local: {conn.get('local_ip', '?')}:{conn.get('local_port', '?')}")
                    lines.append(f"  Protocol: {conn.get('protocol', '?')}")
                    lines.append(f"  Status: {conn.get('status', '?')}")
                    lines.append(f"  Service: {conn.get('service', '?')} ({conn.get('category', '?')})")
                    via = conn.get('via', '')
                    domain_info = conn.get('domain', '?')
                    if via:
                        domain_info += f" (via {via})"
                    lines.append(f"  Domain: {domain_info}")
                    all_doms = conn.get('all_domains', [])
                    if all_doms:
                        lines.append(f"  All Domains: {', '.join(all_doms[:10])}")
                        if len(all_doms) > 10:
                            lines.append(f"    (+{len(all_doms)-10} more)")
                    lines.append(f"  Country: {conn.get('country', '?')} ({conn.get('country_code', '?')})")
                    lines.append(f"  City: {conn.get('city', '?')}, Region: {conn.get('region', '?')}")
                    if conn.get('rdns'):
                        lines.append(f"  rDNS: {conn['rdns']}")
                    if conn.get('asn') or conn.get('asn_org'):
                        lines.append(f"  ASN: {conn.get('asn', '')} {conn.get('asn_org', '')}")
                    lines.append(f"  Org: {conn.get('org', '?')}, ISP: {conn.get('isp', '?')}")
                    lines.append(f"  Coords: ({conn.get('lat', 0):.4f}, {conn.get('lon', 0):.4f})"
                                 + (f"  TZ {conn['timezone']}" if conn.get('timezone') else ""))
                    if conn.get('geo_source'):
                        lines.append(f"  Geo Source: {conn['geo_source']}")
                    lg = conn.get('loc_grade')
                    if lg:
                        lines.append(f"  Location: {conn.get('loc_confidence', 0)}% {lg}")
                        for proof in (conn.get('loc_proof') or [])[:4]:
                            lines.append(f"    {proof}")
                    if conn.get('proxy_type'):
                        lines.append(f"  Proxy: {conn['proxy_type']}"
                                     + (f" — {conn['proxy_detail']}"
                                        if conn.get('proxy_detail') else ""))
                    # MultiVerifier verdict — the connection carries it.
                    infra = [k for k in ('is_vpn', 'is_proxy', 'is_hosting',
                                         'is_cdn') if conn.get(k)]
                    if conn.get('verify_grade') or infra or conn.get('vpn_score'):
                        lines.append(f"  Verify: {conn.get('verify_grade', '?')}"
                                     f"  VPN score {conn.get('vpn_score', 0)}/100")
                        if infra:
                            lines.append(f"  Infra: {', '.join(infra)}"
                                         + (f" — {conn['vpn_provider']}"
                                            if conn.get('vpn_provider') else ""))
                        lbls = conn.get('vpn_labels') or []
                        if lbls:
                            lines.append(f"  Labels: {', '.join(map(str, lbls[:6]))}")
                        if conn.get('rtt_ms') is not None:
                            lines.append(f"  RTT: {conn['rtt_ms']:.0f} ms"
                                         + (f"  TTL {conn['ttl_os']}"
                                            if conn.get('ttl_os') else "")
                                         + (f"  ~{conn['hop_distance']} hops"
                                            if conn.get('hop_distance') is not None else ""))
                        oports = conn.get('open_ports') or []
                        if oports:
                            lines.append("  Open Ports: " + ', '.join(
                                f"{p[0]}/{p[1]}" if isinstance(p, (list, tuple)) and len(p) > 1
                                else str(p) for p in oports[:10]))
                        # Deep MultiVerifier facts — same rows the Inspector shows
                        mvr = (data.get('multi_verifications') or {}).get(ip) or {}
                        if mvr.get('path_claimed_km') is not None:
                            lines.append(f"  Path Check: {mvr['path_claimed_km']:.0f} km claimed vs "
                                         f"~{mvr.get('path_ceiling_km', 0):.0f} km RTT ceiling"
                                         + (" — IMPLAUSIBLE" if mvr.get('path_implausible') else ""))
                        if mvr.get('rtt_outlier_city'):
                            lines.append("  ⚠ PEER: RTT outlier vs same-city endpoints — relabelled")
                        if mvr.get('dns_leak'):
                            lines.append(f"  DNS Leak: {mvr['dns_leak']}")
                        if mvr.get('tls_ja3'):
                            lines.append(f"  TLS JA3: {mvr['tls_ja3']}")
                        if mvr.get('methods'):
                            lines.append("  Verify Methods: " + ', '.join(
                                f"{m.get('name', '')}[{m.get('status', '')}]"
                                for m in mvr['methods']))
                            # every evidence field the curated lines above
                            # did not print still gets a row
                            _mvr_seen = {'path_claimed_km', 'path_ceiling_km',
                                         'path_implausible', 'rtt_outlier_city',
                                         'dns_leak', 'tls_ja3', 'methods'}
                            for _k, _vs in _mv_unrendered(mvr, _MV_ROW_SHOWN):
                                if _k in _mvr_seen:
                                    continue
                                lines.append(f"  {_k}: {_vs[:90]}")
                        for cf in (conn.get('verify_conflicts') or [])[:3]:
                            lines.append(f"  ⚠ {cf}")
                        if conn.get('verify_summary'):
                            lines.append(f"  {conn['verify_summary']}")
                    lines.append(f"  First Seen: {_fmt_ts(conn.get('first_seen', 0))}")
                    lines.append(f"  Last Seen: {_fmt_ts(conn.get('last_seen', 0))}")
                    bw = (data.get('conn_bandwidth') or {}).get(ip) or {}
                    if bw:
                        lines.append(f"  Bandwidth: ▲{_fmt_bytes(bw.get('bytes_sent', 0))} sent  "
                                     f"▼{_fmt_bytes(bw.get('bytes_recv', 0))} recv")
                    lines.append("")
            # Find all deductions mentioning this IP
            lines.append(f"\n=== DEDUCTIONS INVOLVING {ip} ===")
            for d in data.get('deductions', []):
                if ip in (d.get('message', '') + ' '.join(d.get('evidence', []))):
                    lines.append(f"[{d.get('time', '?')}] [{d.get('severity', '?')}] {d.get('category', '?')}")
                    lines.append(f"  Process: {d.get('process', '?')} (PID {d.get('pid', '?')})")
                    lines.append(f"  Message: {d.get('message', '?')}")
                    for ev in d.get('evidence', []):
                        lines.append(f"    -> {ev}")
                    lines.append(f"  Score: {d.get('score', 0)}")
                    lines.append("")
            # Find all process actions involving this IP
            lines.append(f"\n=== PROCESS ACTIONS INVOLVING {ip} ===")
            for act in data.get('all_actions', []):
                if ip in str(act):
                    lines.append(f"  {act}")
            if len(lines) <= 4:
                lines.append("  (No detailed actions recorded yet for this IP)")
            self._ip_actions_text.insert("1.0", "\n".join(lines))
            self._ip_actions_text.config(state="disabled")

    def run(self):
        try:
            self._run_gui()
        except Exception as exc:
            import traceback
            print(f"GUI RUN CRASH: {exc}", flush=True)
            traceback.print_exc()
            # Re-raise so the monitor's run() falls back to terminal mode
            # instead of treating a failed window as a clean GUI exit and
            # shutting the whole program down.
            raise

    def _run_gui(self):
        _require('tkinter'); _require('pil')
        self._root = tk.Tk()
        self._install_label_tooltips()
        self._root.title("GNA Tracer — Full Network Intelligence")
        self._root.geometry("1280x820")
        self._root.configure(bg="#0a0a0f")
        self._root.protocol("WM_DELETE_WINDOW", self._on_close)

        P = self.PAL
        style = ttk.Style()
        style.theme_use("clam")
        style.configure("TNotebook", background=P['bg'], borderwidth=0)
        # Reference-style pill tabs: compact padding + small bold caps so all
        # sixteen tabs stay readable next to the inspector dock.
        style.configure("TNotebook.Tab", background=P['panel'], foreground=P['dim'],
                        padding=[8, 5], font=("Consolas", 8, "bold"))
        style.map("TNotebook.Tab",
                  background=[("selected", "#e94560"), ("active", P['panel_hi'])],
                  foreground=[("selected", "#ffffff"), ("active", P['text'])])
        style.configure("TFrame", background=P['bg'])
        style.configure("Treeview", background=P['textbox'], foreground="#c0c0c0",
                        fieldbackground=P['textbox'], font=("Consolas", 9),
                        rowheight=20)
        style.configure("Treeview.Heading", background=P['panel'], foreground="#ff5566",
                        font=("Consolas", 9, "bold"))
        style.map("Treeview", background=[("selected", "#0f3460")])
        # Dark scrollbars / scale / combobox so the chrome matches the theme.
        style.configure("Vertical.TScrollbar", background=P['panel'],
                        troughcolor=P['bg'], bordercolor=P['bg'],
                        arrowcolor=P['dim'], darkcolor=P['bg'], lightcolor=P['bg'])
        style.map("Vertical.TScrollbar", background=[("active", P['border'])])
        style.configure("Horizontal.TScrollbar", background=P['panel'],
                        troughcolor=P['bg'], bordercolor=P['bg'],
                        arrowcolor=P['dim'], darkcolor=P['bg'], lightcolor=P['bg'])
        style.map("Horizontal.TScrollbar", background=[("active", P['border'])])
        style.configure("TScale", background=P['panel'], troughcolor=P['bg'])
        style.configure("TCombobox", fieldbackground=P['entry'],
                        background=P['panel'], foreground=P['text'],
                        arrowcolor=P['accent'], bordercolor=P['border'])
        style.map("TCombobox",
                  fieldbackground=[("readonly", P['entry'])],
                  foreground=[("readonly", P['text'])])
        style.configure("TSeparator", background=P['border'])

        # ==================== HEADER: brand + threat chip + clock ====================
        # Radiant signature: every panel carries a 1px lighter line along its
        # top edge — reads as a faint top glow. The window gets one too.
        tk.Frame(self._root, bg=P['edge'], height=1).pack(fill="x")
        hdr = tk.Frame(self._root, bg=P['panel'], height=56)
        hdr.pack(fill="x")
        hdr.pack_propagate(False)
        brand = tk.Frame(hdr, bg=P['panel'])
        brand.pack(side="left", padx=(12, 0), pady=7)
