                    # on v6 too (ESP/GRE/IPIP ride next-header, not an
                    # IP proto): without this branch an IPv6 IPsec or
                    # GRE tunnel was invisible.
                    _nh6 = int(_ip6.nh)
                    if _nh6 in _L3_TUNNEL_PROTOS:
                        _l3 = _w.setdefault('l3', {})
                        _nm = _L3_TUNNEL_PROTOS[_nh6]
                        _l3[_nm] = _l3.get(_nm, 0) + 1
                        if _nh6 == 50:
                            _esb = bytes(_ip6.payload)
                            if len(_esb) >= 8:
                                _salink('esp', _esb[:4])
                        if _nh6 in _INNER_DECAP_PROTOS:
                            _pl6 = bytes(_ip6.payload)
                            if _nh6 == 47:
                                if len(_pl6) >= 8 and (_pl6[0] & 0x20):
                                    _ko = 4 + (4 if _pl6[0] & 0xC0
                                               else 0)
                                    _salink('gre', _pl6[_ko:_ko + 4])
                                _pl6 = _parse_gre_inner(_pl6)
                            if _pl6:
                                _inner(_pl6)
                    elif _nh6 in _L3_ODD_PROTOS:
                        _oc = _w.setdefault('l3chan', {})
                        _oc[_L3_ODD_PROTOS[_nh6]] = \
                            _oc.get(_L3_ODD_PROTOS[_nh6], 0) + 1
                        if _nh6 == 132:
                            try:
                                _sa7 = _parse_sctp_addrs(
                                    bytes(_ip6.payload))
                                if _sa7:
                                    _w['sctp'] = _w.get('sctp', 0) + 1
                                    _ss7 = _w.setdefault('sctp_ips',
                                                         set())
                                    for _sip7 in _sa7:
                                        if len(_ss7) < 16 \
                                                or _sip7 in _ss7:
                                            _ss7.add(_sip7)
                                        _leak_ip(_sip7)
                            except Exception:
                                pass
                    elif _nh6 == 58 and has_raw:
                        # ICMPv6 — the v6 forms of every ICMP mask:
                        # fat echoes tunnel data, errors quote the
                        # dropped inner packet, redirect/RA bend
                        # routes.
                        _icb = bytes(_raw.load)
                        _il2 = len(_icb)
                        _it = _icb[0] if _icb else -1
                        if _it in (1, 3, 4) and _il2 >= 48:
                            _inner(_icb[8:])
                            _iq = _w.setdefault('icmq', {})
                            _iq[_it] = _iq.get(_it, 0) + 1
                        elif _it in (137, 134):
                            _rt = _w.setdefault('icmpt', {})
                            _rt[_it] = _rt.get(_it, 0) + 1
                        if _it in (128, 129) and _il2 > 72:
                            _w['icmp'] = _w.get('icmp', 0) + 1
                            _w['icmp_big'] = max(
                                _w.get('icmp_big', 0), _il2)
                            _inner(_icb[8:])
                        elif _it in (139, 140):
                            _ir2 = _w.setdefault('icmpr', {})
                            _ir2[_it] = _ir2.get(_it, 0) + 1
