def migrate_legacy_files() -> None:
    install_dir = PROJECT_DIR.parent.absolute()
    migrations = [("shared_paths.json", SHARED_PATHS_FILE), ("known_peers.json", PEERS_FILE), ("my_join_time.txt", MY_JOIN_TIME_FILE)]
    for old_name, new_path in migrations:
        old_path = install_dir / old_name
        if old_path.exists() and not new_path.exists():
            try:
                shutil.copy2(old_path, new_path)
            except Exception:
                pass

def load_about_text() -> str:
    # Was a disk read per dashboard request; reload only when the file's
    # mtime changes.
    global _about_text_cache
    try:
        mtime = ABOUT_FILE.stat().st_mtime
    except OSError:
        mtime = None
    cached = _about_text_cache
    if cached and cached[0] == mtime:
        return cached[1]
    if ABOUT_FILE.exists():
        text = ABOUT_FILE.read_text(encoding="utf-8")
        _about_text_cache = (mtime, text)
        return text
    return DEFAULT_ABOUT_TEXT

