# infrastructure/id_generator
# ===========================================================================
_used_call_numbers = set()

def generate_random_peer_id():
    suffix = ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))
    return PeerId(f"bank-{suffix}")

def generate_call_number():
    while True:
        part1 = random.randint(100, 999)
        part2 = random.randint(100, 999)
        part3 = random.randint(1000, 9999)
        call_number = f"{part1}-{part2}-{part3}"
        if call_number not in _used_call_numbers:
            _used_call_numbers.add(call_number)
            return call_number

def generate_peer_id_from_ip(ip):
    return PeerId(f"unknown-{ip.replace('.', '-')}")

# ===========================================================================
# infrastructure/discovery
# ===========================================================================
class PeerDiscoveryListener(ServiceListener):
    def __init__(self, state, my_id):
        self.state = state
        self.my_id = my_id
    def add_service(self, zc, type_, name):
        info = zc.get_service_info(type_, name)
        if not info: return
        properties = dict(info.properties or {})
        peer_id_bytes = properties.get(b'id', b'')
        peer_id_str = peer_id_bytes.decode() if peer_id_bytes else ''
        if not peer_id_str or peer_id_str == self.my_id.value: return
        for addr in info.parsed_addresses(IPVersion.V4Only):
            peer_info = PeerInfo(ip=addr, port=info.port, join_time=time.time(), last_seen=time.time())
            self.state.add_discovered_peer(peer_id_str, peer_info)
    def remove_service(self, zc, type_, name): pass
    def update_service(self, zc, type_, name): pass

def register_service(zc, my_id, local_ip):
    service_name = f"{my_id.value}.{SERVICE_TYPE}"
    info = ServiceInfo(SERVICE_TYPE, service_name, addresses=[socket.inet_aton(local_ip)], port=PORT, properties={b'id': my_id.value.encode()})
    zc.register_service(info)
    return info

def start_discovery(zc, state, my_id):
    listener = PeerDiscoveryListener(state, my_id)
    return ServiceBrowser(zc, SERVICE_TYPE, listener)

# ===========================================================================
# infrastructure/global_discovery
# ===========================================================================
GLOBAL_CONFIG_FILE = PROJECT_DIR / "global_config.json"
DEFAULT_GLOBAL_CONFIG = {"enabled": True, "relay_url": "http://localhost:3000", "relay_urls": [], "network_code": "publan-global-v1", "auto_connect": True, "brave_api_key": ""}
# Built-in meeting places, tried in order after user-configured relays. More
# entries = more ways for two instances to find each other when one is down.
DEFAULT_RELAY_URLS = [
    "http://localhost:3000",
    "http://127.0.0.1:3000",
    "http://localhost:3001",
    "http://127.0.0.1:3001",
    "http://localhost:3002",
    "http://127.0.0.1:3002",
    "http://localhost:3003",
    "http://127.0.0.1:3003",
]

def _env_relay_urls():
    """Extra meeting places supplied via GNA_RELAY_URLS (comma/space/newline
    separated) — lets a whole deployment share relays without editing files."""
    raw = os.environ.get('GNA_RELAY_URLS', '')
    urls = []
    for u in re.split(r'[\s,;]+', raw):
        u = u.strip()
        if u.startswith(('http://', 'https://')) and u not in urls:
            urls.append(u)
    return urls

def load_global_config():
    if GLOBAL_CONFIG_FILE.exists():
        try: return json.loads(GLOBAL_CONFIG_FILE.read_text(encoding="utf-8"))
        except Exception: pass
    return DEFAULT_GLOBAL_CONFIG.copy()

def save_global_config(config):
    try: GLOBAL_CONFIG_FILE.write_text(json.dumps(config, indent=2), encoding="utf-8")
    except Exception: pass

class GlobalDiscoveryService:
    def __init__(self, my_peer_id, my_call_number, local_ip, local_port, on_peers_updated=None):
        self.my_peer_id = my_peer_id
        self.my_call_number = my_call_number
        self.local_ip = local_ip
        self.local_port = local_port
        self.on_peers_updated = on_peers_updated
        self.config = load_global_config()
        self.sio = None
        self.global_peers = []
        self.running = False
        self._thread = None
        self._loop = None
        self.active_relay = ""
        self.relay_states = {}
    @property
    def enabled(self): return bool(HAS_SOCKETIO and self.config.get("enabled") and self.config.get("network_code") and self.relay_urls)
    @property
    def network_code(self): return self.config.get("network_code", "")
    @property
    def relay_url(self):
        urls = self.relay_urls
        return urls[0] if urls else "http://localhost:3000"
    @property
    def relay_urls(self):
        """All configured meeting places (relays), deduped, ordered by preference."""
        urls = []
        cfg_urls = self.config.get("relay_urls") or []
        if isinstance(cfg_urls, str):
            cfg_urls = [u.strip() for u in cfg_urls.replace('\n', ',').replace(';', ',').split(',')]
        for u in cfg_urls:
            u = str(u).strip()
            if u and u.startswith(('http://', 'https://')) and u not in urls:
                urls.append(u)
        legacy = (self.config.get("relay_url") or "").strip()
        if legacy and legacy.startswith(('http://', 'https://')) and legacy not in urls:
            urls.append(legacy)
        for u in _env_relay_urls() + DEFAULT_RELAY_URLS:
            if u not in urls:
                urls.append(u)
        return urls
    def start(self):
        if not self.enabled: return
        _require('asyncio'); _require('socketio')
        self.running = True
        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(target=self._run_loop, daemon=True, name="GlobalDiscoveryThread")
        self._thread.start()
    def _run_loop(self):
        asyncio.set_event_loop(self._loop)
        try:
            self._loop.run_until_complete(self._connect_and_run())
        except asyncio.CancelledError:
            pass
        except Exception as e:
            print(f"[WARNING] Global discovery stopped: {e}")
        finally:
            try: self._loop.close()
            except Exception: pass
    async def _connect_and_run(self):
        self.sio = socketio.AsyncClient(reconnection=True, reconnection_attempts=0, reconnection_delay=5, reconnection_delay_max=30)
        @self.sio.event
        async def connect():
            await self._register()
        @self.sio.event
        async def disconnect():
            if self.active_relay in self.relay_states:
                self.relay_states[self.active_relay] = 'disconnected'
        @self.sio.on("global-peer-list")
        async def on_peer_list(data):
            self.global_peers = [p for p in (data or []) if p.get("peerId") != self.my_peer_id]
            if self.on_peers_updated:
                try: self.on_peers_updated(self.global_peers)
                except Exception: pass
        # Outer loop: rotate through all configured meeting places until one works.
        # If a connected relay drops, move on to the next one.
        while self.running:
            for url in self.relay_urls:
                if not self.running: break
                self.relay_states[url] = 'connecting'
                try:
                    await self.sio.connect(url, wait_timeout=8)
                    self.active_relay = url
                    self.relay_states[url] = 'connected'
                    # Heartbeat loop on the active relay
                    while self.running and self.sio and self.sio.connected:
                        for _ in range(10):
                            if not self.running or not self.sio.connected: break
                            await asyncio.sleep(0.5)
                        if not self.running or not self.sio.connected: break
                        try:
                            await self._register()
                            await self.sio.emit("request-global-peers", {"networkCode": self.network_code})
                        except Exception:
                            break
                    if self.sio and self.sio.connected:
                        try: await self.sio.disconnect()
                        except Exception: pass
                    self.active_relay = ""
                    if self.running:
                        self.relay_states[url] = 'disconnected'
                except asyncio.CancelledError:
                    self.relay_states[url] = 'disconnected'
                    break
                except Exception:
                    self.relay_states[url] = 'failed'
            if self.running:
                self.active_relay = ""
                await asyncio.sleep(10)  # back off before retrying all relays
    async def _register(self):
        if not self.sio or not self.sio.connected: return
        await self.sio.emit("register-global-peer", {"networkCode": self.network_code, "peerId": self.my_peer_id, "friendlyName": platform.node(), "ip": self.local_ip, "port": self.local_port, "callNumber": self.my_call_number})
    def stop(self):
        self.running = False
        if self.sio and self._loop and self._loop.is_running():
            try:
                future = asyncio.run_coroutine_threadsafe(self.sio.disconnect(), self._loop)
                future.result(timeout=5)
            except Exception: pass
        if self._thread and self._thread.is_alive(): self._thread.join(timeout=10)
    def get_status(self):
        if not HAS_SOCKETIO: return "UNAVAILABLE (python-socketio not installed)"
        if not self.enabled: return "DISABLED"
        if self.sio and self.sio.connected:
            return f"CONNECTED via {self.active_relay} ({len(self.global_peers)} peers)"
        return "CONNECTING..."
    def get_relay_states(self):
        states = {}
        for url in self.relay_urls:
            if url == self.active_relay and self.sio and self.sio.connected:
                states[url] = 'connected'
            else:
                states[url] = self.relay_states.get(url, 'pending')
        return states

# ===========================================================================
# embedded signaling + relay server
# ===========================================================================
# The original design relied on an external Node.js server.js on :3000 acting
# as BOTH the call-signaling hub and the global-discovery meeting place. When
# it's absent every GNA instance reports OFFLINE. This replaces it in-process:
# the first instance to start binds a socket.io server on the first free port
# in 3000-3003 and hosts the meeting place; other instances find /health
# already answering and simply connect as clients. Configured relays still
# take precedence client-side — this is the always-available backup route.
_EMB_RELAY = {"server": None, "port": None, "relay": None}
_EMB_RELAY_PORTS = (3000, 3001, 3002, 3003)


class _GNARelay:
    """Self-hosted socket.io meeting place + signaling hub (server.js
    replacement). Implements the event surface the clients and dashboard
    expect: global-peer registry/discovery, dashboard notifications, remote-
    access session tracking, and screen-share/remote-input relaying.
    Runs as an ASGI app under uvicorn so real websocket transport works
    (screen frames are too heavy for long-polling)."""

    PEER_TTL = 120.0   # registered peers that stop heartbeating are dropped

    def __init__(self):
        self.sio = socketio.AsyncServer(async_mode='asgi',
                                        cors_allowed_origins='*',
                                        ping_timeout=30, ping_interval=10)
        self.peers = {}        # networkCode -> {peerId: info}
        self.sid_peer = {}     # sid -> (networkCode, peerId)
        self.sessions = {}     # sessionId -> remote-access session dict
        self.lock = threading.RLock()
        self._wire()

    def _peers_for(self, nc):
        now = time.time()
        with self.lock:
            net = self.peers.get(nc, {})
            for pid in [p for p, i in net.items() if now - i.get('ts', 0) > self.PEER_TTL]:
                net.pop(pid, None)
            return [dict(i, peerId=pid) for pid, i in net.items()]

    async def _broadcast_peers(self, nc):
        await self.sio.emit('global-peer-list', self._peers_for(nc))

    def _wire(self):
        sio = self.sio

        @sio.event
        async def disconnect(sid):
            nc = None
            with self.lock:
                entry = self.sid_peer.pop(sid, None)
                if entry:
                    nc = entry[0]
                    self.peers.get(nc, {}).pop(entry[1], None)
            if nc:
                await self._broadcast_peers(nc)

        @sio.on('register-global-peer')
        async def _register(sid, data):
            d = data or {}
            nc, pid = d.get('networkCode'), d.get('peerId')
            if not nc or not pid:
                return
            info = {'friendlyName': d.get('friendlyName', ''),
                    'ip': d.get('ip', ''), 'port': d.get('port', ''),
                    'callNumber': d.get('callNumber', ''), 'ts': time.time()}
            with self.lock:
                old = self.sid_peer.get(sid)
                self.peers.setdefault(nc, {})[pid] = info
                self.sid_peer[sid] = (nc, pid)
                # one sid re-registering under a different id: drop the old one
                if old and old != (nc, pid):
                    self.peers.get(old[0], {}).pop(old[1], None)
            await self._broadcast_peers(nc)

        @sio.on('request-global-peers')
        async def _request(sid, data):
            nc = (data or {}).get('networkCode')
            if nc:
                await sio.emit('global-peer-list', self._peers_for(nc), to=sid)

        @sio.on('dashboard-join')
        async def _dash(sid, data):
            pass  # dashboards are just listeners; kept for API parity

        @sio.on('remote-access-register')
        async def _ra_start(sid, data):
            d = data or {}
            sess_id = str(d.get('sessionId') or '')
            if not sess_id:
                return
            sess = {'sessionId': sess_id, 'active': True,
                    'remotePeerId': d.get('remotePeerId', ''),
                    'remoteName': d.get('remoteName', ''), 'since': time.time()}
            with self.lock:
                self.sessions[sess_id] = sess
            await sio.emit('remote-access-status', dict(sess))

        @sio.on('remote-access-end')
        async def _ra_end(sid, data):
            sess_id = str((data or {}).get('sessionId') or '')
            with self.lock:
                self.sessions.pop(sess_id, None)
            await sio.emit('remote-access-status',
                           {'sessionId': sess_id, 'active': False})

        @sio.on('screen-frame')
        async def _frame(sid, data):
            await sio.emit('screen-frame', data)   # sender -> all viewers

        @sio.on('remote-input')
        async def _input(sid, data):
            await sio.emit('remote-input', data)   # viewer -> sender

    def asgi_app(self):
        """ASGI app: /health + the small REST surface the dashboard calls,
        everything else delegated to the socket.io endpoint."""
        inner = socketio.ASGIApp(self.sio)
        sessions, emit = self.sessions, self.sio.emit

        async def _send_json(send, obj, code=200, extra_headers=()):
            body = obj if isinstance(obj, bytes) else json.dumps(obj).encode()
            headers = [(b'content-type', b'application/json'),
                       (b'access-control-allow-origin', b'*')] + list(extra_headers)
            await send({'type': 'http.response.start', 'status': code,
                        'headers': headers})
            await send({'type': 'http.response.body', 'body': body})

        async def app(scope, receive, send):
            if scope['type'] != 'http':
                return await inner(scope, receive, send)
            path = scope['path']
            method = scope['method']
            if path == '/health':
                return await _send_json(send, {'status': 'ok', 'service': 'gna-relay'})
            if method == 'OPTIONS':
                return await _send_json(send, b'', code=204, extra_headers=[
                    (b'access-control-allow-methods', b'GET,POST,OPTIONS'),
                    (b'access-control-allow-headers', b'Content-Type')])
            if path == '/api/remote-access-status' and method == 'GET':
                with self.lock:
                    sess = [dict(v) for v in sessions.values()]
                return await _send_json(send, {'sessions': sess})
            if method == 'POST' and path in ('/api/share-update',
                                             '/api/remote-access-revoke'):
                body = b''
                while True:
                    msg = await receive()
                    if msg['type'] == 'http.request':
                        body += msg.get('body', b'')
                        if not msg.get('more_body'):
                            break
                    elif msg['type'] == 'http.disconnect':
                        break
                try:
                    d = json.loads(body.decode('utf-8') or '{}')
                except Exception:
                    d = {}
                if path == '/api/share-update':
                    await emit('share-updated', d)
                else:
                    sess_id = str(d.get('sessionId') or '')
                    with self.lock:
                        sessions.pop(sess_id, None)
                    await emit('remote-access-status',
                               {'sessionId': sess_id, 'active': False})
                return await _send_json(send, {'ok': True})
            return await inner(scope, receive, send)
        return app


def _relay_healthy(port, timeout=0.5):
    try:
        return _HTTP_SESSION.get(
            f'http://127.0.0.1:{port}/health', timeout=timeout).status_code == 200
    except Exception:
        return False


def _start_embedded_relay():
    """Bind the embedded relay on the first usable port in 3000-3003.
    If one of those ports already answers /health, another instance (or a
    real server.js) is already hosting — we just record it and connect as
    a client. Returns the serving port or None."""
    if not HAS_SOCKETIO:
        return None
    _require('socketio')
    try:
        import uvicorn
    except ImportError:
        return None
    for port in _EMB_RELAY_PORTS:
        if _relay_healthy(port):
            _EMB_RELAY['port'] = port      # someone already hosts it
            return port
        probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            probe.bind(('0.0.0.0', port))
        except OSError:
            probe.close()
            continue                        # port busy but unhealthy — next
        probe.close()
        relay = _GNARelay()
        config = uvicorn.Config(relay.asgi_app(), host='0.0.0.0', port=port,
                                log_level='error', access_log=False)
        server = uvicorn.Server(config)
        server.install_signal_handlers = lambda: None   # not main thread
        threading.Thread(target=server.run, daemon=True,
                         name=f'GNARelay:{port}').start()
        _EMB_RELAY.update({'server': server, 'port': port, 'relay': relay})
        return port
    return None


def _relay_origin():
    """Origin of the live relay/signaling server — embedded port if we host
    or found one, else the :3000 convention."""
    port = _EMB_RELAY.get('port')
    return f'http://localhost:{port}' if port else 'http://localhost:3000'


# ===========================================================================
# embedded screen-share sender (sender.py carried inside the monolith)
# ===========================================================================
# Two delivery routes, tried in order: (1) the embedded source is written to
# sender.py and spawned as its own process — keeps the status probe's
# cmdline scan honest and survives monolith restarts; (2) if the file can't
# be written or the spawn fails, the same capture loop runs in-process on a
# daemon thread so screen sharing is never dead.
_SENDER_SRC = r'''# sender.py — GNA screen-share sender (embedded in Main_monolith.py).
import base64
import io
import os
import sys
import time

try:
    import socketio
    import mss
    from PIL import Image
except ImportError as e:
    print(f"[sender] missing dependency: {e}")
    sys.exit(1)

RELAY_PORTS = (3000, 3001, 3002, 3003)
FPS = 2.0
JPEG_QUALITY = 55
MAX_WIDTH = 1280
HERE = os.path.dirname(os.path.abspath(__file__))


def _session_id():
    try:
        with open(os.path.join(HERE, 'sender_session_id.txt'), 'r', encoding='utf-8') as f:
            return f.read().strip() or 'sender'
    except Exception:
        return 'sender'


def _find_relay():
    import urllib.request
    for port in RELAY_PORTS:
        try:
            with urllib.request.urlopen(f'http://127.0.0.1:{port}/health', timeout=1.5) as r:
                if r.status == 200:
                    return f'http://127.0.0.1:{port}'
        except Exception:
            continue
    return None


def main():
    session = _session_id()
    sio = socketio.Client(reconnection=True, reconnection_delay=3,
                          reconnection_delay_max=15)

    url = None
    while url is None:
        url = _find_relay()
        if url is None:
            time.sleep(3)

    try:
        sio.connect(url, wait_timeout=8)
    except Exception as e:
        print(f"[sender] relay connect failed: {e}")

    @sio.event
    def connect():
        print(f"[sender] connected to {url}")

    @sio.on('remote-input')
    def on_remote_input(data):
        pass

    with mss.mss() as cap:
        monitor = cap.monitors[1]
        while True:
            try:
                if not sio.connected:
                    try:
                        sio.connect(_find_relay() or url, wait_timeout=5)
                    except Exception:
                        time.sleep(2)
                        continue
                raw = cap.grab(monitor)
                img = Image.frombytes('RGB', raw.size, raw.bgra, 'raw', 'BGRX')
                if img.width > MAX_WIDTH:
                    img = img.resize((MAX_WIDTH, int(img.height * MAX_WIDTH / img.width)),
                                     Image.BILINEAR)
                buf = io.BytesIO()
                img.save(buf, 'JPEG', quality=JPEG_QUALITY)
                sio.emit('screen-frame', {
                    'sessionId': session,
                    'w': img.width, 'h': img.height,
                    'ts': time.time(),
                    'data': base64.b64encode(buf.getvalue()).decode('ascii'),
                })
                time.sleep(1.0 / FPS)
            except Exception as e:
                print(f"[sender] frame error: {e}")
                time.sleep(1)


if __name__ == '__main__':
    try:
        main()
    except KeyboardInterrupt:
        pass
'''


def _ensure_sender_script(path):
    """Materialize sender.py from the embedded source when it's missing —
    keeps the monolith standalone (the sender ships inside it)."""
    try:
        if path.exists():
            return True
        path.write_text(_SENDER_SRC, encoding='utf-8')
        return True
    except Exception:
        return False


def _find_relay_url():
    for port in _EMB_RELAY_PORTS:
        if _relay_healthy(port):
            return f'http://127.0.0.1:{port}'
    return None


_EMB_SENDER = {"running": False}


def _embedded_sender_main():
    """Backup route for sender.py: identical capture loop running in-process
    on a daemon thread. Used when the file can't be written or spawned."""
    global _EMB_SENDER
    if not HAS_SOCKETIO:
        return
    try:
        import mss as _mss
        from PIL import Image as _Image
    except ImportError:
        return
    session = 'embedded-sender'
    try:
        session = (PROJECT_DIR / 'sender_session_id.txt').read_text().strip() or session
    except Exception:
        pass
    _require('socketio')
    sio = socketio.Client(reconnection=True, reconnection_delay=3,
                          reconnection_delay_max=15)
    while True:
        url = _find_relay_url()
        if not url:
            time.sleep(3)
            continue
        try:
            if not sio.connected:
                sio.connect(url, wait_timeout=8)
        except Exception:
            time.sleep(3)
            continue
        _EMB_SENDER['running'] = True
        try:
            with _mss.mss() as cap:
                mon = cap.monitors[1]
                while True:
                    if not sio.connected:
                        break
                    raw = cap.grab(mon)
                    img = _Image.frombytes('RGB', raw.size, raw.bgra, 'raw', 'BGRX')
                    if img.width > 1280:
                        img = img.resize((1280, int(img.height * 1280 / img.width)),
                                         _Image.BILINEAR)
                    buf = _io.BytesIO()
                    img.save(buf, 'JPEG', quality=55)
                    sio.emit('screen-frame', {
                        'sessionId': session, 'w': img.width, 'h': img.height,
                        'ts': time.time(),
                        'data': base64.b64encode(buf.getvalue()).decode('ascii')})
                    time.sleep(0.5)
        except Exception:
            time.sleep(1)
        _EMB_SENDER['running'] = False
        try:
            sio.disconnect()
        except Exception:
            pass


# ===========================================================================
# infrastructure/persistence
# ===========================================================================
def load_shared_paths():
    if not SHARED_PATHS_FILE.exists(): return {}
    try:
        with open(SHARED_PATHS_FILE, encoding='utf-8') as f:
            data = json.load(f)
            if isinstance(data, dict): return data
            return {}
    except Exception: return {}

def save_shared_paths(paths):
    try:
        SHARED_PATHS_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(SHARED_PATHS_FILE, 'w', encoding='utf-8') as f: json.dump(paths, f, indent=2, ensure_ascii=False)
    except Exception: pass

def load_known_peers():
    if not PEERS_FILE.exists(): return {}
    try:
        with open(PEERS_FILE, encoding='utf-8') as f:
            raw_data = json.load(f)
            peers = {}
            for pid, data in raw_data.items():
                try: peers[pid] = PeerInfo(ip=data['ip'], port=data['port'], join_time=data.get('join_time', 0.0), last_seen=data.get('last_seen', 0.0))
                except (KeyError, TypeError): pass
            return peers
    except Exception: return {}

def save_known_peers(peers):
    try:
        PEERS_FILE.parent.mkdir(parents=True, exist_ok=True)
        raw_data = {pid: {'ip': info.ip, 'port': info.port, 'join_time': info.join_time, 'last_seen': info.last_seen} for pid, info in peers.items()}
        with open(PEERS_FILE, 'w', encoding='utf-8') as f: json.dump(raw_data, f, indent=2)
    except Exception: pass

def load_join_time():
    if MY_JOIN_TIME_FILE.exists():
        try: return float(MY_JOIN_TIME_FILE.read_text().strip())
        except (ValueError, IOError): pass
    join_time = time.time()
    try:
        MY_JOIN_TIME_FILE.parent.mkdir(parents=True, exist_ok=True)
        MY_JOIN_TIME_FILE.write_text(str(join_time))
    except Exception: pass
    return join_time

# ===========================================================================
# application/state
# ===========================================================================
@dataclass
class ApplicationState:
    my_id: PeerId
    my_join_time: float
    local_ip: str
    public_ip: str
    call_number: str = ""
    shared_paths: SharedPaths = field(default_factory=dict)
    known_peers: PeerRegistry = field(default_factory=dict)
    discovered_peers: PeerRegistry = field(default_factory=dict)
    inbox: list = field(default_factory=list)
    _lock: RLock = field(default_factory=RLock, init=False, repr=False)
    def get_my_info(self):
        with self._lock:
            ip = self.public_ip if self.public_ip != "unknown" else self.local_ip
            return PeerInfo(ip=ip, port=PORT, join_time=self.my_join_time, last_seen=time.time())
    def update_shared_paths(self, new_paths):
        with self._lock: self.shared_paths = new_paths
    def get_shared_paths(self):
        with self._lock: return dict(self.shared_paths)
    def add_known_peer(self, peer_id, info):
        with self._lock: self.known_peers[peer_id] = info
    def get_known_peers(self):
        with self._lock: return dict(self.known_peers)
    def add_discovered_peer(self, peer_id, info):
        with self._lock: self.discovered_peers[peer_id] = info
    def get_discovered_peers(self):
        with self._lock: return dict(self.discovered_peers)
    def mark_peer_alive(self, peer_id, info, new_peer_id=None):
        """Refresh a peer's last_seen; re-key the entry if the peer reports a
        different session id. Checks both known and discovered registries."""
        with self._lock:
            target_id = new_peer_id or peer_id
            if peer_id in self.known_peers:
                del self.known_peers[peer_id]
                self.known_peers[target_id] = info
            elif peer_id in self.discovered_peers:
                del self.discovered_peers[peer_id]
                self.discovered_peers[target_id] = info
            else:
                self.known_peers[target_id] = info

# ===========================================================================
# upload transfer system
# ===========================================================================
_pending_uploads = {}
_pending_uploads_lock = threading.Lock()
_upload_counter = 0

def _generate_upload_id():
    global _upload_counter
    _upload_counter += 1
    return f"upload-{int(time.time())}-{_upload_counter}"

def add_pending_upload(sender_id, sender_ip, filename, dest_path, file_data):
    with _pending_uploads_lock:
        upload_id = _generate_upload_id()
        _pending_uploads[upload_id] = {
            'id': upload_id,
            'sender_id': sender_id,
            'sender_ip': sender_ip,
            'filename': filename,
            'dest_path': dest_path,
            'file_data': file_data,
            'file_size': len(file_data),
            'timestamp': time.time(),
            'status': 'pending'
        }
        return upload_id

def get_pending_uploads():
    with _pending_uploads_lock:
        return [
            {k: v for k, v in u.items() if k != 'file_data'}
            for u in _pending_uploads.values()
            if u['status'] == 'pending'
        ]

def accept_upload(upload_id):
    with _pending_uploads_lock:
        upload = _pending_uploads.get(upload_id)
        if not upload or upload['status'] != 'pending':
            return None
        upload['status'] = 'accepted'
        return dict(upload)

def reject_upload(upload_id):
    with _pending_uploads_lock:
        upload = _pending_uploads.get(upload_id)
        if not upload or upload['status'] != 'pending':
            return False
        upload['status'] = 'rejected'
        upload['file_data'] = b''
        return True

def cleanup_old_uploads(max_age=300):
    with _pending_uploads_lock:
        now = time.time()
        expired = [uid for uid, u in _pending_uploads.items()
                   if now - u['timestamp'] > max_age and u['status'] != 'pending']
        for uid in expired:
            _pending_uploads.pop(uid, None)

# ===========================================================================
# folder sync system
# ===========================================================================
_active_syncs = {}
_active_syncs_lock = threading.Lock()
_sync_counter = 0

def _generate_sync_id():
    global _sync_counter
    _sync_counter += 1
    return f"sync-{int(time.time())}-{_sync_counter}"

def add_active_sync(peer_id, local_path, remote_path, peer_ip, peer_port):
    with _active_syncs_lock:
        sync_id = _generate_sync_id()
        _active_syncs[sync_id] = {
            'id': sync_id,
            'peer_id': peer_id,
            'peer_ip': peer_ip,
            'peer_port': peer_port,
            'local_path': local_path,
            'remote_path': remote_path,
            'active': True,
            'last_sync': time.time(),
            'files_synced': 0,
            'stop': False,
        }
        return sync_id

def get_active_syncs():
    with _active_syncs_lock:
        return [
            {k: v for k, v in s.items() if k != 'stop'}
            for s in _active_syncs.values()
            if not s.get('stop', False)
        ]

def stop_sync(sync_id):
    with _active_syncs_lock:
        s = _active_syncs.get(sync_id)
        if s:
            s['stop'] = True
            s['active'] = False
            return True
        return False

def run_sync_job(sync_id, state):
    """Background worker: periodically pull files from peer into local folder."""
    while True:
        with _active_syncs_lock:
            s = _active_syncs.get(sync_id)
            if not s or s.get('stop', False):
                return
            peer_ip = s['peer_ip']
            peer_port = s['peer_port']
            remote_path = s['remote_path']
            local_path = s['local_path']
            s['active'] = True
        try:
            # Fetch remote file list
            url = f"http://{peer_ip}:{peer_port}/shared_list"
            resp = _HTTP_SESSION.get(url, timeout=10)
            resp.raise_for_status()
            data = resp.json()
            items = data.get('items', [])
            home = Path.home()
            target_dir = home / local_path.rstrip('/')
            target_dir.mkdir(parents=True, exist_ok=True)

            # Downloads used to run one-at-a-time — a dead/slow peer could
            # serialize a 30s timeout per file. Pull up to 4 in parallel.
            to_fetch = []
            for item in items:
                if item.get('is_folder', False):
                    continue
                item_path = item.get('path', '')
                if remote_path and not item_path.startswith(remote_path):
                    continue
                to_fetch.append(item_path)

            def _stop_requested():
                with _active_syncs_lock:
                    s0 = _active_syncs.get(sync_id)
                    return not s0 or s0.get('stop', False)

            def _dl(item_path):
                if _stop_requested():
                    return 0
                try:
                    dl_url = f"http://{peer_ip}:{peer_port}/preview/{item_path}?download=1"
                    dl_resp = _HTTP_SESSION.get(dl_url, timeout=30)
                    if dl_resp.status_code == 200:
                        file_name = Path(item_path).name
                        dest_file = target_dir / file_name
                        # Only write if different size or missing
                        if not dest_file.exists() or dest_file.stat().st_size != len(dl_resp.content):
                            with open(dest_file, 'wb') as f:
                                f.write(dl_resp.content)
                            return 1
                except Exception:
                    pass
                return 0

            count = 0
            if to_fetch:
                with ThreadPoolExecutor(max_workers=min(4, len(to_fetch))) as pool:
                    for n in pool.map(_dl, to_fetch):
                        count += n
                        if _stop_requested():
                            break
            with _active_syncs_lock:
                s2 = _active_syncs.get(sync_id)
                if s2:
                    s2['files_synced'] = count
                    s2['last_sync'] = time.time()
                    s2['active'] = False
        except Exception as e:
            with _active_syncs_lock:
                s3 = _active_syncs.get(sync_id)
                if s3:
                    s3['active'] = False
            print(f"[SYNC] Error syncing {sync_id}: {e}")
        # Wait 30 seconds before next sync cycle
        for _ in range(30):
            time.sleep(1)
            with _active_syncs_lock:
                s4 = _active_syncs.get(sync_id)
                if not s4 or s4.get('stop', False):
                    return

# ===========================================================================
# remote permission popup prompt (asks host user to approve each action)
# ===========================================================================
_PERM_ACTION_LABELS = {
    'remote_exec': 'Remote Terminal Access',
    'clipboard_write': 'Write to Clipboard',
    'clipboard_read': 'Read Clipboard',
    'power_control': 'Power Control (shutdown/restart/sleep)',
    'screenshot': 'Capture Screenshot',
    'notify': 'Send Notification',
    'process_manager': 'View/Kill Processes',
    'screen_record': 'Record Screen',
    'remote_audio': 'Listen to Microphone',
    'system_audio': 'Listen to System Audio',
    'input_monitor': 'Monitor Keyboard/Mouse Input',
}

def prompt_remote_permission(action_key, requester_info='a remote peer'):
    """Show a blocking Windows MessageBox asking the host to approve an action.
    Returns True if approved, False if denied."""
    label = _PERM_ACTION_LABELS.get(action_key, action_key)
    try:
        ps_script = (
            'Add-Type -AssemblyName System.Windows.Forms;'
            f'$result = [System.Windows.Forms.MessageBox]::Show('
            f'"A remote peer ({requester_info}) is requesting permission to:\\n\\n'
            f'{label}\\n\\nAllow this action?", '
            f'"GNA Permission Request", "YesNo", "Warning");'
            '$result'
        )
        result = subprocess.run(
            ['powershell', '-WindowStyle', 'Hidden', '-Command', ps_script],
            capture_output=True, text=True, timeout=120
        )
        return result.stdout.strip().lower() == 'yes'
    except Exception:
        return False

