def get_sorted_live_peers(state):
    return get_live_peers(my_id=state.my_id, my_info=state.get_my_info(), known_peers=state.get_known_peers(), discovered_peers=state.get_discovered_peers(), current_time=time.time(), timeout_seconds=PEER_TIMEOUT_SECONDS)

def get_current_failover_chain(state):
    return get_failover_chain(get_sorted_live_peers(state), MAX_FAILOVER_CHAIN_SIZE)

def get_current_role(state):
    return get_my_role(state.my_id, get_sorted_live_peers(state))

def get_shared_items_list(state):
    items = []
    for path in state.shared_paths:
        full_item_path = SHARED_DIR / path.rstrip('/')
        is_folder = path.endswith('/')
        if is_folder: size_str = "Folder"
        elif full_item_path.exists(): size_str = f"{get_file_size_kb(full_item_path):,} KB"
        else: size_str = "N/A"
        name = os.path.basename(path.rstrip('/'))
        if is_folder: name += '/'
        items.append(SharedItem(path=path, name=name, size_str=size_str, is_folder=is_folder))
    return items

def get_preview_items(state, max_items=None):
    items = []
    sorted_paths = sorted(state.shared_paths.keys())
    if max_items is not None: sorted_paths = sorted_paths[:max_items]
    for path in sorted_paths:
        full_item_path = SHARED_DIR / path.rstrip('/')
        is_folder = path.endswith('/')
        if is_folder: size_str = "Folder"
        elif full_item_path.exists(): size_str = f"{get_file_size_kb(full_item_path):,} KB"
        else: size_str = "N/A"
        name = os.path.basename(path.rstrip('/'))
        if is_folder: name += '/'
        item = {'name': name, 'size': size_str, 'is_folder': is_folder, 'path': path.lstrip('/')}
        if is_folder: item['download_url'] = f"/preview/{item['path'].rstrip('/')}?download=1"
        elif full_item_path.exists(): item['download_url'] = f"/preview/{item['path']}?download=1"
        else: item['download_url'] = None
        items.append(item)
    return items

def list_explorer_directory(state, requested_path):
    full_path = SHARED_DIR / requested_path if requested_path else SHARED_DIR
    return list_directory_entries(full_path, SHARED_DIR, state.shared_paths)

def update_selection(state, current_path, selected_paths, tags_map=None):
    if tags_map is None: tags_map = {}
    if not isinstance(state.shared_paths, dict): state.shared_paths = {}
    current_norm = normalize_path(current_path) if current_path else ''
    current_prefix = current_norm + '/' if current_norm else ''
    full_path = SHARED_DIR / current_path if current_path else SHARED_DIR
    visible_paths = set(get_visible_paths_in_directory(full_path))
    to_remove = set()
    for p in list(state.shared_paths):
        if p in visible_paths and p not in selected_paths: to_remove.add(p)
        elif current_prefix and p.startswith(current_prefix) and p not in selected_paths: to_remove.add(p)
    for p in to_remove: del state.shared_paths[p]
    for rel_path in selected_paths:
        if not rel_path: continue
        clean_path = normalize_path(rel_path)
        if rel_path.endswith('/') and clean_path and not clean_path.endswith('/'): clean_path += '/'
        if clean_path:
            if rel_path in tags_map: tag_val = tags_map[rel_path]
            elif clean_path in tags_map: tag_val = tags_map[clean_path]
            elif clean_path in state.shared_paths: tag_val = state.shared_paths[clean_path]
            else: tag_val = ""
            state.shared_paths[clean_path] = tag_val
    save_shared_paths(state.shared_paths)

def _matches_query(name, tags, query_terms):
    name_lower = name.lower()
    tags_lower = tags.lower() if tags else ""
    tag_list = [t.strip() for t in tags_lower.split(',') if t.strip()] if tags_lower else []
    for term in query_terms:
        if term in name_lower: continue
        if any(term in t for t in tag_list): continue
        return False
    return True

def search_network(state, query):
    """Search shared files by name (and tags) across this node and every live
    peer. Returns (matching SearchResults, total items available across all
    shared sources)."""
    q_raw = query.strip()
    if not q_raw: return [], 0
    query_terms = [t.strip().lower() for t in re.split(r'[\s,]+', q_raw) if t.strip()]
    if not query_terms: return [], 0
    all_results = []
    sorted_live = get_sorted_live_peers(state)
    # Fetch every remote peer's shared list in parallel — serial fetches made
    # network search latency = peers x timeout instead of ~max(1 timeout).
    remote_jobs = {pid: (data.ip, data.port) for pid, data in sorted_live if pid != state.my_id.value}
    remote_lists = {}
    if remote_jobs:
        def _fetch(job):
            return job[0], fetch_peer_shared_list(job[1][0], job[1][1])
        for pid2, items in _WEB_POOL.map(_fetch, remote_jobs.items()):
            remote_lists[pid2] = items
    total_available = 0
    for pid, data in sorted_live:
        try:
            if pid == state.my_id.value:
                total_available += len(state.shared_paths)
                for path, tags in list(state.shared_paths.items()):
                    name = os.path.basename(path.rstrip('/'))
                    if _matches_query(name, tags, query_terms):
                        is_folder = path.endswith('/')
                        full_item_path = SHARED_DIR / path.rstrip('/')
                        if is_folder: size_str = "Folder"
                        elif full_item_path.exists(): size_str = f"{get_file_size_kb(full_item_path):,} KB"
                        else: size_str = "N/A"
                        tag_display = f" [{tags}]" if tags else ""
                        rel_path = path.lstrip('/').rstrip('/')
                        all_results.append(SearchResult(bank_id=pid, name=name + ('/' if is_folder else '') + tag_display, size=size_str, is_folder=is_folder, link=f"/preview/{path.lstrip('/')}", location=f"gna://{pid}/{rel_path}"))
            else:
                remote_items = remote_lists.get(pid)
                if remote_items:
                    total_available += len(remote_items)
                    for item in remote_items:
                        item_tags = item.get('tags', '')
                        if _matches_query(item['name'], item_tags, query_terms):
                            tag_display = f" [{item_tags}]" if item_tags else ""
                            item_path = item['path'].lstrip('/')
                            all_results.append(SearchResult(bank_id=pid, name=item['name'] + tag_display, size=item['size'], is_folder=item['is_folder'], link=f"/peer_download/{pid}/{item_path}", location=f"gna://{pid}/{item_path.rstrip('/')}"))
        except Exception as e:
            print(f"Search failed for peer {pid}: {e}")
    return all_results, total_available

def search_users(state, query):
    """Search the network for other users by id, call number, or address."""
    q = (query or '').strip().lower()
    if not q: return []
    terms = [t for t in re.split(r'[\s,]+', q) if t]
    if not terms: return []
    global_cn = getattr(state, '_global_call_numbers', {})
    now = time.time()
    results = []
    for pid, data in get_sorted_live_peers(state):
        cn = state.call_number if pid == str(state.my_id) else global_cn.get(pid, '')
        haystack = f"{pid} {cn} {data.ip}:{data.port} {data.ip}".lower()
        if not all(t in haystack for t in terms): continue
        results.append({
            'id': pid, 'ip': data.ip, 'port': data.port,
            'call_number': cn or 'N/A',
            'is_self': pid == str(state.my_id),
            'join_time': data.join_time, 'last_seen': data.last_seen,
            'last_seen_ago': max(0, int(now - data.last_seen)),
        })
    return results

def add_manual_peer(state, ip, port):
    peer_id = generate_peer_id_from_ip(ip)
    peer_info_data = fetch_peer_info(ip, port)
    if peer_info_data and 'id' in peer_info_data: peer_id = PeerId(peer_info_data['id'])
    info = PeerInfo(ip=ip, port=port, join_time=time.time(), last_seen=time.time())
    state.add_known_peer(peer_id.value, info)
    save_known_peers(state.known_peers)
    return peer_id

def update_peer_bookkeeping(state):
    now = time.time()
    state.known_peers[state.my_id.value] = PeerInfo(ip=state.public_ip if state.public_ip != "unknown" else state.local_ip, port=PORT, join_time=state.my_join_time, last_seen=now)
    # Persisted every call (~5s) before — the only field that actually
    # changes between writes is last_seen, which refreshes peers anyway.
    # Write on membership change or once a minute, whichever is first.
    global _peers_save_last, _peers_save_membership
    for _ in range(3):  # dict can resize mid-copy when other threads mutate
        try:
            peers_snapshot = dict(state.known_peers)
            break
        except RuntimeError:
            continue
    else:
        return
    membership = frozenset(peers_snapshot)
    if (membership != _peers_save_membership
            or now - _peers_save_last >= 60):
        _peers_save_membership = membership
        _peers_save_last = now
        save_known_peers(peers_snapshot)

# Peer keep-alive: entries only get last_seen refreshed when a peer is first
# discovered, so without periodic verification every peer would vanish from the
# live list ~40s later. Ping peers approaching staleness to keep the constant
# connection (and the "devices on the network" list) alive.
_PEER_REFRESH_AGE = 25.0       # re-verify once last_seen is older than this
_PEER_DEAD_RETRY = 900.0       # retry seemingly-dead peers for up to 15 min
_peer_exchange_last = 0.0      # last time we ran a peer-list exchange
_peers_save_last = 0.0         # last known_peers.json write
_peers_save_membership = None  # peer-id set at that write

def refresh_stale_peers(state):
    now = time.time()
    my = str(state.my_id)
    candidates = []
    for pid, info in list(state.get_known_peers().items()) + list(state.get_discovered_peers().items()):
        if pid == my: continue
        age = now - info.last_seen
        if age < _PEER_REFRESH_AGE: continue        # still fresh
        if age > _PEER_DEAD_RETRY: continue          # long dead — let it expire
        candidates.append((pid, info))
    if not candidates: return
    def _verify(pid_info):
        pid, info = pid_info
        data = fetch_peer_info(info.ip, info.port)
        if not data: return None
        reported_id = data.get('id') or pid
        return pid, reported_id, PeerInfo(ip=info.ip, port=info.port, join_time=info.join_time or time.time(), last_seen=time.time()), data
    # Shared pool — this ran a fresh 8-thread spawn+join every 5s.
    for res in _WEB_POOL.map(_verify, candidates):
        if not res: continue
        pid, reported_id, info, data = res
        state.mark_peer_alive(pid, info, new_peer_id=reported_id)

def peer_exchange(state):
    """Gossip: ask a few live peers for their peer lists and adopt any verified
    newcomers — an extra meeting place when discovery channels miss someone.
    List pulls and newcomer verification run in parallel: a dead advertiser
    used to serialize a 6s timeout per candidate."""
    my = str(state.my_id)
    live = [info for pid, info in get_sorted_live_peers(state) if pid != my][:3]
    if not live: return

    def _fetch_list(info):
        try:
            resp = _HTTP_SESSION.get(f"http://{info.ip}:{info.port}/api/peers", timeout=4)
            if resp.status_code == 200:
                return resp.json().get('peers', [])
        except Exception:
            pass
        return []

    peer_lists = _WEB_POOL.map(_fetch_list, live)

    known = state.get_known_peers()
    discovered = state.get_discovered_peers()
    candidates = {}
    for plist in peer_lists:
        for p in plist:
            try:
                pid2, ip2, port2 = p.get('id'), p.get('ip'), int(p.get('port') or PORT)
            except (ValueError, TypeError, AttributeError):
                continue
            if not pid2 or pid2 == my or not ip2: continue
            if pid2 in known or pid2 in discovered or pid2 in candidates: continue
            candidates[pid2] = (ip2, port2, p.get('join_time'))
    if not candidates: return

    def _verify(item):
        pid2, (ip2, port2, jt) = item
        # only adopt peers that actually answer us
        if fetch_peer_info(ip2, port2):
            return pid2, ip2, port2, jt
        return None

    for res in _WEB_POOL.map(_verify, candidates.items()):
        if not res: continue
        pid2, ip2, port2, jt = res
        state.add_known_peer(pid2, PeerInfo(ip=ip2, port=port2,
                             join_time=jt or time.time(), last_seen=time.time()))

