# ===========================================================================
# infrastructure/web_search — mass multi-engine search
# ===========================================================================
_WEB_UA = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
    'Accept-Language': 'en-US,en;q=0.9',
    'DNT': '1',
}
_WEB_TIMEOUT = 8.0
_SEARCH_TIMEOUT = 6.0          # per-request cap on engine fetches — fast failure frees the deadline
_MASS_SEARCH_DEADLINE = 9.0    # overall cap — slow engines get marked 'timeout'
_SEARX_TRY = 8                 # instances queried concurrently — first responses merge
_MASS_LIMIT_PER = 80           # per-engine merged cap across its parallel page fetches
_MASS_RESULT_CAP = 1000        # merged results returned — the UI pages them 100/page
# Shared session: connection pooling skips repeat TCP+TLS handshakes for the
# engines and peer calls, which is the dominant per-request cost on LAN/WAN.
_HTTP_SESSION = requests.Session()
from requests.adapters import HTTPAdapter as _HTTPAdapter
_HTTP_SESSION.mount('https://', _HTTPAdapter(pool_connections=64, pool_maxsize=128))
_HTTP_SESSION.mount('http://', _HTTPAdapter(pool_connections=64, pool_maxsize=128))

# Shared worker pool for fan-out HTTP work (search engines, suggestions,
# media sources). A per-query pool cost ~10ms of thread spawn on every
# search and discarded warm keep-alive connections with it. Sized for the
# nested fan-out: 13 outer engine tasks plus ~50 inner page/path fetches
# (multi-page engines × parallel SearX instances), with headroom for two
# searches in flight at once.
_WEB_POOL = ThreadPoolExecutor(max_workers=96, thread_name_prefix='web-io')

def _bs4_soup(markup):
    try:
        from bs4 import BeautifulSoup
        return BeautifulSoup(markup, 'html.parser')
    except ImportError:
        return None

def _clean_text(s):
    return re.sub(r'\s+', ' ', s or '').strip()

def _strip_tags(s):
    return _clean_text(re.sub(r'<[^>]+>', '', s or ''))

def _norm_url(u):
    u = (u or '').strip()
    u = re.sub(r'^https?://(www\.)?', '', u, flags=re.IGNORECASE).rstrip('/').lower()
    return u

def _decode_bing_url(href):
    """Bing wraps result urls in bing.com/ck/a redirects — the real target is
    base64url-encoded in the u= param (with an 'a1' prefix)."""
    if 'bing.com/ck/a' not in href:
        return href
    try:
        u = urllib.parse.parse_qs(urllib.parse.urlparse(href).query).get('u', [''])[0]
        if u.startswith('a1') and len(u) > 4:
            pad = '=' * (-len(u[2:]) % 4)
            return base64.urlsafe_b64decode(u[2:] + pad).decode('utf-8', 'replace')
    except Exception:
        pass
    return href

def _decode_yahoo_url(href):
    """Yahoo wraps result urls in r.search.yahoo.com redirects — extract RU=."""
    if 'r.search.yahoo.com' not in href: return href
    m = re.search(r'/RU=([^/]+)/', href)
    if m:
        try: return urllib.parse.unquote(m.group(1))
        except Exception: pass
    return href

def _parse_duckduckgo(markup, limit):
    """Shared parser for the lite/ and html/ DuckDuckGo endpoints."""
    items = []
    soup = _bs4_soup(markup)
    if soup:
        for a in soup.find_all('a', class_='result-link') + soup.select('a.result__a'):
            title = a.get_text(strip=True)
            url = a.get('href', '')
            snippet = ''
            tr = a.find_parent('tr')
            if tr:
                sib = tr.find_next_sibling('tr')
                if sib:
                    td = sib.find('td', class_='result-snippet')
                    if td: snippet = td.get_text(strip=True)
            if not snippet:
                res = a.find_parent(class_='result')
                if res:
                    sd = res.select_one('.result__snippet')
                    if sd: snippet = sd.get_text(strip=True)
            if url and title:
                items.append({'title': title, 'url': url, 'snippet': snippet})
            if len(items) >= limit: break
    else:
        links = re.findall(r'<a[^>]+class="result-link"[^>]+href="([^"]+)"[^>]*>([^<]+)</a>', markup, re.IGNORECASE)
        snippets = re.findall(r'<td[^>]+class="result-snippet"[^>]*>(.*?)</td>', markup, re.IGNORECASE | re.DOTALL)
        for i, (url, title) in enumerate(links):
            snippet = _strip_tags(snippets[i]) if i < len(snippets) else ''
            items.append({'title': _clean_text(title), 'url': url.strip(), 'snippet': snippet})
            if len(items) >= limit: break
    return items

def _run_fanout(fns, limit, deadline=None):
    """Run callables concurrently on the shared pool; merge + dedupe their
    item lists by normalized URL. Latency = the paths that land inside the
    deadline — stragglers are dropped, not waited on."""
    items, seen = [], set()
    futs = [_WEB_POOL.submit(f) for f in fns]
    try:
        for fut in as_completed(futs, timeout=deadline or (_SEARCH_TIMEOUT + 1.5)):
            try:
                for it in fut.result() or []:
                    key = _norm_url(it.get('url'))
                    if not key or key in seen:
                        continue
                    seen.add(key)
                    items.append(it)
                    if len(items) >= limit:
                        return items
            except Exception:
                continue
    except TimeoutError:
        pass
    return items


def _engine_duckduckgo(query, limit):
    # Three independent paths — lite/html are frequently anomaly-blocked, so
    # fall through to the vqd-token JSON feed that powers the JS frontend.
    # All paths AND result pages run concurrently on the shared pool: latency
    # is the fastest page instead of the sum of sequential fallbacks.
    def _lite(off):
        resp = _HTTP_SESSION.post('https://lite.duckduckgo.com/lite/', data={'q': query, 's': off}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        return _parse_duckduckgo(resp.text, limit)

    def _html(off):
        resp = _HTTP_SESSION.get('https://html.duckduckgo.com/html/', params={'q': query, 's': off}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        return _parse_duckduckgo(resp.text, limit)

    def _vqd_feed():
        vqd = _ddg_vqd(query)
        if not vqd:
            return []
        resp = _HTTP_SESSION.get('https://links.duckduckgo.com/d.js',
            params={'q': query, 'vqd': vqd, 'o': 'json', 'p': '1', 'l': 'us-en'},
            headers={**_WEB_UA, 'Referer': 'https://duckduckgo.com/'}, timeout=_SEARCH_TIMEOUT)
        if not resp.ok:
            return []
        items = []
        for r in (resp.json().get('results') or []):
            url = r.get('u') or r.get('url') or ''
            if url.startswith('/l/?'):
                qs = urllib.parse.parse_qs(urllib.parse.urlparse(url).query)
                url = (qs.get('uddg') or [url])[0]
            if not url.startswith('http'): continue
            items.append({'title': _strip_tags(r.get('t') or r.get('title') or ''),
                          'url': url,
                          'snippet': _strip_tags(r.get('a') or r.get('snippet') or '')})
            if len(items) >= limit: break
        return items

    offsets = (0, 30, 60)
    return _run_fanout(
        [lambda o=off: _lite(o) for off in offsets] +
        [lambda o=off: _html(o) for off in offsets] +
        [_vqd_feed], limit)

def _engine_bing(query, limit):
    def _page(first):
        items = []
        resp = _HTTP_SESSION.get('https://www.bing.com/search', params={'q': query, 'count': 30, 'first': first, 'setlang': 'en'}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        soup = _bs4_soup(resp.text)
        if soup:
            for li in soup.select('li.b_algo'):
                a = li.select_one('h2 a')
                if not a or not a.get('href'): continue
                cap = li.select_one('.b_caption p') or li.select_one('p')
                items.append({'title': a.get_text(strip=True), 'url': _decode_bing_url(a['href']), 'snippet': cap.get_text(strip=True) if cap else ''})
                if len(items) >= limit: break
        else:
            for m in re.finditer(r'<h2[^>]*><a[^>]+href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
                items.append({'title': _strip_tags(m.group(2)), 'url': _decode_bing_url(m.group(1)), 'snippet': ''})
                if len(items) >= limit: break
        return items
    # 'first' paginates in steps of 10 — four pages fetched concurrently.
    return _run_fanout([lambda f=first: _page(f) for first in (1, 11, 21, 31)], limit)

def _engine_mojeek(query, limit):
    def _page(off):
        items = []
        resp = _HTTP_SESSION.get('https://www.mojeek.com/search', params={'q': query, 's': off}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        soup = _bs4_soup(resp.text)
        if soup:
            for li in soup.select('ul.results-standard li, ul.results li'):
                a = li.find('a', href=True)
                if not a: continue
                href = a['href']
                if not href.startswith('http'): continue
                title = a.get_text(strip=True) or href
                snip = li.find('p', class_='s') or li.find('p')
                items.append({'title': title, 'url': href, 'snippet': snip.get_text(strip=True) if snip else ''})
                if len(items) >= limit: break
        else:
            for m in re.finditer(r'<a[^>]+class="ob"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
                items.append({'title': _strip_tags(m.group(2)), 'url': m.group(1), 'snippet': ''})
                if len(items) >= limit: break
        return items
    # 's' paginates in steps of 10 — four pages fetched concurrently.
    return _run_fanout([lambda o=o: _page(o) for o in (0, 10, 20, 30)], limit)

def _engine_yahoo(query, limit):
    def _page(off):
        items = []
        resp = _HTTP_SESSION.get('https://search.yahoo.com/search', params={'p': query, 'n': 30, 'b': off}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        soup = _bs4_soup(resp.text)
        if soup:
            blocks = soup.select('div.dd.algo, div.algo-sr, div.Sr')
            for b in blocks:
                a = b.select_one('h3 a') or b.find('a', href=True)
                if not a: continue
                url = _decode_yahoo_url(a['href'])
                if not url.startswith('http') or 'yahoo.com' in _norm_url(url): continue
                snip = b.select_one('.compText') or b.find('p')
                items.append({'title': a.get_text(strip=True), 'url': url, 'snippet': snip.get_text(strip=True) if snip else ''})
                if len(items) >= limit: break
        else:
            for m in re.finditer(r'<h3[^>]*>\s*<a[^>]+href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
                url = _decode_yahoo_url(m.group(1))
                items.append({'title': _strip_tags(m.group(2)), 'url': url, 'snippet': ''})
                if len(items) >= limit: break
        return items
    # 'b' paginates in steps of 10 — four pages fetched concurrently.
    return _run_fanout([lambda o=off: _page(o) for off in (1, 11, 21, 31)], limit)

def _engine_startpage(query, limit):
    items = []
    resp = _HTTP_SESSION.post('https://www.startpage.com/sp/search', data={'query': query, 'cat': 'web', 'language': 'english'}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
    resp.raise_for_status()
    soup = _bs4_soup(resp.text)
    if soup:
        for r in soup.select('.w-gl__result, .result'):
            a = r.select_one('a.result-link, .w-gl__result-title, h3 a, h2 a')
            if not a or not a.get('href'): continue
            snip = r.select_one('.w-gl__description, .description, p')
            items.append({'title': a.get_text(strip=True), 'url': a['href'], 'snippet': snip.get_text(strip=True) if snip else ''})
            if len(items) >= limit: break
    else:
        for m in re.finditer(r'class="result-link"[^>]*href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
            items.append({'title': _strip_tags(m.group(2)), 'url': m.group(1), 'snippet': ''})
            if len(items) >= limit: break
    return items

def _engine_wikipedia(query, limit):
    resp = _HTTP_SESSION.get('https://en.wikipedia.org/w/api.php', params={
        'action': 'opensearch', 'search': query, 'limit': min(limit, 20),
        'namespace': 0, 'format': 'json',
    }, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
    resp.raise_for_status()
    data = resp.json()
    items = []
    if isinstance(data, list) and len(data) >= 4:
        for title, desc, url in zip(data[1], data[2], data[3]):
            items.append({'title': title, 'url': url, 'snippet': desc})
    return items

# SearXNG public instances rotate a lot — tried in order until one answers.
_SEARX_INSTANCES = ['https://search.rhscz.eu', 'https://priv.au', 'https://paulgo.io',
                    'https://search.rowie.at', 'https://baresearch.org', 'https://searx.be',
                    'https://search.inetol.net', 'https://opnxng.com']

def _engine_searx(query, limit):
    # Every instance x page is queried concurrently — the old serial crawl
    # could burn 4 instances x 2 attempts x the request timeout in one
    # worker. First instances to answer contribute; results merge + dedupe.
    def _one(base, page):
        try:
            resp = _HTTP_SESSION.get(base + '/search', params={'q': query, 'format': 'json', 'pageno': page}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
            if resp.status_code == 200 and 'json' in (resp.headers.get('Content-Type') or ''):
                items = []
                for r in resp.json().get('results', []):
                    items.append({'title': r.get('title', ''), 'url': r.get('url', ''), 'snippet': r.get('content', '')})
                    if len(items) >= limit: break
                if items: return items
        except Exception:
            pass
        # JSON disabled on many instances — try HTML
        try:
            resp = _HTTP_SESSION.get(base + '/search', params={'q': query, 'pageno': page}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
            if resp.status_code != 200: return []
            soup = _bs4_soup(resp.text)
            if not soup: return []
            items = []
            for art in soup.select('article.result'):
                a = art.select_one('h3 a')
                if not a or not a.get('href'): continue
                snip = art.select_one('p.content')
                items.append({'title': a.get_text(strip=True), 'url': a['href'], 'snippet': snip.get_text(strip=True) if snip else ''})
                if len(items) >= limit: break
            return items
        except Exception:
            return []

    fns = [lambda b=base, p=page: _one(b, p)
           for base in _SEARX_INSTANCES[:_SEARX_TRY] for page in (1, 2)]
    # Each instance may make two requests (JSON then HTML) under one
    # worker — allow both plus grace before cutting loose stragglers.
    return _run_fanout(fns, limit, deadline=_SEARCH_TIMEOUT * 2 + 1.0)

def _engine_brave(query, limit):
    key = (load_global_config().get('brave_api_key') or '').strip()
    if not key: raise RuntimeError('no API key')
    def _page(off):
        resp = _HTTP_SESSION.get('https://api.search.brave.com/res/v1/web/search',
                            params={'q': query, 'count': 20, 'offset': off},
                            headers={**_WEB_UA, 'Accept': 'application/json', 'X-Subscription-Token': key},
                            timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        items = []
        for r in (resp.json().get('web') or {}).get('results', []):
            items.append({'title': r.get('title', ''), 'url': r.get('url', ''), 'snippet': r.get('description', '')})
            if len(items) >= limit: break
        return items
    # 'offset' paginates the API — three pages fetched concurrently.
    return _run_fanout([lambda o=off: _page(o) for off in (0, 20, 40)], limit)

def _engine_qwant(query, limit):
    """Qwant — official JSON API (no key required for basic web search)."""
    def _page(off):
        resp = _HTTP_SESSION.get('https://api.qwant.com/v3/search/web',
                            params={'q': query, 'count': 25, 'locale': 'en_US',
                                    'offset': off, 'device': 'desktop', 'safesearch': 0},
                            headers={**_WEB_UA, 'Accept': 'application/json'}, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        data = resp.json()
        result = (data.get('data') or {}).get('result') or {}
        groups = result.get('items') or (result.get('mainline') or {}).get('items') or []
        items = []
        for block in groups:
            rows = block.get('items') if isinstance(block, dict) and isinstance(block.get('items'), list) else [block]
            for r in rows:
                if not isinstance(r, dict): continue
                url = r.get('url', '')
                if not url.startswith('http'): continue
                items.append({'title': r.get('title', ''), 'url': url,
                              'snippet': r.get('desc', '') or r.get('description', '')})
                if len(items) >= limit: return items
        return items
    # offset paginates the API — four pages fetched concurrently.
    return _run_fanout([lambda o=off: _page(o) for off in (0, 25, 50, 75)], limit)

def _engine_ecosia(query, limit):
    """Ecosia — Bing-backed, scrapeable result page."""
    resp = _HTTP_SESSION.get('https://www.ecosia.org/search', params={'q': query},
                        headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
    resp.raise_for_status()
    items = []
    soup = _bs4_soup(resp.text)
    if soup:
        for res in soup.select('.result, [data-test-id="result"], .web-result'):
            a = res.select_one('a.result__link, a[data-test-id="result-link"], .result-title a, h2 a, h3 a, a.result__title')
            if not a or not a.get('href'): continue
            url = a['href']
            if url.startswith('/'): url = urllib.parse.urljoin('https://www.ecosia.org', url)
            if not url.startswith('http') or 'ecosia.org' in _norm_url(url): continue
            snip = res.select_one('.result__description, .result-snippet, [data-test-id="result-snippet"], p')
            items.append({'title': a.get_text(strip=True), 'url': url,
                          'snippet': snip.get_text(strip=True) if snip else ''})
            if len(items) >= limit: break
    else:
        for m in re.finditer(r'<a[^>]+class="[^"]*result[^"]*"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
            url = m.group(1)
            if not url.startswith('http'): continue
            items.append({'title': _strip_tags(m.group(2)), 'url': url, 'snippet': ''})
            if len(items) >= limit: break
    return items

def _engine_aol(query, limit):
    """AOL Search — Yahoo/Bing syndicated results, scrapeable."""
    def _page(off):
        resp = _HTTP_SESSION.get('https://search.aol.com/aol/search', params={'q': query, 'n': 30, 'b': off},
                            headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        resp.raise_for_status()
        items = []
        soup = _bs4_soup(resp.text)
        if soup:
            for b in soup.select('div.dd.algo, div.algo-sr, div.Sr, ol.searchCenterMiddle li, .algo'):
                a = b.select_one('h3 a') or b.find('a', href=True)
                if not a: continue
                url = _decode_yahoo_url(a['href'])
                if not url.startswith('http') or 'aol.com' in _norm_url(url): continue
                snip = b.select_one('.compText, .lh-16') or b.find('p')
                items.append({'title': a.get_text(strip=True), 'url': url,
                              'snippet': snip.get_text(strip=True) if snip else ''})
                if len(items) >= limit: break
        else:
            for m in re.finditer(r'<h3[^>]*>\s*<a[^>]+href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
                url = _decode_yahoo_url(m.group(1))
                if not url.startswith('http'): continue
                items.append({'title': _strip_tags(m.group(2)), 'url': url, 'snippet': ''})
                if len(items) >= limit: break
        return items
    # 'b' paginates in steps of 10 — three pages fetched concurrently.
    return _run_fanout([lambda o=off: _page(o) for off in (1, 11, 21)], limit)

def _engine_etools(query, limit):
    """eTools.ch — Swiss metasearch with fully server-rendered results."""
    resp = _HTTP_SESSION.get('https://www.etools.ch/searchSubmit.do',
                        params={'query': query, 'country': 'web', 'language': 'all'},
                        headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
    resp.raise_for_status()
    items = []
    soup = _bs4_soup(resp.text)
    if soup:
        for a in soup.select('td.record a.title'):
            url = a.get('href', '')
            if not url.startswith('http'): continue
            td = a.find_parent('td', class_='record')
            snip = td.select_one('div.text') if td else None
            items.append({'title': _clean_text(a.get_text(' ', strip=True)), 'url': url,
                          'snippet': _clean_text(snip.get_text(' ', strip=True)) if snip else ''})
            if len(items) >= limit: break
    else:
        for m in re.finditer(r'<td[^>]+class="record"[^>]*>\s*<a[^>]+class="title"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', resp.text, re.IGNORECASE | re.DOTALL):
            items.append({'title': _strip_tags(m.group(2)), 'url': m.group(1), 'snippet': ''})
            if len(items) >= limit: break
    return items

def _engine_mwmbl(query, limit):
    """Mwmbl — open community web index with a public JSON API."""
    resp = _HTTP_SESSION.get('https://api.mwmbl.org/api/v1/search/',
                        params={'s': query}, headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
    resp.raise_for_status()
    data = resp.json()
    items = []
    for r in (data if isinstance(data, list) else []):
        url = r.get('url', '')
        if not url.startswith('http'): continue
        title = ''.join(seg.get('value', '') for seg in (r.get('title') or []) if isinstance(seg, dict))
        snip = ''.join(seg.get('value', '') for seg in (r.get('extract') or []) if isinstance(seg, dict))
        items.append({'title': title or url, 'url': url, 'snippet': snip})
        if len(items) >= limit: break
    return items

WEB_SEARCH_ENGINES = {
    'duckduckgo': _engine_duckduckgo,
    'bing': _engine_bing,
    'qwant': _engine_qwant,
    'ecosia': _engine_ecosia,
    'mojeek': _engine_mojeek,
    'yahoo': _engine_yahoo,
    'aol': _engine_aol,
    'startpage': _engine_startpage,
    'wikipedia': _engine_wikipedia,
    'searx': _engine_searx,
    'brave': _engine_brave,
    'etools': _engine_etools,
    'mwmbl': _engine_mwmbl,
}

def available_engines():
    names = [n for n in WEB_SEARCH_ENGINES if n != 'brave']
    if (load_global_config().get('brave_api_key') or '').strip():
        names.append('brave')
    return names

# Short-lived result cache — a repeat of the same query+engine set inside
# the TTL returns instantly instead of re-hitting every engine.
_SEARCH_CACHE = {}
_SEARCH_CACHE_TTL = 300.0
_search_cache_lock = RLock()

def mass_web_search(query, engines=None, limit_per=_MASS_LIMIT_PER):
    """Run the selected engines in parallel; merge + dedupe results."""
    names = [n for n in (engines or available_engines()) if n in WEB_SEARCH_ENGINES]
    ck = (query.strip().lower(), tuple(sorted(names)), limit_per)
    with _search_cache_lock:
        ent = _SEARCH_CACHE.get(ck)
        if ent and time.time() - ent[0] < _SEARCH_CACHE_TTL:
            cached_out, cached_status = ent[1]
            return [dict(r, engines=list(r['engines'])) for r in cached_out], dict(cached_status)
    merged = {}
    status = {}
    futs = {_WEB_POOL.submit(WEB_SEARCH_ENGINES[n], query, limit_per): n for n in names}
    try:
        for fut in as_completed(futs, timeout=_MASS_SEARCH_DEADLINE):
            name = futs[fut]
            try:
                items = fut.result() or []
                status[name] = {'count': len(items)}
                for it in items:
                    key = _norm_url(it.get('url'))
                    if not key: continue
                    if key in merged:
                        merged[key]['engines'].add(name)
                        if not merged[key]['snippet'] and it.get('snippet'):
                            merged[key]['snippet'] = it['snippet']
                    else:
                        merged[key] = {'title': it.get('title') or it['url'], 'url': it['url'], 'snippet': it.get('snippet', ''), 'engines': {name}}
            except Exception as e:
                status[name] = {'error': str(e)[:120]}
    except TimeoutError:
        pass
    for fut, name in futs.items():
        if name not in status:
            status[name] = {'error': 'timeout'}
            fut.cancel()
    ranked = sorted(merged.values(), key=lambda r: (-len(r['engines']), (r['title'] or '').lower()))
    out = []
    for r in ranked[:_MASS_RESULT_CAP]:
        out.append({'title': r['title'], 'url': r['url'], 'snippet': r['snippet'], 'engines': sorted(r['engines'])})
    with _search_cache_lock:
        _SEARCH_CACHE[ck] = (time.time(), (list(out), dict(status)))
        while len(_SEARCH_CACHE) > 100:
            oldest = min(_SEARCH_CACHE.items(), key=lambda kv: kv[1][0])[0]
            _SEARCH_CACHE.pop(oldest, None)
    return out, status

# ===========================================================================
# presentation/routes
# ===========================================================================
_BROWSE_CACHE = {}          # key -> (ts, body, ctype)
_BROWSE_CACHE_TTL = 90.0
_BROWSE_CACHE_MAX = 14
_browse_cache_lock = RLock()
_bios_info_cache = None     # static hardware text — computed once, forever


def _browse_cache_get(key):
    with _browse_cache_lock:
        ent = _BROWSE_CACHE.get(key)
        if not ent:
            return None
        ts, body, ctype = ent
        if time.time() - ts > _BROWSE_CACHE_TTL:
            _BROWSE_CACHE.pop(key, None)
            return None
        return body, ctype


def _browse_cache_put(key, body, ctype):
    with _browse_cache_lock:
        _BROWSE_CACHE[key] = (time.time(), body, ctype)
        while len(_BROWSE_CACHE) > _BROWSE_CACHE_MAX:
            oldest = min(_BROWSE_CACHE.items(), key=lambda kv: kv[1][0])[0]
            _BROWSE_CACHE.pop(oldest, None)


_SUGGEST_CACHE = {}         # q -> (ts, [suggestions])
_SUGGEST_TTL = 120.0
_suggest_lock = RLock()


def _search_suggestions(query, limit=8):
    """Omnibox autocomplete: DuckDuckGo ac endpoint + Wikipedia opensearch,
    merged, deduped, cached briefly. Never raises — returns []."""
    q = query.strip()[:200]
    if not q:
        return []
    with _suggest_lock:
        ent = _SUGGEST_CACHE.get(q)
        if ent and time.time() - ent[0] < _SUGGEST_TTL:
            return list(ent[1])
    out, seen = [], set()

    def _add(items):
        for s in items:
            s = _clean_text(str(s))[:140]
            if s and s.lower() not in seen and s.lower() != q.lower():
                seen.add(s.lower())
                out.append(s)
                if len(out) >= limit:
                    return

    # Both providers fetched concurrently — latency is max(), not the sum
    # of two up-to-4.5s calls.
    def _ddg():
        r = _HTTP_SESSION.get('https://duckduckgo.com/ac/', params={'q': q, 'type': 'list'},
                              headers=_WEB_UA, timeout=4.5)
        data = r.json() if r.ok else []
        return data[1] if isinstance(data, list) and len(data) > 1 else []

    def _wiki():
        r = _HTTP_SESSION.get('https://en.wikipedia.org/w/api.php', params={
            'action': 'opensearch', 'search': q, 'limit': 4, 'namespace': 0, 'format': 'json'},
            headers=_WEB_UA, timeout=4.5)
        data = r.json() if r.ok else []
        return data[1] if isinstance(data, list) and len(data) > 1 else []

    try:
        futs = [_WEB_POOL.submit(_ddg), _WEB_POOL.submit(_wiki)]
        for fut in futs:
            try:
                _add(fut.result())
            except Exception:
                pass
    except Exception:
        pass
    with _suggest_lock:
        _SUGGEST_CACHE[q] = (time.time(), list(out))
        if len(_SUGGEST_CACHE) > 300:
            for k in list(_SUGGEST_CACHE)[:60]:
                _SUGGEST_CACHE.pop(k, None)
    return out


def _site_info(url):
    """Connection/security details for the page-info panel: TLS certificate,
    resolved addresses, and security-relevant response headers."""
    parts = urllib.parse.urlsplit(url)
    host = parts.hostname or ''
    port = parts.port or (443 if parts.scheme == 'https' else 80)
    info = {'url': url, 'host': host, 'scheme': parts.scheme, 'port': port}
    try:
        info['addresses'] = sorted({ai[4][0] for ai in socket.getaddrinfo(host, port, proto=socket.IPPROTO_TCP)})[:8]
    except Exception:
        info['addresses'] = []
    if parts.scheme == 'https':
        try:
            ctx = ssl.create_default_context()
            with socket.create_connection((host, port), timeout=6) as sock:
                with ctx.wrap_socket(sock, server_hostname=host) as tls:
                    cert = tls.getpeercert()
                    info['tls_version'] = tls.version()
                    info['cipher'] = tls.cipher()[0] if tls.cipher() else ''
                    def _name(dn):
                        return ', '.join('='.join(x) for t in dn for x in t)
                    info['cert_subject'] = _name(cert.get('subject', ()))
                    info['cert_issuer'] = _name(cert.get('issuer', ()))
                    info['cert_not_before'] = cert.get('notBefore', '')
                    info['cert_not_after'] = cert.get('notAfter', '')
                    info['cert_sans'] = len(cert.get('subjectAltName', ()))
        except Exception as e:
            info['tls_error'] = str(e)[:160]
    try:
        resp = _HTTP_SESSION.head(url, headers=_WEB_UA, timeout=8, allow_redirects=True)
        info['status'] = resp.status_code
        info['final_url'] = resp.url
        hdrs = resp.headers
        info['server'] = hdrs.get('Server', '')
        info['content_type'] = hdrs.get('Content-Type', '')
        info['hsts'] = 'Strict-Transport-Security' in hdrs
        info['csp'] = 'Content-Security-Policy' in hdrs
        info['xfo'] = hdrs.get('X-Frame-Options', '')
        info['cookies_set'] = 'Set-Cookie' in hdrs
    except Exception as e:
        info['head_error'] = str(e)[:160]
    return info


def _ddg_vqd(query):
    """Fetch the DuckDuckGo vqd token needed by the i/v/news JSON endpoints."""
    try:
        r = _HTTP_SESSION.get('https://duckduckgo.com/', params={'q': query},
                              headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        m = re.search(r"vqd=['\"]([^'\"]+)['\"]", r.text)
        if not m:
            m = re.search(r'vqd=([\d-]+)&', r.text)
        return m.group(1) if m else None
    except Exception:
        return None


def _engine_ddg_media(query, limit, kind):
    """DuckDuckGo images (i.js), videos (v.js) or news (news.js)."""
    vqd = _ddg_vqd(query)
    if not vqd:
        return []
    page = {'images': 'i.js', 'videos': 'v.js', 'news': 'news.js'}[kind]
    r = _HTTP_SESSION.get('https://duckduckgo.com/' + page,
                          params={'q': query, 'vqd': vqd, 'o': 'json', 'p': '1'},
                          headers={**_WEB_UA, 'Referer': 'https://duckduckgo.com/'},
                          timeout=_SEARCH_TIMEOUT)
    r.raise_for_status()
    items = []
    for it in (r.json().get('results') or []):
        if kind == 'images':
            items.append({'title': it.get('title', ''), 'image': it.get('image', ''),
                          'thumb': it.get('thumbnail', ''), 'url': it.get('url', ''),
                          'source': it.get('source', ''), 'w': it.get('width', 0), 'h': it.get('height', 0)})
        elif kind == 'videos':
            items.append({'title': it.get('title', ''), 'url': it.get('content', ''),
                          'thumb': (it.get('images') or {}).get('medium', '') or (it.get('images') or {}).get('small', ''),
                          'source': it.get('provider', ''), 'duration': it.get('duration', ''),
                          'snippet': it.get('description', '')})
        else:
            items.append({'title': it.get('title', ''), 'url': it.get('url', ''),
                          'snippet': it.get('excerpt', ''), 'source': it.get('source', ''),
                          'date': it.get('date', ''), 'thumb': it.get('image', '')})
        if len(items) >= limit:
            break
    return items


def _engine_commons_images(query, limit):
    """Wikimedia Commons image search — free JSON API, no key."""
    r = _HTTP_SESSION.get('https://commons.wikimedia.org/w/api.php', params={
        'action': 'query', 'generator': 'search', 'gsrsearch': 'filetype:bitmap ' + query,
        'gsrnamespace': 6, 'gsrlimit': min(limit, 40), 'prop': 'imageinfo',
        'iiprop': 'url|size|mime', 'iiurlwidth': 320, 'format': 'json'},
        headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
