def _engine_bing_images(query, limit):
    """Bing image cards via the async carousel endpoint — pages deep via
    'first'. Each card carries an iusc m-attr JSON with the full image
    (murl), thumbnail (turl) and source page (purl)."""
    def _page(first):
        r = _HTTP_SESSION.get('https://www.bing.com/images/async',
                              params={'q': query, 'first': first, 'count': 35},
                              headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        r.raise_for_status()
        items = []
        for m in re.finditer(r'class="iusc"[^>]*?\sm="([^"]+)"', r.text):
            try:
                j = json.loads(html_lib.unescape(m.group(1)))
            except Exception:
                continue
            if not j.get('murl'):
                continue
            page = j.get('purl') or j['murl']
            items.append({'title': j.get('t') or j.get('desc') or '',
                          'image': j['murl'], 'thumb': j.get('turl') or j['murl'],
                          'url': page,
                          'source': (urllib.parse.urlsplit(page).hostname or '').replace('www.', ''),
                          'w': 0, 'h': 0})
            if len(items) >= limit:
                break
        return items
    return _run_fanout([lambda f=f: _page(f) for f in (1, 36, 71, 106)], limit)


