def _engine_bing_videos(query, limit):
    """Bing video search — cards carry vrhm JSON where 'murl' is the real
    watch URL (YouTube/Vimeo/etc.), so results route through the in-app
    player. Thumb/duration pair by document position within the card."""
    def _page(first):
        r = _HTTP_SESSION.get('https://www.bing.com/videos/search',
                              params={'q': query, 'first': first, 'count': 35},
                              headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
        r.raise_for_status()
        text = r.text
        thumbs = [(m.start(), m.group(1)) for m in
                  re.finditer(r'src="(https://tse[^"]+)"', text)]
        items, seen = [], set()
        for m in re.finditer(r'vrhm="(\{[^"]+\})"', text):
            try:
                j = json.loads(html_lib.unescape(m.group(1)))
            except Exception:
                continue
            url = j.get('murl') or ''
            if not url.startswith('http') or url in seen:
                continue
            seen.add(url)
            thumb = ''
            for p, u in thumbs:
                if p >= m.start():
                    break
                thumb = u
            items.append({'title': j.get('vt') or '', 'url': url, 'thumb': thumb,
                          'source': (urllib.parse.urlsplit(url).hostname or '').replace('www.', ''),
                          'duration': j.get('du') or '', 'snippet': ''})
            if len(items) >= limit:
                break
        return items
    return _run_fanout([lambda f=f: _page(f) for f in (1, 36)], limit)


def _engine_bing_news(query, limit):
    """Bing News as RSS — no key, parse items from the feed."""
    r = _HTTP_SESSION.get('https://www.bing.com/news/search',
                          params={'q': query, 'format': 'rss', 'count': min(limit, 50)},
                          headers=_WEB_UA, timeout=_SEARCH_TIMEOUT)
    r.raise_for_status()
    items = []
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(r.text)
        for el in root.iter('item'):
            def _txt(name):
                e = el.find(name)
                return (e.text or '').strip() if e is not None else ''
            link = _txt('link')
            if 'apiclick' in link:  # unwrap Bing's click redirect — real URL in 'url'
                link = (urllib.parse.parse_qs(urllib.parse.urlsplit(link).query)
                        .get('url', [link])[0])
            items.append({'title': _txt('title'), 'url': link,
                          'snippet': _strip_tags(_txt('description')),
                          'source': '', 'date': _txt('pubDate'), 'thumb': ''})
            if len(items) >= limit:
                break
    except Exception:
        for m in re.finditer(r'<item>.*?<title>(.*?)</title>.*?<link>(.*?)</link>', r.text, re.DOTALL):
            items.append({'title': _strip_tags(m.group(1)), 'url': m.group(2),
                          'snippet': '', 'source': '', 'date': '', 'thumb': ''})
            if len(items) >= limit:
                break
    return items


# Per-medium source lists — these are the engines each tab actually queries,
# and what the tab's engine chips toggle.
_MEDIA_SOURCES = {
    'images': [('duckduckgo', lambda q, n: _engine_ddg_media(q, n, 'images')),
               ('bing', _engine_bing_images),
               ('openverse', _engine_openverse_images),
               ('commons', _engine_commons_images)],
    'videos': [('duckduckgo', lambda q, n: _engine_ddg_media(q, n, 'videos')),
               ('bing', _engine_bing_videos)],
    'news':   [('duckduckgo', lambda q, n: _engine_ddg_media(q, n, 'news')),
               ('bing', _engine_bing_news),
               ('gdelt', _engine_gdelt_news)],
}


def mass_media_search(kind, query, engines=None, limit_per=_MASS_LIMIT_PER):
    """Mass image/video/news search across the sources for that medium.
    `engines` filters the source list — same names the tab's chips toggle."""
    sources = _MEDIA_SOURCES.get(kind, [])
    if engines:
        wanted = set(engines)
        sources = [(n, fn) for n, fn in sources if n in wanted]
    merged, status = {}, {}
    futs = {_WEB_POOL.submit(fn, query, limit_per): name for name, fn in sources}
    try:
        for fut in as_completed(futs, timeout=_MASS_SEARCH_DEADLINE):
            name = futs[fut]
            try:
                items = fut.result() or []
                status[name] = {'count': len(items)}
                for it in items:
                    key = _norm_url(it.get('url') or it.get('image') or '')
                    if not key:
                        continue
                    if key in merged:
                        merged[key]['engines'].add(name)
                    else:
                        it['engines'] = {name}
                        merged[key] = it
            except Exception as e:
                status[name] = {'error': str(e)[:120]}
    except TimeoutError:
        pass
    for fut, name in futs.items():
        if name not in status:
            status[name] = {'error': 'timeout'}
            fut.cancel()
    out = []
    for it in sorted(merged.values(), key=lambda r: -len(r['engines']))[:_MASS_RESULT_CAP]:
        it['engines'] = sorted(it['engines'])
        out.append(it)
    return out, status


_REG_HIVES = {
    'HKLM': 'HKEY_LOCAL_MACHINE', 'HKEY_LOCAL_MACHINE': 'HKEY_LOCAL_MACHINE',
    'HKCU': 'HKEY_CURRENT_USER', 'HKEY_CURRENT_USER': 'HKEY_CURRENT_USER',
    'HKCR': 'HKEY_CLASSES_ROOT', 'HKEY_CLASSES_ROOT': 'HKEY_CLASSES_ROOT',
    'HKU': 'HKEY_USERS', 'HKEY_USERS': 'HKEY_USERS',
    'HKCC': 'HKEY_CURRENT_CONFIG', 'HKEY_CURRENT_CONFIG': 'HKEY_CURRENT_CONFIG',
}
_REG_TYPE_NAMES = {}


def _winreg_query(path: str):
    """reg query <path> via in-process winreg — identical output shape,
    no subprocess. Returns the formatted text or None on failure."""
    if not _IS_WINDOWS:
        return None
    if not _REG_TYPE_NAMES:
        _REG_TYPE_NAMES.update({
            winreg.REG_SZ: 'REG_SZ', winreg.REG_EXPAND_SZ: 'REG_EXPAND_SZ',
            winreg.REG_BINARY: 'REG_BINARY', winreg.REG_DWORD: 'REG_DWORD',
            winreg.REG_DWORD_BIG_ENDIAN: 'REG_DWORD_BIG_ENDIAN',
            winreg.REG_QWORD: 'REG_QWORD', winreg.REG_MULTI_SZ: 'REG_MULTI_SZ',
            winreg.REG_LINK: 'REG_LINK', winreg.REG_NONE: 'REG_NONE',
            winreg.REG_RESOURCE_LIST: 'REG_RESOURCE_LIST',
            winreg.REG_FULL_RESOURCE_DESCRIPTOR: 'REG_FULL_RESOURCE_DESCRIPTOR',
        })
    head, _, sub = path.replace('/', '\\').strip('\\').partition('\\')
    hive = _REG_HIVES.get(head.upper())
    if not hive:
        return None
    hive_obj = getattr(winreg, hive)
    lines = [path]
    try:
        with winreg.OpenKey(hive_obj, sub, 0, winreg.KEY_READ) as k:
            i = 0
            while True:
                try:
                    name, val, typ = winreg.EnumValue(k, i)
                    i += 1
                except OSError:
                    break
                tname = _REG_TYPE_NAMES.get(typ, f'REG_TYPE_{typ}')
                if typ == winreg.REG_DWORD:
                    data = f'0x{val:08x} ({val})'
                elif typ == winreg.REG_QWORD:
                    data = f'0x{val:016x} ({val})'
                elif typ == winreg.REG_BINARY:
                    data = ' '.join(f'{b:02x}' for b in bytes(val))
                elif typ == winreg.REG_MULTI_SZ:
                    data = '\\0'.join(str(x) for x in val)
                elif isinstance(val, bytes):
                    data = ' '.join(f'{b:02x}' for b in val)
                else:
                    data = str(val)
                lines.append(f"    {name or '(Default)'}    {tname}    {data}")
            j = 0
            while True:
                try:
                    lines.append(path + '\\' + winreg.EnumKey(k, j))
                    j += 1
                except OSError:
                    break
    except Exception:
        return None
    return '\n'.join(lines)


def create_routes(app, state):
    _require('flask')
    import gzip as _gzip
    _GZIP_TYPES = frozenset({'text/html', 'text/css', 'text/javascript', 'application/javascript',
                             'application/json', 'text/plain', 'image/svg+xml'})
    @app.after_request
    def _gzip_responses(resp):
        """Gzip text responses >=1KB when the client accepts it — the shell and
        dashboard are ~140-190KB and compress ~8x."""
        try:
            if resp.status_code < 200 or resp.status_code >= 300: return resp
            if resp.direct_passthrough or resp.is_streamed: return resp
            if 'gzip' not in (flask_request.headers.get('Accept-Encoding') or '').lower(): return resp
            if (resp.mimetype or '') not in _GZIP_TYPES: return resp
            if resp.headers.get('Content-Encoding'): return resp
            data = resp.get_data()
            if len(data) < 1024: return resp
            comp = _gzip.compress(data, 5)
            resp.set_data(comp)
            resp.headers['Content-Encoding'] = 'gzip'
            resp.headers['Content-Length'] = str(len(comp))
            resp.headers['Vary'] = 'Accept-Encoding'
        except Exception:
            pass
        return resp

