    @app.route('/api/global-config', methods=['POST'])
    def set_global_config_route():
        data = flask_request.get_json(force=True, silent=True)
        if not isinstance(data, dict):
            return jsonify({'status': 'error', 'message': 'Invalid JSON body'}), 400
        cfg = load_global_config()
        relay_urls = data.get('relay_urls', cfg.get('relay_urls', []))
        if isinstance(relay_urls, str):
            relay_urls = [u.strip() for u in relay_urls.replace('\n', ',').replace(';', ',').split(',')]
        relay_urls = [str(u).strip() for u in relay_urls if str(u).strip().startswith(('http://', 'https://'))]
        cfg.update({
            'enabled': bool(data.get('enabled', cfg.get('enabled'))),
            'relay_url': str(data.get('relay_url', cfg.get('relay_url', ''))).strip(),
            'relay_urls': relay_urls,
            'network_code': str(data.get('network_code', cfg.get('network_code', ''))).strip(),
            'auto_connect': bool(data.get('auto_connect', cfg.get('auto_connect', True))),
            'brave_api_key': str(data.get('brave_api_key', cfg.get('brave_api_key', ''))).strip(),
        })
        save_global_config(cfg)
        old_svc = getattr(state, '_global_discovery', None)
        if old_svc: old_svc.stop()
        new_svc = GlobalDiscoveryService(my_peer_id=str(state.my_id), my_call_number=state.call_number, local_ip=state.local_ip, local_port=PORT, on_peers_updated=getattr(old_svc, 'on_peers_updated', None) if old_svc else None)
        state._global_discovery = new_svc
        new_svc.start()
        return jsonify({'status': 'ok', 'enabled': new_svc.enabled})

