    @app.route('/api/web-search')
    def web_search():
        query = flask_request.args.get('q', '').strip()
        if not query: return jsonify({'error': 'No query provided', 'results': []})
        if len(query) > 500: return jsonify({'error': 'Query too long', 'results': []})
        engine_param = flask_request.args.get('engine', 'all').strip().lower()
        if engine_param in ('', 'all'):
            engines = None
        else:
            engines = [e.strip() for e in engine_param.split(',') if e.strip() in WEB_SEARCH_ENGINES]
            if not engines: return jsonify({'error': f'Unknown engine: {engine_param}', 'results': [], 'available': available_engines()})
        try:
            merged, status = mass_web_search(query, engines=engines)
        except Exception as e:
            return jsonify({'error': f'Search failed: {str(e)}', 'results': []})
        return jsonify({'results': merged, 'engines': status, 'engine': 'all' if engines is None else ','.join(engines), 'query': query, 'available': available_engines()})

    @app.route('/api/media-search')
    def media_search():
        """Mass image / video / news search: /api/media-search?type=images&q=.."""
        query = flask_request.args.get('q', '').strip()
        kind = flask_request.args.get('type', 'images').strip().lower()
        if kind not in ('images', 'videos', 'news'):
            return jsonify({'error': 'type must be images, videos or news', 'results': []}), 400
        if not query:
            return jsonify({'error': 'No query provided', 'results': []})
        if len(query) > 500:
            return jsonify({'error': 'Query too long', 'results': []})
        avail = [n for n, _ in _MEDIA_SOURCES.get(kind, [])]
        eng_param = flask_request.args.get('engine', 'all').strip().lower()
        engines = None
        if eng_param and eng_param != 'all':
            engines = [e for e in eng_param.split(',') if e in avail]
        try:
            merged, status = mass_media_search(kind, query, engines=engines)
        except Exception as e:
            return jsonify({'error': f'Search failed: {str(e)}', 'results': []})
        return jsonify({'results': merged, 'engines': status, 'query': query,
                        'type': kind, 'available': avail})

