    # ===== Event Log =====
    @app.route('/api/event-log/<peer_id>')
    def event_log(peer_id):
        try:
            if peer_id == str(state.my_id):
                # In-process read via pywin32 — a PowerShell spawn used to
                # cost ~1s per request just to dump 50 System events.
                if _IS_WINDOWS:
                    try:
                        import win32evtlog
                        import win32evtlogutil
                        _EVT_NAMES = {1: 'Error', 2: 'Warning', 4: 'Information',
                                      8: 'AuditSuccess', 16: 'AuditFailure', 0: 'Info'}
                        hand = win32evtlog.OpenEventLog(None, 'System')
                        try:
                            events = win32evtlog.ReadEventLog(
                                hand,
                                win32evtlog.EVENTLOG_BACKWARDS_READ |
                                win32evtlog.EVENTLOG_SEQUENTIAL_READ, 0)
                        finally:
                            win32evtlog.CloseEventLog(hand)
                        lines = []
                        for ev in events[:50]:
                            try:
                                ts = ev.TimeGenerated.Format('%Y-%m-%d %H:%M:%S')
                            except Exception:
                                ts = ''
                            etype = _EVT_NAMES.get(ev.EventType, str(ev.EventType))
                            try:
                                msg = win32evtlogutil.SafeFormatMessage(ev, 'System')
                            except Exception:
                                msg = ''
                            msg = ' '.join(str(msg).split())[:140]
                            lines.append(f"{ts}  {etype:<11} {ev.SourceName:<28} {ev.EventID & 0xFFFF:<6} {msg}")
                        return jsonify({'success': True, 'info': '\n'.join(lines) or 'No events'})
                    except Exception:
                        pass
                cflags = subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
                r = subprocess.run(['powershell', '-Command', "Get-EventLog -LogName System -Newest 50 | Format-Table -AutoSize -Wrap | Out-String -Width 300"], capture_output=True, text=True, timeout=20, creationflags=cflags)
                return jsonify({'success': True, 'info': r.stdout.strip() or r.stderr.strip() or 'No events'})
            peer_info = state.known_peers.get(peer_id)
            if not peer_info:
                return jsonify({'success': False, 'error': 'Peer not found'})
            resp = _HTTP_SESSION.get(f"http://{peer_info.ip}:{peer_info.port}/api/event-log/{peer_id}", timeout=25)
            return jsonify(resp.json())
        except requests.exceptions.ConnectionError:
            return jsonify({'success': False, 'error': 'Peer unreachable'})
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)})

