    # ===== Drivers =====
    @app.route('/api/drivers/<peer_id>')
    def drivers_list(peer_id):
        try:
            if peer_id == str(state.my_id):
                # Kernel/fs drivers are service keys with Type 1/2 — one
                # in-process registry pass instead of a ~1s driverquery.
                if _IS_WINDOWS:
                    try:
                        _drv_types = {1: 'Kernel Driver', 2: 'File System Driver',
                                      4: 'Adapter', 8: 'Recognizer Driver'}
                        _drv_start = {0: 'Boot', 1: 'System', 2: 'Auto',
                                      3: 'Manual', 4: 'Disabled'}
                        rows = []
                        with winreg.OpenKey(
                                winreg.HKEY_LOCAL_MACHINE,
                                r'SYSTEM\CurrentControlSet\Services', 0,
                                winreg.KEY_READ) as k:
                            i = 0
                            while True:
                                try:
                                    svc = winreg.EnumKey(k, i)
                                    i += 1
                                except OSError:
                                    break
                                try:
                                    with winreg.OpenKey(k, svc, 0,
                                                        winreg.KEY_READ) as sk:
                                        try:
                                            typ, _ = winreg.QueryValueEx(sk, 'Type')
                                        except (OSError, FileNotFoundError):
                                            continue
                                        if typ not in _drv_types:
                                            continue
                                        disp = svc
                                        try:
                                            disp, _ = winreg.QueryValueEx(sk, 'DisplayName')
                                        except (OSError, FileNotFoundError):
                                            pass
                                        start = path = ''
                                        try:
                                            sv, _ = winreg.QueryValueEx(sk, 'Start')
                                            start = _drv_start.get(sv, str(sv))
                                        except (OSError, FileNotFoundError):
                                            pass
                                        try:
                                            path, _ = winreg.QueryValueEx(sk, 'ImagePath')
                                            path = os.path.expandvars(str(path)).strip('"')
                                        except (OSError, FileNotFoundError):
                                            pass
                                        rows.append((svc, str(disp),
                                                     _drv_types[typ], start, str(path)))
                                except OSError:
                                    continue
                        if rows:
                            w0 = max(len(r[0]) for r in rows)
                            w2 = max(len(r[2]) for r in rows)
                            hdr = f"{'Driver Name':<{w0}}  {'Display Name':<40}  {'Driver Type':<{w2}}  {'Start Mode':<10}  Path"
                            lines = [hdr] + [f"{a:<{w0}}  {b[:40]:<40}  {c:<{w2}}  {d:<10}  {e}"
                                             for a, b, c, d, e in sorted(rows)]
                            return jsonify({'success': True, 'info': '\n'.join(lines)})
                    except Exception:
                        pass
                cflags = subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
                r = subprocess.run(['driverquery', '/FO', 'TABLE'], capture_output=True, text=True, timeout=15, creationflags=cflags)
                return jsonify({'success': True, 'info': r.stdout.strip() or 'No driver data'})
            peer_info = state.known_peers.get(peer_id)
            if not peer_info:
                return jsonify({'success': False, 'error': 'Peer not found'})
            resp = _HTTP_SESSION.get(f"http://{peer_info.ip}:{peer_info.port}/api/drivers/{peer_id}", timeout=20)
            return jsonify(resp.json())
        except requests.exceptions.ConnectionError:
            return jsonify({'success': False, 'error': 'Peer unreachable'})
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)})

