    @app.route('/api/peer-detail/<peer_id>')
    def api_peer_detail(peer_id):
        my = str(state.my_id)
        is_self = peer_id == my
        info = state.known_peers.get(peer_id) or state.discovered_peers.get(peer_id)
        global_cn = getattr(state, '_global_call_numbers', {})
        detail = {
            'id': peer_id, 'is_self': is_self,
            'call_number': state.call_number if is_self else global_cn.get(peer_id, 'N/A'),
            'reachable': is_self,
        }
        if is_self:
            detail.update({'ip': state.local_ip, 'port': PORT, 'public_ip': state.public_ip,
                           'join_time': state.my_join_time, 'last_seen': time.time(),
                           'shared_count': len(state.shared_paths),
                           'role': get_current_role(state), 'version': VERSION,
                           'friendly_name': platform.node()})
            return jsonify(detail)
        if not info:
            return jsonify({**detail, 'error': 'Peer not found'}), 404
        detail.update({'ip': info.ip, 'port': info.port,
                       'join_time': info.join_time, 'last_seen': info.last_seen,
                       'last_seen_ago': max(0, int(time.time() - info.last_seen))})
        remote = fetch_peer_info(info.ip, info.port)
        if remote:
            detail['reachable'] = True
            detail['version'] = remote.get('version')
            detail['friendly_name'] = remote.get('friendly_name')
            if remote.get('call_number'): detail['call_number'] = remote['call_number']
            detail['shared_count'] = remote.get('shared_count')
            detail['public_ip'] = remote.get('public_ip')
        else:
            cnt = fetch_peer_shared_count(info.ip, info.port)
            detail['shared_count'] = cnt
        return jsonify(detail)

