    @app.route('/api/inbox', methods=['GET'])
    def api_inbox_poll():
        """Return and clear pages sent to us by peers (send-to-device)."""
        with state._lock:
            items = list(state.inbox)
            state.inbox.clear()
        return jsonify({'items': items})

    @app.route('/api/inbox', methods=['POST'])
    def api_inbox_receive():
        """Receive a page pushed by another peer."""
        data = flask_request.get_json(silent=True) or {}
        url = str(data.get('url', ''))[:2000]
        if not url:
            return jsonify({'ok': False, 'error': 'url required'}), 400
        item = {
            'from': str(data.get('from', ''))[:100],
            'call_number': str(data.get('call_number', ''))[:100],
            'url': url,
            'title': str(data.get('title', ''))[:200] or url,
            'ts': time.time(),
        }
        with state._lock:
            state.inbox.append(item)
            del state.inbox[:-30]
        return jsonify({'ok': True})

    @app.route('/api/send-page', methods=['POST'])
    def api_send_page():
        """Push a URL to a live peer's browser (send-to-device)."""
        data = flask_request.get_json(silent=True) or {}
        peer_id = str(data.get('peer_id', ''))
        url = str(data.get('url', ''))[:2000]
        title = str(data.get('title', ''))[:200]
        if not peer_id or not url:
            return jsonify({'ok': False, 'error': 'peer_id and url required'}), 400
        peers = dict(state.get_known_peers())
        peers.update(state.get_discovered_peers())
        info = peers.get(peer_id)
        if not info:
            return jsonify({'ok': False, 'error': 'peer not found or offline'}), 404
        try:
            r = _HTTP_SESSION.post(
                f"http://{info.ip}:{info.port}/api/inbox",
                json={'from': str(state.my_id), 'call_number': state.call_number,
                      'url': url, 'title': title},
                timeout=4)
            return jsonify({'ok': r.ok})
        except Exception as e:
            return jsonify({'ok': False, 'error': str(e)}), 502


