def setup_logging():
    log_file = DATA_DIR / "gna.log"
    root_logger = logging.getLogger()
    root_logger.setLevel(logging.DEBUG)
    file_handler = logging.handlers.RotatingFileHandler(log_file, maxBytes=5 * 1024 * 1024, backupCount=3)
    file_handler.setLevel(logging.DEBUG)
    file_formatter = logging.Formatter('%(asctime)s | %(levelname)-8s | %(name)s | %(message)s', datefmt='%Y-%m-%d %H:%M:%S')
    file_handler.setFormatter(file_formatter)
    root_logger.addHandler(file_handler)
    console_handler = logging.StreamHandler(sys.stdout)
    console_handler.setLevel(logging.WARNING)
    console_formatter = logging.Formatter('%(levelname)s: %(message)s')
    console_handler.setFormatter(console_formatter)
    root_logger.addHandler(console_handler)
    logging.getLogger('werkzeug').setLevel(logging.ERROR)
    logging.getLogger('flask').setLevel(logging.ERROR)
    logging.getLogger('zeroconf').setLevel(logging.WARNING)

def print_startup_banner():
    print(f">> {APP_NAME} v{VERSION} -- Starting (console will stay open forever)")
    print(f"   Project directory: {PROJECT_DIR}")

_sender_cache = {"status": "UNKNOWN", "ts": 0}
_signaling_cache = {"status": "UNKNOWN", "ts": 0}
_STATUS_CACHE_TTL = 15
_sender_pid = None  # PID of the sender.py subprocess we launched

def _probe_sender_status():
    global _sender_pid
    result_status = "NOT DETECTED"
    # Method 0: the in-process fallback sender (runs when sender.py can't spawn)
    if _EMB_SENDER.get('running'):
        return "RUNNING (embedded)"
    # Method 1: check our own launched sender PID
    if _sender_pid is not None:
        try:
            if psutil.pid_exists(_sender_pid):
                result_status = "RUNNING"
            else:
                _sender_pid = None  # process died
        except Exception:
            _sender_pid = None
    # Method 2: scan processes for a sender.py command line (psutil is far
    # cheaper than spawning tasklist/wmic subprocesses). Prefetch only
    # 'name' — cmdline is the most expensive per-proc attribute, so it's
    # fetched lazily for python-ish processes only.
    if result_status == "NOT DETECTED":
        try:
            for p in psutil.process_iter(['name']):
                try:
                    pname = (p.info.get('name') or '').lower()
                    if 'python' not in pname and 'pyth' not in pname:
                        continue
                    cl = p.cmdline()
                    if any('sender.py' in str(a) for a in cl):
                        result_status = "RUNNING"
                        break
                except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                    continue
        except Exception: pass
    # Method 3 (fallback): window-title check for bat-file launches
    if result_status == "NOT DETECTED" and os.name == 'nt':
        try:
            cflags = subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
            result = subprocess.run(['tasklist', '/FI', 'WINDOWTITLE eq PubLAN Sender'],
                                    capture_output=True, text=True, timeout=3, creationflags=cflags)
            if 'python' in result.stdout.lower(): result_status = "RUNNING"
        except Exception: pass
    return result_status

def check_sender_status():
    """Last-known status, refreshed in the background — never blocks a request."""
    now = time.time()
    if now - _sender_cache["ts"] < _STATUS_CACHE_TTL or _sender_cache.get("pending"):
        return _sender_cache["status"]
    _sender_cache["pending"] = True
    def _run():
        try:
            _sender_cache["status"] = _probe_sender_status()
        finally:
            _sender_cache["ts"] = time.time()
            _sender_cache["pending"] = False
    threading.Thread(target=_run, daemon=True, name="SenderProbe").start()
    return _sender_cache["status"]

def check_signaling_server_status():
    """Last-known status, refreshed in the background — a stalled health probe
    must never block an HTTP request (measured 4s+ when :3000 accepts but hangs)."""
    now = time.time()
    if now - _signaling_cache["ts"] < _STATUS_CACHE_TTL or _signaling_cache.get("pending"):
        return _signaling_cache["status"]
    _signaling_cache["pending"] = True
    def _probe():
        status = "NOT REACHABLE"
        for port in _EMB_RELAY_PORTS:
            try:
                resp = _HTTP_SESSION.get(f"http://localhost:{port}/health", timeout=1.5)
                if resp.status_code == 200:
                    status = "RUNNING" if port == 3000 else f"RUNNING (:{port})"
                    break
                status = f"RESPONDING ({resp.status_code})"
            except Exception:
                continue
        _signaling_cache["status"] = status
        _signaling_cache["ts"] = time.time()
        _signaling_cache["pending"] = False
    threading.Thread(target=_probe, daemon=True, name="SignalingProbe").start()
    return _signaling_cache["status"]

def print_live_status(state):
    sorted_live = get_sorted_live_peers(state)
    my_role = get_current_role(state)
    sender_status = check_sender_status()
    signaling_status = check_signaling_server_status()
    global_svc = getattr(state, '_global_discovery', None)
    if global_svc and global_svc.enabled:
        relay_connected = global_svc.sio and global_svc.sio.connected
        relay_status = "LIVE" if relay_connected else "OFFLINE"
        relay_url = global_svc.relay_url if relay_connected else "(disconnected)"
        relay_peers = len(global_svc.global_peers)
    else:
        relay_status = "DISABLED"
        relay_url = ""
        relay_peers = 0
    print(f"\n{'='*80}")
    print(f"{APP_NAME} v{VERSION} LIVE STATUS — {time.strftime('%H:%M:%S')}")
    print(f"ID : {state.my_id}")
    print(f"Call Number : {state.call_number}")
    print(f"Role : {my_role}")
    print(f"Public IP : {state.public_ip}")
    print(f"Local IP:Port : {state.local_ip}:{PORT}")
    print(f"Live Peers : {len(sorted_live)}")
    print(f"Shared Items : {len(state.shared_paths)}")
    print(f"Sender.py : {sender_status}")
    print(f"Signal Server : {signaling_status}")
    if relay_status == "LIVE":
        print(f"Global Relay : {relay_status} — {relay_url} ({relay_peers} peers)")
    elif relay_status == "OFFLINE":
        print(f"Global Relay : {relay_status} — attempting {global_svc.relay_url}...")
    else:
        print(f"Global Relay : {relay_status}")
    print(f"Status : Active")
    print(f"{'='*80}")

def discovery_thread_fn(state):
    global _peer_exchange_last
    try:
        while True:
            update_peer_bookkeeping(state)
            try: refresh_stale_peers(state)
            except Exception: pass
            now = time.time()
            if now - _peer_exchange_last > 30:
                _peer_exchange_last = now
                try: peer_exchange(state)
                except Exception: pass
            time.sleep(DISCOVERY_INTERVAL_SECONDS)
    except Exception as e:
        print(f"[ERROR] Discovery thread stopped: {e}")

def status_thread_fn(state):
    try:
        # Services boot on the ServiceBootstrap thread — give them a moment so
        # the first status print isn't a stale "OFFLINE/NOT RUNNING" snapshot.
        time.sleep(2)
        while True:
            print_live_status(state)
            time.sleep(STATUS_PRINT_INTERVAL_SECONDS)
    except Exception: pass

def flask_thread_fn(app):
    try:
        app.run(host='0.0.0.0', port=PORT, debug=False, use_reloader=False, threaded=True)
    except Exception as e:
        print(f"[ERROR] Flask server stopped: {e}")

def launch_bat_file():
    """Run Start PubLAN.bat in the project directory (from launcher.py)."""
    try:
        exe_dir = PROJECT_DIR
        bat_path = exe_dir / "Start PubLAN.bat"
        if bat_path.exists():
            print(f"[OK] Launching Start PubLAN.bat from {exe_dir}")
            subprocess.Popen(
                ['cmd.exe', '/c', str(bat_path)],
                cwd=str(exe_dir),
                creationflags=subprocess.CREATE_NEW_CONSOLE,
            )
        else:
            print(f"[WARNING] Start PubLAN.bat not found at {bat_path}")
    except Exception as e:
        print(f"[WARNING] Could not launch Start PubLAN.bat: {e}")

def _wait_port_open(port, timeout=2.0):
    """Poll until 127.0.0.1:port accepts TCP (Flask bind) — so the browser is
    opened against a live server instead of racing the bind and showing an
    error page."""
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            with socket.create_connection(('127.0.0.1', port), timeout=0.15):
                return True
        except OSError:
            time.sleep(0.05)
    return False

# Network objects created on the bootstrap thread must outlive the function —
# if Zeroconf/ServiceBrowser get GC'd, mDNS announcements silently die. The old
# code kept them alive by accident because they lived on main()'s frame, which
# blocks forever. Pin them globally instead.
_BOOT_REFS = []

def _bootstrap_network_services(state, my_id, my_call_number, local_ip):
    """Everything that touches the network at startup — mDNS, relay, global
    discovery, signaling server, sender, caller — boots on this one background
    thread so launch is never gated on external timeouts."""
    _require('socketio'); _require('asyncio')
    # --- LAN discovery (zeroconf register_service blocks ~0.5-2s announcing) ---
    try:
        zc = Zeroconf()
        _BOOT_REFS.append(zc)
        try:
            _BOOT_REFS.append(register_service(zc, my_id, local_ip))
            _BOOT_REFS.append(start_discovery(zc, state, my_id))
        except Exception as e:
            print(f"[WARNING] mDNS registration failed: {e}")
    except Exception as e:
        print(f"[WARNING] Zeroconf unavailable: {e}")

    # Start the embedded signaling + relay server first — the first
    # instance hosts the meeting place, so global discovery has a live
    # route even with no external server.js running.
    try:
        _relay_port = _start_embedded_relay()
        if _relay_port:
            if _EMB_RELAY.get('server'):
                print(f"[OK] Embedded signaling/relay server hosting on :{_relay_port}")
            else:
                print(f"[OK] Signaling/relay server already live on :{_relay_port}")
        else:
            print("[INFO] No relay port available (3000-3003)")
    except Exception as e:
        print(f"[WARNING] Could not start embedded relay: {e}")

    # Start global discovery service
    state._global_call_numbers = {}

    def on_global_peers_updated(peers):
        for p in peers:
            pid = p.get('peerId', '')
            if not pid or pid == str(my_id): continue
            info = PeerInfo(ip=p.get('ip', ''), port=int(p.get('port', PORT)), join_time=time.time(), last_seen=time.time())
            state.add_known_peer(pid, info)
            cn = p.get('callNumber', '')
            if cn: state._global_call_numbers[pid] = cn

    try:
        global_svc = GlobalDiscoveryService(my_peer_id=str(my_id), my_call_number=my_call_number, local_ip=local_ip, local_port=PORT, on_peers_updated=on_global_peers_updated)
        state._global_discovery = global_svc
        global_svc.start()
        if global_svc.enabled:
            print(f"[OK] Global discovery enabled: network='{global_svc.network_code}'")
        else:
            print("[INFO] Global discovery disabled (configure global_config.json to enable)")
    except Exception as e:
        print(f"[WARNING] Could not start global discovery: {e}")

    # Start Node.js signaling server (if not already running)
    try:
        sig_running = False
        try:
            r = _HTTP_SESSION.get("http://localhost:3000/health", timeout=2)
            if r.status_code == 200:
                sig_running = True
        except Exception:
            pass
        if not sig_running:
            server_js = PROJECT_DIR / 'server.js'
            if server_js.exists():
                # npm install first if node_modules missing
                pkg_json = PROJECT_DIR / 'package.json'
                node_modules = PROJECT_DIR / 'node_modules'
                if pkg_json.exists() and not node_modules.exists():
                    try:
                        subprocess.run(['npm', 'install', '--silent'], cwd=str(PROJECT_DIR),
                                       capture_output=True, timeout=60)
                    except Exception:
                        pass
                server_proc = subprocess.Popen(['node', str(server_js)], cwd=str(PROJECT_DIR),
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                 creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0)
                _BOOT_REFS.append(server_proc)
                for _ in range(15):
                    if server_proc.poll() is not None:
                        break
                    try:
                        if _HTTP_SESSION.get("http://localhost:3000/health", timeout=0.5).status_code == 200:
                            break
                    except Exception:
                        pass
                    time.sleep(0.4)
                if server_proc.poll() is None:
                    print("[OK] Signaling server (server.js) started in background")
                else:
                    print(f"[WARNING] server.js exited immediately (code {server_proc.returncode})")
            else:
                print("[INFO] server.js not found — signaling server not started")
        else:
            print("[OK] Signaling server already running on port 3000")
    except Exception as e:
        print(f"[WARNING] Could not start signaling server: {e}")

    # Start sender.py in background (screen sharing). The source is
    # embedded in this file — _ensure_sender_script materializes it when
    # missing, and if the spawn itself fails the in-process sender runs
    # instead. Two routes so screen sharing is never dead.
    _sender_spawned = False
    try:
        sender_path = PROJECT_DIR / 'sender.py'
        if _ensure_sender_script(sender_path):
            # Write sender_session_id.txt (same as bat file does)
            session_id_file = PROJECT_DIR / 'sender_session_id.txt'
            sender_session_id = hashlib.md5(platform.node().encode()).hexdigest()
            try:
                with open(session_id_file, 'w') as f:
                    f.write(sender_session_id)
            except Exception:
                pass
            sender_proc = subprocess.Popen(
                [sys.executable, str(sender_path)],
                cwd=str(PROJECT_DIR),
                creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0,
            )
            global _sender_pid
            _sender_pid = sender_proc.pid
            for _ in range(8):
                if sender_proc.poll() is not None:
                    break
                time.sleep(0.1)
            if sender_proc.poll() is None:
                _sender_spawned = True
                print(f"[OK] Sender.py started in background (PID {_sender_pid})")
            else:
                print(f"[WARNING] Sender.py exited immediately (code {sender_proc.returncode})")
        else:
            print("[WARNING] sender.py could not be materialized")
    except Exception as e:
        print(f"[WARNING] Could not start sender.py: {e}")
    if not _sender_spawned:
        # Backup route: run the same screen-share loop in-process.
        try:
            threading.Thread(target=_embedded_sender_main, daemon=True,
                             name='EmbeddedSender').start()
            print("[OK] Embedded screen-share sender started (in-process)")
        except Exception as e:
            print(f"[WARNING] Could not start embedded sender: {e}")

    # Start caller listener in background
    try:
        caller_path = PROJECT_DIR / 'caller.py'
        if caller_path.exists():
            subprocess.Popen([sys.executable, str(caller_path), str(my_id), my_call_number], creationflags=0)
            print("[OK] Call listener started in background")
    except Exception as e:
        print(f"[WARNING] Could not start call listener: {e}")


def main():
    # Long-running server with dozens of I/O threads: a wider GIL switch
    # interval cuts scheduler churn, and a larger gen-0 GC threshold halves
    # collection passes over this workload's object allocation churn.
    sys.setswitchinterval(0.05)
    gc.set_threshold(50000)
    setup_logging()
    print_startup_banner()

    # NOTE: Start PubLAN.bat is no longer launched here because the monolith
    # now directly starts the signaling server, sender.py, and caller.py.
    # The bat file would launch databank_explorer.py which creates a duplicate
    # Flask instance and a duplicate browser tab.

    try:
        # Self-verification check
        run_startup_integrity_check(PROJECT_DIR)

        migrate_legacy_files()

        my_id = generate_random_peer_id()
        my_call_number = generate_call_number()
        print(f"New random Bank ID this session: {my_id}")
        print(f"Call Number this session: {my_call_number}")

        my_join_time = load_join_time()
        local_ip = get_local_ip()
        # Public IP needs an external HTTP call (up to PUBLIC_IP_TIMEOUT_SECONDS)
        # — start as "unknown" (get_my_info falls back to local_ip) and resolve
        # it on a background thread so it never gates launch.
        public_ip = "unknown"

        state = ApplicationState(
            my_id=my_id, my_join_time=my_join_time,
            local_ip=local_ip, public_ip=public_ip,
            call_number=my_call_number,
            shared_paths=load_shared_paths(),
            known_peers=load_known_peers(),
        )

        shared_count = len(state.shared_paths)
        print(f"Loaded {shared_count} public paths")

        _require('flask')
        app = Flask(__name__)
        app.config['MAX_CONTENT_LENGTH'] = 100 * 1024 * 1024  # 100 MB upload limit
        app.logger.disabled = True
        create_routes(app, state)

        # --- Dashboard first: bind Flask, then open the browser against a live
        # server. Everything network-bound (mDNS, relay, discovery, sender)
        # boots on background threads afterwards — see _bootstrap_network_services.
        threading.Thread(target=flask_thread_fn, args=(app,), daemon=True, name="FlaskThread").start()
        _wait_port_open(PORT, timeout=2.0)

        # Launch MedianBox Monitor early — its own interpreter startup + import
        # takes ~2s in the child process, so spawning now overlaps that with the
        # rest of our boot instead of serializing it behind the service probes.
        # The full program (packet pipeline, all monitor threads, :8470
        # dashboard, and the GNA Tracer GUI window) runs in its own console.
        _mb_launched = False
        try:
            print("[OK] Launching MedianBox Monitor (full program + GNA Tracer window)...")
            # -m runs through the import machinery, so the cached .pyc is
            # used instead of re-compiling ~3.4MB of source as __main__.
            subprocess.Popen(
                [sys.executable, '-m', Path(__file__).resolve().stem, '--medianbox'],
                cwd=str(PROJECT_DIR),
                creationflags=subprocess.CREATE_NEW_CONSOLE,
            )
            _mb_launched = True
        except Exception as e:
            print(f"[WARNING] Could not launch embedded MedianBox Monitor: {e}")
        if not _mb_launched:
            # Fallback: medianbox_monitor_v2.py is a complete standalone copy
            # of the same program — launch the file itself so the monitor
            # (and its GNA Tracer window) still comes up at full.
            try:
                _v2 = PROJECT_DIR / 'medianbox_monitor_v2.py'
                if _v2.exists():
                    subprocess.Popen(
                        [sys.executable, '-m', 'medianbox_monitor_v2'],
                        cwd=str(PROJECT_DIR),
                        creationflags=subprocess.CREATE_NEW_CONSOLE,
                    )
                    print("[OK] Launched standalone medianbox_monitor_v2.py instead")
            except Exception as e:
                print(f"[WARNING] Could not launch medianbox_monitor_v2.py: {e}")

        # Open browser — Flask is already listening (bind-wait above), so the
        # tab loads immediately instead of racing the server start.
        try:
            webbrowser.open(f"http://127.0.0.1:{PORT}")
            print("[OK] Browser opened to Dashboard!")
        except Exception as e:
            print(f"[WARNING] Could not open browser: {e}")
            print(f"         Navigate manually to http://127.0.0.1:{PORT}")

        # Resolve the public IP concurrently — state.public_ip is read on
        # demand by get_my_info / status / dashboard routes, so it simply
        # populates a moment after launch.
        def _resolve_public_ip():
            try:
                state.public_ip = get_public_ip()
            except Exception:
                pass
        threading.Thread(target=_resolve_public_ip, daemon=True, name="PublicIP").start()

        # Peer bookkeeping + status printers
        threading.Thread(target=discovery_thread_fn, args=(state,), daemon=True, name="DiscoveryThread").start()
        threading.Thread(target=status_thread_fn, args=(state,), daemon=True, name="StatusThread").start()

        # Everything else — mDNS/zeroconf, embedded relay, global discovery,
        # signaling server check, sender.py, caller.py — on one background
        # thread so launch completes while services come up in parallel.
        threading.Thread(target=_bootstrap_network_services,
                         args=(state, my_id, my_call_number, local_ip),
                         daemon=True, name="ServiceBootstrap").start()

        # Freeze every object allocated during startup (config, patterns,
        # compiled regexes, routes) — GC no longer scans them each pass.
        try:
            gc.freeze()
        except Exception:
            pass

        # Main thread blocks here forever
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        print("\n[WARNING] Shutting down...")
    except Exception as e:
        print(f"\n[ERROR] {type(e).__name__} - {e}")
        traceback.print_exc()
        sys.exit(1)
    finally:
        print("\nConsole will stay open until you press Enter...")
        input("Press Enter to close this window...")


if __name__ == '__main__':
    if '--medianbox' in sys.argv:
        sys.argv.remove('--medianbox')
        medianbox_main()
    else:
        main()
